    /**
     * @return array<string, mixed>
     */
    private function zipNamePolicyProvenance(ZipPackage $sourcePackage): array
    {
        $pathHierarchy = $sourcePackage->pathHierarchyPreflight();
        $caseInsensitiveNames = $sourcePackage->caseInsensitiveNamePreflight();
        $rawNames = $sourcePackage->rawNamePreflight();
        $nameHygiene = $sourcePackage->nameHygienePreflight();
        $issueCodes = [];
        if ((int) $pathHierarchy['collisionEntryCount'] > 0) {
            $issueCodes[] = 'path-hierarchy-collisions';
        }
        if ((int) $caseInsensitiveNames['collisionEntryCount'] > 0) {
            $issueCodes[] = 'case-insensitive-name-collisions';
        }
        if ((int) $rawNames['collisionEntryCount'] > 0) {
            $issueCodes[] = 'raw-name-collisions';
        }
        if ((int) $rawNames['provenanceEntryCount'] > 0) {
            $issueCodes[] = 'raw-name-provenance-review-entries';
        }
        if ((int) $nameHygiene['reviewEntryCount'] > 0) {
            $issueCodes[] = 'name-hygiene-review-entries';
        }

        return [
            'present' => true,
            'entryCount' => count($sourcePackage->entries()),
            'valid' => $issueCodes === [],
            'issueCount' => count($issueCodes),
            'issueCodes' => $issueCodes,
            'pathHierarchyCollisionEntryCount' => (int) $pathHierarchy['collisionEntryCount'],
            'pathHierarchyCollisionEntries' => $pathHierarchy['collisionEntries'],
            'caseInsensitiveNameCollisionGroupCount' => (int) $caseInsensitiveNames['collisionGroupCount'],
            'caseInsensitiveNameCollisionEntryCount' => (int) $caseInsensitiveNames['collisionEntryCount'],
            'caseInsensitiveNameCollisionGroups' => $caseInsensitiveNames['collisionGroups'],
            'caseInsensitiveNameCollisionEntries' => $caseInsensitiveNames['collisionEntries'],
            'rawNameCollisionGroupCount' => (int) $rawNames['collisionGroupCount'],
            'rawNameCollisionEntryCount' => (int) $rawNames['collisionEntryCount'],
            'rawNameProvenanceEntryCount' => (int) $rawNames['provenanceEntryCount'],
            'rawNameLegacyEncodedEntryCount' => (int) $rawNames['legacyEncodedNameEntryCount'],
            'rawNameUnicodePathExtraEntryCount' => (int) $rawNames['unicodePathExtraEntryCount'],
            'rawNameDecodedDiffersEntryCount' => (int) $rawNames['decodedNameDiffersFromRawNameEntryCount'],
            'rawNameCollisionGroups' => $rawNames['collisionGroups'],
            'rawNameCollisionEntries' => $rawNames['collisionEntries'],
            'rawNameProvenanceEntries' => $rawNames['provenanceEntries'],
            'nameHygieneReviewEntryCount' => (int) $nameHygiene['reviewEntryCount'],
            'nameHygieneLeadingOrTrailingWhitespaceEntryCount' => (int) $nameHygiene['leadingOrTrailingWhitespaceEntryCount'],
            'nameHygieneTrailingDotSegmentEntryCount' => (int) $nameHygiene['trailingDotSegmentEntryCount'],
            'nameHygieneWindowsReservedNameEntryCount' => (int) $nameHygiene['windowsReservedNameEntryCount'],
            'nameHygieneWindowsAlternateDataStreamEntryCount' => (int) $nameHygiene['windowsAlternateDataStreamEntryCount'],
            'nameHygieneUnicodeFormatControlEntryCount' => (int) $nameHygiene['unicodeFormatControlEntryCount'],
            'nameHygieneUnicodeBidiControlEntryCount' => (int) $nameHygiene['unicodeBidiControlEntryCount'],
            'nameHygieneReviewEntries' => $nameHygiene['reviewEntries'],
        ];
    }

    private function zipPackageEntryRoles(ZipPackageEntry $entry, bool $loadedPart): array
    {
        if ($entry->isDirectory()) {
            return ['zip-directory'];
        }

        $roles = ['zip-file-entry'];
        if ($loadedPart) {
            $roles[] = 'loaded-package-part';
        }
        if ($entry->compressionMethod !== 0 && $entry->compressionMethod !== 8) {
            $roles[] = 'zip-unsupported-compression';
        }
        if ($entry->name === '[Content_Types].xml') {
            $roles[] = 'content-types';
        }
        if ($this->isRelationshipPartName($entry->name)) {
            $roles[] = 'relationship-part';
        }

        return $roles;
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @param array<string, mixed> $zipPackage
     * @return array<string, array<string, mixed>>
     */
    private function packagePartInventoryWithZipProvenance(array $partInventory, array $zipPackage): array
    {
        if (($zipPackage['present'] ?? false) !== true || !is_array($zipPackage['byPackagePath'] ?? null)) {
            return $partInventory;
        }

        $opcManifestEntriesByName = [];
        $opcManifest = is_array($zipPackage['opcManifest'] ?? null) ? $zipPackage['opcManifest'] : [];
        foreach (($opcManifest['entries'] ?? []) as $manifestEntry) {
            if (!is_array($manifestEntry) || !is_string($manifestEntry['entryName'] ?? null)) {
                continue;
            }

            $opcManifestEntriesByName[$manifestEntry['entryName']] = $manifestEntry;
        }

        foreach ($zipPackage['byPackagePath'] as $partName => $entry) {
            if (!is_string($partName) || !is_array($entry) || !isset($partInventory[$partName])) {
                continue;
            }

            $partInventory[$partName]['zipEntryPresent'] = true;
            $partInventory[$partName]['centralDirectoryIndex'] = $entry['centralDirectoryIndex'] ?? null;
            $partInventory[$partName]['localHeaderOrder'] = $entry['localHeaderOrder'] ?? null;
            $partInventory[$partName]['localHeaderOffset'] = $entry['localHeaderOffset'] ?? null;
            $partInventory[$partName]['matchesCentralDirectoryOrder'] = $entry['matchesCentralDirectoryOrder'] ?? null;
            $partInventory[$partName]['compressionMethod'] = $entry['compressionMethod'] ?? null;
            $partInventory[$partName]['compressionMethodName'] = $entry['compressionMethodName'] ?? null;
            $partInventory[$partName]['compressionSupported'] = $entry['compressionSupported'] ?? null;
            $partInventory[$partName]['compressedByteLength'] = $entry['compressedByteLength'] ?? null;
            $partInventory[$partName]['zipCrc32'] = $entry['crc32'] ?? null;
            $partInventory[$partName]['zipPackageManifestPresent'] = $entry['packageManifestPresent'] ?? false;
            $partInventory[$partName]['zipPackageManifestVersion'] = $entry['packageManifestVersion'] ?? null;
            $partInventory[$partName]['zipPackageManifestSha256'] = $entry['packageManifestSha256'] ?? null;
            $partInventory[$partName]['zipLocalHeaderLength'] = $entry['localHeaderLength'] ?? null;
            $partInventory[$partName]['zipLocalHeaderSha256'] = $entry['localHeaderSha256'] ?? null;
            $partInventory[$partName]['zipCompressedDataOffset'] = $entry['compressedDataOffset'] ?? null;
            $partInventory[$partName]['zipCompressedDataEnd'] = $entry['compressedDataEnd'] ?? null;
            $partInventory[$partName]['zipCompressedDataSha256'] = $entry['compressedDataSha256'] ?? null;
            $partInventory[$partName]['zipCentralDirectoryRecordOffset'] = $entry['centralDirectoryRecordOffset'] ?? null;
            $partInventory[$partName]['zipCentralDirectoryRecordEnd'] = $entry['centralDirectoryRecordEnd'] ?? null;
            $partInventory[$partName]['zipCentralDirectoryRecordSha256'] = $entry['centralDirectoryRecordSha256'] ?? null;
            $partInventory[$partName]['zipLocalHeaderPreflightPresent'] = $entry['localHeaderPreflightPresent'] ?? false;
            $partInventory[$partName]['zipLocalFixedHeaderOffset'] = $entry['localFixedHeaderOffset'] ?? null;
            $partInventory[$partName]['zipLocalFixedHeaderLength'] = $entry['localFixedHeaderLength'] ?? null;
            $partInventory[$partName]['zipLocalVariableFieldsOffset'] = $entry['localVariableFieldsOffset'] ?? null;
            $partInventory[$partName]['zipLocalVariableFieldsLength'] = $entry['localVariableFieldsLength'] ?? null;
            $partInventory[$partName]['zipLocalNameOffset'] = $entry['localNameOffset'] ?? null;
            $partInventory[$partName]['zipLocalNameLength'] = $entry['localNameLength'] ?? null;
            $partInventory[$partName]['zipLocalExtraFieldOffset'] = $entry['localExtraFieldOffset'] ?? null;
            $partInventory[$partName]['zipLocalExtraFieldLength'] = $entry['localExtraFieldLength'] ?? null;
            $partInventory[$partName]['zipLocalExtraFieldRecordCount'] = $entry['localExtraFieldRecordCount'] ?? 0;
            $partInventory[$partName]['zipLocalExtraFieldIds'] = $entry['localExtraFieldIds'] ?? [];
            $partInventory[$partName]['zipLocalExtraFieldStructureIssues'] =
                $entry['localExtraFieldStructureIssues'] ?? [];
            $partInventory[$partName]['zipLocalExtraFieldRecords'] = $entry['localExtraFieldRecords'] ?? [];
            $partInventory[$partName]['zipHasLocalExtraFields'] = $entry['hasLocalExtraFields'] ?? false;
            $partInventory[$partName]['zipLocalHeaderDataStart'] = $entry['localHeaderDataStart'] ?? null;
            $partInventory[$partName]['zipLocalHeaderCompressedDataEnd'] =
