                'unknownInternalAttributeBits',
                'unixMode',
                'unixModeOctal',
                'unixPermissions',
                'unixPermissionsOctal',
                'hasUnixMode',
                'unixFileType',
                'unixFileTypeName',
                'isUnixExecutableFile',
                'isGroupWritable',
                'isWorldWritable',
                'hasWritablePermissions',
                'platformMetadataPlatform',
                'platformMetadataIssues',
                'platformAttributeIssues',
                'hasPlatformAttributeProvenance',
            ] as $platformAttributeKey) {
                if (array_key_exists($platformAttributeKey, $entry)) {
                    $partInventory[$partName][$platformAttributeKey] = $entry[$platformAttributeKey];
                }
            }
            $partInventory[$partName]['zipPlatformAttributeReviewPolicy'] = $entry['reviewPolicy'] ?? null;
            $partInventory[$partName]['usesDataDescriptor'] = $entry['usesDataDescriptor'] ?? false;
            $partInventory[$partName]['dataDescriptorHasSignature'] = $entry['dataDescriptorHasSignature'] ?? null;
            $partInventory[$partName]['dataDescriptorOffset'] = $entry['dataDescriptorOffset'] ?? null;
            $partInventory[$partName]['dataDescriptorValueOffset'] = $entry['dataDescriptorValueOffset'] ?? null;
            $partInventory[$partName]['dataDescriptorLength'] = $entry['dataDescriptorLength'] ?? null;
            $partInventory[$partName]['dataDescriptorEnd'] = $entry['dataDescriptorEnd'] ?? null;
            $partInventory[$partName]['dataDescriptorCrc32Hex'] = $entry['dataDescriptorCrc32Hex'] ?? null;
            $partInventory[$partName]['dataDescriptorValuesMatchCentral'] = $entry['dataDescriptorValuesMatchCentral'] ?? null;
            $partInventory[$partName]['hasZeroLocalHeaderPlaceholders'] = $entry['hasZeroLocalHeaderPlaceholders'] ?? null;
            $partInventory[$partName]['dataDescriptorIssueCount'] = $entry['dataDescriptorIssueCount'] ?? 0;
            $partInventory[$partName]['dataDescriptorIssues'] = $entry['dataDescriptorIssues'] ?? [];

            $manifestEntry = $opcManifestEntriesByName[$partName] ?? null;
            if (is_array($manifestEntry)) {
                $manifestIssues = array_values(array_filter(
                    is_array($manifestEntry['issues'] ?? null) ? $manifestEntry['issues'] : [],
                    static fn (mixed $issue): bool => is_string($issue)
                ));
                $partInventory[$partName]['zipOpcManifestPresent'] = true;
                $partInventory[$partName]['zipOpcManifestEntryName'] = $manifestEntry['entryName'];
                $partInventory[$partName]['zipOpcManifestPartName'] = $manifestEntry['partName'] ?? null;
                $partInventory[$partName]['zipOpcManifestRole'] = is_string($manifestEntry['role'] ?? null)
                    ? $manifestEntry['role']
                    : null;
                $partInventory[$partName]['zipOpcManifestHandoffKind'] = is_string($manifestEntry['handoffKind'] ?? null)
                    ? $manifestEntry['handoffKind']
                    : null;
                $partInventory[$partName]['zipOpcManifestValid'] = (bool) ($manifestEntry['valid'] ?? false);
                $partInventory[$partName]['zipOpcManifestIssueCount'] = count($manifestIssues);
                $partInventory[$partName]['zipOpcManifestIssues'] = $manifestIssues;
                $partInventory[$partName]['zipOpcManifestContentTypesItem'] = (bool) ($manifestEntry['contentTypesItem'] ?? false);
                $partInventory[$partName]['zipOpcManifestRelationshipPart'] = (bool) ($manifestEntry['relationshipPart'] ?? false);
                $partInventory[$partName]['zipOpcManifestRelationshipPartCandidate'] = (bool) ($manifestEntry['relationshipPartCandidate'] ?? false);
                $partInventory[$partName]['zipOpcManifestRelationshipSource'] = $manifestEntry['relationshipSource'] ?? null;
                $partInventory[$partName]['zipOpcManifestRelationshipSourceExists'] = $manifestEntry['relationshipSourceExists'] ?? null;
                $partInventory[$partName]['zipOpcManifestCentralDirectoryIndex'] = $manifestEntry['centralDirectoryIndex'] ?? null;
                $partInventory[$partName]['zipOpcManifestLocalHeaderOrder'] = $manifestEntry['localHeaderOrder'] ?? null;
                $partInventory[$partName]['zipOpcManifestMatchesCentralDirectoryOrder'] = $manifestEntry['matchesCentralDirectoryOrder'] ?? null;
                $partInventory[$partName]['zipOpcManifestByteCountsAreExact'] = $manifestEntry['byteCountsAreExact'] ?? true;
                $partInventory[$partName]['zipOpcManifestExactCompressedSize'] =
                    $manifestEntry['exactCompressedSize'] ?? $manifestEntry['compressedSize'] ?? null;
                $partInventory[$partName]['zipOpcManifestExactUncompressedSize'] =
                    $manifestEntry['exactUncompressedSize'] ?? $manifestEntry['uncompressedSize'] ?? null;
            }
        }

        return $partInventory;
    }

    private static function zipCompressionMethodName(int $method): string
    {
        return match ($method) {
            0 => 'stored',
            8 => 'deflated',
            default => 'unsupported',
        };
    }

    /**
     * @param array<string, mixed> $contentTypesPart
     * @param array<string, array<string, mixed>> $relationshipParts
     * @param array<string, array<string, mixed>> $partInventory
     * @return array<string, mixed>
     */
    private function packageProvenanceSummary(array $contentTypesPart, array $relationshipParts, array $partInventory): array
    {
        $roleCounts = [];
        $roleByteLengths = [];
        $contentTypeSourceCounts = [];
        $contentTypeSourceByteLengths = [];
        $contentTypeBaseCounts = [];
        $contentTypeParameterPartCount = 0;
        $contentTypeParameterByteLength = 0;
        $contentTypeParameterNameCounts = [];
        $contentTypeParameterSourceCounts = [];
        $contentTypeParameterValueCounts = [];
        $contentTypeParameters = [];
        $partsWithContentTypeParameters = [];
        $packageByteLength = 0;
        $relationshipPartCount = 0;
        $relationshipPartByteLength = 0;
        $missingContentTypePartByteLength = 0;
        $zipOpcManifestLoadedPartCount = 0;
        $zipOpcManifestLoadedPartIssueCount = 0;
        $zipOpcManifestLoadedRelationshipPartCount = 0;
        $zipOpcManifestLoadedContentTypesItemCount = 0;
        $zipOpcManifestLoadedPartRoleCounts = [];
        $zipOpcManifestLoadedPartHandoffKindCounts = [];
        $zipOpcManifestLoadedPartIssueCodeCounts = [];
        $zipOpcManifestLoadedPartNamesByRole = [];
        $zipOpcManifestLoadedPartNamesWithIssues = [];
        foreach ($partInventory as $part) {
            $bytes = (int) ($part['bytes'] ?? 0);
            $packageByteLength += $bytes;
            $source = (string) ($part['contentTypeSource'] ?? 'missing');
            $contentTypeSourceCounts[$source] = ($contentTypeSourceCounts[$source] ?? 0) + 1;
            $contentTypeSourceByteLengths[$source] = ($contentTypeSourceByteLengths[$source] ?? 0) + $bytes;
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            if ($contentTypeBase !== '') {
                $contentTypeBaseCounts[$contentTypeBase] = ($contentTypeBaseCounts[$contentTypeBase] ?? 0) + 1;
            }
            $parameterMap = is_array($part['contentTypeParameterMap'] ?? null)
                ? $part['contentTypeParameterMap']
                : [];
            if ($parameterMap !== []) {
                ++$contentTypeParameterPartCount;
                $contentTypeParameterByteLength += $bytes;
                $contentTypeParameterSourceCounts[$source] =
                    ($contentTypeParameterSourceCounts[$source] ?? 0) + 1;
                $partsWithContentTypeParameters[] = [
                    'partName' => (string) ($part['partName'] ?? ''),
                    'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                    'contentTypeBase' => $contentTypeBase,
                    'contentTypeParameterCount' => (int) ($part['contentTypeParameterCount'] ?? count($parameterMap)),
                    'contentTypeParameters' => is_array($part['contentTypeParameters'] ?? null)
                        ? $part['contentTypeParameters']
                        : [],
                    'contentTypeParameterMap' => $parameterMap,
                    'contentTypeSource' => $source,
                    'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                    'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                    'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
                    'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                ];
            }
            foreach ($parameterMap as $parameterName => $parameterValue) {
                if (!is_string($parameterName) || $parameterName === '') {
                    continue;
                }

                $parameterValue = is_scalar($parameterValue) ? (string) $parameterValue : '';
                $parameterValueKey = $parameterValue === '' ? '(empty)' : $parameterValue;
                if (!isset($contentTypeParameters[$parameterName])) {
                    $contentTypeParameters[$parameterName] = [
                        'name' => $parameterName,
                        'partCount' => 0,
                        'valueCounts' => [],
                        'contentTypeSourceCounts' => [],
                        'contentTypeBases' => [],
                        'contentTypes' => [],
                        'partNames' => [],
                    ];
                }

                $contentTypeParameterNameCounts[$parameterName] =
                    ($contentTypeParameterNameCounts[$parameterName] ?? 0) + 1;
                $contentTypeParameterValueCounts[$parameterName][$parameterValueKey] =
                    ($contentTypeParameterValueCounts[$parameterName][$parameterValueKey] ?? 0) + 1;
                ++$contentTypeParameters[$parameterName]['partCount'];
                $contentTypeParameters[$parameterName]['valueCounts'][$parameterValueKey] =
                    ($contentTypeParameters[$parameterName]['valueCounts'][$parameterValueKey] ?? 0) + 1;
                $contentTypeParameters[$parameterName]['contentTypeSourceCounts'][$source] =
                    ($contentTypeParameters[$parameterName]['contentTypeSourceCounts'][$source] ?? 0) + 1;
                $this->appendUniqueString(
                    $contentTypeParameters[$parameterName]['contentTypeBases'],
                    is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : null,
                );
                $this->appendUniqueString(
                    $contentTypeParameters[$parameterName]['contentTypes'],
                    is_string($part['contentType'] ?? null) ? $part['contentType'] : null,
                );
                $this->appendUniqueString(
                    $contentTypeParameters[$parameterName]['partNames'],
                    is_string($part['partName'] ?? null) ? $part['partName'] : null,
                );
            }
            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $roleCounts[$role] = ($roleCounts[$role] ?? 0) + 1;
                $roleByteLengths[$role] = ($roleByteLengths[$role] ?? 0) + $bytes;
            }
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$relationshipPartCount;
                $relationshipPartByteLength += $bytes;
            }
            if ($source === 'missing') {
                $missingContentTypePartByteLength += $bytes;
            }
            if (($part['zipOpcManifestPresent'] ?? false) === true) {
                ++$zipOpcManifestLoadedPartCount;
                $partName = (string) ($part['partName'] ?? '');
                $manifestRole = is_string($part['zipOpcManifestRole'] ?? null)
                    ? $part['zipOpcManifestRole']
                    : 'unknown';
                $manifestHandoffKind = is_string($part['zipOpcManifestHandoffKind'] ?? null)
                    ? $part['zipOpcManifestHandoffKind']
                    : 'unknown';
                $zipOpcManifestLoadedPartRoleCounts[$manifestRole] =
                    ($zipOpcManifestLoadedPartRoleCounts[$manifestRole] ?? 0) + 1;
                $zipOpcManifestLoadedPartHandoffKindCounts[$manifestHandoffKind] =
                    ($zipOpcManifestLoadedPartHandoffKindCounts[$manifestHandoffKind] ?? 0) + 1;
                $zipOpcManifestLoadedPartNamesByRole[$manifestRole] ??= [];
                $this->appendUniqueString($zipOpcManifestLoadedPartNamesByRole[$manifestRole], $partName);

                if (($part['zipOpcManifestRelationshipPart'] ?? false) === true) {
                    ++$zipOpcManifestLoadedRelationshipPartCount;
                }
                if (($part['zipOpcManifestContentTypesItem'] ?? false) === true) {
                    ++$zipOpcManifestLoadedContentTypesItemCount;
                }

                $manifestIssues = is_array($part['zipOpcManifestIssues'] ?? null)
                    ? $part['zipOpcManifestIssues']
                    : [];
                if ($manifestIssues !== []) {
                    ++$zipOpcManifestLoadedPartIssueCount;
                    $this->appendUniqueString($zipOpcManifestLoadedPartNamesWithIssues, $partName);
                    foreach ($manifestIssues as $manifestIssue) {
                        if (!is_string($manifestIssue) || $manifestIssue === '') {
                            continue;
                        }
                        $zipOpcManifestLoadedPartIssueCodeCounts[$manifestIssue] =
                            ($zipOpcManifestLoadedPartIssueCodeCounts[$manifestIssue] ?? 0) + 1;
                    }
                }
            }
        }

        ksort($roleCounts);
        ksort($roleByteLengths);
        ksort($contentTypeSourceCounts);
        ksort($contentTypeSourceByteLengths);
        ksort($contentTypeBaseCounts);
        ksort($contentTypeParameterNameCounts);
        ksort($contentTypeParameterSourceCounts);
        ksort($contentTypeParameterValueCounts);
        foreach ($contentTypeParameterValueCounts as &$parameterValueCounts) {
            ksort($parameterValueCounts);
        }
        unset($parameterValueCounts);
        ksort($contentTypeParameters);
        foreach ($contentTypeParameters as &$contentTypeParameter) {
            ksort($contentTypeParameter['contentTypeSourceCounts']);
            ksort($contentTypeParameter['valueCounts']);
        }
        unset($contentTypeParameter);
        ksort($zipOpcManifestLoadedPartRoleCounts);
        ksort($zipOpcManifestLoadedPartHandoffKindCounts);
        ksort($zipOpcManifestLoadedPartIssueCodeCounts);
        ksort($zipOpcManifestLoadedPartNamesByRole);
        foreach ($zipOpcManifestLoadedPartNamesByRole as &$manifestPartNames) {
            sort($manifestPartNames, SORT_STRING);
        }
        unset($manifestPartNames);
        sort($zipOpcManifestLoadedPartNamesWithIssues, SORT_STRING);

        $partDirectories = $this->packagePartDirectorySummary($partInventory);
        $partDirectoryBaseNames = $this->packagePartDirectoryBaseNameSummary($partInventory);
        $partDirectoryBaseNameCounts = [];
        foreach ($partDirectoryBaseNames as $directoryBaseNameSummary) {
            $directoryBaseName = (string) ($directoryBaseNameSummary['directoryBaseName'] ?? '');
            $partDirectoryBaseNameCounts[$directoryBaseName] = (int) ($directoryBaseNameSummary['partCount'] ?? 0);
        }
        ksort($partDirectoryBaseNameCounts, SORT_STRING);
        $duplicatePartDirectoryBaseNames = [];
        foreach ($partDirectoryBaseNames as $directoryBaseNameSummary) {
            if ((int) ($directoryBaseNameSummary['directoryCount'] ?? 0) > 1) {
                $duplicatePartDirectoryBaseNames[] = (string) ($directoryBaseNameSummary['directoryBaseName'] ?? '');
            }
        }
        $partDirectoryDepths = $this->packagePartDirectoryDepthSummary($partInventory);
        $partDirectoryDepthCounts = [];
        $parameterizedPartDirectoryDepthCount = 0;
        $parameterizedPartDirectoryDepthBucketCount = 0;
        $missingContentTypePartDirectoryDepthCount = 0;
        foreach ($partDirectoryDepths as $directoryDepthSummary) {
            $directoryDepth = (int) ($directoryDepthSummary['directoryDepth'] ?? 0);
            $partDirectoryDepthCounts[(string) $directoryDepth] = (int) ($directoryDepthSummary['partCount'] ?? 0);
            $parameterizedPartCount = (int) ($directoryDepthSummary['parameterizedPartCount'] ?? 0);
            if ($parameterizedPartCount > 0) {
                $parameterizedPartDirectoryDepthBucketCount++;
                $parameterizedPartDirectoryDepthCount += $parameterizedPartCount;
            }
            if ((int) ($directoryDepthSummary['missingContentTypePartCount'] ?? 0) > 0) {
                $missingContentTypePartDirectoryDepthCount++;
            }
        }
        ksort($partDirectoryDepthCounts, SORT_NUMERIC);
        $partTopLevelSegments = $this->packagePartTopLevelSegmentSummary($partInventory);
        $partPathSegments = $this->packagePartPathSegmentSummary($partInventory);
        $partPathSegmentOccurrenceCount = 0;
        foreach ($partPathSegments as $partPathSegment) {
            $partPathSegmentOccurrenceCount += (int) ($partPathSegment['occurrenceCount'] ?? 0);
        }
        $partPathDepths = $this->packagePartPathDepthSummary($partInventory);
        $parameterizedPartPathDepthCount = 0;
        $parameterizedPartPathDepthBucketCount = 0;
        $missingContentTypePartPathDepthCount = 0;
        foreach ($partPathDepths as $pathDepthSummary) {
            $parameterizedPartCount = (int) ($pathDepthSummary['parameterizedPartCount'] ?? 0);
            if ($parameterizedPartCount > 0) {
                $parameterizedPartPathDepthBucketCount++;
                $parameterizedPartPathDepthCount += $parameterizedPartCount;
            }
            if ((int) ($pathDepthSummary['missingContentTypePartCount'] ?? 0) > 0) {
                $missingContentTypePartPathDepthCount++;
            }
        }
        $partExtensions = $this->packagePartExtensionSummary($partInventory);
        $contentTypeExtensionMismatches = $this->packagePartContentTypeExtensionMismatchSummary($partInventory);
        $partExtensionCaseVariants = $this->packagePartExtensionCaseVariantSummary($partInventory);
        $parameterizedPartExtensionCount = 0;
        $parameterizedPartExtensionBucketCount = 0;
        $missingContentTypePartExtensionCount = 0;
        $declaredDefaultPartExtensionCount = 0;
        foreach ($partExtensions as $extensionSummary) {
            $parameterizedPartCount = (int) ($extensionSummary['parameterizedPartCount'] ?? 0);
            if ($parameterizedPartCount > 0) {
                $parameterizedPartExtensionBucketCount++;
                $parameterizedPartExtensionCount += $parameterizedPartCount;
            }
            if ((int) ($extensionSummary['missingContentTypePartCount'] ?? 0) > 0) {
                $missingContentTypePartExtensionCount++;
            }
            if (($extensionSummary['defaultDeclared'] ?? false) === true) {
                $declaredDefaultPartExtensionCount++;
            }
        }
        $partBaseNames = $this->packagePartBaseNameSummary($partInventory);
        $partBaseNameStems = $this->packagePartBaseNameStemSummary($partInventory);
        $partCaseFoldBaseNames = $this->packagePartCaseFoldBaseNameSummary($partInventory);
        $partNameCharacters = $this->packagePartNameCharacterSummary($partInventory);
        $partPathSegmentCharacters = $this->packagePartPathSegmentCharacterSummary($partInventory);
        $partXmlRoots = $this->packagePartXmlRootSummary($partInventory);
        $partXmlElementAncestry = $this->packagePartXmlElementAncestrySummary($partInventory);
        $partXmlNamespaceShadows = $this->packagePartXmlNamespaceShadowSummary($partInventory);
        $partXmlAttributeCooccurrences = $this->packagePartXmlElementAttributeCooccurrenceSummary($partInventory);
        $partXmlRelationshipReferences = $this->packagePartXmlRelationshipReferenceSummary($partInventory);
        $relationshipIdTopology = $this->relationshipIdTopologySummary($relationshipParts);
        $partContentTypeSyntaxSuffixes = $this->packagePartContentTypeSyntaxSuffixSummary($partInventory);
        $partContentTypeSyntaxSuffixCounts = [];
        $partContentTypeStructuredSyntaxPartCount = 0;
        foreach ($partContentTypeSyntaxSuffixes as $syntaxSuffixSummary) {
            $syntaxSuffixKey = (string) ($syntaxSuffixSummary['contentTypeSyntaxSuffixKey'] ?? '');
            $partContentTypeSyntaxSuffixCounts[$syntaxSuffixKey] = (int) ($syntaxSuffixSummary['partCount'] ?? 0);
            $partContentTypeStructuredSyntaxPartCount += (int) ($syntaxSuffixSummary['structuredSyntaxPartCount'] ?? 0);
        }
        ksort($partContentTypeSyntaxSuffixCounts, SORT_STRING);
        $partContentTypeSources = $this->packagePartContentTypeSourceSummary($partInventory);
        $partContentTypeSourceCounts = [];
        foreach ($partContentTypeSources as $sourceSummary) {
            $sourceKey = (string) ($sourceSummary['contentTypeSource'] ?? 'missing');
            $partContentTypeSourceCounts[$sourceKey] = (int) ($sourceSummary['partCount'] ?? 0);
        }
        ksort($partContentTypeSourceCounts, SORT_STRING);
        $duplicatePartBaseNames = [];
        foreach ($partBaseNames as $baseNameSummary) {
            if ((int) ($baseNameSummary['partCount'] ?? 0) > 1) {
                $duplicatePartBaseNames[] = (string) ($baseNameSummary['baseName'] ?? '');
            }
        }
        $duplicatePartBaseNameStems = [];
        foreach ($partBaseNameStems as $baseNameStemSummary) {
            if ((int) ($baseNameStemSummary['partCount'] ?? 0) > 1) {
                $duplicatePartBaseNameStems[] = (string) ($baseNameStemSummary['baseNameStem'] ?? '');
            }
        }
        $duplicatePartCaseFoldBaseNames = [];
        foreach ($partCaseFoldBaseNames as $caseFoldBaseNameSummary) {
            if ((int) ($caseFoldBaseNameSummary['caseVariantCount'] ?? 0) > 1) {
                $duplicatePartCaseFoldBaseNames[] = (string) ($caseFoldBaseNameSummary['caseFoldBaseName'] ?? '');
            }
        }
        $partContentTypes = $this->packagePartContentTypeSummary($partInventory);
        $partContentTypeParameterNames = $this->packagePartContentTypeParameterNameSummary($partInventory);
        $partContentTypeParameterNameCounts = [];
        foreach ($partContentTypeParameterNames as $parameterNameSummary) {
            $parameterName = (string) ($parameterNameSummary['parameterName'] ?? '');
            $partContentTypeParameterNameCounts[$parameterName] = (int) ($parameterNameSummary['partCount'] ?? 0);
        }
        ksort($partContentTypeParameterNameCounts, SORT_STRING);
        $partContentTypeParameterValues = $this->packagePartContentTypeParameterValueSummary($partInventory);
        $partContentTypeParameterValueCounts = [];
        foreach ($partContentTypeParameterValues as $parameterValueSummary) {
            $parameterValueKey = (string) ($parameterValueSummary['contentTypeParameterValueKey'] ?? '');
            $partContentTypeParameterValueCounts[$parameterValueKey] = (int) ($parameterValueSummary['partCount'] ?? 0);
        }
        ksort($partContentTypeParameterValueCounts, SORT_STRING);
        $partContentTypeParameterSources = $this->packagePartContentTypeParameterSourceSummary($partInventory);
        $partContentTypeParameterSourceCounts = [];
        foreach ($partContentTypeParameterSources as $parameterSourceSummary) {
            $sourceKey = (string) ($parameterSourceSummary['contentTypeSource'] ?? 'missing');
            $partContentTypeParameterSourceCounts[$sourceKey] = (int) ($parameterSourceSummary['partCount'] ?? 0);
        }
        ksort($partContentTypeParameterSourceCounts, SORT_STRING);
        $partContentTypeMediaTypes = $this->packagePartContentTypeMediaTypeSummary($partInventory);
        $partContentTypeMediaTypeCounts = [];
        foreach ($partContentTypeMediaTypes as $mediaTypeSummary) {
            $mediaTypeKey = (string) ($mediaTypeSummary['contentTypeMediaTypeKey'] ?? '');
            $partContentTypeMediaTypeCounts[$mediaTypeKey] = (int) ($mediaTypeSummary['partCount'] ?? 0);
        }
        ksort($partContentTypeMediaTypeCounts, SORT_STRING);
        $partContentTypeSubtypes = $this->packagePartContentTypeSubtypeSummary($partInventory);
        $partContentTypeSubtypeCounts = [];
        foreach ($partContentTypeSubtypes as $subtypeSummary) {
            $subtypeKey = (string) ($subtypeSummary['contentTypeSubtypeKey'] ?? '');
            $partContentTypeSubtypeCounts[$subtypeKey] = (int) ($subtypeSummary['partCount'] ?? 0);
        }
        ksort($partContentTypeSubtypeCounts, SORT_STRING);
        $partContentTypeTrees = $this->packagePartContentTypeTreeSummary($partInventory);
        $partContentTypeTreeCounts = [];
        foreach ($partContentTypeTrees as $treeSummary) {
            $treeKey = (string) ($treeSummary['contentTypeTreeKey'] ?? '');
            $partContentTypeTreeCounts[$treeKey] = (int) ($treeSummary['partCount'] ?? 0);
        }
        ksort($partContentTypeTreeCounts, SORT_STRING);
        $partRoles = $this->packagePartRoleSummary($partInventory);
        $largestParts = $this->largestPackagePartSummary($partInventory);
        $largestPart = $largestParts[0] ?? null;
        $duplicatePartDigests = $this->duplicatePackagePartDigestSummary($partInventory);
        $duplicatePartDigestPartCount = 0;
        $duplicatePartDigestByteLength = 0;
        $duplicatePartDigestPartNames = [];
        $duplicatePartDigestSha256Values = [];
        foreach ($duplicatePartDigests as $digestSummary) {
            $duplicatePartDigestPartCount += (int) ($digestSummary['partCount'] ?? 0);
            $duplicatePartDigestByteLength += (int) ($digestSummary['byteLength'] ?? 0);
            $this->appendUniqueString(
                $duplicatePartDigestSha256Values,
                is_string($digestSummary['sha256'] ?? null) ? $digestSummary['sha256'] : null,
            );
            foreach (($digestSummary['partNames'] ?? []) as $partName) {
                $this->appendUniqueString($duplicatePartDigestPartNames, is_string($partName) ? $partName : null);
            }
        }
        sort($duplicatePartDigestPartNames, SORT_STRING);
        $partZipCompressionMethods = $this->packagePartZipCompressionSummary($partInventory);
        $partZipCompressionMethodCounts = [];
        $partZipCompressedByteLength = 0;
        $partZipUncompressedByteLength = 0;
        $partZipDataDescriptorPartCount = 0;
        $partZipUnsupportedCompressionPartCount = 0;
        foreach ($partZipCompressionMethods as $compressionSummary) {
            $compressionMethodKey = (string) ($compressionSummary['compressionMethodKey'] ?? '');
            $partZipCompressionMethodCounts[$compressionMethodKey] = (int) ($compressionSummary['partCount'] ?? 0);
            $partZipCompressedByteLength += (int) ($compressionSummary['compressedByteLength'] ?? 0);
            $partZipUncompressedByteLength += (int) ($compressionSummary['uncompressedByteLength'] ?? 0);
            $partZipDataDescriptorPartCount += (int) ($compressionSummary['dataDescriptorPartCount'] ?? 0);
            $partZipUnsupportedCompressionPartCount += (int) ($compressionSummary['unsupportedPartCount'] ?? 0);
        }
        ksort($partZipCompressionMethodCounts, SORT_STRING);
        $partByteLengthBuckets = $this->packagePartByteLengthBucketSummary($partInventory);
        $partByteLengthBucketCounts = [];
        $partByteLengthBucketByteLengths = [];
        $partByteLengthBucketRelationshipPartCounts = [];
        $partByteLengthBucketMissingContentTypeCounts = [];
        foreach ($partByteLengthBuckets as $bucketSummary) {
            $bucket = (string) ($bucketSummary['byteLengthBucket'] ?? '');
            if ($bucket === '') {
                continue;
            }

            $partByteLengthBucketCounts[$bucket] = (int) ($bucketSummary['partCount'] ?? 0);
            $partByteLengthBucketByteLengths[$bucket] = (int) ($bucketSummary['byteLength'] ?? 0);
            $partByteLengthBucketRelationshipPartCounts[$bucket] =
                (int) ($bucketSummary['relationshipPartCount'] ?? 0);
            $partByteLengthBucketMissingContentTypeCounts[$bucket] =
                (int) ($bucketSummary['missingContentTypePartCount'] ?? 0);
        }
        $zeroByteParts = $this->zeroBytePackagePartSummary($partInventory);
        $zeroByteRelationshipPartCount = 0;
        $zeroByteMissingContentTypePartCount = 0;
        $zeroByteContentTypeSourceCounts = [];
        $zeroByteRoleCounts = [];
        foreach ($zeroByteParts as $zeroBytePart) {
            if (($zeroBytePart['isRelationshipPart'] ?? false) === true) {
                ++$zeroByteRelationshipPartCount;
            }
            $contentTypeSource = is_string($zeroBytePart['contentTypeSource'] ?? null)
                ? $zeroBytePart['contentTypeSource']
                : 'missing';
            $zeroByteContentTypeSourceCounts[$contentTypeSource] =
                ($zeroByteContentTypeSourceCounts[$contentTypeSource] ?? 0) + 1;
            if ($contentTypeSource === 'missing') {
                ++$zeroByteMissingContentTypePartCount;
            }
            foreach (($zeroBytePart['roles'] ?? []) as $role) {
                $role = (string) $role;
                $zeroByteRoleCounts[$role] = ($zeroByteRoleCounts[$role] ?? 0) + 1;
            }
        }
        ksort($zeroByteContentTypeSourceCounts);
        ksort($zeroByteRoleCounts);
        $maxPartPathSegmentCount = 0;
        $deepestParts = [];
        foreach ($partInventory as $partName => $part) {
            $pathSegmentCount = is_int($part['pathSegmentCount'] ?? null)
                ? $part['pathSegmentCount']
                : count($this->packagePartPathSegments((string) $partName));
            if ($pathSegmentCount < $maxPartPathSegmentCount) {
                continue;
            }

            $item = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null)
                    ? $part['directory']
                    : $this->packagePartDirectory((string) $partName),
                'directoryDepth' => is_int($part['directoryDepth'] ?? null)
                    ? $part['directoryDepth']
                    : $this->packagePartDirectoryDepth($this->packagePartDirectory((string) $partName)),
                'baseName' => is_string($part['baseName'] ?? null)
                    ? $part['baseName']
                    : $this->packagePartBaseName((string) $partName),
                'pathSegmentCount' => $pathSegmentCount,
                'bytes' => (int) ($part['bytes'] ?? 0),
                'contentTypeSource' => is_string($part['contentTypeSource'] ?? null)
                    ? $part['contentTypeSource']
                    : 'missing',
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            if ($pathSegmentCount > $maxPartPathSegmentCount) {
                $maxPartPathSegmentCount = $pathSegmentCount;
                $deepestParts = [];
            }
            $deepestParts[] = $item;
        }
        usort(
            $deepestParts,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
        );
        $relationshipCount = 0;
        $internalRelationshipCount = 0;
        $externalRelationshipCount = 0;
