    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function largestPackagePartSummary(array $partInventory, int $limit = 5): array
    {
        $items = [];
        foreach ($partInventory as $partName => $part) {
            $items[] = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory((string) $partName),
                'baseName' => is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName((string) $partName),
                'partExtension' => is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null,
                'bytes' => (int) ($part['bytes'] ?? 0),
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '',
                'contentTypeSource' => is_string($part['contentTypeSource'] ?? null) ? $part['contentTypeSource'] : 'missing',
                'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
        }

        usort(
            $items,
            static fn (array $left, array $right): int => ($right['bytes'] <=> $left['bytes'])
                ?: strcmp((string) $left['partName'], (string) $right['partName']),
        );

        return array_slice($items, 0, max(0, $limit));
    }

    private function packagePartByteLengthBucket(int $bytes): string
    {
        if ($bytes <= 0) {
            return 'empty';
        }
        if ($bytes <= 64) {
            return 'small';
        }
        if ($bytes <= 1024) {
            return 'medium';
        }
        if ($bytes <= 65536) {
            return 'large';
        }

        return 'huge';
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartByteLengthBucketSummary(array $partInventory): array
    {
        $buckets = [];
        foreach ($partInventory as $partName => $part) {
            $partName = (string) ($part['partName'] ?? $partName);
            $bytes = (int) ($part['bytes'] ?? 0);
            $bucket = is_string($part['byteLengthBucket'] ?? null)
                ? $part['byteLengthBucket']
                : $this->packagePartByteLengthBucket($bytes);
            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }

            if (!isset($buckets[$bucket])) {
                $buckets[$bucket] = [
                    'byteLengthBucket' => $bucket,
                    'partCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'contentTypeSourceCounts' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$buckets[$bucket]['partCount'];
            $buckets[$bucket]['byteLength'] += $bytes;
            $buckets[$bucket]['partNames'][] = $partName;
            $buckets[$bucket]['contentTypeSourceCounts'][$contentTypeSource] =
                ($buckets[$bucket]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;
            if ($contentTypeSource === 'missing') {
                ++$buckets[$bucket]['missingContentTypePartCount'];
            }
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$buckets[$bucket]['relationshipPartCount'];
            }
            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                if ($role === '') {
                    continue;
                }

                $buckets[$bucket]['roleCounts'][$role] =
                    ($buckets[$bucket]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => $partName,
                'directory' => is_string($part['directory'] ?? null)
                    ? $part['directory']
                    : $this->packagePartDirectory($partName),
                'baseName' => is_string($part['baseName'] ?? null)
                    ? $part['baseName']
                    : $this->packagePartBaseName($partName),
                'partExtension' => is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null,
                'bytes' => $bytes,
                'byteLengthBucket' => $bucket,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '',
                'contentTypeSource' => $contentTypeSource,
                'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $buckets[$bucket]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $buckets[$bucket]['largestPart'] = $partSummary;
            }
        }

        $order = [
            'empty' => 0,
            'small' => 1,
            'medium' => 2,
            'large' => 3,
            'huge' => 4,
        ];
        uksort(
            $buckets,
            static fn (string $left, string $right): int => ($order[$left] ?? 99) <=> ($order[$right] ?? 99)
                ?: strcmp($left, $right),
        );
        foreach ($buckets as $bucket => $summary) {
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $buckets[$bucket] = $summary;
        }

        return array_values($buckets);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function duplicatePackagePartDigestSummary(array $partInventory): array
    {
        $digests = [];
        foreach ($partInventory as $partName => $part) {
            $sha256 = is_string($part['sha256'] ?? null) ? $part['sha256'] : '';
            if ($sha256 === '') {
                continue;
            }

            if (!isset($digests[$sha256])) {
                $digests[$sha256] = [
                    'sha256' => $sha256,
                    'crc32Values' => [],
                    'partCount' => 0,
                    'byteLength' => 0,
                    'directories' => [],
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            $partName = (string) ($part['partName'] ?? $partName);
            $bytes = (int) ($part['bytes'] ?? 0);
            $directory = is_string($part['directory'] ?? null)
                ? $part['directory']
                : $this->packagePartDirectory($partName);
            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;

            ++$digests[$sha256]['partCount'];
            $digests[$sha256]['byteLength'] += $bytes;
            $digests[$sha256]['partNames'][] = $partName;
            $digests[$sha256]['contentTypeSourceCounts'][$contentTypeSource] =
                ($digests[$sha256]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;
            $digests[$sha256]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($digests[$sha256]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;
            $this->appendUniqueString($digests[$sha256]['directories'], $directory);
            $this->appendUniqueString(
                $digests[$sha256]['crc32Values'],
                is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
            );

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $digests[$sha256]['roleCounts'][$role] =
                    ($digests[$sha256]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => $partName,
                'directory' => $directory,
                'baseName' => is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName($partName),
                'partExtension' => is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null,
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => $sha256,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $digests[$sha256]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $digests[$sha256]['largestPart'] = $partSummary;
            }
        }

        ksort($digests, SORT_STRING);
        $duplicates = [];
        foreach ($digests as $summary) {
            if ((int) ($summary['partCount'] ?? 0) < 2) {
                continue;
            }

            sort($summary['crc32Values'], SORT_STRING);
            sort($summary['directories'], SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $duplicates[] = $summary;
        }

        return $duplicates;
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartZipCompressionSummary(array $partInventory): array
    {
        $methods = [];
        foreach ($partInventory as $partName => $part) {
            if (($part['zipEntryPresent'] ?? false) !== true) {
                continue;
            }

            $compressionMethod = is_int($part['compressionMethod'] ?? null)
                ? (int) $part['compressionMethod']
                : null;
            $compressionMethodKey = $compressionMethod === null ? '(missing)' : (string) $compressionMethod;
            $compressionMethodName = is_string($part['compressionMethodName'] ?? null)
                ? $part['compressionMethodName']
                : ($compressionMethod === null ? 'missing' : self::zipCompressionMethodName($compressionMethod));
            if (!isset($methods[$compressionMethodKey])) {
                $methods[$compressionMethodKey] = [
                    'compressionMethodKey' => $compressionMethodKey,
                    'compressionMethod' => $compressionMethod,
                    'compressionMethodName' => $compressionMethodName,
                    'partCount' => 0,
                    'compressedByteLength' => 0,
                    'uncompressedByteLength' => 0,
                    'supportedPartCount' => 0,
                    'unsupportedPartCount' => 0,
                    'dataDescriptorPartCount' => 0,
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestCompressedPart' => null,
                ];
            }

            $partName = (string) ($part['partName'] ?? $partName);
            $compressedBytes = is_int($part['compressedByteLength'] ?? null)
                ? (int) $part['compressedByteLength']
                : 0;
            $bytes = (int) ($part['bytes'] ?? 0);
            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null)
                ? $part['contentTypeBase']
                : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;

            ++$methods[$compressionMethodKey]['partCount'];
            $methods[$compressionMethodKey]['compressedByteLength'] += $compressedBytes;
            $methods[$compressionMethodKey]['uncompressedByteLength'] += $bytes;
            $methods[$compressionMethodKey]['partNames'][] = $partName;
            $methods[$compressionMethodKey]['contentTypeSourceCounts'][$contentTypeSource] =
                ($methods[$compressionMethodKey]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;
            $methods[$compressionMethodKey]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($methods[$compressionMethodKey]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            if (($part['compressionSupported'] ?? null) === false) {
                ++$methods[$compressionMethodKey]['unsupportedPartCount'];
            } else {
                ++$methods[$compressionMethodKey]['supportedPartCount'];
            }
            if (($part['usesDataDescriptor'] ?? false) === true) {
                ++$methods[$compressionMethodKey]['dataDescriptorPartCount'];
            }

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                if ($role === '') {
                    continue;
                }
                $methods[$compressionMethodKey]['roleCounts'][$role] =
                    ($methods[$compressionMethodKey]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => $partName,
                'directory' => is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory($partName),
                'baseName' => is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName($partName),
                'bytes' => $bytes,
                'compressedByteLength' => $compressedBytes,
                'compressionMethod' => $compressionMethod,
                'compressionMethodName' => $compressionMethodName,
                'compressionSupported' => ($part['compressionSupported'] ?? null) === false ? false : true,
                'usesDataDescriptor' => (bool) ($part['usesDataDescriptor'] ?? false),
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'zipCrc32' => is_string($part['zipCrc32'] ?? null) ? $part['zipCrc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $methods[$compressionMethodKey]['largestCompressedPart'];
            if (
                !is_array($largestPart)
                || $partSummary['compressedByteLength'] > (int) ($largestPart['compressedByteLength'] ?? 0)
                || (
                    $partSummary['compressedByteLength'] === (int) ($largestPart['compressedByteLength'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $methods[$compressionMethodKey]['largestCompressedPart'] = $partSummary;
            }
        }

        ksort($methods, SORT_STRING);
        foreach ($methods as $methodKey => $summary) {
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $methods[$methodKey] = $summary;
        }

        return array_values($methods);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function zeroBytePackagePartSummary(array $partInventory): array
    {
        $items = [];
        foreach ($partInventory as $partName => $part) {
            if ((int) ($part['bytes'] ?? 0) !== 0) {
                continue;
            }

            $items[] = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory((string) $partName),
                'baseName' => is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName((string) $partName),
                'partExtension' => is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null,
                'bytes' => 0,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '',
                'contentTypeHasParameters' => (bool) ($part['contentTypeHasParameters'] ?? false),
                'contentTypeParameterCount' => (int) ($part['contentTypeParameterCount'] ?? 0),
                'contentTypeSource' => is_string($part['contentTypeSource'] ?? null) ? $part['contentTypeSource'] : 'missing',
                'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
        }

        usort(
            $items,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
        );

        return $items;
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartContentTypeSummary(array $partInventory): array
    {
        $contentTypes = [];
        foreach ($partInventory as $partName => $part) {
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            if (!isset($contentTypes[$contentTypeKey])) {
                $contentTypes[$contentTypeKey] = [
                    'contentTypeKey' => $contentTypeKey,
                    'contentTypeBase' => $contentTypeBase,
                    'contentTypes' => [],
                    'partCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'parameterizedPartCount' => 0,
                    'contentTypeSourceCounts' => [],
                    'defaultExtensions' => [],
                    'overridePartNames' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$contentTypes[$contentTypeKey]['partCount'];
            $bytes = (int) ($part['bytes'] ?? 0);
            $contentTypes[$contentTypeKey]['byteLength'] += $bytes;
            $contentTypes[$contentTypeKey]['partNames'][] = (string) $partName;
            $this->appendUniqueString(
                $contentTypes[$contentTypeKey]['contentTypes'],
                is_string($part['contentType'] ?? null) ? $part['contentType'] : null,
            );
            $this->appendUniqueString(
                $contentTypes[$contentTypeKey]['defaultExtensions'],
                is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
            );
            $this->appendUniqueString(
                $contentTypes[$contentTypeKey]['overridePartNames'],
                is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
            );

            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$contentTypes[$contentTypeKey]['relationshipPartCount'];
            }
            if (($part['contentTypeSource'] ?? '') === 'missing') {
                ++$contentTypes[$contentTypeKey]['missingContentTypePartCount'];
            }
            if (($part['contentTypeHasParameters'] ?? false) === true) {
                ++$contentTypes[$contentTypeKey]['parameterizedPartCount'];
            }

            $contentTypeSource = (string) ($part['contentTypeSource'] ?? 'missing');
            $contentTypes[$contentTypeKey]['contentTypeSourceCounts'][$contentTypeSource] =
                ($contentTypes[$contentTypeKey]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $contentTypes[$contentTypeKey]['roleCounts'][$role] =
                    ($contentTypes[$contentTypeKey]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $contentTypes[$contentTypeKey]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $contentTypes[$contentTypeKey]['largestPart'] = $partSummary;
            }
        }

        ksort($contentTypes, SORT_STRING);
        foreach ($contentTypes as $key => $summary) {
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $contentTypes[$key] = $summary;
        }

        return array_values($contentTypes);
    }

