    /**
     * @param array<string, string> $parts
     * @param array<string, array<string, mixed>> $partInventory
     * @param array<string, array<string, mixed>> $relationshipParts
     * @return array<string, mixed>
     */
    private function packageXmlRelationshipReferenceProvenance(
        array $parts,
        array $partInventory,
        array $relationshipParts,
    ): array {
        $items = [];
        $partNames = [];
        $relationshipPartNames = [];
        $relationshipIds = [];
        $unresolvedRelationshipIds = [];
        $targetParts = [];
        $attributeNameCounts = [];
        $attributeLocalNameCounts = [];
        $elementPathCounts = [];
        $elementNameCounts = [];
        $relationshipTypeCounts = [];
        $issueCodeCounts = [];
        $resolvedCount = 0;
        $unresolvedCount = 0;
        $missingRelationshipPartCount = 0;
        $internalCount = 0;
        $externalCount = 0;
        $existingTargetCount = 0;
        $missingTargetCount = 0;

        foreach ($partInventory as $partName => $part) {
            if (($part['xmlInspectable'] ?? false) !== true || ($part['validXml'] ?? false) !== true) {
                continue;
            }

            $partName = (string) ($part['partName'] ?? $partName);
            $xml = $parts[$partName] ?? null;
            if (!is_string($xml) || $xml === '') {
                continue;
            }

            $dom = $this->loadXmlForProvenance($xml, $partName);
            if (!$dom instanceof \DOMDocument || !$dom->documentElement instanceof \DOMElement) {
                continue;
            }

            $relationshipsPart = $this->relationshipsPartFor($partName);
            $relationshipPart = $relationshipParts[$relationshipsPart] ?? null;
            $relationshipPartExists = is_array($relationshipPart) && ($relationshipPart['exists'] ?? false) === true;
            $relationships = is_array($relationshipPart) && is_array($relationshipPart['relationships'] ?? null)
                ? $relationshipPart['relationships']
                : [];

            $walk = function (\DOMElement $element) use (
                &$walk,
                &$items,
                &$partNames,
                &$relationshipPartNames,
                &$relationshipIds,
                &$unresolvedRelationshipIds,
                &$targetParts,
                &$attributeNameCounts,
                &$attributeLocalNameCounts,
                &$elementPathCounts,
                &$elementNameCounts,
                &$relationshipTypeCounts,
                &$issueCodeCounts,
                &$resolvedCount,
                &$unresolvedCount,
                &$missingRelationshipPartCount,
                &$internalCount,
                &$externalCount,
                &$existingTargetCount,
                &$missingTargetCount,
                $partName,
                $relationshipsPart,
                $relationshipPartExists,
                $relationships,
            ): void {
                foreach ($element->attributes ?? [] as $attribute) {
                    if (
                        !$attribute instanceof \DOMAttr
                        || $attribute->namespaceURI !== self::NS_R
                        || !in_array($attribute->localName, ['id', 'embed', 'link'], true)
                    ) {
                        continue;
                    }

                    $relationshipId = trim($attribute->value);
                    $relationship = $relationshipId === '' ? null : ($relationships[$relationshipId] ?? null);
                    $resolved = is_array($relationship);
                    $external = $resolved ? (bool) ($relationship['external'] ?? false) : null;
                    $exists = $resolved ? (bool) ($relationship['exists'] ?? false) : null;
                    $issues = [];

                    if (!$relationshipPartExists) {
                        $issues[] = 'missing-relationship-part';
                        ++$missingRelationshipPartCount;
                    }
                    if ($relationshipId === '') {
                        $issues[] = 'empty-relationship-id';
                    } elseif (!$resolved) {
                        $issues[] = 'unresolved-relationship-id';
                    }
                    if ($resolved && $external === true) {
                        $issues[] = 'external-relationship-target';
                    }
                    if ($resolved && $external === false && $exists !== true) {
                        $issues[] = 'missing-relationship-target';
                    }

                    if ($resolved) {
                        ++$resolvedCount;
                        if ($external === true) {
                            ++$externalCount;
                        } else {
                            ++$internalCount;
                        }
                        if ($exists === true) {
                            ++$existingTargetCount;
                        } elseif ($external !== true) {
                            ++$missingTargetCount;
                        }
                    } else {
                        ++$unresolvedCount;
                        $this->appendUniqueString($unresolvedRelationshipIds, $relationshipId === '' ? null : $relationshipId);
                    }

                    foreach ($issues as $issue) {
                        $issueCodeCounts[$issue] = ($issueCodeCounts[$issue] ?? 0) + 1;
                    }

                    $attributeName = $this->qualifiedDomAttributeName($attribute);
                    $attributeLocalName = $attribute->localName;
                    $elementPath = $this->xmlProvenanceParentPath($element);
                    $elementQualifiedName = $this->qualifiedDomName($element);
                    $relationshipType = $resolved && is_string($relationship['type'] ?? null)
                        ? $relationship['type']
                        : null;
                    $targetPart = $resolved && is_string($relationship['targetPart'] ?? null)
                        ? $relationship['targetPart']
                        : null;

                    $this->appendUniqueString($partNames, $partName);
                    $this->appendUniqueString($relationshipPartNames, $relationshipsPart);
                    $this->appendUniqueString($relationshipIds, $relationshipId === '' ? null : $relationshipId);
                    $this->appendUniqueString($targetParts, $targetPart);
                    $attributeNameCounts[$attributeName] = ($attributeNameCounts[$attributeName] ?? 0) + 1;
                    $attributeLocalNameCounts[$attributeLocalName] = ($attributeLocalNameCounts[$attributeLocalName] ?? 0) + 1;
                    $elementPathCounts[$elementPath] = ($elementPathCounts[$elementPath] ?? 0) + 1;
                    $elementNameCounts[$elementQualifiedName] = ($elementNameCounts[$elementQualifiedName] ?? 0) + 1;
                    if ($relationshipType !== null && $relationshipType !== '') {
                        $relationshipTypeCounts[$relationshipType] = ($relationshipTypeCounts[$relationshipType] ?? 0) + 1;
                    }

                    $items[] = [
                        'partName' => $partName,
                        'relationshipsPart' => $relationshipsPart,
                        'relationshipPartExists' => $relationshipPartExists,
                        'relationshipId' => $relationshipId,
                        'resolved' => $resolved,
                        'attributeName' => $attributeName,
                        'attributeLocalName' => $attributeLocalName,
                        'attributePrefix' => $this->emptyStringToNull((string) $attribute->prefix),
                        'elementPath' => $elementPath,
                        'elementDepth' => $this->xmlProvenanceParentDepth($elementPath),
                        'elementQualifiedName' => $elementQualifiedName,
                        'elementLocalName' => $element->localName,
                        'elementNamespace' => $element->namespaceURI,
                        'elementPrefix' => $this->emptyStringToNull((string) $element->prefix),
                        'relationshipType' => $relationshipType,
                        'targetMode' => $resolved && is_string($relationship['targetMode'] ?? null) ? $relationship['targetMode'] : null,
                        'external' => $external,
                        'target' => $resolved && is_string($relationship['target'] ?? null) ? $relationship['target'] : null,
                        'resolvedTarget' => $resolved && is_string($relationship['resolvedTarget'] ?? null) ? $relationship['resolvedTarget'] : null,
                        'targetPart' => $targetPart,
                        'targetReferenceSuffix' => $resolved && is_string($relationship['targetReferenceSuffix'] ?? null) ? $relationship['targetReferenceSuffix'] : '',
                        'targetQuery' => $resolved && is_string($relationship['targetQuery'] ?? null) ? $relationship['targetQuery'] : null,
                        'targetFragment' => $resolved && is_string($relationship['targetFragment'] ?? null) ? $relationship['targetFragment'] : null,
                        'targetExists' => $exists,
                        'contentType' => $resolved && is_string($relationship['contentType'] ?? null) ? $relationship['contentType'] : null,
                        'contentTypeBase' => $resolved && is_string($relationship['contentTypeBase'] ?? null) ? $relationship['contentTypeBase'] : null,
                        'contentTypeSource' => $resolved && is_string($relationship['contentTypeSource'] ?? null) ? $relationship['contentTypeSource'] : null,
                        'issues' => $issues,
                    ];
                }

                foreach ($element->childNodes as $child) {
                    if ($child instanceof \DOMElement) {
                        $walk($child);
                    }
                }
            };
            $walk($dom->documentElement);
        }

        ksort($attributeNameCounts, SORT_STRING);
        ksort($attributeLocalNameCounts, SORT_STRING);
        ksort($elementPathCounts, SORT_STRING);
        ksort($elementNameCounts, SORT_STRING);
        ksort($relationshipTypeCounts, SORT_STRING);
        ksort($issueCodeCounts, SORT_STRING);
        sort($partNames, SORT_STRING);
        sort($relationshipPartNames, SORT_STRING);
        sort($relationshipIds, SORT_STRING);
        sort($unresolvedRelationshipIds, SORT_STRING);
        sort($targetParts, SORT_STRING);

        return [
            'count' => count($items),
            'partCount' => count($partNames),
            'resolvedCount' => $resolvedCount,
            'unresolvedCount' => $unresolvedCount,
            'missingRelationshipPartCount' => $missingRelationshipPartCount,
            'internalCount' => $internalCount,
            'externalCount' => $externalCount,
            'existingTargetCount' => $existingTargetCount,
            'missingTargetCount' => $missingTargetCount,
            'partNames' => $partNames,
            'relationshipParts' => $relationshipPartNames,
            'relationshipIds' => $relationshipIds,
            'unresolvedRelationshipIds' => $unresolvedRelationshipIds,
            'targetParts' => $targetParts,
            'attributeNameCounts' => $attributeNameCounts,
            'attributeLocalNameCounts' => $attributeLocalNameCounts,
            'elementPathCounts' => $elementPathCounts,
            'elementNameCounts' => $elementNameCounts,
            'relationshipTypeCounts' => $relationshipTypeCounts,
            'issueCount' => array_sum($issueCodeCounts),
            'issueCodeCounts' => $issueCodeCounts,
            'issueCodes' => array_keys($issueCodeCounts),
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageThumbnailProvenance(array $parts, array $rootRelationships, array $contentTypes): array
    {
        $thumbnailRelationships = [];
        foreach ($rootRelationships as $relationship) {
            if ($relationship['type'] === self::THUMBNAIL_REL) {
                $thumbnailRelationships[] = $relationship;
            }
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $targetParts = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $externalTargetKindCounts = [];
        $externalTargetSchemeCounts = [];
        $externalTargetIssueCodes = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $rootHasMultipleThumbnails = count($thumbnailRelationships) > 1;
        foreach ($thumbnailRelationships as $relationship) {
            $summary = $this->relationshipInventorySummary($parts, $relationship, '/', '_rels/.rels', $contentTypes);
            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            $external = (bool) ($summary['external'] ?? false);
            $exists = (bool) ($summary['exists'] ?? false);
            $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
            $relationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
            $targetHasRelationships = $relationshipsPart !== null && isset($parts[$relationshipsPart]);
            $issues = [];

            if ($rootHasMultipleThumbnails) {
                $issues[] = 'multiple-thumbnail-relationships-for-source';
            }
            if ($external) {
                $issues[] = 'external-thumbnail-target';
                foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issues[] = $issue;
                    }
                }
            } elseif (!$exists) {
                $issues[] = 'missing-in-package';
            }
            if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-content-type';
            }
            if ($contentTypeBase !== '' && !$this->isImageContentType($contentTypeBase)) {
                $issues[] = 'invalid-thumbnail-content-type';
            }
            if ($targetHasRelationships) {
                $issues[] = 'thumbnail-target-has-relationships';
            }

            $issues = array_values(array_unique($issues));
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }

            $item = [
                'source' => '/',
                'id' => $summary['id'],
                'type' => $summary['type'],
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'resolvedTarget' => $summary['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
                'externalTargetKind' => $summary['externalTargetKind'],
                'externalTargetScheme' => $summary['externalTargetScheme'],
                'externalTargetAllowed' => $summary['externalTargetAllowed'],
                'externalTargetIssues' => $summary['externalTargetIssues'],
                'contentType' => $summary['contentType'],
                'contentTypeBase' => $summary['contentTypeBase'],
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'expectedContentTypePrefix' => 'image/',
                'external' => $external,
                'exists' => $exists,
                'relationshipsPart' => '_rels/.rels',
                'targetRelationshipsPart' => $relationshipsPart,
                'targetHasRelationships' => $targetHasRelationships,
                'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
                'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
                'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
                'storedByteLength' => null,
                'storedCrc32' => null,
                'canExposeAsDocumentMedia' => false,
                'reviewPolicy' => 'package-thumbnail-metadata-only',
                'valid' => $issues === [],
                'issues' => $issues,
            ];

            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($targetParts, $targetPart);
            if ($external) {
                $this->appendUniqueString($externalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
                if (($summary['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
                }

                $kind = is_string($summary['externalTargetKind'] ?? null) ? $summary['externalTargetKind'] : '(unknown)';
                $externalTargetKindCounts[$kind] = ($externalTargetKindCounts[$kind] ?? 0) + 1;
                $scheme = is_string($summary['externalTargetScheme'] ?? null) ? $summary['externalTargetScheme'] : '(none)';
                $externalTargetSchemeCounts[$scheme] = ($externalTargetSchemeCounts[$scheme] ?? 0) + 1;

                foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            $this->appendUniqueString($contentTypesSeen, is_string($summary['contentType'] ?? null) ? $summary['contentType'] : null);
        }

        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetKindCounts, SORT_STRING);
        ksort($externalTargetSchemeCounts, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'readableCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true && $item['byteLength'] !== null,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true,
            )),
            'unsafeExternalCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true,
            )),
            'invalidCount' => count(array_filter($items, static fn (array $item): bool => $item['valid'] !== true)),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetKindCounts' => $externalTargetKindCounts,
            'externalTargetSchemeCounts' => $externalTargetSchemeCounts,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    private function isImageContentType(string $contentType): bool
    {
        return str_starts_with(strtolower(trim(explode(';', $contentType, 2)[0])), 'image/');
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageEncryptedPackageProvenance(array $parts, array $rootRelationships, array $contentTypes): array
    {
        $relationships = [];
        foreach ($rootRelationships as $relationship) {
            if ($relationship['type'] === self::ENCRYPTED_PACKAGE_REL) {
                $relationships[] = $relationship;
            }
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $targetParts = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $contentTypesSeen = [];
        $externalTargetIssueCodes = [];
        $issueCodes = [];
        $hasMultipleRelationships = count($relationships) > 1;

        foreach ($relationships as $relationship) {
            $summary = $this->relationshipInventorySummary($parts, $relationship, '/', '_rels/.rels', $contentTypes);
            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            $external = (bool) ($summary['external'] ?? false);
            $exists = (bool) ($summary['exists'] ?? false);
            $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
            $relationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
            $targetHasRelationships = $relationshipsPart !== null && isset($parts[$relationshipsPart]);
            $issues = [];

            if ($hasMultipleRelationships) {
                $issues[] = 'multiple-encrypted-package-relationships';
            }
            if ($external) {
                $issues[] = 'external-encrypted-package-target';
                foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issues[] = $issue;
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            } elseif (!$exists) {
                $issues[] = 'missing-encrypted-package-part';
            }
            if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-encrypted-package-content-type';
            } elseif (!$external && $contentTypeBase !== '' && $contentTypeBase !== self::CT_ENCRYPTED_PACKAGE) {
                $issues[] = 'invalid-encrypted-package-content-type';
            }
            if ($targetHasRelationships) {
                $issues[] = 'encrypted-package-target-has-relationships';
            }

            $issues = array_values(array_unique($issues));
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }

            $item = [
                'source' => '/',
                'id' => $summary['id'],
                'type' => $summary['type'],
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'resolvedTarget' => $summary['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
                'targetParentTraversalCount' => $summary['targetParentTraversalCount'],
                'targetHasParentTraversal' => $summary['targetHasParentTraversal'],
                'targetStartsAtPackageRoot' => $summary['targetStartsAtPackageRoot'],
                'sameSourcePart' => $summary['sameSourcePart'],
                'externalTargetKind' => $summary['externalTargetKind'],
                'externalTargetScheme' => $summary['externalTargetScheme'],
                'externalTargetAllowed' => $summary['externalTargetAllowed'],
                'externalTargetIssues' => $summary['externalTargetIssues'],
                'contentType' => $summary['contentType'],
                'contentTypeBase' => $summary['contentTypeBase'],
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'expectedContentTypeBase' => self::CT_ENCRYPTED_PACKAGE,
                'external' => $external,
                'exists' => $exists,
                'relationshipsPart' => '_rels/.rels',
                'targetRelationshipsPart' => $relationshipsPart,
                'targetHasRelationships' => $targetHasRelationships,
                'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
                'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
                'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
                'canExposeBytes' => false,
                'byteExposurePolicy' => 'encrypted-package-bytes-blocked',
                'reviewPolicy' => 'encrypted-package-metadata-only',
                'valid' => $issues === [],
                'issues' => $issues,
                'relationship' => $summary,
            ];

            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($targetParts, $targetPart);
            if ($external) {
                $this->appendUniqueString($externalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
                if (($summary['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
                }
            }
            $this->appendUniqueString($contentTypesSeen, is_string($summary['contentType'] ?? null) ? $summary['contentType'] : null);
        }

        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'present' => $items !== [],
            'count' => count($items),
            'existingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true,
            )),
            'unsafeExternalCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true,
            )),
            'invalidCount' => count(array_filter($items, static fn (array $item): bool => $item['valid'] !== true)),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'contentTypes' => $contentTypesSeen,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'issueCodes' => array_keys($issueCodes),
            'byteExposurePolicy' => 'encrypted-package-bytes-blocked',
            'reviewPolicy' => 'encrypted-package-metadata-only',
            'canExposeBytes' => false,
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageRootRelationshipResources(array $parts, array $rootRelationships, array $contentTypes): array
    {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $relationshipTypes = [];
        $targetParts = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $targetRelationshipTypes = [];
        $targetRelationshipTargetParts = [];
        $targetRelationshipExternalTargets = [];
        $targetRelationshipContentTypes = [];
        $targetRelationshipExternalIssueCodes = [];
        $issueCodes = [];

        foreach ($rootRelationships as $relationship) {
            if (in_array($relationship['type'], self::STANDARD_PACKAGE_ROOT_RELATIONSHIP_TYPES, true)) {
                continue;
            }

            $summary = $this->relationshipInventorySummary($parts, $relationship, '/', '_rels/.rels', $contentTypes);
            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            $external = (bool) ($summary['external'] ?? false);
            $exists = (bool) ($summary['exists'] ?? false);
            $relationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
            $targetHasRelationships = $relationshipsPart !== null && isset($parts[$relationshipsPart]);
            $targetRelationships = $targetHasRelationships && $relationshipsPart !== null
                ? $this->readRelationshipsPart($parts, $relationshipsPart)
                : [];
            $targetRelationshipIds = [];
            $itemTargetRelationshipTypes = [];
            $itemTargetRelationshipTargetParts = [];
            $itemTargetRelationshipExternalTargets = [];
            $itemTargetRelationshipContentTypes = [];
            $itemTargetRelationshipSummaries = [];
            $itemTargetRelationshipExistingCount = 0;
            $itemTargetRelationshipMissingCount = 0;
            $itemTargetRelationshipExternalCount = 0;
            $itemTargetRelationshipAllowedExternalCount = 0;
            $itemTargetRelationshipUnsafeExternalCount = 0;
            $itemTargetRelationshipMissingContentTypeCount = 0;
            $itemTargetRelationshipExternalIssueCodes = [];
            foreach ($targetRelationships as $targetRelationship) {
                $targetRelationshipSummary = $this->relationshipInventorySummary(
                    $parts,
                    $targetRelationship,
                    (string) $targetPart,
                    (string) $relationshipsPart,
                    $contentTypes,
                );
                $itemTargetRelationshipSummaries[] = $this->relationshipProvenanceSummaryItem($targetRelationshipSummary);
                $this->appendUniqueString($targetRelationshipIds, is_string($targetRelationshipSummary['id'] ?? null) ? $targetRelationshipSummary['id'] : null);
                $this->appendUniqueString($itemTargetRelationshipTypes, is_string($targetRelationshipSummary['type'] ?? null) ? $targetRelationshipSummary['type'] : null);
                if (($targetRelationshipSummary['external'] ?? false) === true) {
                    ++$itemTargetRelationshipExternalCount;
                    $this->appendUniqueString($itemTargetRelationshipExternalTargets, is_string($targetRelationshipSummary['target'] ?? null) ? $targetRelationshipSummary['target'] : null);
                    if (($targetRelationshipSummary['externalTargetAllowed'] ?? null) === true) {
                        ++$itemTargetRelationshipAllowedExternalCount;
                    } else {
                        ++$itemTargetRelationshipUnsafeExternalCount;
                    }
                    foreach (($targetRelationshipSummary['externalTargetIssues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $itemTargetRelationshipExternalIssueCodes[$issue] = true;
                        }
                    }
                } else {
                    if (($targetRelationshipSummary['exists'] ?? false) === true) {
                        ++$itemTargetRelationshipExistingCount;
                    } else {
                        ++$itemTargetRelationshipMissingCount;
                    }
                    if (($targetRelationshipSummary['contentTypeSource'] ?? '') === 'missing') {
                        ++$itemTargetRelationshipMissingContentTypeCount;
                    }
                    $this->appendUniqueString($itemTargetRelationshipTargetParts, is_string($targetRelationshipSummary['targetPart'] ?? null) ? $targetRelationshipSummary['targetPart'] : null);
                }
                $this->appendUniqueString($itemTargetRelationshipContentTypes, is_string($targetRelationshipSummary['contentType'] ?? null) ? $targetRelationshipSummary['contentType'] : null);
            }
            ksort($itemTargetRelationshipExternalIssueCodes, SORT_STRING);
            $externalTargetIssues = is_array($summary['externalTargetIssues'] ?? null)
                ? array_values(array_map('strval', $summary['externalTargetIssues']))
                : [];
            $issues = [];

            if ($external) {
                $issues[] = 'external-package-root-relationship';
                $issues = array_merge($issues, $externalTargetIssues);
            } elseif (!$exists) {
                $issues[] = 'missing-package-root-target';
            }
            if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-package-root-content-type';
            }

            $issues = array_values(array_unique($issues));
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }

            $item = [
                'source' => '/',
                'id' => $summary['id'],
                'type' => $summary['type'],
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'external' => $external,
                'resolvedTarget' => $summary['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
                'targetParentTraversalCount' => $summary['targetParentTraversalCount'],
                'targetHasParentTraversal' => $summary['targetHasParentTraversal'],
                'targetStartsAtPackageRoot' => $summary['targetStartsAtPackageRoot'],
                'sameSourcePart' => $summary['sameSourcePart'],
                'externalTargetKind' => $summary['externalTargetKind'],
                'externalTargetScheme' => $summary['externalTargetScheme'],
                'externalTargetAllowed' => $summary['externalTargetAllowed'],
                'externalTargetIssues' => $externalTargetIssues,
                'exists' => $exists,
                'contentType' => $summary['contentType'],
                'contentTypeBase' => $summary['contentTypeBase'],
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'relationshipsPart' => '_rels/.rels',
                'targetRelationshipsPart' => $relationshipsPart,
                'targetHasRelationships' => $targetHasRelationships,
                'targetRelationshipRecordCount' => count($targetRelationships),
                'targetRelationshipExistingCount' => $itemTargetRelationshipExistingCount,
                'targetRelationshipMissingCount' => $itemTargetRelationshipMissingCount,
                'targetRelationshipExternalCount' => $itemTargetRelationshipExternalCount,
                'targetRelationshipAllowedExternalCount' => $itemTargetRelationshipAllowedExternalCount,
                'targetRelationshipUnsafeExternalCount' => $itemTargetRelationshipUnsafeExternalCount,
                'targetRelationshipMissingContentTypeCount' => $itemTargetRelationshipMissingContentTypeCount,
                'targetRelationshipIds' => $targetRelationshipIds,
                'targetRelationshipTypes' => $itemTargetRelationshipTypes,
                'targetRelationshipTargetParts' => $itemTargetRelationshipTargetParts,
                'targetRelationshipExternalTargets' => $itemTargetRelationshipExternalTargets,
                'targetRelationshipContentTypes' => $itemTargetRelationshipContentTypes,
                'targetRelationshipExternalIssueCodes' => array_keys($itemTargetRelationshipExternalIssueCodes),
                'targetRelationships' => $itemTargetRelationshipSummaries,
                'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
                'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
                'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
                'canExposeBytes' => false,
                'byteExposurePolicy' => 'package-root-relationship-bytes-blocked',
                'reviewPolicy' => 'package-root-relationship-metadata-only',
                'valid' => $issues === [],
                'issues' => $issues,
            ];

            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($relationshipTypes, is_string($item['type'] ?? null) ? $item['type'] : null);
            $this->appendUniqueString($targetParts, $targetPart);
            if ($external) {
                $this->appendUniqueString($externalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($summary['contentType'] ?? null) ? $summary['contentType'] : null);
            foreach ($itemTargetRelationshipTypes as $targetRelationshipType) {
                $this->appendUniqueString($targetRelationshipTypes, is_string($targetRelationshipType) ? $targetRelationshipType : null);
            }
            foreach ($itemTargetRelationshipTargetParts as $targetRelationshipTargetPart) {
                $this->appendUniqueString($targetRelationshipTargetParts, is_string($targetRelationshipTargetPart) ? $targetRelationshipTargetPart : null);
            }
            foreach ($itemTargetRelationshipExternalTargets as $targetRelationshipExternalTarget) {
                $this->appendUniqueString($targetRelationshipExternalTargets, is_string($targetRelationshipExternalTarget) ? $targetRelationshipExternalTarget : null);
            }
            foreach ($itemTargetRelationshipContentTypes as $targetRelationshipContentType) {
                $this->appendUniqueString($targetRelationshipContentTypes, is_string($targetRelationshipContentType) ? $targetRelationshipContentType : null);
            }
            foreach (array_keys($itemTargetRelationshipExternalIssueCodes) as $targetRelationshipIssueCode) {
                $targetRelationshipExternalIssueCodes[$targetRelationshipIssueCode] = true;
            }
        }

        ksort($issueCodes, SORT_STRING);
        ksort($targetRelationshipExternalIssueCodes, SORT_STRING);

        return [
            'present' => $items !== [],
            'count' => count($items),
            'existingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'targetRelationshipCount' => count(array_filter($items, static fn (array $item): bool => $item['targetHasRelationships'] === true)),
            'targetRelationshipRecordCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipRecordCount'] ?? 0), $items)),
            'targetRelationshipExistingCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipExistingCount'] ?? 0), $items)),
            'targetRelationshipMissingCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipMissingCount'] ?? 0), $items)),
            'targetRelationshipExternalCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipExternalCount'] ?? 0), $items)),
            'targetRelationshipAllowedExternalCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipAllowedExternalCount'] ?? 0), $items)),
            'targetRelationshipUnsafeExternalCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipUnsafeExternalCount'] ?? 0), $items)),
            'targetRelationshipMissingContentTypeCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipMissingContentTypeCount'] ?? 0), $items)),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'relationshipTypes' => $relationshipTypes,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'targetRelationshipTypes' => $targetRelationshipTypes,
            'targetRelationshipTargetParts' => $targetRelationshipTargetParts,
            'targetRelationshipExternalTargets' => $targetRelationshipExternalTargets,
            'targetRelationshipContentTypes' => $targetRelationshipContentTypes,
            'targetRelationshipExternalIssueCodes' => array_keys($targetRelationshipExternalIssueCodes),
            'byteExposurePolicy' => 'package-root-relationship-bytes-blocked',
            'reviewPolicy' => 'package-root-relationship-metadata-only',
            'canExposeBytes' => false,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageDigitalSignatureProvenance(array $parts, array $rootRelationships, array $contentTypes): array
    {
        $originRelationships = [];
        foreach ($rootRelationships as $relationship) {
            if ($relationship['type'] === self::DIGITAL_SIGNATURE_ORIGIN_REL) {
                $originRelationships[] = $relationship;
            }
        }

        $origins = [];
        $signatures = [];
        $byOriginRelationshipId = [];
        $bySignatureRelationshipId = [];
        $originRelationshipIds = [];
        $signatureRelationshipIds = [];
        $originParts = [];
        $signatureParts = [];
        $originSha256s = [];
        $signatureSha256s = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $externalTargetIssueCodes = [];
        $contentTypesSeen = [];
        $issueCodes = [];

        foreach ($originRelationships as $relationship) {
            $origin = $this->digitalSignatureOriginItem($parts, $relationship, $contentTypes, count($origins));
            $origins[] = $origin;
            $byOriginRelationshipId[(string) $origin['id']] = $origin;
            $originRelationshipIds[] = (string) $origin['id'];
            $this->appendUniqueString($originParts, is_string($origin['targetPart'] ?? null) ? $origin['targetPart'] : null);
            $this->appendUniqueString($originSha256s, is_string($origin['sha256'] ?? null) ? $origin['sha256'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($origin['contentType'] ?? null) ? $origin['contentType'] : null);
            if (($origin['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($origin['target'] ?? null) ? $origin['target'] : null);
                if (($origin['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($origin['target'] ?? null) ? $origin['target'] : null);
                }
                foreach (($origin['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($origin['issues'] ?? []) as $issue) {
                $issueCodes[(string) $issue] = true;
            }

            foreach (($origin['signatures']['items'] ?? []) as $signature) {
                if (!is_array($signature)) {
                    continue;
                }
                $signatures[] = $signature;
                $bySignatureRelationshipId[(string) $signature['id']] = $signature;
                $signatureRelationshipIds[] = (string) $signature['id'];
                $this->appendUniqueString($signatureParts, is_string($signature['targetPart'] ?? null) ? $signature['targetPart'] : null);
                $this->appendUniqueString($signatureSha256s, is_string($signature['sha256'] ?? null) ? $signature['sha256'] : null);
                $this->appendUniqueString($contentTypesSeen, is_string($signature['contentType'] ?? null) ? $signature['contentType'] : null);
                if (($signature['external'] ?? false) === true) {
                    $this->appendUniqueString($externalTargets, is_string($signature['target'] ?? null) ? $signature['target'] : null);
                    if (($signature['externalTargetAllowed'] ?? null) !== true) {
                        $this->appendUniqueString($unsafeExternalTargets, is_string($signature['target'] ?? null) ? $signature['target'] : null);
                    }
                    foreach (($signature['externalTargetIssues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $externalTargetIssueCodes[$issue] = true;
                        }
                    }
                }
                foreach (($signature['issues'] ?? []) as $issue) {
                    $issueCodes[(string) $issue] = true;
                }
            }
        }

        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        $referenceUriKindCounts = [];
        $referenceUris = [];
        $referenceTransformAlgorithms = [];
        $digestMethodAlgorithms = [];
        $signatureMethodAlgorithms = [];
        $canonicalizationMethodAlgorithms = [];
        $referenceTargetParts = [];
        $referenceTargetContentTypes = [];
        $referenceTargetSha256s = [];
        $referenceCount = 0;
        $packageReferenceCount = 0;
        $sameDocumentReferenceCount = 0;
        $externalReferenceCount = 0;
        $relativeReferenceCount = 0;
        $emptyReferenceCount = 0;
        $referenceTargetExistingCount = 0;
        $referenceTargetMissingCount = 0;
        $referenceTargetMissingContentTypeCount = 0;
        $referenceTransformCount = 0;
        $referenceDigestValueCount = 0;
        $referenceDigestValueMissingCount = 0;
        $signatureValuePresentCount = 0;
        foreach ($signatures as $signature) {
            $referenceCount += (int) ($signature['referenceCount'] ?? 0);
            $packageReferenceCount += (int) ($signature['packageReferenceCount'] ?? 0);
            $sameDocumentReferenceCount += (int) ($signature['sameDocumentReferenceCount'] ?? 0);
            $externalReferenceCount += (int) ($signature['externalReferenceCount'] ?? 0);
            $relativeReferenceCount += (int) ($signature['relativeReferenceCount'] ?? 0);
            $emptyReferenceCount += (int) ($signature['emptyReferenceCount'] ?? 0);
            $referenceTargetExistingCount += (int) ($signature['referenceTargetExistingCount'] ?? 0);
            $referenceTargetMissingCount += (int) ($signature['referenceTargetMissingCount'] ?? 0);
            $referenceTargetMissingContentTypeCount += (int) ($signature['referenceTargetMissingContentTypeCount'] ?? 0);
            $referenceTransformCount += (int) ($signature['referenceTransformCount'] ?? 0);
            $referenceDigestValueCount += (int) ($signature['referenceDigestValueCount'] ?? 0);
            $referenceDigestValueMissingCount += (int) ($signature['referenceDigestValueMissingCount'] ?? 0);
            if (($signature['hasSignatureValue'] ?? false) === true) {
                ++$signatureValuePresentCount;
            }

            foreach (($signature['referenceUriKindCounts'] ?? []) as $kind => $count) {
                if (!is_string($kind) || $kind === '') {
                    continue;
                }
                $referenceUriKindCounts[$kind] = ($referenceUriKindCounts[$kind] ?? 0) + (int) $count;
            }
            foreach (($signature['referenceUris'] ?? []) as $uri) {
                $this->appendUniqueString($referenceUris, is_string($uri) ? $uri : null);
            }
            foreach (($signature['referenceTargetParts'] ?? []) as $partName) {
                $this->appendUniqueString($referenceTargetParts, is_string($partName) ? $partName : null);
            }
            foreach (($signature['referenceTargetContentTypes'] ?? []) as $contentType) {
                $this->appendUniqueString($referenceTargetContentTypes, is_string($contentType) ? $contentType : null);
            }
            foreach (($signature['referenceTargetSha256s'] ?? []) as $sha256) {
                $this->appendUniqueString($referenceTargetSha256s, is_string($sha256) ? $sha256 : null);
            }
            foreach (($signature['referenceTransformAlgorithms'] ?? []) as $algorithm) {
                $this->appendUniqueString($referenceTransformAlgorithms, is_string($algorithm) ? $algorithm : null);
            }
            foreach (($signature['digestMethodAlgorithms'] ?? []) as $algorithm) {
                $this->appendUniqueString($digestMethodAlgorithms, is_string($algorithm) ? $algorithm : null);
            }
            foreach (($signature['signatureMethodAlgorithms'] ?? []) as $algorithm) {
                $this->appendUniqueString($signatureMethodAlgorithms, is_string($algorithm) ? $algorithm : null);
            }
            foreach (($signature['canonicalizationMethodAlgorithms'] ?? []) as $algorithm) {
                $this->appendUniqueString($canonicalizationMethodAlgorithms, is_string($algorithm) ? $algorithm : null);
            }
        }
        ksort($referenceUriKindCounts, SORT_STRING);

        return [
            'present' => $origins !== [],
            'originCount' => count($origins),
            'existingOriginCount' => count(array_filter(
                $origins,
                static fn (array $origin): bool => $origin['external'] === false && $origin['exists'] === true,
            )),
            'missingOriginCount' => count(array_filter(
                $origins,
                static fn (array $origin): bool => $origin['external'] === false && $origin['exists'] === false,
            )),
            'externalOriginCount' => count(array_filter($origins, static fn (array $origin): bool => $origin['external'] === true)),
            'allowedExternalOriginCount' => count(array_filter(
                $origins,
                static fn (array $origin): bool => $origin['external'] === true && ($origin['externalTargetAllowed'] ?? null) === true,
            )),
            'unsafeExternalOriginCount' => count(array_filter(
                $origins,
                static fn (array $origin): bool => $origin['external'] === true && ($origin['externalTargetAllowed'] ?? null) !== true,
            )),
            'signatureCount' => count($signatures),
            'existingSignatureCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => $signature['external'] === false && $signature['exists'] === true,
            )),
            'missingSignatureCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => $signature['external'] === false && $signature['exists'] === false,
            )),
            'externalSignatureCount' => count(array_filter($signatures, static fn (array $signature): bool => $signature['external'] === true)),
            'allowedExternalSignatureCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => $signature['external'] === true && ($signature['externalTargetAllowed'] ?? null) === true,
            )),
            'unsafeExternalSignatureCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => $signature['external'] === true && ($signature['externalTargetAllowed'] ?? null) !== true,
            )),
            'invalidSignatureXmlCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => in_array('invalid-signature-xml', $signature['issues'], true),
            )),
            'unexpectedSignatureRootCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => in_array('unexpected-signature-root', $signature['issues'], true),
            )),
            'issueCount' => count(array_filter(
                array_merge($origins, $signatures),
                static fn (array $item): bool => $item['issues'] !== [],
            )),
            'originRelationshipIds' => $originRelationshipIds,
            'signatureRelationshipIds' => $signatureRelationshipIds,
            'originParts' => $originParts,
            'signatureParts' => $signatureParts,
            'originSha256Count' => count($originSha256s),
            'signatureSha256Count' => count($signatureSha256s),
            'originSha256s' => $originSha256s,
            'signatureSha256s' => $signatureSha256s,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'referenceCount' => $referenceCount,
            'referenceUriKindCounts' => $referenceUriKindCounts,
            'referenceUris' => $referenceUris,
            'packageReferenceCount' => $packageReferenceCount,
            'sameDocumentReferenceCount' => $sameDocumentReferenceCount,
            'externalReferenceCount' => $externalReferenceCount,
            'relativeReferenceCount' => $relativeReferenceCount,
            'emptyReferenceCount' => $emptyReferenceCount,
            'referenceTargetExistingCount' => $referenceTargetExistingCount,
            'referenceTargetMissingCount' => $referenceTargetMissingCount,
            'referenceTargetMissingContentTypeCount' => $referenceTargetMissingContentTypeCount,
            'referenceTargetSha256Count' => count($referenceTargetSha256s),
            'referenceTargetParts' => $referenceTargetParts,
            'referenceTargetContentTypes' => $referenceTargetContentTypes,
            'referenceTargetSha256s' => $referenceTargetSha256s,
            'referenceTransformCount' => $referenceTransformCount,
            'referenceTransformAlgorithms' => $referenceTransformAlgorithms,
            'referenceDigestValueCount' => $referenceDigestValueCount,
            'referenceDigestValueMissingCount' => $referenceDigestValueMissingCount,
            'digestMethodAlgorithms' => $digestMethodAlgorithms,
            'signatureMethodAlgorithms' => $signatureMethodAlgorithms,
            'canonicalizationMethodAlgorithms' => $canonicalizationMethodAlgorithms,
            'signatureValuePresentCount' => $signatureValuePresentCount,
            'byOriginRelationshipId' => $byOriginRelationshipId,
            'bySignatureRelationshipId' => $bySignatureRelationshipId,
            'origins' => $origins,
            'signatures' => $signatures,
            'cryptographicValidation' => false,
            'reviewPolicy' => 'digital-signature-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function digitalSignatureOriginItem(array $parts, array $relationship, array $contentTypes, int $index): array
    {
        $summary = $this->relationshipInventorySummary($parts, $relationship, '/', '_rels/.rels', $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $relationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $relationships = $relationshipsPart === null ? [] : $this->readRelationshipsPart($parts, $relationshipsPart);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        $issues = [];

        if ($external) {
            $issues[] = 'external-signature-origin';
            foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issues[] = $issue;
                }
            }
        } elseif (!$exists) {
            $issues[] = 'missing-origin-part';
        }
        if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
            $issues[] = 'missing-origin-content-type';
        } elseif (!$external && $contentTypeBase !== '' && $contentTypeBase !== self::CT_DIGITAL_SIGNATURE_ORIGIN) {
            $issues[] = 'unexpected-origin-content-type';
        }
        if (!$external && $exists && $relationshipsPart !== null && !isset($parts[$relationshipsPart])) {
            $issues[] = 'missing-origin-relationships';
        }

        $signatures = $this->digitalSignatureParts(
            $parts,
            $targetPart,
            $relationshipsPart,
            $relationships,
            $contentTypes,
        );

        return [
            'index' => $index,
            'source' => '/',
            'id' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'externalTargetIssues' => $summary['externalTargetIssues'],
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'expectedContentTypeBase' => self::CT_DIGITAL_SIGNATURE_ORIGIN,
            'external' => $external,
            'exists' => $exists,
            'relationshipsPart' => '_rels/.rels',
            'originRelationshipsPart' => $relationshipsPart,
            'originRelationshipCount' => count($relationships),
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'signatures' => $signatures,
            'signatureCount' => $signatures['count'],
            'signatureIssueCount' => $signatures['issueCount'],
            'cryptographicValidation' => false,
            'reviewPolicy' => 'digital-signature-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function digitalSignatureParts(
        array $parts,
        ?string $sourcePart,
        ?string $relationshipsPart,
        array $relationships,
        array $contentTypes,
    ): array {
        if ($sourcePart === null || $relationshipsPart === null) {
            return [
                'count' => 0,
                'existingCount' => 0,
                'missingCount' => 0,
                'externalCount' => 0,
                'allowedExternalTargetCount' => 0,
                'unsafeExternalTargetCount' => 0,
                'invalidXmlCount' => 0,
                'unexpectedRootCount' => 0,
                'issueCount' => 0,
                'referenceTargetExistingCount' => 0,
                'referenceTargetMissingCount' => 0,
                'referenceTargetMissingContentTypeCount' => 0,
                'referenceTargetSha256Count' => 0,
                'relationshipIds' => [],
                'partNames' => [],
                'externalTargets' => [],
                'unsafeExternalTargets' => [],
                'contentTypes' => [],
                'referenceTargetParts' => [],
                'referenceTargetContentTypes' => [],
                'referenceTargetSha256s' => [],
                'externalTargetIssueCodes' => [],
                'issueCodes' => [],
                'byRelationshipId' => [],
                'items' => [],
            ];
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $contentTypesSeen = [];
        $referenceTargetParts = [];
        $referenceTargetContentTypes = [];
        $referenceTargetSha256s = [];
        $externalTargetIssueCodes = [];
        $issueCodes = [];

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::DIGITAL_SIGNATURE_SIGNATURE_REL) {
                continue;
            }

            $item = $this->digitalSignaturePartItem(
                $parts,
                $relationship,
                $sourcePart,
                $relationshipsPart,
                $contentTypes,
                count($items),
            );
            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            foreach (($item['referenceTargetParts'] ?? []) as $partName) {
                $this->appendUniqueString($referenceTargetParts, is_string($partName) ? $partName : null);
            }
            foreach (($item['referenceTargetContentTypes'] ?? []) as $contentType) {
                $this->appendUniqueString($referenceTargetContentTypes, is_string($contentType) ? $contentType : null);
            }
            foreach (($item['referenceTargetSha256s'] ?? []) as $sha256) {
                $this->appendUniqueString($referenceTargetSha256s, is_string($sha256) ? $sha256 : null);
            }
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }
                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($item['issues'] ?? []) as $issue) {
                $issueCodes[(string) $issue] = true;
            }
        }

        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'existingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'invalidXmlCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('invalid-signature-xml', $item['issues'], true),
            )),
            'unexpectedRootCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('unexpected-signature-root', $item['issues'], true),
            )),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'referenceTargetExistingCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['referenceTargetExistingCount'] ?? 0), $items)),
            'referenceTargetMissingCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['referenceTargetMissingCount'] ?? 0), $items)),
            'referenceTargetMissingContentTypeCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['referenceTargetMissingContentTypeCount'] ?? 0), $items)),
            'referenceTargetSha256Count' => count($referenceTargetSha256s),
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'contentTypes' => $contentTypesSeen,
            'referenceTargetParts' => $referenceTargetParts,
            'referenceTargetContentTypes' => $referenceTargetContentTypes,
            'referenceTargetSha256s' => $referenceTargetSha256s,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function digitalSignaturePartItem(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        $issues = [];

        if ($external) {
            $issues[] = 'external-signature-target';
            foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issues[] = $issue;
                }
            }
        } elseif (!$exists) {
            $issues[] = 'missing-signature-part';
        }
        if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
            $issues[] = 'missing-signature-content-type';
        } elseif (!$external && $contentTypeBase !== '' && $contentTypeBase !== self::CT_DIGITAL_SIGNATURE_XMLSIGNATURE) {
            $issues[] = 'unexpected-signature-content-type';
        }

        $metadata = $this->emptyDigitalSignatureXmlMetadata();
        if ($exists && $targetPart !== null) {
            $metadata = $this->digitalSignatureXmlMetadata($parts[$targetPart], $targetPart, $parts, $contentTypes);
            if ($metadata['validXml'] === false) {
                $issues[] = 'invalid-signature-xml';
            } elseif ($metadata['validRoot'] === false) {
                $issues[] = 'unexpected-signature-root';
            }
        }

        return [
            'index' => $index,
            'source' => $sourcePart,
            'id' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'externalTargetIssues' => $summary['externalTargetIssues'],
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'expectedContentTypeBase' => self::CT_DIGITAL_SIGNATURE_XMLSIGNATURE,
            'external' => $external,
            'exists' => $exists,
            'relationshipsPart' => $relationshipsPart,
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'validXml' => $metadata['validXml'],
            'xmlParseError' => $metadata['xmlParseError'],
            'rootNamespace' => $metadata['rootNamespace'],
            'rootLocalName' => $metadata['rootLocalName'],
            'validRoot' => $metadata['validRoot'],
            'referenceCount' => $metadata['referenceCount'],
            'referenceUris' => $metadata['referenceUris'],
            'references' => $metadata['references'],
            'referenceUriKindCounts' => $metadata['referenceUriKindCounts'],
            'packageReferenceCount' => $metadata['packageReferenceCount'],
            'sameDocumentReferenceCount' => $metadata['sameDocumentReferenceCount'],
            'externalReferenceCount' => $metadata['externalReferenceCount'],
            'relativeReferenceCount' => $metadata['relativeReferenceCount'],
            'emptyReferenceCount' => $metadata['emptyReferenceCount'],
            'referenceTargetExistingCount' => $metadata['referenceTargetExistingCount'],
            'referenceTargetMissingCount' => $metadata['referenceTargetMissingCount'],
            'referenceTargetMissingContentTypeCount' => $metadata['referenceTargetMissingContentTypeCount'],
            'referenceTargetSha256Count' => $metadata['referenceTargetSha256Count'],
            'referenceTargetParts' => $metadata['referenceTargetParts'],
            'referenceTargetContentTypes' => $metadata['referenceTargetContentTypes'],
            'referenceTargetSha256s' => $metadata['referenceTargetSha256s'],
            'referenceTransformCount' => $metadata['referenceTransformCount'],
            'referenceTransformAlgorithms' => $metadata['referenceTransformAlgorithms'],
            'referenceDigestValueCount' => $metadata['referenceDigestValueCount'],
            'referenceDigestValueMissingCount' => $metadata['referenceDigestValueMissingCount'],
            'digestMethodAlgorithms' => $metadata['digestMethodAlgorithms'],
            'signatureMethodAlgorithms' => $metadata['signatureMethodAlgorithms'],
            'canonicalizationMethodAlgorithms' => $metadata['canonicalizationMethodAlgorithms'],
            'hasSignatureValue' => $metadata['hasSignatureValue'],
            'cryptographicValidation' => false,
            'reviewPolicy' => 'digital-signature-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyDigitalSignatureXmlMetadata(): array
    {
        return [
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'referenceCount' => 0,
            'referenceUris' => [],
            'references' => [],
            'referenceUriKindCounts' => [],
            'packageReferenceCount' => 0,
            'sameDocumentReferenceCount' => 0,
            'externalReferenceCount' => 0,
            'relativeReferenceCount' => 0,
            'emptyReferenceCount' => 0,
            'referenceTargetExistingCount' => 0,
            'referenceTargetMissingCount' => 0,
            'referenceTargetMissingContentTypeCount' => 0,
            'referenceTargetSha256Count' => 0,
            'referenceTargetParts' => [],
            'referenceTargetContentTypes' => [],
            'referenceTargetSha256s' => [],
            'referenceTransformCount' => 0,
            'referenceTransformAlgorithms' => [],
            'referenceDigestValueCount' => 0,
            'referenceDigestValueMissingCount' => 0,
            'digestMethodAlgorithms' => [],
            'signatureMethodAlgorithms' => [],
            'canonicalizationMethodAlgorithms' => [],
            'hasSignatureValue' => null,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function digitalSignatureXmlMetadata(string $xml, string $partName, array $parts, array $contentTypes): array
    {
        $metadata = $this->emptyDigitalSignatureXmlMetadata();
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            $metadata['validXml'] = false;
            $metadata['xmlParseError'] = $this->lastXmlPreflightError($xml, $partName);

            return $metadata;
        }

        $root = $dom->documentElement;
        $metadata['validXml'] = $root instanceof \DOMElement;
        $metadata['xmlParseError'] = null;
        $metadata['rootNamespace'] = $root instanceof \DOMElement ? $root->namespaceURI : null;
        $metadata['rootLocalName'] = $root instanceof \DOMElement ? $root->localName : null;
        $metadata['validRoot'] = $root instanceof \DOMElement
            && $root->namespaceURI === self::NS_XMLDSIG
            && $root->localName === 'Signature';

        if ($metadata['validRoot'] !== true || !$root instanceof \DOMElement) {
            return $metadata;
        }

        $metadata['referenceCount'] = 0;
        foreach ($root->getElementsByTagNameNS(self::NS_XMLDSIG, 'Reference') as $reference) {
            if (!$reference instanceof \DOMElement) {
                continue;
            }

            $item = $this->digitalSignatureReferenceMetadata($reference, $metadata['referenceCount'], $parts, $contentTypes);
            ++$metadata['referenceCount'];
            $metadata['references'][] = $item;
            $metadata['referenceUriKindCounts'][$item['uriKind']] =
                ($metadata['referenceUriKindCounts'][$item['uriKind']] ?? 0) + 1;
            $this->appendUniqueString($metadata['referenceUris'], $item['uri']);
            if ($item['uriKind'] === 'package-part') {
                ++$metadata['packageReferenceCount'];
            } elseif ($item['uriKind'] === 'same-document') {
                ++$metadata['sameDocumentReferenceCount'];
            } elseif ($item['uriKind'] === 'external') {
                ++$metadata['externalReferenceCount'];
            } elseif ($item['uriKind'] === 'relative') {
                ++$metadata['relativeReferenceCount'];
            } elseif ($item['uriKind'] === 'empty') {
                ++$metadata['emptyReferenceCount'];
            }
            if ($item['targetPart'] !== null) {
                $this->appendUniqueString($metadata['referenceTargetParts'], $item['targetPart']);
                $this->appendUniqueString($metadata['referenceTargetContentTypes'], $item['targetContentType']);
                if ($item['targetExists'] === true) {
                    ++$metadata['referenceTargetExistingCount'];
                    $this->appendUniqueString($metadata['referenceTargetSha256s'], $item['targetSha256']);
                } else {
                    ++$metadata['referenceTargetMissingCount'];
                }
                if ($item['targetContentTypeSource'] === 'missing') {
                    ++$metadata['referenceTargetMissingContentTypeCount'];
                }
            }
            $metadata['referenceTransformCount'] += $item['transformCount'];
            foreach ($item['transformAlgorithms'] as $algorithm) {
                $this->appendUniqueString($metadata['referenceTransformAlgorithms'], $algorithm);
            }
            if ($item['digestMethodAlgorithm'] !== null) {
                $this->appendUniqueString($metadata['digestMethodAlgorithms'], $item['digestMethodAlgorithm']);
            }
            if ($item['digestValuePresent']) {
                ++$metadata['referenceDigestValueCount'];
            } else {
                ++$metadata['referenceDigestValueMissingCount'];
            }
        }
        ksort($metadata['referenceUriKindCounts'], SORT_STRING);
        $metadata['referenceTargetSha256Count'] = count($metadata['referenceTargetSha256s']);

        foreach ($root->getElementsByTagNameNS(self::NS_XMLDSIG, 'SignatureMethod') as $signatureMethod) {
            if ($signatureMethod instanceof \DOMElement) {
                $this->appendUniqueString($metadata['signatureMethodAlgorithms'], $signatureMethod->getAttribute('Algorithm'));
            }
        }

        foreach ($root->getElementsByTagNameNS(self::NS_XMLDSIG, 'CanonicalizationMethod') as $canonicalizationMethod) {
            if ($canonicalizationMethod instanceof \DOMElement) {
                $this->appendUniqueString($metadata['canonicalizationMethodAlgorithms'], $canonicalizationMethod->getAttribute('Algorithm'));
            }
        }

        $metadata['hasSignatureValue'] = false;
        foreach ($root->getElementsByTagNameNS(self::NS_XMLDSIG, 'SignatureValue') as $signatureValue) {
            if ($signatureValue instanceof \DOMElement && trim($signatureValue->textContent) !== '') {
                $metadata['hasSignatureValue'] = true;
                break;
            }
        }

        return $metadata;
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function digitalSignatureReferenceMetadata(\DOMElement $reference, int $index, array $parts, array $contentTypes): array
    {
        $uri = $reference->getAttribute('URI');
        $uriKind = $this->digitalSignatureReferenceUriKind($uri);
        $suffix = $this->targetReferenceSuffix($uri);
        $targetPart = $uriKind === 'package-part' ? $this->stripQueryAndFragment($uri) : null;
        $targetExists = $targetPart !== null && isset($parts[$targetPart]);
        $targetContentType = $targetPart === null
            ? $this->missingContentTypeResolution(null)
            : $this->contentTypeResolutionForPart($targetPart, $contentTypes);
        $targetBytes = $targetExists && $targetPart !== null ? $parts[$targetPart] : null;
        $transforms = [];
        foreach ($reference->getElementsByTagNameNS(self::NS_XMLDSIG, 'Transform') as $transform) {
            if ($transform instanceof \DOMElement) {
                $this->appendUniqueString($transforms, $transform->getAttribute('Algorithm'));
            }
        }

        $digestMethod = $this->firstChildElementByNamespace($reference, self::NS_XMLDSIG, 'DigestMethod');
        $digestValue = $this->firstChildElementByNamespace($reference, self::NS_XMLDSIG, 'DigestValue');
        $digestValueText = $digestValue instanceof \DOMElement ? trim($digestValue->textContent) : '';

        return [
            'index' => $index,
            'uri' => $uri,
            'uriKind' => $uriKind,
            'targetPart' => $targetPart,
            'targetQuery' => $suffix['query'],
            'targetFragment' => $suffix['fragment'],
            'targetReferenceSuffix' => $suffix['suffix'],
            'external' => $uriKind === 'external',
            'sameDocument' => $uriKind === 'same-document' || $uriKind === 'empty',
            'startsAtPackageRoot' => str_starts_with($uri, '/'),
            'targetExists' => $targetPart === null ? null : $targetExists,
            'targetByteLength' => $targetBytes === null ? null : strlen($targetBytes),
            'targetCrc32' => $targetBytes === null ? null : sprintf('%08x', crc32($targetBytes)),
            'targetSha256' => $targetBytes === null ? null : hash('sha256', $targetBytes),
            'targetContentType' => $targetPart === null ? null : $targetContentType['contentType'],
            'targetContentTypeBase' => $targetPart === null ? null : $targetContentType['contentTypeBase'],
            'targetContentTypeHasParameters' => $targetPart === null ? null : $targetContentType['contentTypeHasParameters'],
            'targetContentTypeParameterCount' => $targetPart === null ? null : $targetContentType['contentTypeParameterCount'],
            'targetContentTypeParameters' => $targetPart === null ? [] : $targetContentType['contentTypeParameters'],
            'targetContentTypeParameterMap' => $targetPart === null ? [] : $targetContentType['contentTypeParameterMap'],
            'targetContentTypeSource' => $targetPart === null ? null : $targetContentType['contentTypeSource'],
            'targetDefaultExtension' => $targetPart === null ? null : $targetContentType['defaultExtension'],
            'targetOverridePartName' => $targetPart === null ? null : $targetContentType['overridePartName'],
            'targetCanExposeBytes' => $targetPart === null ? null : false,
            'targetByteExposurePolicy' => $targetPart === null ? null : 'digital-signature-reference-target-bytes-blocked',
            'targetReviewPolicy' => $targetPart === null ? null : 'digital-signature-reference-target-metadata-only',
            'transformCount' => count($transforms),
            'transformAlgorithms' => $transforms,
            'digestMethodAlgorithm' => $digestMethod instanceof \DOMElement
                ? $this->emptyStringToNull($digestMethod->getAttribute('Algorithm'))
                : null,
            'digestValuePresent' => $digestValueText !== '',
            'digestValueLength' => strlen($digestValueText),
        ];
    }

    private function digitalSignatureReferenceUriKind(string $uri): string
    {
        $trimmed = trim($uri);
        if ($trimmed === '') {
            return 'empty';
        }
        if (str_starts_with($trimmed, '#')) {
            return 'same-document';
        }
        if (
            str_starts_with($trimmed, '//')
            || preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $trimmed) === 1
        ) {
            return 'external';
        }
        if (str_starts_with($trimmed, '/')) {
            return 'package-part';
        }

        return 'relative';
    }

    private function firstChildElementByNamespace(\DOMElement $parent, string $namespace, string $localName): ?\DOMElement
    {
        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === $namespace && $child->localName === $localName) {
                return $child;
            }
        }

        return null;
    }

    private function firstDescendantElementByNamespace(\DOMElement $parent, string $namespace, string $localName): ?\DOMElement
    {
        foreach ($parent->getElementsByTagNameNS($namespace, $localName) as $candidate) {
            if ($candidate instanceof \DOMElement) {
                return $candidate;
            }
        }

        return null;
    }

    /**
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @return array<string, mixed>
     */
    private function selectedXmlPartDefinition(
        string $kind,
        string $partName,
        string $xml,
        bool $exists,
        ?array $relationship,
        string $relationshipSourcePart,
        string $relationshipsPart,
        bool $required,
        string $expectedRootNamespace,
        string $expectedRootLocalName,
        string $expectedContentTypeBase,
        array $expectedAlternativeContentTypeBases = [],
    ): array {
        $expectedContentTypeBases = array_values(array_unique(array_filter(
            array_merge([$expectedContentTypeBase], $expectedAlternativeContentTypeBases),
            static fn (string $contentTypeBase): bool => $contentTypeBase !== '',
        )));

        return [
            'kind' => $kind,
            'partName' => $partName,
            'xml' => $xml,
            'exists' => $exists,
            'relationship' => $relationship,
            'relationshipSourcePart' => $relationshipSourcePart,
            'relationshipsPart' => $relationshipsPart,
            'required' => $required,
            'expectedRootNamespace' => $expectedRootNamespace,
            'expectedRootLocalName' => $expectedRootLocalName,
            'expectedContentTypeBase' => $expectedContentTypeBase,
            'expectedContentTypeBases' => $expectedContentTypeBases,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<array<string, mixed>> $definitions
     * @return array<string, mixed>
     */
    private function selectedXmlPartProvenance(array $parts, array $contentTypes, array $definitions): array
    {
        $items = [];
        $byKind = [];
        $issueKinds = [];
        $issueCount = 0;

        foreach ($definitions as $definition) {
            $item = $this->selectedXmlPartProvenanceItem($parts, $contentTypes, $definition);
            $items[] = $item;
            $byKind[$item['kind']] = $item;
            if ($item['issues'] !== []) {
                $issueKinds[] = $item['kind'];
                $issueCount += count($item['issues']);
            }
        }

        $rootNamespacePrefixes = [];
        $rootAttributeCount = 0;
        $rootNamespaceDeclarationCount = 0;
        $rootPrefixedCount = 0;
        $xmlDeclarationCount = 0;
        $xmlDeclarationEncodingCounts = [];
        $xmlStandaloneDeclarationCount = 0;
        $xmlStandaloneYesCount = 0;
        $xmlStandaloneNoCount = 0;
        $selectionSourceCounts = [];
        $relationshipSourcePartCounts = [];
        $relationshipsPartCounts = [];
        $relationshipTargetReferenceSuffixes = [];
        $relationshipTargetReferenceSuffixCount = 0;
        $relationshipTargetQueryCount = 0;
        $relationshipTargetFragmentCount = 0;
        $relationshipSelectedPartNames = [];
        $existingContentTypeSourceCounts = [];
        $existingContentTypeBaseCounts = [];
        foreach ($items as $item) {
            $selectionSource = is_string($item['selectionSource'] ?? null) ? $item['selectionSource'] : 'unknown';
            $selectionSourceCounts[$selectionSource] = ($selectionSourceCounts[$selectionSource] ?? 0) + 1;

            if (($item['exists'] ?? false) === true) {
                $contentTypeSource = is_string($item['contentTypeSource'] ?? null) ? $item['contentTypeSource'] : 'missing';
                if ($contentTypeSource === '') {
                    $contentTypeSource = 'missing';
                }
                $existingContentTypeSourceCounts[$contentTypeSource] = ($existingContentTypeSourceCounts[$contentTypeSource] ?? 0) + 1;

                $contentTypeBase = is_string($item['contentTypeBase'] ?? null) ? $item['contentTypeBase'] : '';
                $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
                $existingContentTypeBaseCounts[$contentTypeBaseKey] = ($existingContentTypeBaseCounts[$contentTypeBaseKey] ?? 0) + 1;
            }

            if (($item['relationshipId'] ?? null) !== null) {
                $this->appendUniqueString(
                    $relationshipSelectedPartNames,
                    is_string($item['partName'] ?? null) ? $item['partName'] : null,
                );

                $relationshipSourcePart = is_string($item['relationshipSourcePart'] ?? null)
                    ? $item['relationshipSourcePart']
                    : '';
                if ($relationshipSourcePart !== '') {
                    $relationshipSourcePartCounts[$relationshipSourcePart] =
                        ($relationshipSourcePartCounts[$relationshipSourcePart] ?? 0) + 1;
                }

                $relationshipsPart = is_string($item['relationshipsPart'] ?? null)
                    ? $item['relationshipsPart']
                    : '';
                if ($relationshipsPart !== '') {
                    $relationshipsPartCounts[$relationshipsPart] =
                        ($relationshipsPartCounts[$relationshipsPart] ?? 0) + 1;
                }

                $targetReferenceSuffix = is_string($item['targetReferenceSuffix'] ?? null)
                    ? $item['targetReferenceSuffix']
                    : '';
                if ($targetReferenceSuffix !== '') {
                    ++$relationshipTargetReferenceSuffixCount;
                    $this->appendUniqueString($relationshipTargetReferenceSuffixes, $targetReferenceSuffix);
                }
                if (($item['targetQuery'] ?? null) !== null) {
                    ++$relationshipTargetQueryCount;
                }
                if (($item['targetFragment'] ?? null) !== null) {
                    ++$relationshipTargetFragmentCount;
                }
            }

            $rootAttributeCount += (int) ($item['rootAttributeCount'] ?? 0);
            $rootNamespaceDeclarationCount += (int) ($item['rootNamespaceDeclarationCount'] ?? 0);
            if (($item['rootPrefix'] ?? null) !== null) {
                ++$rootPrefixedCount;
            }
            if (($item['xmlDeclarationPresent'] ?? false) === true) {
                ++$xmlDeclarationCount;
            }
            $encoding = is_string($item['xmlDeclarationEncoding'] ?? null) ? $item['xmlDeclarationEncoding'] : '';
            if ($encoding !== '') {
                $xmlDeclarationEncodingCounts[$encoding] = ($xmlDeclarationEncodingCounts[$encoding] ?? 0) + 1;
            }
            if (is_bool($item['xmlDeclarationStandalone'] ?? null)) {
                ++$xmlStandaloneDeclarationCount;
                if ($item['xmlDeclarationStandalone'] === true) {
                    ++$xmlStandaloneYesCount;
                } else {
                    ++$xmlStandaloneNoCount;
                }
            }
            foreach (($item['rootNamespacePrefixes'] ?? []) as $prefix) {
                if (is_string($prefix)) {
                    $this->appendUniqueString($rootNamespacePrefixes, $prefix);
                }
            }
        }
        ksort($selectionSourceCounts, SORT_STRING);
        ksort($relationshipSourcePartCounts, SORT_STRING);
        ksort($relationshipsPartCounts, SORT_STRING);
        ksort($existingContentTypeSourceCounts, SORT_STRING);
        ksort($existingContentTypeBaseCounts, SORT_STRING);
        ksort($xmlDeclarationEncodingCounts, SORT_STRING);

        return [
            'count' => count($items),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['exists'] === true)),
            'relationshipSelectedCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipId'] !== null)),
            'selectionSourceCounts' => $selectionSourceCounts,
            'relationshipSourcePartCounts' => $relationshipSourcePartCounts,
            'relationshipsPartCounts' => $relationshipsPartCounts,
            'relationshipTargetReferenceSuffixCount' => $relationshipTargetReferenceSuffixCount,
            'relationshipTargetQueryCount' => $relationshipTargetQueryCount,
            'relationshipTargetFragmentCount' => $relationshipTargetFragmentCount,
            'relationshipTargetReferenceSuffixes' => $relationshipTargetReferenceSuffixes,
            'relationshipSelectedPartNames' => $relationshipSelectedPartNames,
            'existingContentTypeSourceCounts' => $existingContentTypeSourceCounts,
            'existingContentTypeBaseCounts' => $existingContentTypeBaseCounts,
            'byteDigestCount' => count(array_filter($items, static fn (array $item): bool => is_string($item['sha256'] ?? null))),
            'missingRequiredOrReferencedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-required-part', $item['issues'], true)
                    || in_array('missing-relationship-target', $item['issues'], true),
            )),
            'validRootCount' => count(array_filter($items, static fn (array $item): bool => $item['validRoot'] === true)),
            'invalidRootCount' => count(array_filter($items, static fn (array $item): bool => $item['validRoot'] === false)),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-xml', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-content-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'rootPrefixedCount' => $rootPrefixedCount,
            'rootAttributeCount' => $rootAttributeCount,
            'rootNamespaceDeclarationCount' => $rootNamespaceDeclarationCount,
            'rootNamespacePrefixes' => $rootNamespacePrefixes,
            'xmlDeclarationCount' => $xmlDeclarationCount,
            'xmlDeclarationEncodingCounts' => $xmlDeclarationEncodingCounts,
            'xmlStandaloneDeclarationCount' => $xmlStandaloneDeclarationCount,
            'xmlStandaloneYesCount' => $xmlStandaloneYesCount,
            'xmlStandaloneNoCount' => $xmlStandaloneNoCount,
            'issueCount' => $issueCount,
            'issueKinds' => $issueKinds,
            'byKind' => $byKind,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, mixed> $definition
     * @return array<string, mixed>
     */
    private function selectedXmlPartProvenanceItem(array $parts, array $contentTypes, array $definition): array
    {
        $kind = (string) $definition['kind'];
        $partName = (string) $definition['partName'];
        $exists = (bool) $definition['exists'];
        $required = (bool) $definition['required'];
        $relationship = is_array($definition['relationship']) ? $definition['relationship'] : null;
        $expectedRootNamespace = (string) $definition['expectedRootNamespace'];
        $expectedRootLocalName = (string) $definition['expectedRootLocalName'];
        $expectedContentTypeBase = (string) $definition['expectedContentTypeBase'];
        $expectedContentTypeBases = is_array($definition['expectedContentTypeBases'] ?? null)
            ? array_values(array_filter(
                array_map('strval', $definition['expectedContentTypeBases']),
                static fn (string $contentTypeBase): bool => $contentTypeBase !== '',
            ))
            : ($expectedContentTypeBase === '' ? [] : [$expectedContentTypeBase]);
        $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
        $partBytes = $exists && array_key_exists($partName, $parts) ? $parts[$partName] : null;
        $validateContentType = $exists || $required || $relationship !== null;
        $contentTypeMatchesExpected = null;
        $issues = [];

        if ($expectedContentTypeBases !== [] && $validateContentType) {
            $contentTypeMatchesExpected = in_array($contentTypeResolution['contentTypeBase'], $expectedContentTypeBases, true);
            if (!$contentTypeMatchesExpected) {
                $issues[] = $contentTypeResolution['contentTypeSource'] === 'missing'
                    ? 'missing-content-type'
                    : 'unexpected-content-type';
            }
        }

        $item = [
            'kind' => $kind,
            'partName' => $partName,
            'selectionSource' => $relationship !== null ? 'relationship' : ($exists ? 'conventional-part' : 'conventional-fallback'),
            'required' => $required,
            'exists' => $exists,
            'bytes' => $partBytes === null ? 0 : strlen($partBytes),
            'crc32' => $partBytes === null ? null : sprintf('%08x', crc32($partBytes)),
            'sha256' => $partBytes === null ? null : hash('sha256', $partBytes),
            'expectedRootNamespace' => $expectedRootNamespace,
            'expectedRootLocalName' => $expectedRootLocalName,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'rootQualifiedName' => null,
            'rootPrefix' => null,
            'rootAttributeCount' => 0,
            'rootNamespaceDeclarationCount' => 0,
            'rootNamespacePrefixes' => [],
            'xmlDeclarationPresent' => false,
            'xmlDeclarationVersion' => null,
            'xmlDeclarationEncoding' => null,
            'xmlDeclarationStandalone' => null,
            'xmlDeclarationAttributeCount' => 0,
            'xmlDeclarationAttributeNames' => [],
            'validRoot' => null,
            'xmlParseError' => null,
            'expectedContentTypeBase' => $expectedContentTypeBase,
            'expectedContentTypeBases' => $expectedContentTypeBases,
            'contentTypeMatchesExpected' => $contentTypeMatchesExpected,
            'relationshipId' => null,
            'relationshipType' => null,
            'relationshipSourcePart' => null,
            'relationshipsPart' => null,
            'relationshipTarget' => null,
            'relationshipTargetMode' => null,
            'relationshipResolvedTarget' => null,
            'targetReferenceSuffix' => '',
            'targetQuery' => null,
            'targetFragment' => null,
            'issues' => $issues,
        ] + $contentTypeResolution;

        if ($relationship !== null) {
            $suffix = $this->targetReferenceSuffix($relationship['resolvedTarget']);
            $item['relationshipId'] = $relationship['id'];
            $item['relationshipType'] = $relationship['type'];
            $item['relationshipSourcePart'] = (string) $definition['relationshipSourcePart'];
            $item['relationshipsPart'] = (string) $definition['relationshipsPart'];
            $item['relationshipTarget'] = $relationship['target'];
            $item['relationshipTargetMode'] = $relationship['targetMode'];
            $item['relationshipResolvedTarget'] = $relationship['resolvedTarget'];
            $item['targetReferenceSuffix'] = $suffix['suffix'];
            $item['targetQuery'] = $suffix['query'];
            $item['targetFragment'] = $suffix['fragment'];
        }

        if (!$exists) {
            if ($required) {
                $item['issues'][] = 'missing-required-part';
            }
            if ($relationship !== null) {
                $item['issues'][] = 'missing-relationship-target';
            }

            return $item;
        }

        $xml = is_string($definition['xml']) ? $definition['xml'] : ($parts[$partName] ?? '');
        $xmlDeclaration = $this->xmlDeclarationProvenance($xml);
        $item['xmlDeclarationPresent'] = $xmlDeclaration['present'];
        $item['xmlDeclarationVersion'] = $xmlDeclaration['version'];
        $item['xmlDeclarationEncoding'] = $xmlDeclaration['encoding'];
        $item['xmlDeclarationStandalone'] = $xmlDeclaration['standalone'];
        $item['xmlDeclarationAttributeCount'] = $xmlDeclaration['attributeCount'];
        $item['xmlDeclarationAttributeNames'] = $xmlDeclaration['attributeNames'];
        if ($xml === '') {
            $item['validRoot'] = false;
            $item['issues'][] = 'empty-xml-part';

            return $item;
        }

        $root = $this->xmlRootProvenance($xml, $partName);
        if ($root['validXml'] === false) {
            $item['validRoot'] = false;
            $item['xmlParseError'] = $root['xmlParseError'];
            $item['issues'][] = 'invalid-xml';

            return $item;
        }

        $item['rootNamespace'] = $root['namespace'];
        $item['rootLocalName'] = $root['localName'];
        $item['rootQualifiedName'] = $root['qualifiedName'];
        $item['rootPrefix'] = $root['prefix'];
        $item['rootAttributeCount'] = $root['attributeCount'];
        $item['rootNamespaceDeclarationCount'] = $root['namespaceDeclarationCount'];
        $item['rootNamespacePrefixes'] = $root['namespacePrefixes'];
        $item['validRoot'] = $root['namespace'] === $expectedRootNamespace && $root['localName'] === $expectedRootLocalName;
        if ($item['validRoot'] === false) {
            $item['issues'][] = 'unexpected-root';
        }

        return $item;
    }

    /**
     * @return array{present:bool, version:?string, encoding:?string, standalone:?bool, attributeCount:int, attributeNames:list<string>}
     */
    private function xmlDeclarationProvenance(string $xml): array
    {
        if (preg_match('/^(?:\xEF\xBB\xBF)?\s*<\?xml\s+([^?]*?)\?>/i', $xml, $match) !== 1) {
            return [
                'present' => false,
                'version' => null,
                'encoding' => null,
                'standalone' => null,
                'attributeCount' => 0,
                'attributeNames' => [],
            ];
        }

        $attributes = [];
        preg_match_all('/([A-Za-z_][A-Za-z0-9_.:-]*)\s*=\s*(["\'])(.*?)\2/s', (string) $match[1], $matches, PREG_SET_ORDER);
        foreach ($matches as $attribute) {
            $name = strtolower((string) $attribute[1]);
            if (array_key_exists($name, $attributes)) {
                continue;
            }

            $attributes[$name] = (string) $attribute[3];
        }

        $standalone = null;
        $standaloneValue = strtolower($attributes['standalone'] ?? '');
        if ($standaloneValue === 'yes') {
            $standalone = true;
        } elseif ($standaloneValue === 'no') {
            $standalone = false;
        }

        return [
            'present' => true,
            'version' => isset($attributes['version']) && $attributes['version'] !== '' ? $attributes['version'] : null,
            'encoding' => isset($attributes['encoding']) && $attributes['encoding'] !== '' ? $attributes['encoding'] : null,
            'standalone' => $standalone,
            'attributeCount' => count($attributes),
            'attributeNames' => array_keys($attributes),
        ];
    }

    /**
     * @return array{present:bool, name:?string, publicId:?string, systemId:?string, hasPublicId:bool, hasSystemId:bool, hasInternalSubset:bool, internalSubsetByteLength:int, internalSubsetCrc32:?string, internalSubsetSha256:?string, entityCount:int, entityNames:list<string>, notationCount:int, notationNames:list<string>, systemIdKind:?string, systemIdScheme:?string, systemIdAllowed:?bool, systemIdIssues:list<string>}
     */
    private function xmlDocumentTypeProvenance(string $xml, string $partName): array
    {
        $empty = [
            'present' => false,
            'name' => null,
            'publicId' => null,
            'systemId' => null,
            'hasPublicId' => false,
            'hasSystemId' => false,
            'hasInternalSubset' => false,
            'internalSubsetByteLength' => 0,
            'internalSubsetCrc32' => null,
            'internalSubsetSha256' => null,
            'entityCount' => 0,
            'entityNames' => [],
            'notationCount' => 0,
            'notationNames' => [],
            'systemIdKind' => null,
            'systemIdScheme' => null,
            'systemIdAllowed' => null,
            'systemIdIssues' => [],
        ];

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument || !$dom->doctype instanceof \DOMDocumentType) {
            return $empty;
        }

        $doctype = $dom->doctype;
        $publicId = $doctype->publicId === '' ? null : $doctype->publicId;
        $systemId = $doctype->systemId === '' ? null : $doctype->systemId;
        $internalSubset = $doctype->internalSubset;
        $systemIdPolicy = $systemId === null ? null : $this->externalRelationshipTargetPolicy($systemId);
        $entityNames = $this->xmlDocumentTypeNamedNodeNames($doctype->entities);
        $notationNames = $this->xmlDocumentTypeNamedNodeNames($doctype->notations);

        return [
            'present' => true,
            'name' => $doctype->name === '' ? null : $doctype->name,
            'publicId' => $publicId,
            'systemId' => $systemId,
            'hasPublicId' => $publicId !== null,
            'hasSystemId' => $systemId !== null,
            'hasInternalSubset' => $internalSubset !== '',
            'internalSubsetByteLength' => strlen($internalSubset),
            'internalSubsetCrc32' => $internalSubset === '' ? null : sprintf('%08x', crc32($internalSubset)),
            'internalSubsetSha256' => $internalSubset === '' ? null : hash('sha256', $internalSubset),
            'entityCount' => count($entityNames),
            'entityNames' => $entityNames,
            'notationCount' => count($notationNames),
            'notationNames' => $notationNames,
            'systemIdKind' => is_array($systemIdPolicy) ? $systemIdPolicy['kind'] : null,
            'systemIdScheme' => is_array($systemIdPolicy) ? $systemIdPolicy['scheme'] : null,
            'systemIdAllowed' => is_array($systemIdPolicy) ? $systemIdPolicy['allowed'] : null,
            'systemIdIssues' => is_array($systemIdPolicy) ? $systemIdPolicy['issues'] : [],
        ];
    }

    /**
     * @return list<string>
     */
    private function xmlDocumentTypeNamedNodeNames(\DOMNamedNodeMap $nodes): array
    {
        $names = [];
        foreach ($nodes as $node) {
            if (!$node instanceof \DOMNode || $node->nodeName === '') {
                continue;
            }

            $this->appendUniqueString($names, $node->nodeName);
        }
        sort($names, SORT_STRING);

        return $names;
    }

    /**
     * @return array{count:int, targetCounts:array<string, int>, targets:list<string>, parentPathCounts:array<string, int>, parentPaths:list<string>, parentNamespaceCounts:array<string, int>, parentLocalNameCounts:array<string, int>, parentQualifiedNameCounts:array<string, int>, dataAttributeValueShapeCounts:array<string, int>, dataAttributeValueShapes:list<string>, dataAttributeTokenValueCount:int, items:list<array<string, mixed>>}
     */
    private function xmlProcessingInstructionProvenance(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'count' => 0,
                'targetCounts' => [],
                'targets' => [],
                'parentPathCounts' => [],
                'parentPaths' => [],
                'parentNamespaceCounts' => [],
                'parentLocalNameCounts' => [],
                'parentQualifiedNameCounts' => [],
                'dataAttributeValueShapeCounts' => [],
                'dataAttributeValueShapes' => [],
                'dataAttributeTokenValueCount' => 0,
                'items' => [],
            ];
        }

        $items = [];
        $targets = [];
        $targetCounts = [];
        $parentPathCounts = [];
        $parentPaths = [];
        $parentNamespaceCounts = [];
        $parentLocalNameCounts = [];
        $parentQualifiedNameCounts = [];
        $dataAttributeValueShapeCounts = [];
        $dataAttributeValueShapes = [];
        $dataAttributeTokenValueCount = 0;
        $ordinal = 0;
        $walk = function (\DOMNode $node) use (
            &$walk,
            &$items,
            &$targets,
            &$targetCounts,
            &$parentPathCounts,
            &$parentPaths,
            &$parentNamespaceCounts,
            &$parentLocalNameCounts,
            &$parentQualifiedNameCounts,
