            'attributeSetNamespaceCounts' => $attributeSetNamespaceCounts,
            'attributeSetLocalNameCounts' => $attributeSetLocalNameCounts,
            'attributeSetQualifiedNameCounts' => $attributeSetQualifiedNameCounts,
            'attributeSets' => $attributeSets,
            'cooccurrenceGroupCount' => $cooccurrenceGroupCount,
            'cooccurrencePairCount' => $cooccurrencePairCount,
            'cooccurrencePairNameCounts' => $cooccurrencePairNameCounts,
            'cooccurrencePairNames' => $cooccurrencePairNames,
            'cooccurrencePrefixPairCounts' => $cooccurrencePrefixPairCounts,
            'cooccurrencePrefixPairs' => $cooccurrencePrefixPairs,
            'cooccurrenceNamespacePairCounts' => $cooccurrenceNamespacePairCounts,
            'cooccurrenceNamespacePairs' => $cooccurrenceNamespacePairs,
            'cooccurrenceElementPathCounts' => $cooccurrenceElementPathCounts,
            'cooccurrenceElementPaths' => $cooccurrenceElementPaths,
            'cooccurrenceElementNameCounts' => $cooccurrenceElementNameCounts,
            'cooccurrenceSamePrefixPairCount' => $cooccurrenceSamePrefixPairCount,
            'cooccurrenceSameNamespacePairCount' => $cooccurrenceSameNamespacePairCount,
            'cooccurrences' => $cooccurrences,
            'items' => $items,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function xmlElementAttributeGroupProvenance(string $xml, string $partName): array
    {
        $empty = [
            'count' => 0,
            'attributeCount' => 0,
            'maxAttributeCount' => 0,
            'multiAttributeCount' => 0,
            'attributeCountBuckets' => [],
            'elementPathCounts' => [],
            'elementPaths' => [],
            'elementNamespaceCounts' => [],
            'elementLocalNameCounts' => [],
            'elementQualifiedNameCounts' => [],
            'firstAttributeNameCounts' => [],
            'lastAttributeNameCounts' => [],
            'attributeNameSequenceCounts' => [],
            'items' => [],
        ];

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument || !$dom->documentElement instanceof \DOMElement) {
            return $empty;
        }

        $items = [];
        $attributeCountBuckets = [];
        $elementPathCounts = [];
        $elementPaths = [];
        $elementNamespaceCounts = [];
        $elementLocalNameCounts = [];
        $elementQualifiedNameCounts = [];
        $firstAttributeNameCounts = [];
        $lastAttributeNameCounts = [];
        $attributeNameSequenceCounts = [];
        $attributeCount = 0;
        $maxAttributeCount = 0;
        $multiAttributeCount = 0;
        $ordinal = 0;

        $walk = function (\DOMElement $element) use (
            &$walk,
            &$items,
            &$attributeCountBuckets,
            &$elementPathCounts,
            &$elementPaths,
            &$elementNamespaceCounts,
            &$elementLocalNameCounts,
            &$elementQualifiedNameCounts,
            &$firstAttributeNameCounts,
            &$lastAttributeNameCounts,
            &$attributeNameSequenceCounts,
            &$attributeCount,
            &$maxAttributeCount,
            &$multiAttributeCount,
            &$ordinal,
        ): void {
            $attributeNames = [];
            $attributeLocalNames = [];
            $attributeNamespaces = [];
            $attributePrefixes = [];
            $hasXmlLang = false;
            $hasRelationshipAttribute = false;
            $hasUnqualifiedAttribute = false;
            $hasNamespacedAttribute = false;

            foreach ($element->attributes ?? [] as $attribute) {
                if (!$attribute instanceof \DOMAttr) {
                    continue;
                }
                if ($attribute->namespaceURI === 'http://www.w3.org/2000/xmlns/' || $attribute->nodeName === 'xmlns') {
                    continue;
                }

                $attributeName = $this->qualifiedDomAttributeName($attribute);
                $attributeNames[] = $attributeName;
                $attributeLocalNames[] = $attribute->localName;

                $attributeNamespace = $attribute->namespaceURI;
                if (is_string($attributeNamespace) && $attributeNamespace !== '') {
                    $attributeNamespaces[$attributeNamespace] = true;
                    $hasNamespacedAttribute = true;
                } else {
                    $hasUnqualifiedAttribute = true;
                }

                $attributePrefix = $this->emptyStringToNull((string) $attribute->prefix);
                if ($attributePrefix !== null) {
                    $attributePrefixes[$attributePrefix] = true;
                }

                if ($attributeNamespace === self::NS_XML && $attribute->localName === 'lang') {
                    $hasXmlLang = true;
                }
                if ($attributeNamespace === self::NS_R) {
                    $hasRelationshipAttribute = true;
                }
            }

            $elementAttributeCount = count($attributeNames);
            if ($elementAttributeCount > 0) {
                ++$ordinal;
                $elementPath = $this->xmlProvenanceParentPath($element);
                $elementDepth = $this->xmlProvenanceParentDepth($elementPath);
                $elementNamespace = is_string($element->namespaceURI) && $element->namespaceURI !== ''
                    ? $element->namespaceURI
                    : null;
                $elementLocalName = $element->localName === '' ? null : $element->localName;
                $elementQualifiedName = $element->tagName === '' ? $elementLocalName : $element->tagName;
                $elementPrefix = $this->emptyStringToNull((string) $element->prefix);
                $elementNamespaceKey = $elementNamespace ?? '(none)';
                $elementLocalNameKey = $elementLocalName ?? '(none)';
                $elementQualifiedNameKey = $elementQualifiedName ?? '(none)';
                $firstAttributeName = $attributeNames[0] ?? null;
                $lastAttributeName = $attributeNames[$elementAttributeCount - 1] ?? null;
                $attributeNameSequence = implode(' ', $attributeNames);
                $attributeCountBucket = $this->xmlElementAttributeCountBucket($elementAttributeCount);
                $attributeNamespaceList = array_keys($attributeNamespaces);
                $attributePrefixList = array_keys($attributePrefixes);

                sort($attributeNamespaceList, SORT_STRING);
                sort($attributePrefixList, SORT_STRING);

                $attributeCount += $elementAttributeCount;
                $maxAttributeCount = max($maxAttributeCount, $elementAttributeCount);
                if ($elementAttributeCount > 1) {
                    ++$multiAttributeCount;
                }
                $attributeCountBuckets[$attributeCountBucket] = ($attributeCountBuckets[$attributeCountBucket] ?? 0) + 1;
                $elementPathCounts[$elementPath] = ($elementPathCounts[$elementPath] ?? 0) + 1;
                $this->appendUniqueString($elementPaths, $elementPath);
                $elementNamespaceCounts[$elementNamespaceKey] = ($elementNamespaceCounts[$elementNamespaceKey] ?? 0) + 1;
                $elementLocalNameCounts[$elementLocalNameKey] = ($elementLocalNameCounts[$elementLocalNameKey] ?? 0) + 1;
                $elementQualifiedNameCounts[$elementQualifiedNameKey] =
                    ($elementQualifiedNameCounts[$elementQualifiedNameKey] ?? 0) + 1;
                if ($firstAttributeName !== null) {
                    $firstAttributeNameCounts[$firstAttributeName] =
                        ($firstAttributeNameCounts[$firstAttributeName] ?? 0) + 1;
                }
                if ($lastAttributeName !== null) {
                    $lastAttributeNameCounts[$lastAttributeName] =
                        ($lastAttributeNameCounts[$lastAttributeName] ?? 0) + 1;
                }
                $attributeNameSequenceCounts[$attributeNameSequence] =
                    ($attributeNameSequenceCounts[$attributeNameSequence] ?? 0) + 1;

                $items[] = [
                    'ordinal' => $ordinal,
                    'elementPath' => $elementPath,
                    'elementDepth' => $elementDepth,
                    'elementNamespace' => $elementNamespace,
                    'elementLocalName' => $elementLocalName,
                    'elementQualifiedName' => $elementQualifiedName,
                    'elementPrefix' => $elementPrefix,
                    'attributeCount' => $elementAttributeCount,
                    'attributeCountBucket' => $attributeCountBucket,
                    'attributeNames' => $attributeNames,
                    'attributeLocalNames' => $attributeLocalNames,
                    'attributeNamespaces' => $attributeNamespaceList,
                    'attributePrefixes' => $attributePrefixList,
                    'attributeNamespaceCount' => count($attributeNamespaceList),
                    'attributePrefixCount' => count($attributePrefixList),
                    'firstAttributeName' => $firstAttributeName,
                    'lastAttributeName' => $lastAttributeName,
                    'attributeNameSequenceCrc32' => $attributeNameSequence === ''
                        ? null
                        : sprintf('%08x', crc32($attributeNameSequence)),
                    'attributeNameSequenceSha256' => $attributeNameSequence === ''
                        ? null
                        : hash('sha256', $attributeNameSequence),
                    'hasXmlLang' => $hasXmlLang,
                    'hasRelationshipAttribute' => $hasRelationshipAttribute,
                    'hasUnqualifiedAttribute' => $hasUnqualifiedAttribute,
                    'hasNamespacedAttribute' => $hasNamespacedAttribute,
                ];
            }

            foreach ($element->childNodes as $child) {
                if ($child instanceof \DOMElement) {
                    $walk($child);
                }
            }
        };
        $walk($dom->documentElement);

        ksort($attributeCountBuckets, SORT_STRING);
        ksort($elementPathCounts, SORT_STRING);
        ksort($elementNamespaceCounts, SORT_STRING);
        ksort($elementLocalNameCounts, SORT_STRING);
        ksort($elementQualifiedNameCounts, SORT_STRING);
        ksort($firstAttributeNameCounts, SORT_STRING);
        ksort($lastAttributeNameCounts, SORT_STRING);
        ksort($attributeNameSequenceCounts, SORT_STRING);
        sort($elementPaths, SORT_STRING);

        return [
            'count' => count($items),
            'attributeCount' => $attributeCount,
            'maxAttributeCount' => $maxAttributeCount,
            'multiAttributeCount' => $multiAttributeCount,
            'attributeCountBuckets' => $attributeCountBuckets,
            'elementPathCounts' => $elementPathCounts,
            'elementPaths' => $elementPaths,
            'elementNamespaceCounts' => $elementNamespaceCounts,
            'elementLocalNameCounts' => $elementLocalNameCounts,
            'elementQualifiedNameCounts' => $elementQualifiedNameCounts,
            'firstAttributeNameCounts' => $firstAttributeNameCounts,
            'lastAttributeNameCounts' => $lastAttributeNameCounts,
            'attributeNameSequenceCounts' => $attributeNameSequenceCounts,
            'items' => $items,
        ];
    }

    /**
     * @return array{shape:string, tokenCount:int, containsWhitespace:bool, hasLeadingWhitespace:bool, hasTrailingWhitespace:bool}
     */
    private function xmlAttributeValueShape(string $value, \DOMAttr $attribute): array
    {
        $trimmed = trim($value);
        $tokenCount = $trimmed === ''
            ? 0
            : count(preg_split('/\s+/', $trimmed) ?: []);
        $containsWhitespace = preg_match('/\s/', $value) === 1;
        $hasLeadingWhitespace = $value !== '' && preg_match('/^\s/', $value) === 1;
        $hasTrailingWhitespace = $value !== '' && preg_match('/\s$/', $value) === 1;
        $shape = 'token';

        if ($trimmed === '') {
            $shape = 'empty';
        } elseif ($attribute->namespaceURI === self::NS_R && preg_match('/\A[A-Za-z_][A-Za-z0-9_.:-]*\z/', $trimmed) === 1) {
            $shape = 'relationship-id';
        } elseif (preg_match('/\A(?:true|false|on|off|yes|no)\z/i', $trimmed) === 1) {
            $shape = 'boolean';
        } elseif (preg_match('/\A[+-]?\d+\z/', $trimmed) === 1) {
            $shape = 'integer';
        } elseif (preg_match('/\A[+-]?(?:\d+\.\d+|\d+\.\d*|\.\d+)\z/', $trimmed) === 1) {
            $shape = 'decimal';
        } elseif (preg_match('/\A[A-Za-z_][A-Za-z0-9_.-]*:[A-Za-z_][A-Za-z0-9_.-]*\z/', $trimmed) === 1) {
            $shape = 'qname';
        } elseif (preg_match('/\A[A-Za-z][A-Za-z0-9+.-]*:/', $trimmed) === 1) {
            $shape = 'absolute-uri';
        } elseif (str_starts_with($trimmed, '//')) {
            $shape = 'network-path-reference';
        } elseif (str_starts_with($trimmed, '#')) {
            $shape = 'fragment-reference';
        } elseif ($tokenCount > 1) {
            $shape = 'token-list';
        } elseif (str_contains($trimmed, '/') || str_contains($trimmed, '\\')) {
            $shape = 'relative-reference';
        }

        return [
            'shape' => $shape,
            'tokenCount' => $tokenCount,
            'containsWhitespace' => $containsWhitespace,
            'hasLeadingWhitespace' => $hasLeadingWhitespace,
            'hasTrailingWhitespace' => $hasTrailingWhitespace,
        ];
    }

    private function xmlElementAttributeValueLengthBucket(int $byteLength): string
    {
        if ($byteLength <= 0) {
            return '0';
        }
        if ($byteLength <= 8) {
            return '1-8';
        }
        if ($byteLength <= 32) {
            return '9-32';
        }
        if ($byteLength <= 128) {
            return '33-128';
        }

        return '129+';
    }

    /**
     * @return array{shape:string, tokenCount:int, containsWhitespace:bool, hasLeadingWhitespace:bool, hasTrailingWhitespace:bool}
     */
    private function xmlPseudoAttributeValueShape(string $value): array
    {
        $trimmed = trim($value);
        $tokenCount = $trimmed === ''
            ? 0
            : count(preg_split('/\s+/', $trimmed) ?: []);
        $containsWhitespace = preg_match('/\s/', $value) === 1;
        $hasLeadingWhitespace = $value !== '' && preg_match('/^\s/', $value) === 1;
        $hasTrailingWhitespace = $value !== '' && preg_match('/\s$/', $value) === 1;
        $shape = 'token';

        if ($trimmed === '') {
            $shape = 'empty';
        } elseif (preg_match('/\A(?:true|false|on|off|yes|no)\z/i', $trimmed) === 1) {
            $shape = 'boolean';
        } elseif (preg_match('/\A[+-]?\d+\z/', $trimmed) === 1) {
            $shape = 'integer';
        } elseif (preg_match('/\A[+-]?(?:\d+\.\d+|\d+\.\d*|\.\d+)\z/', $trimmed) === 1) {
            $shape = 'decimal';
        } elseif (preg_match('/\A[A-Za-z_][A-Za-z0-9_.-]*:[A-Za-z_][A-Za-z0-9_.-]*\z/', $trimmed) === 1) {
            $shape = 'qname';
        } elseif (preg_match('/\A[A-Za-z][A-Za-z0-9+.-]*:/', $trimmed) === 1) {
            $shape = 'absolute-uri';
        } elseif (str_starts_with($trimmed, '//')) {
            $shape = 'network-path-reference';
        } elseif ($tokenCount > 1) {
            $shape = 'token-list';
        } elseif (str_contains($trimmed, '/') || str_contains($trimmed, '\\')) {
            $shape = 'relative-reference';
        }

        return [
            'shape' => $shape,
            'tokenCount' => $tokenCount,
            'containsWhitespace' => $containsWhitespace,
            'hasLeadingWhitespace' => $hasLeadingWhitespace,
            'hasTrailingWhitespace' => $hasTrailingWhitespace,
        ];
    }

    /**
     * @return array{count:int, names:list<string>, valueShapeCounts:array<string, int>, valueShapes:list<string>, tokenValueCount:int, items:list<array{name:string, valueByteLength:int, valueShape:string, valueTokenCount:int, valueContainsWhitespace:bool, valueHasLeadingWhitespace:bool, valueHasTrailingWhitespace:bool, valueCrc32:?string, valueSha256:?string}>}
     */
    private function xmlProcessingInstructionPseudoAttributes(string $data): array
    {
        preg_match_all('/([A-Za-z_][A-Za-z0-9_.:-]*)\s*=\s*(["\'])(.*?)\2/s', $data, $matches, PREG_SET_ORDER);

        $names = [];
        $valueShapeCounts = [];
        $valueShapes = [];
        $tokenValueCount = 0;
        $items = [];
        $seen = [];
        foreach ($matches as $match) {
            $name = (string) $match[1];
            if ($name === '' || isset($seen[$name])) {
                continue;
            }

            $value = (string) $match[3];
            $valueShape = $this->xmlPseudoAttributeValueShape($value);
            $valueShapeName = $valueShape['shape'];
            $seen[$name] = true;
            $names[] = $name;
            $valueShapeCounts[$valueShapeName] = ($valueShapeCounts[$valueShapeName] ?? 0) + 1;
            $this->appendUniqueString($valueShapes, $valueShapeName);
            $tokenValueCount += $valueShape['tokenCount'];
            $items[] = [
                'name' => $name,
                'valueByteLength' => strlen($value),
                'valueShape' => $valueShapeName,
                'valueTokenCount' => $valueShape['tokenCount'],
                'valueContainsWhitespace' => $valueShape['containsWhitespace'],
                'valueHasLeadingWhitespace' => $valueShape['hasLeadingWhitespace'],
                'valueHasTrailingWhitespace' => $valueShape['hasTrailingWhitespace'],
                'valueCrc32' => $value === '' ? null : sprintf('%08x', crc32($value)),
                'valueSha256' => $value === '' ? null : hash('sha256', $value),
            ];
        }

        ksort($valueShapeCounts, SORT_STRING);
        sort($names, SORT_STRING);
        sort($valueShapes, SORT_STRING);
        usort(
            $items,
            static fn (array $left, array $right): int => strcmp((string) $left['name'], (string) $right['name']),
        );

        return [
            'count' => count($items),
            'names' => $names,
            'valueShapeCounts' => $valueShapeCounts,
            'valueShapes' => $valueShapes,
            'tokenValueCount' => $tokenValueCount,
            'items' => $items,
        ];
    }

    /**
     * @return array{validXml:bool, xmlParseError:?string, namespace:?string, localName:?string, qualifiedName:?string, prefix:?string, attributeCount:int, attributeNames:list<string>, attributeNameCounts:array<string, int>, attributeValueByteLength:int, attributes:list<array{name:string, prefix:?string, namespace:?string, localName:string, valueByteLength:int, valueCrc32:?string, valueSha256:?string}>, namespaceDeclarationCount:int, namespacePrefixes:list<string>, childElementCount:int, childElementNames:list<string>, childElementNameCounts:array<string, int>, childElementNamespaceCounts:array<string, int>, childElementNamespaces:list<string>, childElementLocalNameCounts:array<string, int>, childElementPrefixCounts:array<string, int>, childElementPrefixes:list<string>, childElementFirstName:?string, childElementLastName:?string, childElements:list<array{index:int, namespace:?string, localName:string, qualifiedName:string, prefix:?string}>}
     */
    private function xmlRootProvenance(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'validXml' => false,
                'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                'namespace' => null,
                'localName' => null,
                'qualifiedName' => null,
                'prefix' => null,
                'attributeCount' => 0,
                'attributeNames' => [],
                'attributeNameCounts' => [],
                'attributeValueByteLength' => 0,
                'attributes' => [],
                'namespaceDeclarationCount' => 0,
                'namespacePrefixes' => [],
                'childElementCount' => 0,
                'childElementNames' => [],
                'childElementNameCounts' => [],
                'childElementNamespaceCounts' => [],
                'childElementNamespaces' => [],
                'childElementLocalNameCounts' => [],
                'childElementPrefixCounts' => [],
                'childElementPrefixes' => [],
                'childElementFirstName' => null,
                'childElementLastName' => null,
                'childElements' => [],
            ];
        }

        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            return [
                'validXml' => false,
                'xmlParseError' => 'missing XML document element',
                'namespace' => null,
                'localName' => null,
                'qualifiedName' => null,
                'prefix' => null,
                'attributeCount' => 0,
                'attributeNames' => [],
                'attributeNameCounts' => [],
                'attributeValueByteLength' => 0,
                'attributes' => [],
                'namespaceDeclarationCount' => 0,
                'namespacePrefixes' => [],
                'childElementCount' => 0,
                'childElementNames' => [],
                'childElementNameCounts' => [],
                'childElementNamespaceCounts' => [],
                'childElementNamespaces' => [],
                'childElementLocalNameCounts' => [],
                'childElementPrefixCounts' => [],
                'childElementPrefixes' => [],
                'childElementFirstName' => null,
                'childElementLastName' => null,
                'childElements' => [],
            ];
        }

        $attributeCount = 0;
        $attributeNames = [];
        $attributeNameCounts = [];
        $attributeValueByteLength = 0;
        $attributes = [];
        foreach ($root->attributes ?? [] as $attribute) {
            if (!$attribute instanceof \DOMAttr) {
                continue;
            }
            if ($attribute->namespaceURI === 'http://www.w3.org/2000/xmlns/' || $attribute->nodeName === 'xmlns') {
                continue;
            }

            ++$attributeCount;
            $name = $this->qualifiedDomAttributeName($attribute);
            $value = $attribute->value;
            $attributeNameCounts[$name] = ($attributeNameCounts[$name] ?? 0) + 1;
            $this->appendUniqueString($attributeNames, $name);
            $attributeValueByteLength += strlen($value);
            $attributes[] = [
                'name' => $name,
                'prefix' => $this->emptyStringToNull((string) $attribute->prefix),
                'namespace' => $attribute->namespaceURI,
                'localName' => $attribute->localName,
                'valueByteLength' => strlen($value),
                'valueCrc32' => $value === '' ? null : sprintf('%08x', crc32($value)),
                'valueSha256' => $value === '' ? null : hash('sha256', $value),
            ];
        }
        $namespaceDeclarations = $this->rootNamespaceDeclarations($xml);
        $childElementNames = [];
        $childElementNameCounts = [];
        $childElementNamespaceCounts = [];
        $childElementNamespaces = [];
        $childElementLocalNameCounts = [];
        $childElementPrefixCounts = [];
        $childElementPrefixes = [];
        $childElements = [];
        $childElementIndex = 0;
        foreach ($root->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }

            ++$childElementIndex;
            $childNamespace = is_string($child->namespaceURI) && $child->namespaceURI !== ''
                ? $child->namespaceURI
                : null;
            $childLocalName = $child->localName === '' ? '(none)' : $child->localName;
            $childQualifiedName = $child->tagName === '' ? $childLocalName : $child->tagName;
            $childPrefix = $this->emptyStringToNull((string) $child->prefix);
            $childNamespaceKey = $childNamespace ?? '(none)';
            $childPrefixKey = $childPrefix ?? '(none)';

            $childElementNameCounts[$childQualifiedName] = ($childElementNameCounts[$childQualifiedName] ?? 0) + 1;
            $childElementNamespaceCounts[$childNamespaceKey] =
                ($childElementNamespaceCounts[$childNamespaceKey] ?? 0) + 1;
            $childElementLocalNameCounts[$childLocalName] = ($childElementLocalNameCounts[$childLocalName] ?? 0) + 1;
            $childElementPrefixCounts[$childPrefixKey] = ($childElementPrefixCounts[$childPrefixKey] ?? 0) + 1;
            $this->appendUniqueString($childElementNames, $childQualifiedName);
            if ($childNamespace !== null) {
                $this->appendUniqueString($childElementNamespaces, $childNamespace);
            }
            if ($childPrefix !== null) {
                $this->appendUniqueString($childElementPrefixes, $childPrefix);
            }

            $childElements[] = [
                'index' => $childElementIndex,
                'namespace' => $childNamespace,
                'localName' => $childLocalName,
                'qualifiedName' => $childQualifiedName,
                'prefix' => $childPrefix,
            ];
        }
        ksort($attributeNameCounts, SORT_STRING);
        ksort($childElementNameCounts, SORT_STRING);
        ksort($childElementNamespaceCounts, SORT_STRING);
        ksort($childElementLocalNameCounts, SORT_STRING);
        ksort($childElementPrefixCounts, SORT_STRING);
        sort($attributeNames, SORT_STRING);
        sort($childElementNames, SORT_STRING);
        sort($childElementNamespaces, SORT_STRING);
        sort($childElementPrefixes, SORT_STRING);
        usort(
            $attributes,
            static fn (array $left, array $right): int => strcmp((string) $left['name'], (string) $right['name']),
        );

        return [
            'validXml' => true,
            'xmlParseError' => null,
            'namespace' => $root->namespaceURI,
            'localName' => $root->localName,
            'qualifiedName' => $root->tagName,
            'prefix' => $root->prefix === '' ? null : $root->prefix,
            'attributeCount' => $attributeCount,
            'attributeNames' => $attributeNames,
            'attributeNameCounts' => $attributeNameCounts,
            'attributeValueByteLength' => $attributeValueByteLength,
            'attributes' => $attributes,
            'namespaceDeclarationCount' => $namespaceDeclarations['count'],
            'namespacePrefixes' => $namespaceDeclarations['prefixes'],
            'childElementCount' => count($childElements),
            'childElementNames' => $childElementNames,
            'childElementNameCounts' => $childElementNameCounts,
            'childElementNamespaceCounts' => $childElementNamespaceCounts,
            'childElementNamespaces' => $childElementNamespaces,
            'childElementLocalNameCounts' => $childElementLocalNameCounts,
            'childElementPrefixCounts' => $childElementPrefixCounts,
            'childElementPrefixes' => $childElementPrefixes,
            'childElementFirstName' => $childElements[0]['qualifiedName'] ?? null,
            'childElementLastName' => $childElements[count($childElements) - 1]['qualifiedName'] ?? null,
            'childElements' => $childElements,
        ];
    }

    /**
     * @return array{count:int, prefixes:list<string>}
     */
    private function rootNamespaceDeclarations(string $xml): array
    {
        if (preg_match('/<(?![?!])([A-Za-z_][A-Za-z0-9_.:-]*)([^>]*)>/s', $xml, $rootMatch) !== 1) {
            return [
                'count' => 0,
                'prefixes' => [],
            ];
        }

        $prefixes = [];
        preg_match_all('/\sxmlns(?::([A-Za-z_][A-Za-z0-9_.-]*))?\s*=\s*(["\'])(.*?)\2/s', (string) $rootMatch[2], $matches, PREG_SET_ORDER);
        foreach ($matches as $match) {
            $this->appendUniqueString($prefixes, ($match[1] ?? '') === '' ? 'default' : (string) $match[1]);
        }

        return [
            'count' => count($matches),
            'prefixes' => $prefixes,
        ];
    }

    /**
     * @param array<string, mixed> $relationship
     * @return array<string, mixed>
     */
    private function relationshipProvenanceSummaryItem(array $relationship): array
    {
        $externalTargetIssues = is_array($relationship['externalTargetIssues'] ?? null)
            ? array_values(array_map('strval', $relationship['externalTargetIssues']))
            : [];
        $targetPathCharacterFlags = is_array($relationship['targetPathCharacterFlags'] ?? null)
            ? array_values(array_map('strval', $relationship['targetPathCharacterFlags']))
            : [];

        return [
            'id' => $relationship['id'] ?? '',
            'type' => $relationship['type'] ?? '',
            'sourcePart' => $relationship['sourcePart'] ?? '',
            'relationshipsPart' => $relationship['relationshipsPart'] ?? '',
            'target' => $relationship['target'] ?? '',
            'targetMode' => $relationship['targetMode'] ?? '',
            'resolvedTarget' => $relationship['resolvedTarget'] ?? '',
            'external' => (bool) ($relationship['external'] ?? false),
            'targetPart' => $relationship['targetPart'] ?? null,
            'targetReferenceSuffix' => $relationship['targetReferenceSuffix'] ?? '',
            'targetQuery' => $relationship['targetQuery'] ?? null,
            'targetFragment' => $relationship['targetFragment'] ?? null,
            'targetParentTraversalCount' => (int) ($relationship['targetParentTraversalCount'] ?? 0),
            'targetHasParentTraversal' => (bool) ($relationship['targetHasParentTraversal'] ?? false),
            'targetStartsAtPackageRoot' => (bool) ($relationship['targetStartsAtPackageRoot'] ?? false),
            'sameSourcePart' => (bool) ($relationship['sameSourcePart'] ?? false),
            'targetPathCharacterFlags' => $targetPathCharacterFlags,
            'targetHasBackslash' => (bool) ($relationship['targetHasBackslash'] ?? false),
            'targetHasEmptyPathSegment' => (bool) ($relationship['targetHasEmptyPathSegment'] ?? false),
            'targetHasCurrentDirectorySegment' => (bool) ($relationship['targetHasCurrentDirectorySegment'] ?? false),
            'targetHasPercentEncodedOctet' => (bool) ($relationship['targetHasPercentEncodedOctet'] ?? false),
            'targetHasWhitespace' => (bool) ($relationship['targetHasWhitespace'] ?? false),
            'targetHasNonAscii' => (bool) ($relationship['targetHasNonAscii'] ?? false),
            'externalTargetKind' => is_string($relationship['externalTargetKind'] ?? null) ? $relationship['externalTargetKind'] : null,
            'externalTargetScheme' => is_string($relationship['externalTargetScheme'] ?? null) ? $relationship['externalTargetScheme'] : null,
            'externalTargetAllowed' => is_bool($relationship['externalTargetAllowed'] ?? null) ? $relationship['externalTargetAllowed'] : null,
            'externalTargetIssues' => $externalTargetIssues,
            'exists' => (bool) ($relationship['exists'] ?? false),
            'contentType' => $relationship['contentType'] ?? null,
            'contentTypeBase' => $relationship['contentTypeBase'] ?? null,
            'contentTypeHasParameters' => (bool) ($relationship['contentTypeHasParameters'] ?? false),
            'contentTypeParameterCount' => (int) ($relationship['contentTypeParameterCount'] ?? 0),
            'contentTypeParameters' => $relationship['contentTypeParameters'] ?? [],
            'contentTypeParameterMap' => $relationship['contentTypeParameterMap'] ?? [],
            'contentTypeSource' => $relationship['contentTypeSource'] ?? 'missing',
            'defaultExtension' => $relationship['defaultExtension'] ?? null,
            'overridePartName' => $relationship['overridePartName'] ?? null,
        ];
    }

    /**
     * @param array<string, mixed> $relationshipPart
     * @return array<string, mixed>
     */
    private function missingRelationshipSourceSummary(string $relationshipsPart, array $relationshipPart): array
    {
        $relationships = [];
        $relationshipIds = [];
        $targetParts = [];
        $existingTargetParts = [];
        $missingTargetParts = [];
        $externalTargets = [];
        $missingContentTypeTargetParts = [];
        $targetReferenceSuffixes = [];
        $internalTargetCount = 0;
        $externalTargetCount = 0;
        $existingTargetCount = 0;
        $missingTargetCount = 0;
        $missingContentTypeCount = 0;

        foreach (($relationshipPart['relationships'] ?? []) as $relationship) {
            if (!is_array($relationship)) {
                continue;
            }

            $item = $this->relationshipProvenanceSummaryItem($relationship);
            $relationships[] = $item;
            $this->appendUniqueString($relationshipIds, is_string($item['id'] ?? null) ? $item['id'] : null);

            $targetReferenceSuffix = is_string($item['targetReferenceSuffix'] ?? null) ? $item['targetReferenceSuffix'] : '';
            if ($targetReferenceSuffix !== '') {
                $this->appendUniqueString($targetReferenceSuffixes, $targetReferenceSuffix);
            }

            if (($item['external'] ?? false) === true) {
                ++$externalTargetCount;
                $this->appendUniqueString($externalTargets, is_string($item['resolvedTarget'] ?? null) ? $item['resolvedTarget'] : null);
                continue;
            }

            ++$internalTargetCount;
            $targetPart = is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null;
            $this->appendUniqueString($targetParts, $targetPart);

            if (($item['exists'] ?? false) === true) {
                ++$existingTargetCount;
                $this->appendUniqueString($existingTargetParts, $targetPart);
            } else {
                ++$missingTargetCount;
                $this->appendUniqueString($missingTargetParts, $targetPart);
            }

            if (($item['contentTypeSource'] ?? '') === 'missing') {
                ++$missingContentTypeCount;
                $this->appendUniqueString($missingContentTypeTargetParts, $targetPart);
            }
        }

        return [
            'relationshipsPart' => $relationshipsPart,
            'sourcePart' => is_string($relationshipPart['sourcePart'] ?? null) ? $relationshipPart['sourcePart'] : '',
            'sourceExists' => false,
            'relationshipCount' => count($relationships),
            'relationshipRecordCount' => (int) ($relationshipPart['relationshipRecordCount'] ?? count($relationships)),
            'internalTargetCount' => $internalTargetCount,
            'externalTargetCount' => $externalTargetCount,
            'existingTargetCount' => $existingTargetCount,
            'missingTargetCount' => $missingTargetCount,
            'missingContentTypeCount' => $missingContentTypeCount,
            'relationshipIds' => $relationshipIds,
            'targetParts' => $targetParts,
            'existingTargetParts' => $existingTargetParts,
            'missingTargetParts' => $missingTargetParts,
            'externalTargets' => $externalTargets,
            'missingContentTypeTargetParts' => $missingContentTypeTargetParts,
            'targetReferenceSuffixes' => $targetReferenceSuffixes,
            'relationships' => $relationships,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $documentRelationships
     * @return array<string, mixed>
     */
    private function packageRelationshipPartsProvenance(
        array $parts,
        array $contentTypes,
        string $documentPart,
        string $documentRelationshipsPart,
        array $rootRelationships,
        array $documentRelationships,
    ): array {
        $relationshipParts = [
            '_rels/.rels' => $this->relationshipPartProvenance($parts, '_rels/.rels', '/', $rootRelationships, $contentTypes),
            $documentRelationshipsPart => $this->relationshipPartProvenance(
                $parts,
                $documentRelationshipsPart,
                $documentPart,
                $documentRelationships,
                $contentTypes,
            ),
        ];

        foreach ($parts as $partName => $_contents) {
            if (!$this->isRelationshipPartName($partName) || isset($relationshipParts[$partName])) {
                continue;
            }

            $relationshipParts[$partName] = $this->relationshipPartProvenance(
                $parts,
                $partName,
                $this->relationshipSourcePartForInventory($partName),
                $this->readRelationshipsPart($parts, $partName),
                $contentTypes,
            );
        }

        return $relationshipParts;
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipParts
     * @param array<string, array<string, mixed>> $partInventory
     * @return array<string, array<string, mixed>>
     */
    private function relationshipPartsWithSourceProvenance(array $relationshipParts, array $partInventory): array
    {
        foreach ($relationshipParts as $partName => $relationshipPart) {
            $sourcePart = is_string($relationshipPart['sourcePart'] ?? null) ? $relationshipPart['sourcePart'] : '';
            $source = $this->relationshipSourceProvenance($sourcePart, $partInventory);
            $relationshipPart += $source;

            foreach (['relationships', 'relationshipRecords'] as $collectionKey) {
                if (!is_array($relationshipPart[$collectionKey] ?? null)) {
                    continue;
                }

                foreach ($relationshipPart[$collectionKey] as $key => $relationship) {
                    if (!is_array($relationship)) {
                        continue;
                    }
                    $relationshipPart[$collectionKey][$key] = $relationship + $source;
                }
            }

            $relationshipParts[$partName] = $relationshipPart;
        }

        return $relationshipParts;
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return array<string, mixed>
     */
    private function relationshipSourceProvenance(string $sourcePart, array $partInventory): array
    {
        $sourceInventory = $sourcePart !== '' && $sourcePart !== '/'
            ? ($partInventory[$sourcePart] ?? null)
            : null;
        $sourceKind = $this->relationshipSourceKind($sourcePart, $sourceInventory);
        $isPackageRoot = $sourcePart === '/';
        $sourceExists = $isPackageRoot || is_array($sourceInventory);
        $sourcePathDepth = $sourcePart === ''
            ? null
            : count($this->packagePartPathSegments($sourcePart));
        $sourceDirectory = $isPackageRoot ? '/' : ($sourcePart === '' ? '' : $this->packagePartDirectory($sourcePart));
        $sourceDirectoryDepth = $sourceDirectory === '' ? null : $this->packagePartDirectoryDepth($sourceDirectory);

        return [
            'relationshipSourceKind' => $sourceKind,
            'sourceIsPackageRoot' => $isPackageRoot,
            'sourceIsRelationshipPart' => $sourcePart !== '' && $this->isRelationshipPartName($sourcePart),
            'sourceExists' => $sourceExists,
            'sourceDirectory' => $sourceDirectory,
            'sourceDirectoryDepth' => $sourceDirectoryDepth,
            'sourcePathDepth' => $sourcePathDepth,
            'sourceBaseName' => $isPackageRoot ? '/' : ($sourcePart === '' ? '' : $this->packagePartBaseName($sourcePart)),
            'sourcePartExtension' => $isPackageRoot || $sourcePart === '' ? null : $this->packagePartExtension($sourcePart),
            'sourceBytes' => is_array($sourceInventory) ? (int) ($sourceInventory['bytes'] ?? 0) : null,
            'sourceCrc32' => is_array($sourceInventory) && is_string($sourceInventory['crc32'] ?? null) ? $sourceInventory['crc32'] : null,
            'sourceSha256' => is_array($sourceInventory) && is_string($sourceInventory['sha256'] ?? null) ? $sourceInventory['sha256'] : null,
            'sourceContentType' => is_array($sourceInventory) && is_string($sourceInventory['contentType'] ?? null) ? $sourceInventory['contentType'] : null,
            'sourceContentTypeBase' => is_array($sourceInventory) && is_string($sourceInventory['contentTypeBase'] ?? null) ? $sourceInventory['contentTypeBase'] : null,
            'sourceContentTypeSource' => is_array($sourceInventory) && is_string($sourceInventory['contentTypeSource'] ?? null) ? $sourceInventory['contentTypeSource'] : null,
            'sourceContentTypeHasParameters' => is_array($sourceInventory) ? (bool) ($sourceInventory['contentTypeHasParameters'] ?? false) : false,
            'sourceContentTypeParameterCount' => is_array($sourceInventory) ? (int) ($sourceInventory['contentTypeParameterCount'] ?? 0) : 0,
            'sourceContentTypeParameters' => is_array($sourceInventory) && is_array($sourceInventory['contentTypeParameters'] ?? null) ? $sourceInventory['contentTypeParameters'] : [],
            'sourceContentTypeParameterMap' => is_array($sourceInventory) && is_array($sourceInventory['contentTypeParameterMap'] ?? null) ? $sourceInventory['contentTypeParameterMap'] : [],
            'sourceRoles' => $isPackageRoot
                ? ['package-root']
                : (is_array($sourceInventory) ? array_values(array_map('strval', $sourceInventory['roles'] ?? [])) : []),
        ];
    }

    /**
     * @param ?array<string, mixed> $sourceInventory
     */
    private function relationshipSourceKind(string $sourcePart, ?array $sourceInventory): string
    {
        if ($sourcePart === '') {
            return 'invalid-source';
        }

        if ($sourcePart === '/') {
            return 'package-root';
        }

        if ($this->isRelationshipPartName($sourcePart)) {
            return 'relationship-part';
        }

        if ($sourcePart === '[Content_Types].xml') {
            return 'content-types-item';
        }

        if (!is_array($sourceInventory)) {
            return 'missing-source';
        }

        return 'package-part';
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipParts
     * @return array<string, mixed>
     */
    private function relationshipIdTopologySummary(array $relationshipParts): array
    {
        $recordCount = 0;
        $idRecordCount = 0;
        $emptyIdRecordCount = 0;
        $partsWithIds = [];
        $shapeCounts = [];
        $prefixCounts = [];
        $numericSuffixWidthCounts = [];
        $byId = [];

        foreach ($relationshipParts as $relationshipsPart => $relationshipPart) {
            $records = is_array($relationshipPart['relationshipRecords'] ?? null)
                ? $relationshipPart['relationshipRecords']
                : [];
            if ($records === [] && is_array($relationshipPart['relationships'] ?? null)) {
                $records = array_values($relationshipPart['relationships']);
            }

            foreach ($records as $record) {
                if (!is_array($record)) {
                    continue;
                }

                ++$recordCount;
                $id = is_string($record['id'] ?? null) ? $record['id'] : '';
                if ($id === '') {
                    ++$emptyIdRecordCount;
                    continue;
                }

                ++$idRecordCount;
                $relationshipsPartName = is_string($record['relationshipsPart'] ?? null)
                    ? $record['relationshipsPart']
                    : (string) $relationshipsPart;
                $sourcePart = is_string($record['sourcePart'] ?? null)
                    ? $record['sourcePart']
                    : (is_string($relationshipPart['sourcePart'] ?? null) ? $relationshipPart['sourcePart'] : '');
                $sourceKind = is_string($record['relationshipSourceKind'] ?? null)
                    ? $record['relationshipSourceKind']
                    : (is_string($relationshipPart['relationshipSourceKind'] ?? null) ? $relationshipPart['relationshipSourceKind'] : 'unknown');
                $targetMode = is_string($record['targetMode'] ?? null) ? $record['targetMode'] : '';
                $targetModeKey = $targetMode === '' ? '(implicit-internal)' : $targetMode;
                $type = is_string($record['type'] ?? null) ? $record['type'] : '';
                $shape = $this->relationshipIdShape($id);
                $prefix = $this->relationshipIdPrefixKey($id);
                $suffixWidth = $this->relationshipIdNumericSuffixWidth($id);

                $partsWithIds[$relationshipsPartName] = true;
                $shapeCounts[$shape] = ($shapeCounts[$shape] ?? 0) + 1;
                $prefixCounts[$prefix] = ($prefixCounts[$prefix] ?? 0) + 1;
                if ($suffixWidth !== null) {
                    $numericSuffixWidthCounts[$suffixWidth] = ($numericSuffixWidthCounts[$suffixWidth] ?? 0) + 1;
                }

                if (!isset($byId[$id])) {
                    $byId[$id] = [
                        'id' => $id,
                        'recordCount' => 0,
                        'relationshipParts' => [],
                        'sourceParts' => [],
                        'relationshipTypes' => [],
                        'targetModeCounts' => [],
                        'sourceKindCounts' => [],
                        'ordinalsByRelationshipPart' => [],
                    ];
                }

                ++$byId[$id]['recordCount'];
                $this->appendUniqueString($byId[$id]['relationshipParts'], $relationshipsPartName);
                $this->appendUniqueString($byId[$id]['sourceParts'], $sourcePart);
                $this->appendUniqueString($byId[$id]['relationshipTypes'], $type);
                $byId[$id]['targetModeCounts'][$targetModeKey] =
                    ($byId[$id]['targetModeCounts'][$targetModeKey] ?? 0) + 1;
                $byId[$id]['sourceKindCounts'][$sourceKind] =
                    ($byId[$id]['sourceKindCounts'][$sourceKind] ?? 0) + 1;
                $byId[$id]['ordinalsByRelationshipPart'][$relationshipsPartName] ??= [];
                if (is_int($record['ordinal'] ?? null)) {
                    $byId[$id]['ordinalsByRelationshipPart'][$relationshipsPartName][] = $record['ordinal'];
                }
            }
        }

        ksort($shapeCounts, SORT_STRING);
        ksort($prefixCounts, SORT_STRING);
        ksort($numericSuffixWidthCounts, SORT_STRING);
        ksort($byId, SORT_STRING);

        $scopeReuseGroups = [];
        $scopeReuseIds = [];
        $scopeReuseRecordCount = 0;
        foreach ($byId as $id => $summary) {
            sort($summary['relationshipParts'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['relationshipTypes'], SORT_STRING);
            ksort($summary['targetModeCounts'], SORT_STRING);
            ksort($summary['sourceKindCounts'], SORT_STRING);
            ksort($summary['ordinalsByRelationshipPart'], SORT_STRING);
            foreach ($summary['ordinalsByRelationshipPart'] as &$ordinals) {
                sort($ordinals, SORT_NUMERIC);
            }
            unset($ordinals);

            $summary['relationshipPartCount'] = count($summary['relationshipParts']);
            $summary['sourcePartCount'] = count($summary['sourceParts']);
            if ($summary['relationshipPartCount'] < 2) {
                continue;
            }

            $scopeReuseIds[] = (string) $id;
            $scopeReuseRecordCount += (int) $summary['recordCount'];
            $scopeReuseGroups[] = $summary;
        }

        sort($scopeReuseIds, SORT_STRING);

        return [
            'recordCount' => $recordCount,
            'idRecordCount' => $idRecordCount,
            'emptyIdRecordCount' => $emptyIdRecordCount,
            'uniqueIdCount' => count($byId),
            'partCount' => count($partsWithIds),
            'shapeCounts' => $shapeCounts,
            'prefixCounts' => $prefixCounts,
            'numericSuffixWidthCounts' => $numericSuffixWidthCounts,
            'scopeReuseCount' => count($scopeReuseGroups),
            'scopeReuseRecordCount' => $scopeReuseRecordCount,
            'scopeReuseIds' => $scopeReuseIds,
            'scopeReuseGroups' => $scopeReuseGroups,
        ];
    }

    private function relationshipIdShape(string $id): string
    {
        if ($id === '') {
            return '(empty)';
        }
        if (preg_match('/^rId\d+$/', $id) === 1) {
            return 'rId-number';
        }
        if (preg_match('/^[A-Za-z_][A-Za-z0-9_.:-]*\d+$/', $id) === 1) {
            return 'xml-name-number';
        }
        if (preg_match('/^\d+$/', $id) === 1) {
            return 'numeric';
        }
        if (preg_match('/^[A-Za-z_][A-Za-z0-9_.:-]*$/', $id) === 1) {
            return 'xml-name';
        }

        return 'other';
    }

    private function relationshipIdPrefixKey(string $id): string
    {
        if ($id === '') {
            return '(empty)';
        }
        if (preg_match('/^(rId)\d+$/', $id, $matches) === 1) {
            return $matches[1];
        }
        if (preg_match('/^([A-Za-z_][A-Za-z0-9_.:-]*?)\d+$/', $id, $matches) === 1) {
            return $matches[1];
        }
        if (preg_match('/^\d+$/', $id) === 1) {
            return '(numeric)';
        }
        if (preg_match('/^[A-Za-z_][A-Za-z0-9_.:-]*$/', $id) === 1) {
            return '(non-numeric)';
        }

        return '(other)';
    }

    private function relationshipIdNumericSuffixWidth(string $id): ?string
    {
        if (preg_match('/(\d+)$/', $id, $matches) !== 1) {
            return null;
        }

        return strlen($matches[1]) . '-digit';
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipParts
     * @param array<string, array<string, mixed>> $partInventory
     * @return array<string, array<string, mixed>>
     */
    private function relationshipTypeProvenance(array $relationshipParts, array $partInventory): array
    {
        $types = [];
        foreach ($relationshipParts as $relationshipPart) {
            $relationships = $relationshipPart['relationships'] ?? [];
            if (!is_array($relationships)) {
                continue;
            }

            foreach ($relationships as $relationship) {
                if (!is_array($relationship)) {
                    continue;
                }

                $type = is_string($relationship['type'] ?? null) ? $relationship['type'] : '';
                $typeKey = $type === '' ? '(missing-type)' : $type;
                if (!isset($types[$typeKey])) {
                    $types[$typeKey] = [
                        'type' => $type,
                        'label' => $this->relationshipTypeLabel($type),
                        'count' => 0,
                        'internalCount' => 0,
                        'externalCount' => 0,
                        'existingTargetCount' => 0,
                        'missingTargetCount' => 0,
                        'missingContentTypeTargetCount' => 0,
                        'parameterizedContentTypeTargetCount' => 0,
                        'packageRootTargetCount' => 0,
                        'parentTraversalTargetCount' => 0,
                        'sameSourceTargetCount' => 0,
                        'targetPathCharacterReviewTargetCount' => 0,
                        'allowedExternalTargetCount' => 0,
                        'unsafeExternalTargetCount' => 0,
                        'targetPathCharacterFlagCounts' => [],
                        'externalTargetKindCounts' => [],
                        'externalTargetSchemeCounts' => [],
                        'externalTargetIssueCounts' => [],
                        'existingTargetPartByteLength' => 0,
                        'relationshipParts' => [],
                        'sourceParts' => [],
                        'sourceKindCounts' => [],
                        'sourceDirectoryCounts' => [],
                        'sourceContentTypeCounts' => [],
                        'sourceContentTypeSourceCounts' => [],
                        'sourceRoleCounts' => [],
                        'targetParts' => [],
                        'existingTargetParts' => [],
                        'missingTargetParts' => [],
                        'targetDirectories' => [],
                        'targetDirectoryCounts' => [],
                        'targetPartExtensions' => [],
                        'targetPartExtensionCounts' => [],
                        'targetPartWithoutExtensionCount' => 0,
                        'externalTargets' => [],
                        'unsafeExternalTargets' => [],
                        'contentTypes' => [],
                        'targetContentTypeSourceCounts' => [],
                        'targetRoleCounts' => [],
                        'existingTargetPartDigests' => [],
                        'largestExistingTargetPart' => null,
                        'relationships' => [],
                        '_seenExistingTargetParts' => [],
                    ];
                }

                $external = (bool) ($relationship['external'] ?? false);
                $exists = (bool) ($relationship['exists'] ?? false);
                $targetPart = is_string($relationship['targetPart'] ?? null) ? $relationship['targetPart'] : null;
                $targetPartExtension = $targetPart === null ? null : $this->packagePartExtension($targetPart);
                $relationshipsPart = is_string($relationship['relationshipsPart'] ?? null) ? $relationship['relationshipsPart'] : '';
                $sourcePart = is_string($relationship['sourcePart'] ?? null) ? $relationship['sourcePart'] : '';
                $target = is_string($relationship['target'] ?? null) ? $relationship['target'] : '';
                $resolvedTarget = is_string($relationship['resolvedTarget'] ?? null) ? $relationship['resolvedTarget'] : '';
                $contentType = is_string($relationship['contentType'] ?? null) ? $relationship['contentType'] : '';
                $contentTypeParameters = is_array($relationship['contentTypeParameters'] ?? null) ? $relationship['contentTypeParameters'] : [];
                $contentTypeParameterMap = is_array($relationship['contentTypeParameterMap'] ?? null) ? $relationship['contentTypeParameterMap'] : [];
                $contentTypeParameterCount = is_int($relationship['contentTypeParameterCount'] ?? null)
                    ? $relationship['contentTypeParameterCount']
                    : count($contentTypeParameters);
                $contentTypeSource = is_string($relationship['contentTypeSource'] ?? null) ? $relationship['contentTypeSource'] : '';
                $targetContentTypeSource = $contentTypeSource === '' ? 'missing' : $contentTypeSource;
                $sourceKind = is_string($relationship['relationshipSourceKind'] ?? null)
                    ? $relationship['relationshipSourceKind']
                    : 'invalid-source';
                $sourceDirectory = is_string($relationship['sourceDirectory'] ?? null)
                    ? $relationship['sourceDirectory']
                    : '';
                $sourceContentTypeBase = is_string($relationship['sourceContentTypeBase'] ?? null)
                    ? $relationship['sourceContentTypeBase']
                    : '';
                $sourceContentTypeSource = is_string($relationship['sourceContentTypeSource'] ?? null)
                    ? $relationship['sourceContentTypeSource']
                    : '';

                $types[$typeKey]['count']++;
                $types[$typeKey]['sourceKindCounts'][$sourceKind] =
                    ($types[$typeKey]['sourceKindCounts'][$sourceKind] ?? 0) + 1;
                if ($sourceDirectory !== '') {
                    $types[$typeKey]['sourceDirectoryCounts'][$sourceDirectory] =
                        ($types[$typeKey]['sourceDirectoryCounts'][$sourceDirectory] ?? 0) + 1;
                }
                if ($sourceContentTypeBase !== '') {
                    $types[$typeKey]['sourceContentTypeCounts'][$sourceContentTypeBase] =
                        ($types[$typeKey]['sourceContentTypeCounts'][$sourceContentTypeBase] ?? 0) + 1;
                }
                if ($sourceContentTypeSource !== '') {
                    $types[$typeKey]['sourceContentTypeSourceCounts'][$sourceContentTypeSource] =
                        ($types[$typeKey]['sourceContentTypeSourceCounts'][$sourceContentTypeSource] ?? 0) + 1;
                }
                foreach (array_values(array_map('strval', $relationship['sourceRoles'] ?? [])) as $sourceRole) {
                    $types[$typeKey]['sourceRoleCounts'][$sourceRole] =
                        ($types[$typeKey]['sourceRoleCounts'][$sourceRole] ?? 0) + 1;
                }
                if ($external) {
                    $types[$typeKey]['externalCount']++;
                    $this->appendUniqueString($types[$typeKey]['externalTargets'], $target);
                    $externalKind = is_string($relationship['externalTargetKind'] ?? null)
                        ? $relationship['externalTargetKind']
                        : '';
                    if ($externalKind !== '') {
                        $types[$typeKey]['externalTargetKindCounts'][$externalKind] =
                            ($types[$typeKey]['externalTargetKindCounts'][$externalKind] ?? 0) + 1;
                    }

                    $externalScheme = is_string($relationship['externalTargetScheme'] ?? null)
                        ? $relationship['externalTargetScheme']
                        : '(none)';
                    $types[$typeKey]['externalTargetSchemeCounts'][$externalScheme] =
                        ($types[$typeKey]['externalTargetSchemeCounts'][$externalScheme] ?? 0) + 1;

                    if (($relationship['externalTargetAllowed'] ?? null) === false) {
                        $types[$typeKey]['unsafeExternalTargetCount']++;
                        $types[$typeKey]['unsafeExternalTargets'][] = $this->relationshipProvenanceSummaryItem($relationship);
                    } elseif (($relationship['externalTargetAllowed'] ?? null) === true) {
                        $types[$typeKey]['allowedExternalTargetCount']++;
                    }

                    foreach (($relationship['externalTargetIssues'] ?? []) as $issue) {
                        $issue = (string) $issue;
                        if ($issue === '') {
                            continue;
                        }
                        $types[$typeKey]['externalTargetIssueCounts'][$issue] =
                            ($types[$typeKey]['externalTargetIssueCounts'][$issue] ?? 0) + 1;
                    }
                } else {
                    $types[$typeKey]['internalCount']++;
                    if (($relationship['targetHasParentTraversal'] ?? false) === true) {
                        $types[$typeKey]['parentTraversalTargetCount']++;
                    }
                    if (($relationship['targetStartsAtPackageRoot'] ?? false) === true) {
                        $types[$typeKey]['packageRootTargetCount']++;
                    }
                    if (($relationship['sameSourcePart'] ?? false) === true) {
                        $types[$typeKey]['sameSourceTargetCount']++;
                    }
                    $targetPathCharacterFlags = is_array($relationship['targetPathCharacterFlags'] ?? null)
                        ? array_values(array_map('strval', $relationship['targetPathCharacterFlags']))
                        : [];
                    if ($targetPathCharacterFlags !== []) {
                        $types[$typeKey]['targetPathCharacterReviewTargetCount']++;
                        foreach ($targetPathCharacterFlags as $targetPathCharacterFlag) {
                            if ($targetPathCharacterFlag === '') {
                                continue;
                            }

                            $types[$typeKey]['targetPathCharacterFlagCounts'][$targetPathCharacterFlag] =
                                ($types[$typeKey]['targetPathCharacterFlagCounts'][$targetPathCharacterFlag] ?? 0) + 1;
                        }
                    }
                    $this->appendUniqueString($types[$typeKey]['targetParts'], $targetPart);
                    if ($targetPart !== null) {
                        $targetPartInventory = $partInventory[$targetPart] ?? null;
                        $targetDirectory = is_array($targetPartInventory) && is_string($targetPartInventory['directory'] ?? null)
                            ? $targetPartInventory['directory']
                            : $this->packagePartDirectory($targetPart);
                        $targetPartExtension = is_array($targetPartInventory) && is_string($targetPartInventory['partExtension'] ?? null)
                            ? $targetPartInventory['partExtension']
                            : $targetPartExtension;
                        $targetPartExtensionKey = $targetPartExtension ?? '(none)';
                        $types[$typeKey]['targetDirectoryCounts'][$targetDirectory] =
                            ($types[$typeKey]['targetDirectoryCounts'][$targetDirectory] ?? 0) + 1;
                        $this->appendUniqueString($types[$typeKey]['targetDirectories'], $targetDirectory);
                        $types[$typeKey]['targetPartExtensionCounts'][$targetPartExtensionKey] =
                            ($types[$typeKey]['targetPartExtensionCounts'][$targetPartExtensionKey] ?? 0) + 1;
                        if ($targetPartExtension === null) {
                            $types[$typeKey]['targetPartWithoutExtensionCount']++;
                        } else {
                            $this->appendUniqueString($types[$typeKey]['targetPartExtensions'], $targetPartExtension);
                        }

                        $types[$typeKey]['targetContentTypeSourceCounts'][$targetContentTypeSource] =
                            ($types[$typeKey]['targetContentTypeSourceCounts'][$targetContentTypeSource] ?? 0) + 1;
                        if ($targetContentTypeSource === 'missing') {
                            $types[$typeKey]['missingContentTypeTargetCount']++;
                        }
                        if ((bool) ($relationship['contentTypeHasParameters'] ?? false)) {
                            $types[$typeKey]['parameterizedContentTypeTargetCount']++;
                        }

                        if (is_array($targetPartInventory)) {
                            foreach (($targetPartInventory['roles'] ?? []) as $role) {
                                $role = (string) $role;
                                $types[$typeKey]['targetRoleCounts'][$role] =
                                    ($types[$typeKey]['targetRoleCounts'][$role] ?? 0) + 1;
                            }

                            if ($exists && !isset($types[$typeKey]['_seenExistingTargetParts'][$targetPart])) {
                                $types[$typeKey]['_seenExistingTargetParts'][$targetPart] = true;
                                $targetPartSummary = [
                                    'partName' => $targetPart,
                                    'directory' => $targetDirectory,
                                    'partExtension' => $targetPartExtension,
                                    'bytes' => (int) ($targetPartInventory['bytes'] ?? 0),
                                    'crc32' => is_string($targetPartInventory['crc32'] ?? null) ? $targetPartInventory['crc32'] : null,
                                    'sha256' => is_string($targetPartInventory['sha256'] ?? null) ? $targetPartInventory['sha256'] : null,
                                    'contentType' => is_string($targetPartInventory['contentType'] ?? null) ? $targetPartInventory['contentType'] : '',
                                    'contentTypeBase' => is_string($targetPartInventory['contentTypeBase'] ?? null) ? $targetPartInventory['contentTypeBase'] : '',
                                    'contentTypeSource' => is_string($targetPartInventory['contentTypeSource'] ?? null) ? $targetPartInventory['contentTypeSource'] : 'missing',
                                    'roles' => array_values(array_map('strval', $targetPartInventory['roles'] ?? [])),
                                ];
                                $types[$typeKey]['existingTargetPartByteLength'] += $targetPartSummary['bytes'];
                                $types[$typeKey]['existingTargetPartDigests'][] = $targetPartSummary;
                                $largest = $types[$typeKey]['largestExistingTargetPart'];
                                if (
                                    !is_array($largest)
                                    || $targetPartSummary['bytes'] > (int) ($largest['bytes'] ?? 0)
                                    || (
                                        $targetPartSummary['bytes'] === (int) ($largest['bytes'] ?? 0)
                                        && strcmp($targetPartSummary['partName'], (string) ($largest['partName'] ?? '')) < 0
                                    )
                                ) {
                                    $types[$typeKey]['largestExistingTargetPart'] = $targetPartSummary;
                                }
                            }
                        }
                    }
                    if ($exists) {
                        $types[$typeKey]['existingTargetCount']++;
                        $this->appendUniqueString($types[$typeKey]['existingTargetParts'], $targetPart);
                    } else {
                        $types[$typeKey]['missingTargetCount']++;
                        $this->appendUniqueString($types[$typeKey]['missingTargetParts'], $targetPart);
                    }
                }

                $this->appendUniqueString($types[$typeKey]['relationshipParts'], $relationshipsPart);
                $this->appendUniqueString($types[$typeKey]['sourceParts'], $sourcePart);
                $this->appendUniqueString($types[$typeKey]['contentTypes'], $contentType);
                $types[$typeKey]['relationships'][] = [
                    'id' => is_string($relationship['id'] ?? null) ? $relationship['id'] : '',
                    'sourcePart' => $sourcePart,
                    'relationshipsPart' => $relationshipsPart,
                    'relationshipSourceKind' => $sourceKind,
                    'sourceDirectory' => $sourceDirectory,
                    'sourceContentTypeBase' => $sourceContentTypeBase === '' ? null : $sourceContentTypeBase,
                    'sourceContentTypeSource' => $sourceContentTypeSource === '' ? null : $sourceContentTypeSource,
                    'sourceRoles' => array_values(array_map('strval', $relationship['sourceRoles'] ?? [])),
                    'target' => $target,
                    'targetMode' => is_string($relationship['targetMode'] ?? null) ? $relationship['targetMode'] : '',
                    'resolvedTarget' => $resolvedTarget,
                    'external' => $external,
                    'targetPart' => $targetPart,
                    'targetPartExtension' => $targetPartExtension,
                    'exists' => $exists,
                    'contentType' => $contentType,
                    'contentTypeBase' => is_string($relationship['contentTypeBase'] ?? null) ? $relationship['contentTypeBase'] : '',
                    'contentTypeHasParameters' => (bool) ($relationship['contentTypeHasParameters'] ?? false),
                    'contentTypeParameterCount' => $contentTypeParameterCount,
                    'contentTypeParameters' => $contentTypeParameters,
                    'contentTypeParameterMap' => $contentTypeParameterMap,
                    'contentTypeSource' => $contentTypeSource,
                    'defaultExtension' => is_string($relationship['defaultExtension'] ?? null) ? $relationship['defaultExtension'] : null,
                    'overridePartName' => is_string($relationship['overridePartName'] ?? null) ? $relationship['overridePartName'] : null,
                    'targetReferenceSuffix' => is_string($relationship['targetReferenceSuffix'] ?? null) ? $relationship['targetReferenceSuffix'] : '',
                    'targetQuery' => is_string($relationship['targetQuery'] ?? null) ? $relationship['targetQuery'] : null,
                    'targetFragment' => is_string($relationship['targetFragment'] ?? null) ? $relationship['targetFragment'] : null,
                    'targetParentTraversalCount' => (int) ($relationship['targetParentTraversalCount'] ?? 0),
                    'targetHasParentTraversal' => (bool) ($relationship['targetHasParentTraversal'] ?? false),
                    'targetStartsAtPackageRoot' => (bool) ($relationship['targetStartsAtPackageRoot'] ?? false),
                    'sameSourcePart' => (bool) ($relationship['sameSourcePart'] ?? false),
                    'targetPathCharacterFlags' => is_array($relationship['targetPathCharacterFlags'] ?? null)
                        ? array_values(array_map('strval', $relationship['targetPathCharacterFlags']))
                        : [],
                    'targetHasBackslash' => (bool) ($relationship['targetHasBackslash'] ?? false),
                    'targetHasEmptyPathSegment' => (bool) ($relationship['targetHasEmptyPathSegment'] ?? false),
                    'targetHasCurrentDirectorySegment' => (bool) ($relationship['targetHasCurrentDirectorySegment'] ?? false),
                    'targetHasPercentEncodedOctet' => (bool) ($relationship['targetHasPercentEncodedOctet'] ?? false),
                    'targetHasWhitespace' => (bool) ($relationship['targetHasWhitespace'] ?? false),
                    'targetHasNonAscii' => (bool) ($relationship['targetHasNonAscii'] ?? false),
                    'externalTargetKind' => is_string($relationship['externalTargetKind'] ?? null) ? $relationship['externalTargetKind'] : null,
                    'externalTargetScheme' => is_string($relationship['externalTargetScheme'] ?? null) ? $relationship['externalTargetScheme'] : null,
                    'externalTargetAllowed' => is_bool($relationship['externalTargetAllowed'] ?? null) ? $relationship['externalTargetAllowed'] : null,
                    'externalTargetIssues' => is_array($relationship['externalTargetIssues'] ?? null)
                        ? array_values(array_map('strval', $relationship['externalTargetIssues']))
                        : [],
                ];
            }
        }

        foreach ($types as &$type) {
            ksort($type['sourceKindCounts']);
            ksort($type['sourceDirectoryCounts']);
            ksort($type['sourceContentTypeCounts']);
            ksort($type['sourceContentTypeSourceCounts']);
            ksort($type['sourceRoleCounts']);
            ksort($type['targetDirectoryCounts']);
            ksort($type['targetPartExtensionCounts']);
            ksort($type['targetPathCharacterFlagCounts']);
            ksort($type['externalTargetKindCounts']);
            ksort($type['externalTargetSchemeCounts']);
            ksort($type['externalTargetIssueCounts']);
            sort($type['targetPartExtensions'], SORT_STRING);
            ksort($type['targetContentTypeSourceCounts']);
            ksort($type['targetRoleCounts']);
            usort(
                $type['existingTargetPartDigests'],
                static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
            );
            unset($type['_seenExistingTargetParts']);
        }
        unset($type);

        ksort($types);

        return $types;
    }

    private function relationshipTypeLabel(string $type): string
    {
        if ($type === '') {
            return 'missing-type';
        }

        $trimmed = rtrim($type, '/#');
        $slash = strrpos($trimmed, '/');
        $hash = strrpos($trimmed, '#');
        $position = max($slash === false ? -1 : $slash, $hash === false ? -1 : $hash);

        return $position >= 0 && $position < strlen($trimmed) - 1
            ? substr($trimmed, $position + 1)
            : $trimmed;
    }

    /**
     * @param list<string> $values
     */
    private function appendUniqueString(array &$values, ?string $value): void
    {
        if ($value === null || $value === '') {
            return;
        }

        if (!in_array($value, $values, true)) {
            $values[] = $value;
        }
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function contentTypesPartProvenance(array $parts, array $contentTypes): array
    {
        $preflight = isset($parts['[Content_Types].xml'])
            ? OpcContentTypes::preflightXml($parts['[Content_Types].xml'])
            : null;
        $defaults = [];
        foreach ($contentTypes['defaults'] as $extension => $contentType) {
            $defaults[$extension] = [
                'extension' => $extension,
            ] + $this->contentTypeReport($contentType);
        }

        $overrides = [];
        foreach ($contentTypes['overrides'] as $partName => $contentType) {
            $overrides[$partName] = [
                'partName' => $partName,
                'exists' => isset($parts[$partName]),
            ] + $this->contentTypeReport($contentType);
        }
        $parameterizedContentTypes = $this->parameterizedContentTypeDeclarations($defaults, $overrides);
        $defaultDeclarationSummary = $this->contentTypeDefaultDeclarationSummary($parts, $contentTypes);
        $overrideDeclarationSummary = $this->contentTypeOverrideDeclarationSummary($parts, $overrides);
        $missingOverrides = array_values(array_filter(
            $overrideDeclarationSummary['declarations'],
            static fn (array $declaration): bool => ($declaration['exists'] ?? true) === false,
        ));
        usort(
            $missingOverrides,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
        );
        $invalidContentTypeRecords = $this->invalidContentTypeRecordSnapshots($preflight);
        $invalidContentTypeRecordIssueBuckets = $this->contentTypeRecordIssueBuckets($invalidContentTypeRecords);

        return [
            'partName' => '[Content_Types].xml',
            'exists' => isset($parts['[Content_Types].xml']),
            'bytes' => isset($parts['[Content_Types].xml']) ? strlen($parts['[Content_Types].xml']) : 0,
            'defaultCount' => count($defaults),
            'overrideCount' => count($overrides),
            'defaults' => $defaults,
            'overrides' => $overrides,
            'defaultDeclarationCount' => $defaultDeclarationSummary['declarationCount'],
            'usedDefaultDeclarationCount' => $defaultDeclarationSummary['usedDeclarationCount'],
            'unusedDefaultDeclarationCount' => $defaultDeclarationSummary['unusedDeclarationCount'],
            'defaultResolvedPartCount' => $defaultDeclarationSummary['defaultResolvedPartCount'],
            'overrideResolvedPartCount' => $defaultDeclarationSummary['overrideResolvedPartCount'],
            'missingDefaultContentTypePartCount' => $defaultDeclarationSummary['missingPartCount'],
            'extensionlessMissingContentTypePartCount' => $defaultDeclarationSummary['extensionlessMissingPartCount'],
            'unusedDefaultExtensions' => $defaultDeclarationSummary['unusedExtensions'],
            'missingDefaultExtensions' => $defaultDeclarationSummary['missingExtensions'],
            'defaultDeclarationIssueCounts' => $defaultDeclarationSummary['issueCounts'],
            'defaultDeclarationIssues' => $defaultDeclarationSummary['issues'],
            'defaultDeclarations' => $defaultDeclarationSummary['declarations'],
            'defaultDeclarationMissingParts' => $defaultDeclarationSummary['missingParts'],
            'overrideDeclarationCount' => $overrideDeclarationSummary['declarationCount'],
            'usedOverrideDeclarationCount' => $overrideDeclarationSummary['usedDeclarationCount'],
            'unusedOverrideDeclarationCount' => $overrideDeclarationSummary['unusedDeclarationCount'],
            'invalidOverrideDeclarationCount' => $overrideDeclarationSummary['invalidDeclarationCount'],
            'unusedOverridePartNames' => $overrideDeclarationSummary['unusedPartNames'],
            'overrideDeclarationIssueCounts' => $overrideDeclarationSummary['issueCounts'],
            'overrideDeclarationIssues' => $overrideDeclarationSummary['issues'],
            'overrideDeclarations' => $overrideDeclarationSummary['declarations'],
            'missingOverrideCount' => count($missingOverrides),
            'missingOverrideParts' => array_column($missingOverrides, 'partName'),
            'missingOverrides' => $missingOverrides,
            'parameterizedContentTypeCount' => count($parameterizedContentTypes),
            'parameterizedContentTypes' => $parameterizedContentTypes,
            'preflight' => $preflight,
            'valid' => $preflight === null ? false : $preflight['valid'],
            'xmlParseError' => $preflight === null ? null : $preflight['parseError'],
            'issues' => $preflight === null ? ['missing-content-types-part'] : $preflight['issues'],
            'issueCounts' => $preflight === null ? ['missing-content-types-part' => 1] : $preflight['issueCounts'],
            'recordCount' => $preflight === null ? 0 : $preflight['recordCount'],
            'invalidRecordCount' => $preflight === null ? 0 : $preflight['invalidCount'],
            'declaredDefaultRecordCount' => $preflight === null ? 0 : $preflight['defaultCount'],
            'declaredOverrideRecordCount' => $preflight === null ? 0 : $preflight['overrideCount'],
            'duplicateDefaultExtensionCount' => $preflight === null ? 0 : $preflight['duplicateDefaultExtensionCount'],
            'duplicateOverridePartNameCount' => $preflight === null ? 0 : $preflight['duplicateOverridePartNameCount'],
            'duplicateDefaultExtensions' => $preflight === null ? [] : $preflight['duplicateDefaultExtensions'],
            'duplicateOverridePartNames' => $preflight === null ? [] : $preflight['duplicateOverridePartNames'],
            'duplicateDefaultExtensionGroups' => $preflight === null ? [] : $preflight['duplicateDefaultExtensionGroups'],
            'duplicateOverridePartNameGroups' => $preflight === null ? [] : $preflight['duplicateOverridePartNameGroups'],
            'invalidContentTypeRecordIssueCounts' => $this->issueBucketCounts($invalidContentTypeRecordIssueBuckets),
            'invalidContentTypeRecordIssueCodes' => array_keys($invalidContentTypeRecordIssueBuckets),
            'invalidContentTypeRecordIssueBuckets' => $invalidContentTypeRecordIssueBuckets,
            'invalidContentTypeRecords' => $invalidContentTypeRecords,
        ];
    }

    /**
     * @param ?array<string, mixed> $preflight
     * @return list<array<string, mixed>>
     */
    private function invalidContentTypeRecordSnapshots(?array $preflight): array
    {
        if ($preflight === null || !is_array($preflight['records'] ?? null)) {
            return [];
        }

        $records = [];
        foreach ($preflight['records'] as $record) {
            if (!is_array($record) || ($record['valid'] ?? true) === true) {
                continue;
            }

            $records[] = [
                'recordIndex' => (int) ($record['recordIndex'] ?? count($records)),
                'kind' => is_string($record['kind'] ?? null) ? $record['kind'] : '',
                'extension' => is_string($record['extension'] ?? null) ? $record['extension'] : null,
                'normalizedExtension' => is_string($record['normalizedExtension'] ?? null) ? $record['normalizedExtension'] : null,
                'partName' => is_string($record['partName'] ?? null) ? $record['partName'] : null,
                'normalizedPartName' => is_string($record['normalizedPartName'] ?? null) ? $record['normalizedPartName'] : null,
                'contentType' => is_string($record['contentType'] ?? null) ? $record['contentType'] : null,
                'equivalenceKey' => is_string($record['equivalenceKey'] ?? null) ? $record['equivalenceKey'] : null,
                'issues' => is_array($record['issues'] ?? null)
                    ? array_values(array_map('strval', $record['issues']))
                    : [],
            ];
        }

        usort($records, static fn (array $left, array $right): int => $left['recordIndex'] <=> $right['recordIndex']);

        return $records;
    }

    /**
     * @param list<array<string, mixed>> $records
     * @return array<string, list<array<string, mixed>>>
     */
    private function contentTypeRecordIssueBuckets(array $records): array
    {
        $buckets = [];
        foreach ($records as $record) {
            $issues = is_array($record['issues'] ?? null) ? $record['issues'] : [];
            foreach ($issues as $issue) {
                $issue = (string) $issue;
                if ($issue === '') {
                    continue;
                }

                $buckets[$issue][] = [
                    'recordIndex' => (int) ($record['recordIndex'] ?? 0),
                    'kind' => is_string($record['kind'] ?? null) ? $record['kind'] : '',
                    'extension' => is_string($record['extension'] ?? null) ? $record['extension'] : null,
                    'normalizedExtension' => is_string($record['normalizedExtension'] ?? null) ? $record['normalizedExtension'] : null,
                    'partName' => is_string($record['partName'] ?? null) ? $record['partName'] : null,
                    'normalizedPartName' => is_string($record['normalizedPartName'] ?? null) ? $record['normalizedPartName'] : null,
                    'contentType' => is_string($record['contentType'] ?? null) ? $record['contentType'] : null,
                ];
            }
        }

        ksort($buckets, SORT_STRING);

        return $buckets;
    }

    /**
     * @param array<string, list<array<string, mixed>>> $buckets
     * @return array<string, int>
     */
    private function issueBucketCounts(array $buckets): array
    {
        $counts = [];
        foreach ($buckets as $issue => $records) {
            $counts[(string) $issue] = count($records);
        }

        return $counts;
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array{declarationCount:int, usedDeclarationCount:int, unusedDeclarationCount:int, defaultResolvedPartCount:int, overrideResolvedPartCount:int, missingPartCount:int, extensionlessMissingPartCount:int, unusedExtensions:list<string>, missingExtensions:list<string>, issueCounts:array<string, int>, issues:list<string>, declarations:list<array<string, mixed>>, missingParts:list<array<string, mixed>>}
     */
    private function contentTypeDefaultDeclarationSummary(array $parts, array $contentTypes): array
    {
        $declarations = [];
        foreach ($contentTypes['defaults'] as $extension => $contentType) {
            $declarations[$extension] = [
                'extension' => $extension,
                'normalizedExtension' => strtolower($extension),
                'packagePartCount' => 0,
                'relationshipPartCount' => 0,
                'byteLength' => 0,
                'packageParts' => [],
                'valid' => true,
                'issues' => [],
            ] + $this->contentTypeReport($contentType);
        }

        $defaultResolvedPartCount = 0;
        $overrideResolvedPartCount = 0;
        $missingParts = [];
        $missingExtensions = [];
        $issueCounts = [];
        $extensionlessMissingPartCount = 0;

        foreach ($parts as $partName => $contents) {
            $resolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
            $source = $resolution['contentTypeSource'] ?? 'missing';

            if ($source === 'override') {
                ++$overrideResolvedPartCount;
                continue;
            }

            if ($source === 'default') {
                ++$defaultResolvedPartCount;
                $defaultExtension = is_string($resolution['defaultExtension'] ?? null)
                    ? $resolution['defaultExtension']
                    : '';
                if (isset($declarations[$defaultExtension])) {
                    ++$declarations[$defaultExtension]['packagePartCount'];
                    $declarations[$defaultExtension]['byteLength'] += strlen($contents);
                    $declarations[$defaultExtension]['packageParts'][] = $partName;
                    if ($this->isRelationshipPartName($partName)) {
                        ++$declarations[$defaultExtension]['relationshipPartCount'];
                    }
                }
                continue;
            }

            $extension = is_string($resolution['defaultExtension'] ?? null)
                ? $resolution['defaultExtension']
                : null;
            $issues = ['missing-content-type'];
            if ($extension === null || $extension === '') {
                ++$extensionlessMissingPartCount;
                $extension = null;
                $issues[] = 'missing-content-type-extension';
            } else {
                $this->appendUniqueString($missingExtensions, $extension);
                $issues[] = 'missing-content-type-default';
            }

            foreach ($issues as $issue) {
                $issueCounts[$issue] = ($issueCounts[$issue] ?? 0) + 1;
            }

            $missingParts[] = [
                'partName' => $partName,
                'extension' => $extension,
                'bytes' => strlen($contents),
                'relationshipPart' => $this->isRelationshipPartName($partName),
                'issues' => $issues,
            ];
        }

        $usedDeclarationCount = 0;
        $unusedExtensions = [];
        foreach ($declarations as &$declaration) {
            sort($declaration['packageParts'], SORT_STRING);
            if ($declaration['packagePartCount'] > 0) {
                ++$usedDeclarationCount;
            } else {
                $unusedExtensions[] = $declaration['extension'];
            }
        }
        unset($declaration);

        sort($unusedExtensions, SORT_STRING);
        sort($missingExtensions, SORT_STRING);
        ksort($issueCounts, SORT_STRING);
        usort(
            $missingParts,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName'])
        );

        return [
            'declarationCount' => count($declarations),
            'usedDeclarationCount' => $usedDeclarationCount,
            'unusedDeclarationCount' => count($unusedExtensions),
            'defaultResolvedPartCount' => $defaultResolvedPartCount,
            'overrideResolvedPartCount' => $overrideResolvedPartCount,
            'missingPartCount' => count($missingParts),
            'extensionlessMissingPartCount' => $extensionlessMissingPartCount,
            'unusedExtensions' => $unusedExtensions,
            'missingExtensions' => $missingExtensions,
            'issueCounts' => $issueCounts,
            'issues' => array_keys($issueCounts),
            'declarations' => array_values($declarations),
            'missingParts' => $missingParts,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array<string, mixed>> $overrides
     * @return array{declarationCount:int, usedDeclarationCount:int, unusedDeclarationCount:int, invalidDeclarationCount:int, unusedPartNames:list<string>, issueCounts:array<string, int>, issues:list<string>, declarations:list<array<string, mixed>>}
     */
    private function contentTypeOverrideDeclarationSummary(array $parts, array $overrides): array
    {
        $declarations = [];
        $unusedPartNames = [];
        $issueCounts = [];
        $usedDeclarationCount = 0;
        $invalidDeclarationCount = 0;

        foreach ($overrides as $partName => $override) {
            $exists = isset($parts[$partName]);
            $relationshipPart = $this->isRelationshipPartName($partName);
            $relationshipSource = null;
            $relationshipSourceExists = null;
            $issues = [];

            if ($exists) {
                ++$usedDeclarationCount;
            } else {
                $issues[] = 'override-target-missing-part';
                $unusedPartNames[] = $partName;
            }

            $contentTypeBase = is_string($override['contentTypeBase'] ?? null)
                ? $override['contentTypeBase']
                : '';

            if ($partName === '[Content_Types].xml') {
                $issues[] = 'content-types-override-target';
            }

            if ($relationshipPart) {
                $relationshipSource = $this->relationshipSourcePartForInventory($partName);
                $relationshipSourceExists = $this->relationshipSourceExists($parts, $relationshipSource);

                if ($contentTypeBase !== self::CT_PACKAGE_RELATIONSHIPS) {
                    $issues[] = 'invalid-relationship-content-type';
                }
                if (!$relationshipSourceExists) {
                    $issues[] = 'relationship-override-source-missing';
                }
            } elseif ($contentTypeBase === self::CT_PACKAGE_RELATIONSHIPS) {
                $issues[] = 'relationship-content-type-on-non-relationship-part';
            }

            $issues = array_values(array_unique($issues));
            sort($issues, SORT_STRING);
            if ($issues !== []) {
                ++$invalidDeclarationCount;
                foreach ($issues as $issue) {
                    $issueCounts[$issue] = ($issueCounts[$issue] ?? 0) + 1;
                }
            }

            $declarations[] = [
                'partName' => $partName,
                'contentType' => is_string($override['contentType'] ?? null) ? $override['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeHasParameters' => (bool) ($override['contentTypeHasParameters'] ?? false),
                'contentTypeParameterCount' => (int) ($override['contentTypeParameterCount'] ?? 0),
                'contentTypeParameters' => is_array($override['contentTypeParameters'] ?? null) ? $override['contentTypeParameters'] : [],
                'contentTypeParameterMap' => is_array($override['contentTypeParameterMap'] ?? null) ? $override['contentTypeParameterMap'] : [],
                'exists' => $exists,
                'matchKind' => $exists ? 'exact' : 'missing',
                'relationshipPart' => $relationshipPart,
                'relationshipSource' => $relationshipSource,
                'relationshipSourceExists' => $relationshipSourceExists,
                'valid' => $issues === [],
                'issues' => $issues,
            ];
        }

        sort($unusedPartNames, SORT_STRING);
        ksort($issueCounts, SORT_STRING);

        return [
            'declarationCount' => count($declarations),
            'usedDeclarationCount' => $usedDeclarationCount,
            'unusedDeclarationCount' => count($unusedPartNames),
            'invalidDeclarationCount' => $invalidDeclarationCount,
            'unusedPartNames' => $unusedPartNames,
            'issueCounts' => $issueCounts,
            'issues' => array_keys($issueCounts),
            'declarations' => $declarations,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function relationshipPartProvenance(
        array $parts,
        string $relationshipsPart,
        string $sourcePart,
        array $relationships,
        array $contentTypes,
    ): array {
        $recordDiagnostics = $this->readRelationshipRecordsPartDiagnostics($parts, $relationshipsPart);
        $relationshipSummaries = [];
        foreach ($relationships as $id => $relationship) {
            $relationshipSummaries[$id] = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        }
        $relationshipRecords = $this->relationshipRecordProvenance(
            $parts,
            $relationshipsPart,
            $sourcePart,
            $contentTypes,
            $recordDiagnostics['records'],
        );
        $relationshipPartIssueCodes = array_values(array_map('strval', $recordDiagnostics['issues']));
        $duplicateIds = [];
        foreach ($relationshipRecords as $record) {
            if (($record['duplicateId'] ?? false) === true) {
                $duplicateIds[(string) $record['id']] = true;
            }
        }
        $duplicateItems = $this->duplicateRelationshipIdItems($relationshipRecords);
        $duplicateRecordCount = count(array_filter($relationshipRecords, static fn (array $record): bool => ($record['duplicateId'] ?? false) === true));
        $invalidRecords = array_values(array_filter($relationshipRecords, static fn (array $record): bool => ($record['valid'] ?? true) !== true));
        $recordIssueCodes = [];
        $recordIssueCount = 0;
        foreach ($invalidRecords as $record) {
            foreach (($record['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $recordIssueCodes[$issue] = true;
                    ++$recordIssueCount;
                }
            }
        }
        ksort($recordIssueCodes);

        return [
            'partName' => $relationshipsPart,
            'sourcePart' => $sourcePart,
            'sourceExists' => $this->relationshipSourceExists($parts, $sourcePart),
            'exists' => isset($parts[$relationshipsPart]),
            'bytes' => isset($parts[$relationshipsPart]) ? strlen($parts[$relationshipsPart]) : 0,
            'validXml' => $recordDiagnostics['validXml'],
            'validRoot' => $recordDiagnostics['validRoot'],
            'rootNamespace' => $recordDiagnostics['rootNamespace'],
            'rootLocalName' => $recordDiagnostics['rootLocalName'],
            'xmlParseError' => $recordDiagnostics['xmlParseError'],
            'relationshipCount' => count($relationshipSummaries),
        ] + $this->relationshipPartTargetSummary($relationshipSummaries) + [
            'relationshipRecordCount' => count($relationshipRecords),
            'relationshipPartIssueCount' => count($relationshipPartIssueCodes),
            'relationshipPartIssueCodes' => $relationshipPartIssueCodes,
            'duplicateRelationshipIdCount' => count($duplicateIds),
            'duplicateRelationshipRecordCount' => $duplicateRecordCount,
            'duplicateRelationshipIds' => array_keys($duplicateIds),
            'duplicateRelationshipIdItems' => $duplicateItems,
            'invalidRelationshipRecordCount' => count($invalidRecords),
            'relationshipRecordIssueCount' => $recordIssueCount,
            'relationshipRecordIssueCodes' => array_keys($recordIssueCodes),
            'invalidRelationshipRecords' => $invalidRecords,
            'relationships' => $relationshipSummaries,
            'relationshipRecords' => $relationshipRecords,
        ];
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipSummaries
     * @return array<string, mixed>
     */
    private function relationshipPartTargetSummary(array $relationshipSummaries): array
    {
        $internalRelationshipCount = 0;
        $externalRelationshipCount = 0;
        $existingTargetCount = 0;
        $missingTargetCount = 0;
        $missingContentTypeTargetCount = 0;
        $targetParts = [];
        $existingTargetParts = [];
        $missingTargetParts = [];
        $externalTargets = [];
        $contentTypes = [];
        $contentTypeBases = [];

        foreach ($relationshipSummaries as $relationship) {
            if (($relationship['external'] ?? false) === true) {
                ++$externalRelationshipCount;
                $this->appendUniqueString($externalTargets, is_string($relationship['target'] ?? null) ? $relationship['target'] : null);

                continue;
            }

            ++$internalRelationshipCount;
            $targetPart = is_string($relationship['targetPart'] ?? null) ? $relationship['targetPart'] : null;
            $this->appendUniqueString($targetParts, $targetPart);
            $this->appendUniqueString($contentTypes, is_string($relationship['contentType'] ?? null) ? $relationship['contentType'] : null);
            $this->appendUniqueString($contentTypeBases, is_string($relationship['contentTypeBase'] ?? null) ? $relationship['contentTypeBase'] : null);

            if (($relationship['exists'] ?? false) === true) {
                ++$existingTargetCount;
                $this->appendUniqueString($existingTargetParts, $targetPart);
            } else {
                ++$missingTargetCount;
                $this->appendUniqueString($missingTargetParts, $targetPart);
            }

            if (($relationship['contentTypeSource'] ?? '') === 'missing') {
                ++$missingContentTypeTargetCount;
            }
        }

        return [
            'internalRelationshipCount' => $internalRelationshipCount,
            'externalRelationshipCount' => $externalRelationshipCount,
            'existingTargetCount' => $existingTargetCount,
            'missingTargetCount' => $missingTargetCount,
            'missingContentTypeTargetCount' => $missingContentTypeTargetCount,
            'targetPartCount' => count($targetParts),
            'targetParts' => $targetParts,
            'existingTargetParts' => $existingTargetParts,
            'missingTargetParts' => $missingTargetParts,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypes,
            'contentTypeBases' => $contentTypeBases,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<array{ordinal:int, id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>|null $records
     * @return list<array<string, mixed>>
     */
    private function relationshipRecordProvenance(
        array $parts,
        string $relationshipsPart,
        string $sourcePart,
        array $contentTypes,
        ?array $records = null,
    ): array {
        $records ??= $this->readRelationshipRecordsPart($parts, $relationshipsPart);
        $idCounts = [];
        foreach ($records as $record) {
            $idCounts[$record['id']] = ($idCounts[$record['id']] ?? 0) + 1;
        }

        $items = [];
        foreach ($records as $record) {
            $issues = $this->relationshipRecordIssues($record);
            $summary = $this->relationshipInventorySummary($parts, $record, $sourcePart, $relationshipsPart, $contentTypes);
            $summary['ordinal'] = $record['ordinal'];
            $summary['valid'] = $issues === [];
            $summary['issues'] = $issues;
            $summary['duplicateId'] = $record['id'] !== '' && ($idCounts[$record['id']] ?? 0) > 1;
            $items[] = $summary;
        }

        return $items;
    }

    /**
     * @param array<string, mixed> $record
     * @return list<string>
     */
    private function relationshipRecordIssues(array $record): array
    {
        $issues = [];
        if (($record['id'] ?? '') === '') {
            $issues[] = 'missing-relationship-id';
        }
        if (($record['type'] ?? '') === '') {
            $issues[] = 'missing-relationship-type';
        }
        if (($record['target'] ?? '') === '') {
            $issues[] = 'missing-relationship-target';
        }

        $targetMode = is_string($record['targetMode'] ?? null) ? $record['targetMode'] : '';
        if ($targetMode !== '' && $targetMode !== 'Internal' && $targetMode !== 'External') {
            $issues[] = 'unexpected-relationship-target-mode';
        }

        return $issues;
    }

    /**
     * @param list<array<string, mixed>> $relationshipRecords
     * @return list<array<string, mixed>>
     */
    private function duplicateRelationshipIdItems(array $relationshipRecords): array
    {
        $byId = [];
        foreach ($relationshipRecords as $record) {
            $id = is_string($record['id'] ?? null) ? $record['id'] : '';
            if ($id === '') {
                continue;
            }

            $byId[$id][] = $record;
        }

        $items = [];
        foreach ($byId as $id => $records) {
            if (count($records) < 2) {
                continue;
            }

            $items[] = [
                'id' => $id,
                'relationshipsPart' => is_string($records[0]['relationshipsPart'] ?? null) ? $records[0]['relationshipsPart'] : '',
                'sourcePart' => is_string($records[0]['sourcePart'] ?? null) ? $records[0]['sourcePart'] : '',
                'ordinals' => array_column($records, 'ordinal'),
                'types' => array_column($records, 'type'),
                'targets' => array_column($records, 'target'),
                'targetModes' => array_column($records, 'targetMode'),
                'resolvedTargets' => array_column($records, 'resolvedTarget'),
                'targetParts' => array_column($records, 'targetPart'),
                'targetReferenceSuffixes' => array_column($records, 'targetReferenceSuffix'),
                'externalValues' => array_column($records, 'external'),
                'existsValues' => array_column($records, 'exists'),
                'contentTypes' => array_column($records, 'contentType'),
                'relationships' => $records,
            ];
        }

        return $items;
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function relationshipInventorySummary(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
    ): array {
        $external = $this->isExternalRelationshipTarget($relationship);
        $externalPolicy = $external ? $this->externalRelationshipTargetPolicy($relationship['target']) : null;
        $targetPart = $external || $relationship['target'] === ''
            ? null
            : $this->stripQueryAndFragment($relationship['resolvedTarget']);
        $suffix = $this->targetReferenceSuffix($relationship['resolvedTarget']);
        $contentTypeResolution = $targetPart === null
            ? $this->missingContentTypeResolution(null)
            : $this->contentTypeResolutionForPart($targetPart, $contentTypes);
        $targetPath = $this->relationshipTargetPathProvenance(
            $relationship['target'],
            $relationship['targetMode'],
            $sourcePart,
            $targetPart,
            $external,
        );

        return [
            'id' => $relationship['id'],
            'type' => $relationship['type'],
            'sourcePart' => $sourcePart,
            'relationshipsPart' => $relationshipsPart,
            'target' => $relationship['target'],
            'targetMode' => $relationship['targetMode'],
            'external' => $external,
            'resolvedTarget' => $relationship['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $suffix['query'],
            'targetFragment' => $suffix['fragment'],
            'targetReferenceSuffix' => $suffix['suffix'],
            'targetParentTraversalCount' => $targetPath['parentTraversalCount'],
            'targetHasParentTraversal' => $targetPath['hasParentTraversal'],
            'targetStartsAtPackageRoot' => $targetPath['startsAtPackageRoot'],
            'sameSourcePart' => $targetPath['sameSourcePart'],
            'targetPathCharacterFlags' => $targetPath['characterFlags'],
            'targetHasBackslash' => $targetPath['hasBackslash'],
            'targetHasEmptyPathSegment' => $targetPath['hasEmptyPathSegment'],
            'targetHasCurrentDirectorySegment' => $targetPath['hasCurrentDirectorySegment'],
            'targetHasPercentEncodedOctet' => $targetPath['hasPercentEncodedOctet'],
            'targetHasWhitespace' => $targetPath['hasWhitespace'],
            'targetHasNonAscii' => $targetPath['hasNonAscii'],
            'externalTargetKind' => is_array($externalPolicy) ? $externalPolicy['kind'] : null,
            'externalTargetScheme' => is_array($externalPolicy) ? $externalPolicy['scheme'] : null,
            'externalTargetAllowed' => is_array($externalPolicy) ? $externalPolicy['allowed'] : null,
            'externalTargetIssues' => is_array($externalPolicy) ? $externalPolicy['issues'] : [],
            'exists' => $targetPart !== null && isset($parts[$targetPart]),
            'contentType' => $contentTypeResolution['contentType'],
            'contentTypeBase' => $contentTypeResolution['contentTypeBase'],
            'contentTypeHasParameters' => $contentTypeResolution['contentTypeHasParameters'],
            'contentTypeParameterCount' => $contentTypeResolution['contentTypeParameterCount'],
            'contentTypeParameters' => $contentTypeResolution['contentTypeParameters'],
            'contentTypeParameterMap' => $contentTypeResolution['contentTypeParameterMap'],
            'contentTypeSource' => $contentTypeResolution['contentTypeSource'],
            'defaultExtension' => $contentTypeResolution['defaultExtension'],
            'overridePartName' => $contentTypeResolution['overridePartName'],
        ];
    }

    /**
     * @return array{parentTraversalCount:int, hasParentTraversal:bool, startsAtPackageRoot:bool, sameSourcePart:bool, characterFlags:list<string>, hasBackslash:bool, hasEmptyPathSegment:bool, hasCurrentDirectorySegment:bool, hasPercentEncodedOctet:bool, hasWhitespace:bool, hasNonAscii:bool}
     */
    private function relationshipTargetPathProvenance(
        string $target,
        string $targetMode,
        string $sourcePart,
        ?string $targetPart,
        bool $external,
    ): array {
        if ($external || $target === '' || $targetMode === 'External') {
            return [
                'parentTraversalCount' => 0,
                'hasParentTraversal' => false,
                'startsAtPackageRoot' => false,
                'sameSourcePart' => false,
                'characterFlags' => [],
                'hasBackslash' => false,
                'hasEmptyPathSegment' => false,
                'hasCurrentDirectorySegment' => false,
                'hasPercentEncodedOctet' => false,
                'hasWhitespace' => false,
                'hasNonAscii' => false,
            ];
        }

        $rawTargetPart = preg_replace('/[#?].*$/', '', $target) ?? $target;
        $characterFlags = [];
        $hasBackslash = str_contains($rawTargetPart, '\\');
        $separatorNormalizedTargetPart = str_replace('\\', '/', $rawTargetPart);
        $rawSegments = explode('/', ltrim($separatorNormalizedTargetPart, '/'));
        $hasEmptyPathSegment = in_array('', $rawSegments, true);
        $hasCurrentDirectorySegment = in_array('.', $rawSegments, true);
        $hasPercentEncodedOctet = preg_match('/%[0-9A-Fa-f]{2}/', $rawTargetPart) === 1;
        $hasWhitespace = preg_match('/[ \t\r\n\f\v]/', $rawTargetPart) === 1;
        $hasNonAscii = preg_match('/[^\x00-\x7F]/', $rawTargetPart) === 1;
        if ($hasBackslash) {
            $characterFlags[] = 'backslash';
        }
        if ($hasEmptyPathSegment) {
            $characterFlags[] = 'empty-path-segment';
        }
        if ($hasCurrentDirectorySegment) {
            $characterFlags[] = 'current-directory-segment';
        }
        if ($hasPercentEncodedOctet) {
            $characterFlags[] = 'percent-encoded-octet';
        }
        if ($hasWhitespace) {
            $characterFlags[] = 'whitespace';
        }
        if ($hasNonAscii) {
            $characterFlags[] = 'non-ascii';
        }
        $segments = array_values(array_filter(
            $rawSegments,
            static fn (string $segment): bool => $segment !== '' && $segment !== '.',
        ));
        $parentTraversalCount = count(array_filter($segments, static fn (string $segment): bool => $segment === '..'));
        $normalizedSourcePart = $this->normalizePartName($sourcePart);

        return [
            'parentTraversalCount' => $parentTraversalCount,
            'hasParentTraversal' => $parentTraversalCount > 0,
            'startsAtPackageRoot' => str_starts_with($separatorNormalizedTargetPart, '/'),
            'sameSourcePart' => $targetPart !== null
                && $normalizedSourcePart !== ''
                && $targetPart === $normalizedSourcePart,
            'characterFlags' => $characterFlags,
            'hasBackslash' => $hasBackslash,
            'hasEmptyPathSegment' => $hasEmptyPathSegment,
            'hasCurrentDirectorySegment' => $hasCurrentDirectorySegment,
            'hasPercentEncodedOctet' => $hasPercentEncodedOctet,
            'hasWhitespace' => $hasWhitespace,
            'hasNonAscii' => $hasNonAscii,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $documentRelationships
     * @return array<string, array<string, mixed>>
     */
    private function packagePartInventory(
        array $parts,
        array $contentTypes,
        array $rootRelationships,
        string $documentPart,
        string $documentRelationshipsPart,
        array $documentRelationships,
    ): array {
        $rolesByPart = [];
        $this->addPartRole($rolesByPart, '[Content_Types].xml', 'content-types');
        $this->addPartRole($rolesByPart, '_rels/.rels', 'package-relationships');
        $this->addPartRole($rolesByPart, $documentPart, 'office-document');
        $this->addPartRole($rolesByPart, $documentRelationshipsPart, 'office-document-relationships');
        foreach ($parts as $partName => $_contents) {
            if ($this->isRelationshipPartName($partName)) {
                $this->addPartRole($rolesByPart, $partName, 'relationship-part');
            }
        }

        foreach ($rootRelationships as $relationship) {
            if ($this->isExternalRelationshipTarget($relationship)) {
                continue;
            }
            $targetPart = $this->stripQueryAndFragment($relationship['resolvedTarget']);
            $this->addPartRole($rolesByPart, $targetPart, 'root-relationship-target');
            $this->addRelationshipTargetInventoryRole($rolesByPart, $targetPart, $relationship['type']);
        }
        foreach ($documentRelationships as $relationship) {
            if ($this->isExternalRelationshipTarget($relationship)) {
                continue;
            }
            $targetPart = $this->stripQueryAndFragment($relationship['resolvedTarget']);
            $this->addPartRole($rolesByPart, $targetPart, 'document-relationship-target');
            $this->addRelationshipTargetInventoryRole($rolesByPart, $targetPart, $relationship['type']);
        }
        $headerFooterSourceParts = [];
        $headerFooterSourceTypes = [];
        foreach ($documentRelationships as $relationship) {
            if (
                ($relationship['type'] !== self::HEADER_REL && $relationship['type'] !== self::FOOTER_REL)
                || $this->isExternalRelationshipTarget($relationship)
            ) {
                continue;
            }

            $targetPart = $this->stripQueryAndFragment($relationship['resolvedTarget']);
            $headerFooterSourceParts[$targetPart] = true;
            $headerFooterSourceTypes[$targetPart][$relationship['type'] === self::HEADER_REL ? 'header' : 'footer'] = true;
        }
        foreach ($parts as $relationshipPart => $_contents) {
            if (
                !$this->isRelationshipPartName($relationshipPart)
                || $relationshipPart === '_rels/.rels'
                || $relationshipPart === $documentRelationshipsPart
            ) {
                continue;
            }

            $relationshipSourcePart = $this->relationshipSourcePartForInventory($relationshipPart);
            $relationshipSourceContentTypeBase = '';
            if ($relationshipSourcePart !== '' && $relationshipSourcePart !== '/') {
                $relationshipSourceContentTypeBase = $this->contentTypeResolutionForPart($relationshipSourcePart, $contentTypes)['contentTypeBase'];
            }
            $isNumberingRelationshipPart = $relationshipSourceContentTypeBase === self::CT_WORD_NUMBERING;
            $isThemeRelationshipPart = $relationshipSourceContentTypeBase === self::CT_THEME;
            $isGlossaryRelationshipPart = $relationshipSourceContentTypeBase === self::CT_WORD_GLOSSARY_DOCUMENT;
            $isHeaderFooterRelationshipPart = isset($headerFooterSourceParts[$relationshipSourcePart])
                || in_array($relationshipSourceContentTypeBase, [self::CT_WORD_HEADER, self::CT_WORD_FOOTER], true);
            $isHeaderRelationshipPart = isset($headerFooterSourceTypes[$relationshipSourcePart]['header'])
                || $relationshipSourceContentTypeBase === self::CT_WORD_HEADER;
            $isFooterRelationshipPart = isset($headerFooterSourceTypes[$relationshipSourcePart]['footer'])
                || $relationshipSourceContentTypeBase === self::CT_WORD_FOOTER;
            $noteCommentMediaRole = match ($relationshipSourceContentTypeBase) {
                self::CT_WORD_FOOTNOTES => 'footnote-media',
                self::CT_WORD_ENDNOTES => 'endnote-media',
                self::CT_WORD_COMMENTS => 'comment-media',
                default => null,
            };
            $noteCommentHyperlinkRole = match ($relationshipSourceContentTypeBase) {
                self::CT_WORD_FOOTNOTES => 'footnote-hyperlink-target',
                self::CT_WORD_ENDNOTES => 'endnote-hyperlink-target',
                self::CT_WORD_COMMENTS => 'comment-hyperlink-target',
                default => null,
            };

            foreach ($this->readRelationshipsPart($parts, $relationshipPart) as $relationship) {
                if ($this->isExternalRelationshipTarget($relationship)) {
                    continue;
                }
                $targetPart = $this->stripQueryAndFragment($relationship['resolvedTarget']);
                $this->addPartRole($rolesByPart, $targetPart, 'relationship-target');
                $this->addRelationshipTargetInventoryRole($rolesByPart, $targetPart, $relationship['type']);
                if ($isNumberingRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'numbering-picture-bullet');
                }
                if ($isThemeRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'theme-media');
                }
                if ($isGlossaryRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'glossary-document-media');
                }
                if ($isGlossaryRelationshipPart && $relationship['type'] === self::HYPERLINK_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'glossary-document-hyperlink-target');
                }
                if ($isHeaderFooterRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'header-footer-media');
                }
                if ($isHeaderFooterRelationshipPart && $relationship['type'] === self::HYPERLINK_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'header-footer-hyperlink-target');
                    if ($isHeaderRelationshipPart) {
                        $this->addPartRole($rolesByPart, $targetPart, 'header-hyperlink-target');
                    }
                    if ($isFooterRelationshipPart) {
                        $this->addPartRole($rolesByPart, $targetPart, 'footer-hyperlink-target');
                    }
                }
                if ($noteCommentMediaRole !== null && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, $noteCommentMediaRole);
                    $this->addPartRole($rolesByPart, $targetPart, 'note-comment-media');
                }
                if ($noteCommentHyperlinkRole !== null && $relationship['type'] === self::HYPERLINK_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, $noteCommentHyperlinkRole);
                    $this->addPartRole($rolesByPart, $targetPart, 'note-comment-hyperlink-target');
                }
            }
        }

        $inventory = [];
        foreach ($parts as $partName => $contents) {
            $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
            $partExtension = $this->packagePartExtension($partName);
            $rawPartExtension = $this->packagePartRawExtension($partName);
            $directory = $this->packagePartDirectory($partName);
            $directoryBaseName = $this->packagePartDirectoryBaseName($directory);
            $baseName = $this->packagePartBaseName($partName);
            $baseNameStem = $this->packagePartBaseNameStem($partName);
            $pathSegments = $this->packagePartPathSegments($partName);
            $roles = array_keys($rolesByPart[$partName] ?? []);
            if ($roles === []) {
                $roles = ['package-part'];
            }
            $byteLength = strlen($contents);
            $partNameCharacterFlags = $this->packagePartNameCharacterFlags($partName);
            $pathSegmentCharacterReviews = $this->packagePartPathSegmentCharacterReviews($pathSegments);
            $pathSegmentCharacterFlags = [];
            $pathSegmentCharacterFlagCounts = [];
            foreach ($pathSegmentCharacterReviews as $pathSegmentCharacterReview) {
                foreach (($pathSegmentCharacterReview['flags'] ?? []) as $flag) {
                    if (!is_string($flag) || $flag === '') {
                        continue;
                    }

                    $this->appendUniqueString($pathSegmentCharacterFlags, $flag);
                    $pathSegmentCharacterFlagCounts[$flag] = ($pathSegmentCharacterFlagCounts[$flag] ?? 0) + 1;
                }
            }
            sort($pathSegmentCharacterFlags, SORT_STRING);
            ksort($pathSegmentCharacterFlagCounts, SORT_STRING);
            $xmlRoot = $this->packagePartXmlRootInventory($contents, $partName, $contentTypeResolution, $partExtension);
            $xmlRelationshipReferences = $this->packagePartXmlRelationshipReferenceInventory(
                $contents,
                $partName,
                $contentTypeResolution,
                $partExtension,
                $parts,
                $contentTypes,
            );

            $entry = [
                'partName' => $partName,
                'directory' => $directory,
                'directoryBaseName' => $directoryBaseName,
                'directoryDepth' => $this->packagePartDirectoryDepth($directory),
                'baseName' => $baseName,
                'baseNameStem' => $baseNameStem,
                'caseFoldBaseName' => $this->packagePartCaseFoldKey($baseName),
                'caseFoldBaseNameStem' => $this->packagePartCaseFoldKey($baseNameStem),
                'pathSegments' => $pathSegments,
                'topLevelSegment' => $pathSegments[0] ?? '',
                'pathSegmentCount' => count($pathSegments),
                'partExtension' => $partExtension,
                'rawPartExtension' => $rawPartExtension,
                'partExtensionHasUppercase' => $rawPartExtension !== null && preg_match('/[A-Z]/', $rawPartExtension) === 1,
                'partExtensionWasNormalized' => $partExtension !== null && $rawPartExtension !== null && $rawPartExtension !== $partExtension,
                'partExtensionDefaultDeclared' => $partExtension !== null && isset($contentTypes['defaults'][$partExtension]),
                'partExtensionDefaultContentType' => $partExtension === null ? null : ($contentTypes['defaults'][$partExtension] ?? null),
                'bytes' => $byteLength,
                'byteLengthBucket' => $this->packagePartByteLengthBucket($byteLength),
                'crc32' => sprintf('%08x', crc32($contents)),
                'sha256' => hash('sha256', $contents),
                'contentType' => $contentTypeResolution['contentType'],
                'contentTypeBase' => $contentTypeResolution['contentTypeBase'],
                'contentTypeHasParameters' => $contentTypeResolution['contentTypeHasParameters'],
                'contentTypeParameterCount' => $contentTypeResolution['contentTypeParameterCount'],
                'contentTypeParameters' => $contentTypeResolution['contentTypeParameters'],
                'contentTypeParameterMap' => $contentTypeResolution['contentTypeParameterMap'],
                'contentTypeSource' => $contentTypeResolution['contentTypeSource'],
                'defaultExtension' => $contentTypeResolution['defaultExtension'],
                'overridePartName' => $contentTypeResolution['overridePartName'],
                'isRelationshipPart' => $this->isRelationshipPartName($partName),
                'roles' => $roles,
                'partNameCharacterFlags' => $partNameCharacterFlags,
                'partNameHasUppercase' => in_array('uppercase', $partNameCharacterFlags, true),
                'partNameHasWhitespace' => in_array('whitespace', $partNameCharacterFlags, true),
                'partNameHasPercentEncodedOctet' => in_array('percent-encoded-octet', $partNameCharacterFlags, true),
                'partNameHasNonAscii' => in_array('non-ascii', $partNameCharacterFlags, true),
                'pathSegmentCharacterReviews' => $pathSegmentCharacterReviews,
                'pathSegmentCharacterReviewCount' => count($pathSegmentCharacterReviews),
                'pathSegmentCharacterFlags' => $pathSegmentCharacterFlags,
                'pathSegmentCharacterFlagCounts' => $pathSegmentCharacterFlagCounts,
                'pathSegmentHasUppercase' => in_array('uppercase', $pathSegmentCharacterFlags, true),
                'pathSegmentHasWhitespace' => in_array('whitespace', $pathSegmentCharacterFlags, true),
                'pathSegmentHasPercentEncodedOctet' => in_array('percent-encoded-octet', $pathSegmentCharacterFlags, true),
                'pathSegmentHasNonAscii' => in_array('non-ascii', $pathSegmentCharacterFlags, true),
            ] + $xmlRoot + $xmlRelationshipReferences;
            if ($entry['isRelationshipPart']) {
                $relationshipSourcePart = $this->relationshipSourcePartForInventory($partName);
                $entry['relationshipSourcePart'] = $relationshipSourcePart;
                $entry['relationshipSourceExists'] = $this->relationshipSourceExists($parts, $relationshipSourcePart);
            }
            $inventory[$partName] = $entry;
        }

        return $inventory;
    }

    /**
     * @return list<string>
     */
    private function packagePartNameCharacterFlags(string $partName): array
    {
        $flags = [];
        if (preg_match('/[A-Z]/', $partName) === 1) {
            $flags[] = 'uppercase';
        }
        if (preg_match('/[ \t\r\n\f\v]/', $partName) === 1) {
            $flags[] = 'whitespace';
        }
        if (preg_match('/%[0-9A-Fa-f]{2}/', $partName) === 1) {
            $flags[] = 'percent-encoded-octet';
        }
        if (preg_match('/[^\x00-\x7F]/', $partName) === 1) {
            $flags[] = 'non-ascii';
        }

        return $flags;
    }

    /**
     * @param list<string> $pathSegments
     * @return list<array{pathSegmentIndex:int, segment:string, flags:list<string>}>
     */
    private function packagePartPathSegmentCharacterReviews(array $pathSegments): array
    {
        $reviews = [];
        foreach ($pathSegments as $pathSegmentIndex => $segment) {
            if (!is_string($segment) || $segment === '') {
                continue;
            }

            $flags = $this->packagePartNameCharacterFlags($segment);
            if ($flags === []) {
                continue;
            }

            $reviews[] = [
                'pathSegmentIndex' => $pathSegmentIndex,
                'segment' => $segment,
                'flags' => $flags,
            ];
        }

        return $reviews;
    }

