    /**
     * @param array<string, string> $parts
     */
    private function relationshipSourceExists(array $parts, string $sourcePart): bool
    {
        return $sourcePart === '/' || ($sourcePart !== '' && isset($parts[$sourcePart]));
    }

    /**
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     */
    private function isExternalRelationshipTarget(array $relationship): bool
    {
        return $relationship['targetMode'] === 'External'
            || preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $relationship['resolvedTarget']) === 1;
    }

    /**
     * @return array{query:?string, fragment:?string, suffix:string}
     */
    private function targetReferenceSuffix(string $resolvedTarget): array
    {
        $fragment = null;
        $query = null;
        $suffix = '';
        $beforeFragment = $resolvedTarget;
        $fragmentPosition = strpos($resolvedTarget, '#');
        if ($fragmentPosition !== false) {
            $fragment = substr($resolvedTarget, $fragmentPosition + 1);
            $beforeFragment = substr($resolvedTarget, 0, $fragmentPosition);
            $suffix = '#' . $fragment;
        }

        $queryPosition = strpos($beforeFragment, '?');
        if ($queryPosition !== false) {
            $query = substr($beforeFragment, $queryPosition + 1);
            $suffix = '?' . $query . ($fragment === null ? '' : '#' . $fragment);
        }

        return [
            'query' => $query,
            'fragment' => $fragment,
            'suffix' => $suffix,
        ];
    }

    /**
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function contentTypeResolutionForPart(string $partName, array $contentTypes): array
    {
        $partName = $this->stripQueryAndFragment($partName);
        if (isset($contentTypes['overrides'][$partName])) {
            return [
                'contentType' => $contentTypes['overrides'][$partName],
                'contentTypeSource' => 'override',
                'defaultExtension' => null,
                'overridePartName' => $partName,
            ] + $this->contentTypeReport($contentTypes['overrides'][$partName]);
        }

        $extension = strtolower(pathinfo($partName, PATHINFO_EXTENSION));
        if ($extension !== '' && isset($contentTypes['defaults'][$extension])) {
            return [
                'contentType' => $contentTypes['defaults'][$extension],
                'contentTypeSource' => 'default',
                'defaultExtension' => $extension,
                'overridePartName' => null,
            ] + $this->contentTypeReport($contentTypes['defaults'][$extension]);
        }

        return $this->missingContentTypeResolution($extension === '' ? null : $extension);
    }

    /**
     * @return array<string, mixed>
     */
    private function missingContentTypeResolution(?string $defaultExtension): array
    {
        return [
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => $defaultExtension,
            'overridePartName' => null,
        ];
    }

    /**
     * @return array{contentType:string, contentTypeBase:string, contentTypeHasParameters:bool, contentTypeParameterCount:int, contentTypeParameters:list<array{name:string, value:string, raw:string}>, contentTypeParameterMap:array<string, string>}
     */
    private function contentTypeReport(string $contentType): array
    {
        $segments = explode(';', $contentType);
        $base = strtolower(trim((string) array_shift($segments)));
        $parameters = [];
        $parameterMap = [];

        foreach ($segments as $segment) {
            $raw = trim($segment);
            if ($raw === '') {
                continue;
            }

            $equals = strpos($raw, '=');
            $name = $equals === false ? strtolower(trim($raw)) : strtolower(trim(substr($raw, 0, $equals)));
            if ($name === '') {
                continue;
            }

            $value = $equals === false ? '' : trim(substr($raw, $equals + 1));
            if (strlen($value) >= 2 && $value[0] === '"' && substr($value, -1) === '"') {
                $value = substr($value, 1, -1);
                $value = preg_replace('/\\\\([\x20-\x7E])/', '$1', $value) ?? $value;
            }

            $parameters[] = [
                'name' => $name,
                'value' => $value,
                'raw' => $raw,
            ];
            $parameterMap[$name] = $value;
        }

        return [
            'contentType' => $contentType,
            'contentTypeBase' => $base,
            'contentTypeHasParameters' => $parameters !== [],
            'contentTypeParameterCount' => count($parameters),
            'contentTypeParameters' => $parameters,
            'contentTypeParameterMap' => $parameterMap,
        ];
    }

    private function contentTypeStructuredSyntaxSuffix(string $contentTypeBase): ?string
    {
        $slashPosition = strpos($contentTypeBase, '/');
        if ($slashPosition === false) {
            return null;
        }

        $subtype = substr($contentTypeBase, $slashPosition + 1);
        $plusPosition = strrpos($subtype, '+');
        if ($plusPosition === false || $plusPosition === strlen($subtype) - 1) {
            return null;
        }

        $suffix = strtolower(substr($subtype, $plusPosition + 1));

        return $suffix === '' ? null : $suffix;
    }

    private function contentTypeMediaTypeKey(string $contentTypeBase): string
    {
        if ($contentTypeBase === '') {
            return '(missing)';
        }

        $slashPosition = strpos($contentTypeBase, '/');
        if ($slashPosition === false || $slashPosition === 0) {
            return '(invalid)';
        }

        return strtolower(substr($contentTypeBase, 0, $slashPosition));
    }

    private function contentTypeSubtypeKey(string $contentTypeBase): string
    {
        if ($contentTypeBase === '') {
            return '(missing)';
        }

        $slashPosition = strpos($contentTypeBase, '/');
        if ($slashPosition === false || $slashPosition === 0 || $slashPosition === strlen($contentTypeBase) - 1) {
            return '(invalid)';
        }

        $subtype = substr($contentTypeBase, $slashPosition + 1);
        if ($subtype === '' || strpos($subtype, '/') !== false) {
            return '(invalid)';
        }

        return strtolower($subtype);
    }

    private function contentTypeTreeKey(string $contentTypeBase): string
    {
        $subtype = $this->contentTypeSubtypeKey($contentTypeBase);
        if ($subtype[0] === '(') {
            return $subtype;
        }

        if (!str_starts_with($subtype, 'vnd.')) {
            return 'standard';
        }

        $structuredSuffixPosition = strpos($subtype, '+');
        $vendorSubtype = $structuredSuffixPosition === false ? $subtype : substr($subtype, 0, $structuredSuffixPosition);
        $segments = explode('.', $vendorSubtype);
        if (!isset($segments[1]) || $segments[1] === '') {
            return 'vnd';
        }

        return 'vnd.' . $segments[1];
    }

    /**
     * @param array<string, array<string, mixed>> $defaults
     * @param array<string, array<string, mixed>> $overrides
     * @return list<array<string, mixed>>
     */
    private function parameterizedContentTypeDeclarations(array $defaults, array $overrides): array
    {
        $items = [];
        foreach ($defaults as $extension => $default) {
            if (($default['contentTypeHasParameters'] ?? false) !== true) {
                continue;
            }

            $items[] = [
                'kind' => 'default',
                'extension' => $extension,
                'contentType' => $default['contentType'],
                'contentTypeBase' => $default['contentTypeBase'],
                'contentTypeParameterCount' => $default['contentTypeParameterCount'],
                'contentTypeParameters' => $default['contentTypeParameters'],
                'contentTypeParameterMap' => $default['contentTypeParameterMap'],
            ];
        }

        foreach ($overrides as $partName => $override) {
            if (($override['contentTypeHasParameters'] ?? false) !== true) {
                continue;
            }

            $items[] = [
                'kind' => 'override',
                'partName' => $partName,
                'exists' => $override['exists'],
                'contentType' => $override['contentType'],
                'contentTypeBase' => $override['contentTypeBase'],
                'contentTypeParameterCount' => $override['contentTypeParameterCount'],
                'contentTypeParameters' => $override['contentTypeParameters'],
                'contentTypeParameterMap' => $override['contentTypeParameterMap'],
            ];
        }

        return $items;
    }

    private function isRelationshipPartName(string $partName): bool
    {
        return $partName === '_rels/.rels'
            || preg_match('~^_rels/[^/]+\.rels$~', $partName) === 1
            || (str_ends_with($partName, '.rels') && str_contains($partName, '/_rels/'));
    }

    private function relationshipSourcePartForInventory(string $relationshipPart): string
    {
        if ($relationshipPart === '_rels/.rels') {
            return '/';
        }

        return $this->sourcePartForRelationshipsPart($relationshipPart);
    }

    /**
     * @param array<string, array<string, mixed>> $pictureBullets
     * @return array<string, array{abstractNumId:string, levels:array<int, array<string, mixed>>}>
     */
    private function readNumbering(string $xml, string $partName, array $pictureBullets = []): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [];
        }
        $xpath = $this->xpath($dom);
        $abstracts = [];
        foreach ($this->elements($xpath, '/w:numbering/w:abstractNum') as $abstract) {
            $abstractId = $abstract->getAttributeNS(self::NS_W, 'abstractNumId');
            if ($abstractId === '') {
                continue;
            }

            $levels = [];
            foreach ($this->elements($xpath, 'w:lvl', $abstract) as $level) {
                $ilvl = (int) $level->getAttributeNS(self::NS_W, 'ilvl');
                $levelDefinition = [
                    'format' => $this->childAttr($level, 'numFmt', 'val') ?: 'decimal',
                    'text' => $this->childAttr($level, 'lvlText', 'val') ?: '%' . ($ilvl + 1) . '.',
                    'start' => max(1, (int) ($this->childAttr($level, 'start', 'val') ?: '1')),
                ];
                $pictureBulletId = $this->childAttr($level, 'lvlPicBulletId', 'val');
                if ($pictureBulletId !== '') {
                    $levelDefinition['pictureBulletId'] = $pictureBulletId;
                    if (isset($pictureBullets[$pictureBulletId])) {
                        $levelDefinition['pictureBullet'] = $pictureBullets[$pictureBulletId];
                    }
                }
                $levels[$ilvl] = $levelDefinition;
            }
            $abstracts[$abstractId] = $levels;
        }

        $numbering = [];
        foreach ($this->elements($xpath, '/w:numbering/w:num') as $num) {
            $numId = $num->getAttributeNS(self::NS_W, 'numId');
            $abstractNumId = $this->childAttr($num, 'abstractNumId', 'val');
            if ($numId === '' || $abstractNumId === '' || !isset($abstracts[$abstractNumId])) {
                continue;
            }

            $levels = $abstracts[$abstractNumId];
            foreach ($this->elements($xpath, 'w:lvlOverride', $num) as $override) {
                $ilvl = (int) $override->getAttributeNS(self::NS_W, 'ilvl');
                $startOverride = $this->childAttr($override, 'startOverride', 'val');
                if ($startOverride !== '') {
                    $levels[$ilvl]['start'] = max(1, (int) $startOverride);
                }
            }

            $numbering[$numId] = [
                'abstractNumId' => $abstractNumId,
                'levels' => $levels,
            ];
        }

        return $numbering;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readNumberingPictureBullets(
        string $xml,
        string $partName,
        array $parts,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $empty = [
            'partName' => $partName,
            'relationshipsPart' => $relationshipsPart,
            'relationshipsPartExists' => isset($parts[$relationshipsPart]),
            'count' => 0,
            'relationshipCount' => count($relationships),
            'imageRelationshipCount' => 0,
            'referencedRelationshipCount' => 0,
            'unreferencedRelationshipCount' => 0,
            'existingCount' => 0,
            'missingCount' => 0,
            'externalCount' => 0,
            'unexpectedRelationshipTypeCount' => 0,
            'missingContentTypeCount' => 0,
            'unexpectedContentTypeCount' => 0,
            'issueCount' => 0,
            'ids' => [],
            'relationshipIds' => [],
            'referencedRelationshipIds' => [],
            'unreferencedRelationshipIds' => [],
            'partNames' => [],
            'externalTargets' => [],
            'contentTypes' => [],
            'issueCodes' => [],
            'byId' => [],
            'byRelationshipId' => [],
            'items' => [],
            'byteExposurePolicy' => 'numbering-picture-bullet-bytes-blocked',
            'reviewPolicy' => 'numbering-picture-bullet-metadata-only',
        ];

        if ($xml === '') {
            return $empty;
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return $empty;
        }
        $xpath = $this->xpath($dom);
        $items = [];
        $byId = [];
        $byRelationshipId = [];
        $ids = [];
        $relationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];

        foreach ($this->elements($xpath, '/w:numbering/w:numPicBullet') as $pictureBullet) {
            $id = $pictureBullet->getAttributeNS(self::NS_W, 'numPicBulletId');
            if ($id === '') {
                continue;
            }

            $item = $this->numberingPictureBulletItem(
                $pictureBullet,
                $id,
                count($items),
                $parts,
                $partName,
                $relationshipsPart,
                $relationships,
                $contentTypes,
            );
            $items[] = $item;
            $byId[$id] = $item;
            $ids[] = $id;

            $relationshipId = is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '';
            if ($relationshipId !== '') {
                $this->appendUniqueString($relationshipIds, $relationshipId);
                $byRelationshipId[$relationshipId] = $item;
            }
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL) {
                $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            }
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }

        $imageRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] === self::IMAGE_REL) {
                $this->appendUniqueString($imageRelationshipIds, $relationship['id']);
            }
        }
        $unreferencedRelationshipIds = array_values(array_diff($imageRelationshipIds, $relationshipIds));
        ksort($issueCodes, SORT_STRING);

        return [
            'partName' => $partName,
            'relationshipsPart' => $relationshipsPart,
            'relationshipsPartExists' => isset($parts[$relationshipsPart]),
            'count' => count($items),
            'relationshipCount' => count($relationships),
            'imageRelationshipCount' => count($imageRelationshipIds),
            'referencedRelationshipCount' => count($relationshipIds),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => ($item['relationshipType'] ?? null) === self::IMAGE_REL && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-numbering-picture-bullet-image', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => ($item['relationshipType'] ?? null) === self::IMAGE_REL && $item['external'] === true)),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-numbering-picture-bullet-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-numbering-picture-bullet-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'ids' => $ids,
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $relationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byId' => $byId,
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'numbering-picture-bullet-bytes-blocked',
            'reviewPolicy' => 'numbering-picture-bullet-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function numberingPictureBulletItem(
        \DOMElement $pictureBullet,
        string $id,
        int $index,
        array $parts,
        string $partName,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $item = [
            'index' => $index,
            'id' => $id,
            'sourcePart' => $partName,
            'relationshipsPart' => $relationshipsPart,
            'relationshipsPartExists' => isset($parts[$relationshipsPart]),
            'relationshipId' => null,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'external' => false,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'exists' => false,
            'byteLength' => null,
            'bytes' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'shapeAlt' => null,
            'title' => null,
            'byteExposurePolicy' => 'numbering-picture-bullet-bytes-blocked',
            'reviewPolicy' => 'numbering-picture-bullet-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        $imageData = $this->firstDescendantElementByNamespace($pictureBullet, self::NS_V, 'imagedata');
        if (!$imageData instanceof \DOMElement) {
            $item['issues'][] = 'missing-image-data';
            return $item;
        }

        $title = trim($imageData->getAttributeNS(self::NS_O, 'title'));
        if ($title !== '') {
            $item['title'] = $title;
        }
        $shape = $imageData->parentNode;
        if ($shape instanceof \DOMElement && $shape->namespaceURI === self::NS_V && $shape->localName === 'shape') {
            $alt = trim($shape->getAttribute('alt'));
            if ($alt !== '') {
                $item['shapeAlt'] = $alt;
            }
        }

        $relationshipId = $imageData->getAttributeNS(self::NS_R, 'id');
        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        $item['relationshipId'] = $relationshipId;
        if (!isset($parts[$relationshipsPart])) {
            $item['issues'][] = 'missing-numbering-relationships';
            return $item;
        }

        $relationship = $relationships[$relationshipId] ?? null;
        if (!is_array($relationship)) {
            $item['issues'][] = 'missing-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $partName, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) ($summary['exists'] ?? false);
        $external = (bool) ($summary['external'] ?? false);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['external'] = $external;
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['bytes'] = $item['byteLength'];
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $contentTypeBase;
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::IMAGE_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($external) {
            $item['issues'][] = 'external-numbering-picture-bullet';
            foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $item['issues'][] = $issue;
                }
            }
        } else {
            if (!$exists) {
                $item['issues'][] = 'missing-numbering-picture-bullet-image';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-numbering-picture-bullet-content-type';
            } elseif (!str_starts_with($contentTypeBase, 'image/')) {
                $item['issues'][] = 'unexpected-numbering-picture-bullet-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @return array<string, mixed>
     */
    private function readCoreProperties(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $meta = [];
        foreach ([
            'title' => 'string(/cp:coreProperties/dc:title)',
            'creator' => 'string(/cp:coreProperties/dc:creator)',
            'description' => 'string(/cp:coreProperties/dc:description)',
            'subject' => 'string(/cp:coreProperties/dc:subject)',
            'keywords' => 'string(/cp:coreProperties/cp:keywords)',
            'created' => 'string(/cp:coreProperties/dcterms:created)',
            'modified' => 'string(/cp:coreProperties/dcterms:modified)',
        ] as $name => $query) {
            $value = trim((string) $xpath->evaluate($query));
            if ($value !== '') {
                $meta[$name] = $value;
            }
        }

        if (isset($meta['creator'])) {
            $meta['author'] = [$meta['creator']];
            $meta['authors'] = [$meta['creator']];
        }
        if (isset($meta['title'])) {
            $meta['titleInlines'] = [new AstNode('text', ['text' => $meta['title']])];
        }

        return $meta;
    }

    /**
     * @return array<string, mixed>
     */
    private function readExtendedProperties(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $properties = [];

        foreach ([
            'Template' => 'template',
            'Manager' => 'manager',
            'Company' => 'company',
            'Application' => 'application',
            'AppVersion' => 'appVersion',
            'HyperlinkBase' => 'hyperlinkBase',
        ] as $source => $target) {
            $value = $this->extendedPropertyText($xpath, $source);
            if ($value !== '') {
                $properties[$target] = $value;
            }
        }

        foreach ([
            'Pages' => 'pages',
            'Words' => 'words',
            'Characters' => 'characters',
            'CharactersWithSpaces' => 'charactersWithSpaces',
            'Lines' => 'lines',
            'Paragraphs' => 'paragraphs',
            'DocSecurity' => 'docSecurity',
        ] as $source => $target) {
            $value = $this->extendedPropertyText($xpath, $source);
            if ($value !== '' && is_numeric($value)) {
                $properties[$target] = (int) $value;
            }
        }

        foreach ([
            'ScaleCrop' => 'scaleCrop',
            'LinksUpToDate' => 'linksUpToDate',
            'SharedDoc' => 'sharedDoc',
            'HyperlinksChanged' => 'hyperlinksChanged',
        ] as $source => $target) {
            $element = $this->firstElement($xpath, '/ep:Properties/ep:' . $source, $dom);
            if ($element instanceof \DOMElement) {
                $properties[$target] = $this->openXmlBooleanText($element->textContent);
            }
        }

        $headingPairs = $this->extendedHeadingPairs($xpath, $dom);
        if ($headingPairs !== []) {
            $properties['headingPairs'] = $headingPairs;
        }
        $headingPairsVector = $this->firstElement($xpath, '/ep:Properties/ep:HeadingPairs/vt:vector', $dom);
        if ($headingPairsVector instanceof \DOMElement) {
            $properties['headingPairsVector'] = $this->extendedHeadingPairsVectorProvenance($headingPairsVector);
        }

        $titlesOfParts = $this->extendedTitlesOfParts($xpath, $dom);
        if ($titlesOfParts !== []) {
            $properties['titlesOfParts'] = $titlesOfParts;
        }
        $titlesOfPartsVector = $this->firstElement($xpath, '/ep:Properties/ep:TitlesOfParts/vt:vector', $dom);
        if ($titlesOfPartsVector instanceof \DOMElement) {
            $properties['titlesOfPartsVector'] = $this->docPropsVectorProvenance(
                $titlesOfPartsVector,
                'extended-titles-of-parts',
                'lpstr',
            ) + [
                'titleCount' => count($titlesOfParts),
            ];
        }

        return $properties;
    }

    private function extendedPropertyText(\DOMXPath $xpath, string $localName): string
    {
        return trim((string) $xpath->evaluate('string(/ep:Properties/ep:' . $localName . ')'));
    }

    /**
     * @return list<array{name:string, count:int}>
     */
    private function extendedHeadingPairs(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $vector = $this->firstElement($xpath, '/ep:Properties/ep:HeadingPairs/vt:vector', $dom);
        if (!$vector instanceof \DOMElement) {
            return [];
        }

        $values = $this->docPropsVectorValues($vector);
        $pairs = [];
        for ($index = 0; $index + 1 < count($values); $index += 2) {
            $name = trim((string) $values[$index]);
            $count = $values[$index + 1];
            if ($name !== '' && is_int($count)) {
                $pairs[] = ['name' => $name, 'count' => $count];
            }
        }

        return $pairs;
    }

    /**
     * @return list<string>
     */
    private function extendedTitlesOfParts(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $vector = $this->firstElement($xpath, '/ep:Properties/ep:TitlesOfParts/vt:vector', $dom);
        if (!$vector instanceof \DOMElement) {
            return [];
        }

        $titles = [];
        foreach ($this->docPropsVectorValues($vector) as $value) {
            $title = trim((string) $value);
            if ($title !== '') {
                $titles[] = $title;
            }
        }

        return $titles;
    }

    /**
     * @return array<string, mixed>
     */
    private function extendedHeadingPairsVectorProvenance(\DOMElement $vector): array
    {
        $values = $this->docPropsVectorValues($vector);
        $types = $this->docPropsVectorValueTypes($vector);
        $issues = [];
        $items = [];
        $validPairCount = 0;
        $invalidPairCount = 0;
        $unpairedValueCount = count($values) % 2;

        for ($index = 0; $index < count($values); $index += 2) {
            $pairIssues = [];
            $nameValue = $values[$index] ?? null;
            $name = is_scalar($nameValue) ? trim((string) $nameValue) : '';
            if ($name === '') {
                $pairIssues[] = 'extended-heading-pairs-empty-name';
            }

            $countValuePresent = array_key_exists($index + 1, $values);
            $countValue = $countValuePresent ? $values[$index + 1] : null;
            $count = is_int($countValue) ? $countValue : null;
            if (!$countValuePresent) {
                $pairIssues[] = 'extended-heading-pairs-unpaired-value';
            } elseif ($count === null) {
                $pairIssues[] = 'extended-heading-pairs-non-integer-count';
            }

            $pairIssues = array_values(array_unique($pairIssues));
            sort($pairIssues, SORT_STRING);
            foreach ($pairIssues as $issue) {
                $issues[$issue] = true;
            }

            if ($pairIssues === []) {
                ++$validPairCount;
            } else {
                ++$invalidPairCount;
            }

            $items[] = [
                'index' => intdiv($index, 2),
                'name' => $name !== '' ? $name : null,
                'count' => $count,
                'nameValueType' => $types[$index] ?? null,
                'countValueType' => $types[$index + 1] ?? null,
                'valid' => $pairIssues === [],
                'issues' => $pairIssues,
            ];
        }

        $provenance = $this->docPropsVectorProvenance($vector, 'extended-heading-pairs', 'variant');
        foreach (($provenance['issueCodes'] ?? []) as $issue) {
            if (is_string($issue) && $issue !== '') {
                $issues[$issue] = true;
            }
        }
        ksort($issues, SORT_STRING);
        $provenance['pairRecordCount'] = count($items);
        $provenance['validPairCount'] = $validPairCount;
        $provenance['invalidPairCount'] = $invalidPairCount;
        $provenance['unpairedValueCount'] = $unpairedValueCount;
        $provenance['issueCount'] = count($issues);
        $provenance['issueCodes'] = array_keys($issues);
        $provenance['items'] = $items;

        return $provenance;
    }

    /**
     * @return array<string, mixed>
     */
    private function docPropsVectorProvenance(\DOMElement $vector, string $issuePrefix, ?string $expectedBaseType): array
    {
        $values = $this->docPropsVectorValues($vector);
        $types = $this->docPropsVectorValueTypes($vector);
        $issues = [];
        $provenance = [
            'valueCount' => count($values),
            'valueItemTypes' => $types,
        ];

        $declaredValueCount = null;
        $size = trim($vector->getAttribute('size'));
        if ($size !== '') {
            if (ctype_digit($size)) {
                $declaredValueCount = (int) $size;
                $provenance['declaredValueCount'] = $declaredValueCount;
                $provenance['declaredValueCountMatchesActual'] = $declaredValueCount === count($values);
                if ($declaredValueCount !== count($values)) {
                    $issues[] = $issuePrefix . '-vector-size-mismatch';
                }
            } else {
                $provenance['declaredValueCountRawByteLength'] = strlen($size);
                $provenance['declaredValueCountRawCrc32'] = sprintf('%08x', crc32($size));
                $provenance['declaredValueCountRawSha256'] = hash('sha256', $size);
                $issues[] = $issuePrefix . '-non-numeric-vector-size';
            }
        }

        $baseType = trim($vector->getAttribute('baseType'));
        if ($baseType !== '') {
            $provenance['valueBaseType'] = $baseType;
        }
        if ($expectedBaseType !== null) {
            $provenance['expectedBaseType'] = $expectedBaseType;
            $provenance['baseTypeMatchesExpected'] = $baseType === '' || $baseType === $expectedBaseType;
            if ($baseType !== '' && $baseType !== $expectedBaseType) {
                $issues[] = $issuePrefix . '-unexpected-base-type';
            }
        }

        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);
        $provenance['issueCount'] = count($issues);
        $provenance['issueCodes'] = $issues;

        return $provenance;
    }

    /**
     * @return array{count:int, duplicateNameCount:int, duplicateNames:list<string>, items:list<array<string, mixed>>, byName:array<string, mixed>}
     */
    private function readCustomProperties(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $items = [];
        $byName = [];
        $seenNames = [];
        $duplicateNames = [];

        foreach ($this->elements($xpath, '/cust:Properties/cust:property') as $property) {
            $name = trim($property->getAttribute('name'));
            if ($name === '') {
                continue;
            }

            $valueElement = $this->firstDocPropsValueElement($property);
            if (!$valueElement instanceof \DOMElement) {
                continue;
            }

            $value = $this->docPropsTypedValue($valueElement);
            $duplicate = isset($seenNames[$name]);
            $seenNames[$name] = true;
            if ($duplicate) {
                $duplicateNames[$name] = true;
            } else {
                $byName[$name] = $value;
            }

            $item = [
                'name' => $name,
                'valueType' => $valueElement->localName,
                'value' => $value,
                'duplicate' => $duplicate,
            ] + $this->docPropsAggregateValueMetadata($valueElement);
            $pid = $property->getAttribute('pid');
            if ($pid !== '' && is_numeric($pid)) {
                $item['pid'] = (int) $pid;
            }
            $fmtid = trim($property->getAttribute('fmtid'));
            if ($fmtid !== '') {
                $item['fmtid'] = $fmtid;
            }

            $items[] = $item;
        }

        if ($items === []) {
            return [];
        }

        return [
            'count' => count($items),
            'duplicateNameCount' => count($duplicateNames),
            'duplicateNames' => array_keys($duplicateNames),
            'items' => $items,
            'byName' => $byName,
        ];
    }

    /**
     * @return list<mixed>
     */
    private function docPropsVectorValues(\DOMElement $vector): array
    {
        $values = [];
        foreach ($vector->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_VT) {
                continue;
            }

            if ($child->localName === 'variant') {
                $valueElement = $this->firstDocPropsValueElement($child);
                if ($valueElement instanceof \DOMElement) {
                    $values[] = $this->docPropsTypedValue($valueElement);
                }
                continue;
            }

            $values[] = $this->docPropsTypedValue($child);
        }

        return $values;
    }

    private function firstDocPropsValueElement(\DOMElement $parent): ?\DOMElement
    {
        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_VT) {
                return $child;
            }
        }

        return null;
    }

    private function docPropsTypedValue(\DOMElement $valueElement): mixed
    {
        $value = trim($valueElement->textContent);

        return match ($valueElement->localName) {
            'array', 'vector' => $this->docPropsVectorValues($valueElement),
            'bool' => $this->openXmlBooleanText($value),
            'i1', 'i2', 'i4', 'i8', 'int', 'ui1', 'ui2', 'ui4', 'ui8', 'uint' => is_numeric($value) ? (int) $value : 0,
            'r4', 'r8', 'decimal' => is_numeric($value) ? (float) $value : 0.0,
            default => $value,
        };
    }

    /**
     * @return array<string, mixed>
     */
    private function docPropsAggregateValueMetadata(\DOMElement $valueElement): array
    {
        if (!in_array($valueElement->localName, ['array', 'vector'], true)) {
            return [];
        }

        $metadata = [
            'valueCount' => count($this->docPropsVectorValues($valueElement)),
        ];

        $size = trim($valueElement->getAttribute('size'));
        if ($size !== '' && is_numeric($size)) {
            $metadata['declaredValueCount'] = (int) $size;
        }

        $baseType = trim($valueElement->getAttribute('baseType'));
        if ($baseType !== '') {
            $metadata['valueBaseType'] = $baseType;
        }

        if ($valueElement->localName === 'array') {
            $lowerBound = trim($valueElement->getAttribute('lBound'));
            if ($lowerBound === '') {
                $lowerBound = trim($valueElement->getAttribute('lbound'));
            }
            if ($lowerBound !== '' && is_numeric($lowerBound)) {
                $metadata['lowerBound'] = (int) $lowerBound;
            }
        }

        $itemTypes = $this->docPropsVectorValueTypes($valueElement);
        if ($itemTypes !== []) {
            $metadata['valueItemTypes'] = $itemTypes;
        }

        return $metadata;
    }

    /**
     * @return list<string>
     */
    private function docPropsVectorValueTypes(\DOMElement $vector): array
    {
        $types = [];
        foreach ($vector->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_VT) {
                continue;
            }

            if ($child->localName === 'variant') {
                $valueElement = $this->firstDocPropsValueElement($child);
                if ($valueElement instanceof \DOMElement) {
                    $types[] = $valueElement->localName;
                }
                continue;
            }

            $types[] = $child->localName;
        }

        return $types;
    }

    private function openXmlBooleanText(string $value): bool
    {
        return in_array(strtolower(trim($value)), ['1', 'true', 'on', 'yes'], true);
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettings(
        string $xml,
        string $partName,
        array $parts,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $settings = [];

        foreach ([
            'trackRevisions' => 'trackRevisions',
            'doNotTrackMoves' => 'doNotTrackMoves',
            'doNotTrackFormatting' => 'doNotTrackFormatting',
            'evenAndOddHeaders' => 'evenAndOddHeaders',
            'updateFields' => 'updateFields',
        ] as $key => $localName) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement) {
                $settings[$key] = $this->wordBoolean($element);
            }
        }

        $defaultTabStop = $this->firstElement($xpath, '/w:settings/w:defaultTabStop', $dom);
        if ($defaultTabStop instanceof \DOMElement && is_numeric($defaultTabStop->getAttributeNS(self::NS_W, 'val'))) {
            $settings['defaultTabStopTwips'] = (int) $defaultTabStop->getAttributeNS(self::NS_W, 'val');
        }

        $view = $this->firstElement($xpath, '/w:settings/w:view', $dom);
        if ($view instanceof \DOMElement) {
            $value = $view->getAttributeNS(self::NS_W, 'val');
            if ($value !== '') {
                $settings['view'] = $value;
            }
        }

        $zoom = $this->firstElement($xpath, '/w:settings/w:zoom', $dom);
        if ($zoom instanceof \DOMElement) {
            $settings['zoom'] = array_filter([
                'percent' => is_numeric($zoom->getAttributeNS(self::NS_W, 'percent'))
                    ? (int) $zoom->getAttributeNS(self::NS_W, 'percent')
                    : null,
                'value' => $zoom->getAttributeNS(self::NS_W, 'val') ?: null,
            ], static fn (mixed $value): bool => $value !== null && $value !== '');
        }

        foreach ([
            'decimalSymbol' => 'decimalSymbol',
            'listSeparator' => 'listSeparator',
        ] as $key => $localName) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement) {
                $value = $element->getAttributeNS(self::NS_W, 'val');
                if ($value !== '') {
                    $settings[$key] = $value;
                }
            }
        }

        $themeFontLanguage = $this->firstElement($xpath, '/w:settings/w:themeFontLang', $dom);
        if ($themeFontLanguage instanceof \DOMElement) {
            $themeFontLanguageSettings = $this->wordAttributeMap($themeFontLanguage, ['val', 'eastAsia', 'bidi']);
            if ($themeFontLanguageSettings !== []) {
                $settings['themeFontLanguage'] = $themeFontLanguageSettings;
            }
        }

        $colorSchemeMapping = $this->firstElement($xpath, '/w:settings/w:clrSchemeMapping', $dom);
        if ($colorSchemeMapping instanceof \DOMElement) {
            $colorSchemeMappingSettings = $this->wordAttributeMap($colorSchemeMapping, [
                'bg1',
                't1',
                'bg2',
                't2',
                'accent1',
                'accent2',
                'accent3',
                'accent4',
                'accent5',
                'accent6',
                'hyperlink',
                'followedHyperlink',
            ]);
            if ($colorSchemeMappingSettings !== []) {
                $settings['colorSchemeMapping'] = $colorSchemeMappingSettings;
            }
        }

        $protection = $this->firstElement($xpath, '/w:settings/w:documentProtection', $dom);
        if ($protection instanceof \DOMElement) {
            $settings['documentProtection'] = $this->wordAttributeMap($protection, [
                'edit',
                'enforcement',
                'algorithmName',
                'hashValue',
                'saltValue',
                'spinCount',
                'cryptProviderType',
                'cryptAlgorithmClass',
                'cryptAlgorithmType',
                'cryptAlgorithmSid',
                'cryptSpinCount',
            ]);
            if (isset($settings['documentProtection']['enforcement'])) {
                $settings['documentProtection']['enforcement'] = $this->wordBoolean($protection, 'enforcement');
            }
            foreach (['spinCount', 'cryptAlgorithmSid', 'cryptSpinCount'] as $numericKey) {
                if (isset($settings['documentProtection'][$numericKey]) && is_numeric($settings['documentProtection'][$numericKey])) {
                    $settings['documentProtection'][$numericKey] = (int) $settings['documentProtection'][$numericKey];
                }
            }
        }

        $writeProtection = $this->firstElement($xpath, '/w:settings/w:writeProtection', $dom);
        if ($writeProtection instanceof \DOMElement) {
            $settings['writeProtection'] = $this->wordAttributeMap($writeProtection, [
                'recommended',
                'algorithmName',
                'hashValue',
                'saltValue',
                'spinCount',
                'cryptProviderType',
                'cryptAlgorithmClass',
                'cryptAlgorithmType',
                'cryptAlgorithmSid',
                'cryptSpinCount',
            ]);
            if (isset($settings['writeProtection']['recommended'])) {
                $settings['writeProtection']['recommended'] = $this->wordBoolean($writeProtection, 'recommended');
            }
            foreach (['spinCount', 'cryptAlgorithmSid', 'cryptSpinCount'] as $numericKey) {
                if (isset($settings['writeProtection'][$numericKey]) && is_numeric($settings['writeProtection'][$numericKey])) {
                    $settings['writeProtection'][$numericKey] = (int) $settings['writeProtection'][$numericKey];
                }
            }
        }

        $revisionView = $this->firstElement($xpath, '/w:settings/w:revisionView', $dom);
        if ($revisionView instanceof \DOMElement) {
            $revisionViewSettings = [];
            foreach ([
                'markup',
                'comments',
                'insDel',
                'formatting',
                'inkAnnotations',
            ] as $attribute) {
                if ($revisionView->getAttributeNS(self::NS_W, $attribute) !== '') {
                    $revisionViewSettings[$attribute] = $this->wordBoolean($revisionView, $attribute);
                }
            }
            if ($revisionViewSettings !== []) {
                $settings['revisionView'] = $revisionViewSettings;
            }
        }

        $proofState = $this->firstElement($xpath, '/w:settings/w:proofState', $dom);
        if ($proofState instanceof \DOMElement) {
            $proofing = $this->wordAttributeMap($proofState, ['spelling', 'grammar']);
            if ($proofing !== []) {
                $settings['proofing'] = $proofing;
            }
        }

        $viewStateDetails = $this->settingsViewStateDetails($settings);
        if ($viewStateDetails !== []) {
            $settings['viewStateDetails'] = $viewStateDetails;
        }

        $hyphenation = [];
        foreach ([
            'autoHyphenation' => 'autoHyphenation',
            'doNotHyphenateCaps' => 'doNotHyphenateCaps',
        ] as $localName => $key) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement) {
                $hyphenation[$key] = $this->wordBoolean($element);
            }
        }
        foreach ([
            'consecutiveHyphenLimit' => 'consecutiveHyphenLimit',
            'hyphenationZone' => 'hyphenationZoneTwips',
        ] as $localName => $key) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement && is_numeric($element->getAttributeNS(self::NS_W, 'val'))) {
                $hyphenation[$key] = (int) $element->getAttributeNS(self::NS_W, 'val');
            }
        }
        if ($hyphenation !== []) {
            $settings['hyphenation'] = $hyphenation;
        }

        $savePolicy = [];
        foreach ([
            'saveFormsData' => 'saveFormsData',
            'savePreviewPicture' => 'savePreviewPicture',
            'doNotEmbedSmartTags' => 'doNotEmbedSmartTags',
            'embedTrueTypeFonts' => 'embedTrueTypeFonts',
            'embedSystemFonts' => 'embedSystemFonts',
            'saveSubsetFonts' => 'saveSubsetFonts',
        ] as $localName => $key) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement) {
                $savePolicy[$key] = $this->wordBoolean($element);
            }
        }
        if ($savePolicy !== []) {
            $settings['savePolicy'] = $savePolicy;
        }

        $mathProperties = $this->readSettingsMathProperties($xpath, $dom);
        if ($mathProperties !== []) {
            $settings['mathProperties'] = $mathProperties;
        }

        $compatibility = $this->readSettingsCompatibility($xpath, $dom);
        if ($compatibility['flatItems'] !== []) {
            $settings['compatibility'] = $compatibility['flatItems'];
            unset($compatibility['flatItems']);
            $settings['compatibilityDetails'] = $compatibility;
        }

        $documentVariables = $this->readSettingsDocumentVariables($xpath, $dom);
        if ($documentVariables['byName'] !== []) {
            $settings['documentVariables'] = $documentVariables['byName'];
        }
        if ($documentVariables['items'] !== []) {
            $settings['documentVariableDetails'] = $documentVariables;
        }

        $rsidDetails = $this->readSettingsRsids($xpath, $dom);
        if ($rsidDetails['rootPresent'] || $rsidDetails['items'] !== []) {
            $settings['rsidDetails'] = $rsidDetails;
        }
        if ($rsidDetails['nonEmptyValues'] !== []) {
            $settings['rsids'] = $rsidDetails['nonEmptyValues'];
        }

        $mailMerge = $this->readMailMergeSettings(
            $dom,
            $parts,
            $partName,
            $relationshipsPart,
            $relationships,
            $contentTypes,
        );
        if ($mailMerge !== []) {
            $settings['mailMerge'] = $mailMerge;
        }

        return $settings;
    }

    /**
     * @param array<string, mixed> $settings
     * @return array<string, mixed>
     */
    private function settingsPolicySummary(array $settings): array
    {
        $flagSummary = $this->settingsBooleanFlagSummary($settings, [
            'trackRevisions',
            'doNotTrackMoves',
            'doNotTrackFormatting',
            'evenAndOddHeaders',
            'updateFields',
        ]);

        $documentProtection = $this->settingsProtectionPolicyMetadata($settings['documentProtection'] ?? null, 'enforcement');
        $writeProtection = $this->settingsProtectionPolicyMetadata($settings['writeProtection'] ?? null, 'recommended');
        $hyphenation = $this->settingsHyphenationPolicyMetadata($settings['hyphenation'] ?? null);
        $savePolicy = $this->settingsSavePolicyMetadata($settings['savePolicy'] ?? null);

        if (
            $flagSummary['flagCount'] === 0
            && $documentProtection === null
            && $writeProtection === null
            && $hyphenation === null
            && $savePolicy === null
        ) {
            return [];
        }

        $protectionHashValuePresentCount = 0;
        $protectionSaltValuePresentCount = 0;
        foreach ([$documentProtection, $writeProtection] as $protection) {
            if (!is_array($protection)) {
                continue;
            }
            if (($protection['hashValuePresent'] ?? false) === true) {
                ++$protectionHashValuePresentCount;
            }
            if (($protection['saltValuePresent'] ?? false) === true) {
                ++$protectionSaltValuePresentCount;
            }
        }

        $summary = [
            'flagCount' => $flagSummary['flagCount'],
            'enabledFlagCount' => $flagSummary['enabledFlagCount'],
            'disabledFlagCount' => $flagSummary['disabledFlagCount'],
            'enabledFlags' => $flagSummary['enabledFlags'],
            'disabledFlags' => $flagSummary['disabledFlags'],
            'documentProtectionPresent' => $documentProtection !== null,
            'writeProtectionPresent' => $writeProtection !== null,
            'protectionHashValuePresentCount' => $protectionHashValuePresentCount,
            'protectionSaltValuePresentCount' => $protectionSaltValuePresentCount,
            'hyphenationFlagCount' => 0,
            'hyphenationEnabledFlags' => [],
            'hyphenationDisabledFlags' => [],
            'savePolicyFlagCount' => 0,
            'savePolicyEnabledFlags' => [],
            'savePolicyDisabledFlags' => [],
            'fontEmbeddingPolicyFlags' => [],
            'reviewPolicy' => 'settings-policy-metadata-only',
        ];

        if ($documentProtection !== null) {
            $summary['documentProtection'] = $documentProtection;
        }
        if ($writeProtection !== null) {
            $summary['writeProtection'] = $writeProtection;
        }
        if ($hyphenation !== null) {
            $summary['hyphenation'] = $hyphenation;
            $summary['hyphenationFlagCount'] = $hyphenation['flagCount'];
            $summary['hyphenationEnabledFlags'] = $hyphenation['enabledFlags'];
            $summary['hyphenationDisabledFlags'] = $hyphenation['disabledFlags'];
        }
        if ($savePolicy !== null) {
            $summary['savePolicy'] = $savePolicy;
            $summary['savePolicyFlagCount'] = $savePolicy['flagCount'];
            $summary['savePolicyEnabledFlags'] = $savePolicy['enabledFlags'];
            $summary['savePolicyDisabledFlags'] = $savePolicy['disabledFlags'];
            $summary['fontEmbeddingPolicyFlags'] = $savePolicy['fontEmbeddingFlags'];
        }

        return $summary;
    }

    /**
     * @param array<string, mixed> $source
     * @param list<string> $flagNames
     * @return array{flagCount:int, enabledFlagCount:int, disabledFlagCount:int, enabledFlags:list<string>, disabledFlags:list<string>}
     */
    private function settingsBooleanFlagSummary(array $source, array $flagNames): array
    {
        $enabledFlags = [];
        $disabledFlags = [];

        foreach ($flagNames as $flagName) {
            if (!array_key_exists($flagName, $source) || !is_bool($source[$flagName])) {
                continue;
            }

            if ($source[$flagName]) {
                $enabledFlags[] = $flagName;
            } else {
                $disabledFlags[] = $flagName;
            }
        }

        return [
            'flagCount' => count($enabledFlags) + count($disabledFlags),
            'enabledFlagCount' => count($enabledFlags),
            'disabledFlagCount' => count($disabledFlags),
            'enabledFlags' => $enabledFlags,
            'disabledFlags' => $disabledFlags,
        ];
    }

    /**
     * @return array<string, mixed>|null
     */
    private function settingsProtectionPolicyMetadata(mixed $source, string $booleanKey): ?array
    {
        if (!is_array($source)) {
            return null;
        }

        $metadata = [
            'attributeCount' => count($source),
            'hashValuePresent' => false,
            'saltValuePresent' => false,
            'reviewPolicy' => 'settings-protection-metadata-only',
        ];

        foreach (['edit', 'algorithmName', 'cryptProviderType', 'cryptAlgorithmClass', 'cryptAlgorithmType'] as $key) {
            if (isset($source[$key]) && is_string($source[$key]) && $source[$key] !== '') {
                $metadata[$key] = $source[$key];
            }
        }

        if (isset($source[$booleanKey]) && is_bool($source[$booleanKey])) {
            $metadata[$booleanKey] = $source[$booleanKey];
        }

        foreach (['spinCount', 'cryptAlgorithmSid', 'cryptSpinCount'] as $key) {
            if (isset($source[$key]) && is_int($source[$key])) {
                $metadata[$key] = $source[$key];
            }
        }

        foreach (['hashValue', 'saltValue'] as $key) {
            if (!isset($source[$key]) || !is_string($source[$key]) || $source[$key] === '') {
                continue;
            }

            $metadata[$key . 'Present'] = true;
            $metadata[$key . 'Length'] = strlen($source[$key]);
            $metadata[$key . 'Sha256'] = hash('sha256', $source[$key]);
        }

        return $metadata;
    }

    /**
     * @return array<string, mixed>|null
     */
    private function settingsHyphenationPolicyMetadata(mixed $source): ?array
    {
        if (!is_array($source)) {
            return null;
        }

        $flagSummary = $this->settingsBooleanFlagSummary($source, [
            'autoHyphenation',
            'doNotHyphenateCaps',
        ]);
        $metadata = $flagSummary + [
            'numericSettingCount' => 0,
            'reviewPolicy' => 'settings-hyphenation-metadata-only',
        ];

        foreach (['consecutiveHyphenLimit', 'hyphenationZoneTwips'] as $key) {
            if (isset($source[$key]) && is_int($source[$key])) {
                $metadata[$key] = $source[$key];
                ++$metadata['numericSettingCount'];
            }
        }

        return $metadata;
    }

    /**
     * @return array<string, mixed>|null
     */
    private function settingsSavePolicyMetadata(mixed $source): ?array
    {
        if (!is_array($source)) {
            return null;
        }

        $flagSummary = $this->settingsBooleanFlagSummary($source, [
            'saveFormsData',
            'savePreviewPicture',
            'doNotEmbedSmartTags',
            'embedTrueTypeFonts',
            'embedSystemFonts',
            'saveSubsetFonts',
        ]);
        $fontEmbeddingFlags = [];
        foreach (['embedTrueTypeFonts', 'embedSystemFonts', 'saveSubsetFonts'] as $flagName) {
            if (array_key_exists($flagName, $source) && is_bool($source[$flagName])) {
                $fontEmbeddingFlags[$flagName] = $source[$flagName];
            }
        }

        return $flagSummary + [
            'fontEmbeddingFlagCount' => count($fontEmbeddingFlags),
            'fontEmbeddingFlags' => $fontEmbeddingFlags,
            'reviewPolicy' => 'settings-save-policy-metadata-only',
        ];
    }

    /**
     * @param array<string, mixed> $settings
     * @return array<string, mixed>
     */
    private function settingsViewStateDetails(array $settings): array
    {
        $details = [];
        $issueCodes = [];

        if (isset($settings['view']) && is_string($settings['view']) && $settings['view'] !== '') {
            $details['view'] = $settings['view'];
        }

        $zoom = $settings['zoom'] ?? null;
        if (is_array($zoom) && $zoom !== []) {
            $zoomDetails = [];
            if (isset($zoom['percent']) && is_int($zoom['percent'])) {
                $zoomDetails['percent'] = $zoom['percent'];
            }
            if (isset($zoom['value']) && is_string($zoom['value']) && $zoom['value'] !== '') {
                $zoomDetails['value'] = $zoom['value'];
            }
            if ($zoomDetails !== []) {
                $details['zoom'] = $zoomDetails;
            }
        }

        $revisionView = $settings['revisionView'] ?? null;
        if (is_array($revisionView) && $revisionView !== []) {
            $enabledAttributes = [];
            $disabledAttributes = [];
            foreach ($revisionView as $attribute => $enabled) {
                if ($enabled === true) {
                    $enabledAttributes[] = (string) $attribute;
                } elseif ($enabled === false) {
                    $disabledAttributes[] = (string) $attribute;
                }
            }

            $details['revisionView'] = $revisionView;
            $details['revisionViewAttributeCount'] = count($revisionView);
            $details['revisionViewEnabledCount'] = count($enabledAttributes);
            $details['revisionViewDisabledCount'] = count($disabledAttributes);
            $details['revisionViewEnabledAttributes'] = $enabledAttributes;
            $details['revisionViewDisabledAttributes'] = $disabledAttributes;
        }

        $proofing = $settings['proofing'] ?? null;
        if (is_array($proofing) && $proofing !== []) {
            $cleanAttributes = [];
            $dirtyAttributes = [];
            $otherAttributes = [];
            foreach ($proofing as $attribute => $state) {
                if ($state === 'clean') {
                    $cleanAttributes[] = (string) $attribute;
                } elseif ($state === 'dirty') {
                    $dirtyAttributes[] = (string) $attribute;
                } else {
                    $otherAttributes[] = (string) $attribute;
                }
            }

            if ($otherAttributes !== []) {
                $issueCodes[] = 'unknown-proof-state';
            }

            $details['proofing'] = $proofing;
            $details['proofingAttributeCount'] = count($proofing);
            $details['proofingCleanCount'] = count($cleanAttributes);
            $details['proofingDirtyCount'] = count($dirtyAttributes);
            $details['proofingOtherCount'] = count($otherAttributes);
            $details['proofingCleanAttributes'] = $cleanAttributes;
            $details['proofingDirtyAttributes'] = $dirtyAttributes;
            $details['proofingOtherAttributes'] = $otherAttributes;
        }

        if ($details === []) {
            return [];
        }

        $details['issueCount'] = count($issueCodes);
        $details['issueCodes'] = $issueCodes;

        return $details;
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettingsCompatibility(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $items = [];
        $flatItems = [];
        $nameCounts = [];
        $uris = [];

        foreach ($this->elements($xpath, '/w:settings/w:compat/w:compatSetting', $dom) as $setting) {
            $name = $setting->getAttributeNS(self::NS_W, 'name');
            $uri = $setting->getAttributeNS(self::NS_W, 'uri');
            $value = $setting->getAttributeNS(self::NS_W, 'val');
            $item = [
                'index' => count($items),
                'name' => $name,
                'uri' => $uri,
                'value' => $value,
                'issues' => [],
            ];

            if ($name === '') {
                $item['issues'][] = 'missing-name';
            } else {
                $nameCounts[$name] = ($nameCounts[$name] ?? 0) + 1;
            }
            $this->appendUniqueString($uris, $uri);

            $items[] = $item;
            $flatItems[] = array_filter([
                'name' => $name ?: null,
                'uri' => $uri ?: null,
                'value' => $value ?: null,
            ], static fn (mixed $value): bool => $value !== null && $value !== '');
        }

        $duplicateNames = [];
        foreach ($nameCounts as $name => $count) {
            if ($count > 1) {
                $duplicateNames[] = $name;
            }
        }
        sort($duplicateNames, SORT_STRING);
        sort($uris, SORT_STRING);

        $duplicateLookup = array_fill_keys($duplicateNames, true);
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as &$item) {
            $name = $item['name'];
            $item['duplicateName'] = is_string($name) && isset($duplicateLookup[$name]);
            if ($item['duplicateName']) {
                $item['issues'][] = 'duplicate-name';
            }
            if ($item['issues'] !== []) {
                ++$issueCount;
                foreach ($item['issues'] as $issue) {
                    $issueCodes[$issue] = true;
                }
            }
        }
        unset($item);
        ksort($issueCodes, SORT_STRING);

        $byName = [];
        foreach ($items as $item) {
            if ($item['name'] !== '') {
                $byName[$item['name']] = $item;
            }
        }

        return [
            'count' => count($items),
            'namedCount' => count(array_filter($items, static fn (array $item): bool => $item['name'] !== '')),
            'emptyNameCount' => count(array_filter($items, static fn (array $item): bool => $item['name'] === '')),
            'uniqueNameCount' => count($nameCounts),
            'duplicateNameCount' => count($duplicateNames),
            'duplicateNames' => $duplicateNames,
            'uriCount' => count($uris),
            'uris' => $uris,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'items' => $items,
            'byName' => $byName,
            'flatItems' => $flatItems,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettingsDocumentVariables(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $items = [];
        $byName = [];
        $nameCounts = [];

        foreach ($this->elements($xpath, '/w:settings/w:docVars/w:docVar', $dom) as $variable) {
            $name = $variable->getAttributeNS(self::NS_W, 'name');
            $value = $variable->getAttributeNS(self::NS_W, 'val');
            $item = [
                'index' => count($items),
                'name' => $name,
                'value' => $value,
                'valueLength' => strlen($value),
                'valueSha256' => hash('sha256', $value),
                'issues' => [],
            ];

            if ($name === '') {
                $item['issues'][] = 'missing-name';
            } else {
                $byName[$name] = $value;
                $nameCounts[$name] = ($nameCounts[$name] ?? 0) + 1;
            }

            $items[] = $item;
        }

        $duplicateNames = [];
        foreach ($nameCounts as $name => $count) {
            if ($count > 1) {
                $duplicateNames[] = $name;
            }
        }
        sort($duplicateNames, SORT_STRING);

        $duplicateLookup = array_fill_keys($duplicateNames, true);
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as &$item) {
            $name = $item['name'];
            $item['duplicateName'] = is_string($name) && isset($duplicateLookup[$name]);
            if ($item['duplicateName']) {
                $item['issues'][] = 'duplicate-name';
            }
            if ($item['issues'] !== []) {
                ++$issueCount;
                foreach ($item['issues'] as $issue) {
                    $issueCodes[$issue] = true;
                }
            }
        }
        unset($item);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'namedCount' => count(array_filter($items, static fn (array $item): bool => $item['name'] !== '')),
            'emptyNameCount' => count(array_filter($items, static fn (array $item): bool => $item['name'] === '')),
            'duplicateNameCount' => count($duplicateNames),
            'duplicateNames' => $duplicateNames,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'items' => $items,
            'byName' => $byName,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettingsRsids(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $root = $this->firstElement($xpath, '/w:settings/w:rsids/w:rsidRoot', $dom);
        $rootPresent = $root instanceof \DOMElement;
        $rootValue = $rootPresent ? $root->getAttributeNS(self::NS_W, 'val') : '';
        $rootIssues = [];
        if ($rootPresent && $rootValue === '') {
            $rootIssues[] = 'missing-root-value';
        } elseif ($rootPresent && !$this->isOpenXmlRsidValue($rootValue)) {
            $rootIssues[] = 'invalid-root-hex';
        }

        $items = [];
        $values = [];
        $nonEmptyValues = [];
        $valueCounts = [];
        $invalidValueCount = 0;
        foreach ($this->elements($xpath, '/w:settings/w:rsids/w:rsid', $dom) as $rsid) {
            $value = $rsid->getAttributeNS(self::NS_W, 'val');
            $validHex = $value !== '' && $this->isOpenXmlRsidValue($value);
            $issues = [];
            if ($value === '') {
                $issues[] = 'missing-value';
            } else {
                $nonEmptyValues[] = $value;
                $valueCounts[$value] = ($valueCounts[$value] ?? 0) + 1;
                if (!$validHex) {
                    $issues[] = 'invalid-hex';
                    ++$invalidValueCount;
                }
            }
            $values[] = $value;
            $items[] = [
                'index' => count($items),
                'value' => $value,
                'valueLength' => strlen($value),
                'validHex' => $validHex,
                'issues' => $issues,
            ];
        }

        $duplicateValues = [];
        foreach ($valueCounts as $value => $count) {
            if ($count > 1) {
                $duplicateValues[] = $value;
            }
        }
        sort($duplicateValues, SORT_STRING);

        $duplicateLookup = array_fill_keys($duplicateValues, true);
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as &$item) {
            $value = $item['value'];
            $item['duplicateValue'] = is_string($value) && $value !== '' && isset($duplicateLookup[$value]);
            if ($item['duplicateValue']) {
                $item['issues'][] = 'duplicate-value';
            }
            if ($item['issues'] !== []) {
                ++$issueCount;
                foreach ($item['issues'] as $issue) {
                    $issueCodes[$issue] = true;
                }
            }
        }
        unset($item);
        ksort($issueCodes, SORT_STRING);

        $rootIssueCodes = array_fill_keys($rootIssues, true);
        ksort($rootIssueCodes, SORT_STRING);

        return [
            'rootPresent' => $rootPresent,
            'rootValue' => $rootValue,
            'rootValueLength' => strlen($rootValue),
            'rootValidHex' => $rootPresent && $this->isOpenXmlRsidValue($rootValue),
            'rootIssueCount' => count($rootIssues),
            'rootIssueCodes' => array_keys($rootIssueCodes),
            'count' => count($items),
            'nonEmptyCount' => count($nonEmptyValues),
            'emptyValueCount' => count($items) - count($nonEmptyValues),
            'uniqueValueCount' => count($valueCounts),
            'duplicateValueCount' => count($duplicateValues),
            'duplicateValues' => $duplicateValues,
            'invalidValueCount' => $invalidValueCount,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'values' => $values,
            'nonEmptyValues' => $nonEmptyValues,
            'items' => $items,
        ];
    }

    private function isOpenXmlRsidValue(string $value): bool
    {
        return preg_match('/\A[0-9A-Fa-f]{8}\z/', $value) === 1;
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettingsMathProperties(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $mathProperties = $this->firstElement($xpath, '/w:settings/m:mathPr', $dom);
        if (!$mathProperties instanceof \DOMElement) {
            return [];
        }

        $items = [];
        $byName = [];
        $nameCounts = [];
        $names = [];
        $numericValueCount = 0;
        foreach ($mathProperties->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_M) {
                continue;
            }

            $name = $child->localName;
            $value = $child->getAttributeNS(self::NS_M, 'val');
            if ($value === '') {
                $value = $child->getAttribute('val');
            }
            $hasValue = $value !== '';
            $issues = [];
            $item = [
                'index' => count($items),
                'name' => $name,
                'value' => $value,
                'hasValue' => $hasValue,
                'valueLength' => strlen($value),
                'issues' => [],
            ];
            if ($hasValue) {
                $byName[$name] = $value;
                if (preg_match('/^-?\d+$/', $value) === 1) {
                    $item['numericValue'] = (int) $value;
                    ++$numericValueCount;
                }
            } else {
                $issues[] = 'missing-value';
            }

            $nameCounts[$name] = ($nameCounts[$name] ?? 0) + 1;
            $this->appendUniqueString($names, $name);
            $item['issues'] = $issues;
            $items[] = $item;
        }

        $duplicateNames = [];
        foreach ($nameCounts as $name => $count) {
            if ($count > 1) {
                $duplicateNames[] = $name;
            }
        }
        sort($duplicateNames, SORT_STRING);

        $duplicateLookup = array_fill_keys($duplicateNames, true);
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as &$item) {
            $name = $item['name'];
            $item['duplicateName'] = is_string($name) && isset($duplicateLookup[$name]);
            if ($item['duplicateName']) {
                $item['issues'][] = 'duplicate-name';
            }
            if ($item['issues'] !== []) {
                ++$issueCount;
                foreach ($item['issues'] as $issue) {
                    $issueCodes[$issue] = true;
                }
            }
        }
        unset($item);
        sort($names, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'valuedCount' => count(array_filter($items, static fn (array $item): bool => $item['hasValue'] === true)),
            'emptyValueCount' => count(array_filter($items, static fn (array $item): bool => $item['hasValue'] === false)),
            'uniqueNameCount' => count($names),
            'names' => $names,
            'numericValueCount' => $numericValueCount,
            'duplicateNameCount' => count($duplicateNames),
            'duplicateNames' => $duplicateNames,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'items' => $items,
            'byName' => $byName,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readMailMergeSettings(
        \DOMDocument $dom,
        array $parts,
        string $settingsPart,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $xpath = $this->xpath($dom);
        $mailMerge = $this->firstElement($xpath, '/w:settings/w:mailMerge', $dom);
        if (!$mailMerge instanceof \DOMElement) {
            return [];
        }

        $metadata = [];
        foreach ([
            'mainDocumentType' => 'mainDocumentType',
            'destination' => 'destination',
            'dataType' => 'dataType',
            'query' => 'query',
            'mailSubject' => 'mailSubject',
        ] as $source => $target) {
            $value = $this->settingsStringChildValue($mailMerge, $source);
            if ($value !== null) {
                $metadata[$target] = $value;
            }
        }

        $connectString = $this->settingsStringChildValue($mailMerge, 'connectString');
        if ($connectString !== null) {
            $metadata['connectStringPresent'] = true;
            $metadata['connectStringLength'] = strlen($connectString);
            $metadata['connectStringSha256'] = hash('sha256', $connectString);
        }

        foreach ([
            'viewMergedData' => 'viewMergedData',
            'linkToQuery' => 'linkToQuery',
            'doNotSuppressBlankLines' => 'doNotSuppressBlankLines',
        ] as $source => $target) {
            $value = $this->settingsOnOffChildValue($mailMerge, $source);
            if ($value !== null) {
                $metadata[$target] = $value;
            }
        }

        foreach ([
            'activeRecord' => 'activeRecord',
            'checkErrors' => 'checkErrors',
        ] as $source => $target) {
            $value = $this->settingsIntChildValue($mailMerge, $source);
            if ($value !== null) {
                $metadata[$target] = $value;
            }
        }

        $relationshipCount = 0;
        $issueCount = 0;
        $issueCodes = [];
        $relationshipChildren = [
            [
                'parent' => $mailMerge,
                'key' => 'dataSource',
                'expectedRelationshipTypes' => [self::MAIL_MERGE_SOURCE_REL],
                'reviewPolicy' => 'mail-merge-source',
            ],
            [
                'parent' => $mailMerge,
                'key' => 'headerSource',
                'expectedRelationshipTypes' => [self::MAIL_MERGE_HEADER_SOURCE_REL],
                'reviewPolicy' => 'mail-merge-header-source',
            ],
        ];
        $odso = $this->childElement($mailMerge, 'odso');
        if ($odso instanceof \DOMElement) {
            $odsoMetadata = $this->readMailMergeOdsoSettings($odso);
            if ($odsoMetadata !== []) {
                $metadata['odso'] = $odsoMetadata;
            }
            $relationshipChildren[] = [
                'parent' => $odso,
                'key' => 'recipientData',
                'expectedRelationshipTypes' => [self::MAIL_MERGE_RECIPIENT_DATA_REL, self::MAIL_MERGE_RECIPIENT_DATA_COMPAT_REL],
                'reviewPolicy' => 'mail-merge-recipient-data',
            ];
        }

        foreach ($relationshipChildren as $relationshipChild) {
            $summary = $this->mailMergeRelationshipChildSummary(
                $relationshipChild['parent'],
                $relationshipChild['key'],
                $parts,
                $settingsPart,
                $relationshipsPart,
                $relationships,
                $contentTypes,
                $relationshipChild['expectedRelationshipTypes'],
                $relationshipChild['reviewPolicy'],
            );
            if ($summary === null) {
                continue;
            }

            if ($relationshipChild['key'] === 'recipientData') {
                $summary = $this->mailMergeRecipientDataPartSummary($summary, $parts);
            }

            $metadata[$relationshipChild['key']] = $summary;
            ++$relationshipCount;
            if ($summary['issues'] !== []) {
                ++$issueCount;
                foreach ($summary['issues'] as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                    }
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        $metadata['relationshipCount'] = $relationshipCount;
        $metadata['issueCount'] = $issueCount;
        $metadata['issueCodes'] = array_keys($issueCodes);

        return $metadata;
    }

    private function readMailMergeOdsoSettings(\DOMElement $odso): array
    {
        $metadata = [
            'sourcePresentCount' => 0,
            'sourceKinds' => [],
            'fieldMapDataCount' => 0,
            'fieldMapDataNamedCount' => 0,
            'fieldMapDataMappedNameCount' => 0,
            'fieldMapDataDynamicAddressCount' => 0,
            'fieldMapDataIssueCount' => 0,
            'fieldMapDataIssueCodes' => [],
            'fieldMapDataColumnIndexes' => [],
            'fieldMapDataItems' => [],
            'reviewPolicy' => 'mail-merge-odso-metadata-only',
        ];

        foreach ([
            'type' => 'type',
            'lid' => 'languageId',
        ] as $source => $target) {
            $value = $this->settingsStringChildValue($odso, $source);
            if ($value !== null) {
                $metadata[$target] = $value;
            }
        }

        foreach ([
            'udl' => 'udl',
            'table' => 'table',
            'src' => 'source',
        ] as $source => $target) {
            $value = $this->settingsStringChildValue($odso, $source);
            if ($value === null) {
                continue;
            }

            $metadata[$target . 'Present'] = true;
            $metadata[$target . 'Length'] = strlen($value);
            $metadata[$target . 'Sha256'] = hash('sha256', $value);
            ++$metadata['sourcePresentCount'];
            $metadata['sourceKinds'][] = $target;
        }

        $firstHeaderRow = $this->settingsOnOffChildValue($odso, 'fHdr');
        if ($firstHeaderRow !== null) {
            $metadata['firstHeaderRow'] = $firstHeaderRow;
        }

        $columnDelimiter = $this->settingsIntChildValue($odso, 'colDelim');
        if ($columnDelimiter !== null) {
            $metadata['columnDelimiter'] = $columnDelimiter;
        }

        $fieldMapItems = [];
        $columnIndexes = [];
        $issueCodes = [];
        foreach ($this->childElementsByLocalName($odso, 'fieldMapData') as $index => $fieldMapData) {
            $name = $this->settingsStringChildValue($fieldMapData, 'name');
            $mappedName = $this->settingsStringChildValue($fieldMapData, 'mappedName');
            $columnIndex = $this->settingsIntChildValue($fieldMapData, 'column');
            $dynamicAddress = $this->settingsOnOffChildValue($fieldMapData, 'dynamicAddress');
            $issues = [];

            if ($name === null) {
                $issues[] = 'missing-field-map-name';
            }
            if ($columnIndex === null) {
                $issues[] = 'missing-field-map-column';
            } else {
                $columnIndexes[$columnIndex] = true;
            }

            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }
            sort($issues, SORT_STRING);

            $fieldMapItems[] = [
                'index' => $index,
                'type' => $this->settingsStringChildValue($fieldMapData, 'type'),
                'columnIndex' => $columnIndex,
                'languageId' => $this->settingsStringChildValue($fieldMapData, 'lid'),
                'dynamicAddress' => $dynamicAddress,
                'namePresent' => $name !== null,
                'nameLength' => $name === null ? null : strlen($name),
                'nameSha256' => $name === null ? null : hash('sha256', $name),
                'mappedNamePresent' => $mappedName !== null,
                'mappedNameLength' => $mappedName === null ? null : strlen($mappedName),
                'mappedNameSha256' => $mappedName === null ? null : hash('sha256', $mappedName),
                'issues' => $issues,
            ];
        }

        $columnIndexValues = array_keys($columnIndexes);
        sort($columnIndexValues, SORT_NUMERIC);
        ksort($issueCodes, SORT_STRING);

        $metadata['fieldMapDataCount'] = count($fieldMapItems);
        $metadata['fieldMapDataNamedCount'] = count(array_filter($fieldMapItems, static fn (array $item): bool => $item['namePresent'] === true));
        $metadata['fieldMapDataMappedNameCount'] = count(array_filter($fieldMapItems, static fn (array $item): bool => $item['mappedNamePresent'] === true));
        $metadata['fieldMapDataDynamicAddressCount'] = count(array_filter($fieldMapItems, static fn (array $item): bool => $item['dynamicAddress'] === true));
        $metadata['fieldMapDataIssueCount'] = count($issueCodes);
        $metadata['fieldMapDataIssueCodes'] = array_keys($issueCodes);
        $metadata['fieldMapDataColumnIndexes'] = $columnIndexValues;
        $metadata['fieldMapDataItems'] = $fieldMapItems;

        return $metadata;
    }

    private function settingsStringChildValue(\DOMElement $parent, string $localName): ?string
    {
        $child = $this->childElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $value = trim($child->getAttributeNS(self::NS_W, 'val'));

        return $value === '' ? null : $value;
    }

    private function settingsOnOffChildValue(\DOMElement $parent, string $localName): ?bool
    {
        $child = $this->childElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        return $this->wordBoolean($child);
    }

    private function settingsIntChildValue(\DOMElement $parent, string $localName): ?int
    {
        $child = $this->childElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $value = trim($child->getAttributeNS(self::NS_W, 'val'));

        return is_numeric($value) ? (int) $value : null;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<string> $expectedRelationshipTypes
     * @return array<string, mixed>|null
     */
    private function mailMergeRelationshipChildSummary(
        \DOMElement $mailMerge,
        string $localName,
        array $parts,
        string $settingsPart,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        array $expectedRelationshipTypes,
        string $reviewPolicy
    ): ?array {
        $child = $this->childElement($mailMerge, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $relationshipId = $child->getAttributeNS(self::NS_R, 'id');
        $item = [
            'id' => $relationshipId,
            'sourcePart' => $settingsPart,
            'relationshipsPart' => $relationshipsPart,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'external' => null,
            'exists' => null,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'byteExposurePolicy' => $reviewPolicy . '-bytes-blocked',
            'reviewPolicy' => $reviewPolicy . '-metadata-only',
            'relationship' => null,
            'issues' => [],
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';

            return $item;
        }

        if (!isset($parts[$relationshipsPart])) {
            $item['issues'][] = 'missing-relationships';

            return $item;
        }

        $relationship = $relationships[$relationshipId] ?? null;
        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';

            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $settingsPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['external'] = $external;
        $item['exists'] = (bool) ($summary['exists'] ?? false);
        $item['byteLength'] = $targetPart !== null && $item['exists'] === true ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $item['exists'] === true ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $item['exists'] === true ? hash('sha256', $parts[$targetPart]) : null;
        $item['relationship'] = $summary;

        if (!in_array($relationship['type'], $expectedRelationshipTypes, true)) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($external) {
            $externalPolicy = $this->externalRelationshipTargetPolicy($relationship['target']);
            $item['externalTargetKind'] = $externalPolicy['kind'];
            $item['externalTargetScheme'] = $externalPolicy['scheme'];
            $item['externalTargetAllowed'] = $externalPolicy['allowed'];
            $item['issues'] = array_values(array_unique(array_merge($item['issues'], $externalPolicy['issues'])));
        } else {
            if ($item['exists'] !== true) {
                $item['issues'][] = 'missing-in-package';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);

        return $item;
    }

    /**
     * @param array<string, mixed> $item
     * @param array<string, string> $parts
     * @return array<string, mixed>
     */
    private function mailMergeRecipientDataPartSummary(array $item, array $parts): array
    {
        $expectedContentTypeBases = [
            self::CT_MAIL_MERGE_RECIPIENT_DATA,
            self::CT_MS_MAIL_MERGE_RECIPIENT_DATA,
        ];
        $item['expectedContentTypeBases'] = $expectedContentTypeBases;
        $item['contentTypeMatchesExpected'] = null;
        $item['validXml'] = null;
        $item['xmlParseError'] = null;
        $item['rootNamespace'] = null;
        $item['rootLocalName'] = null;
        $item['validRoot'] = null;
        $item['recordCount'] = 0;
        $item['includedRecordCount'] = 0;
        $item['explicitIncludedRecordCount'] = 0;
        $item['implicitIncludedRecordCount'] = 0;
        $item['excludedRecordCount'] = 0;
        $item['uniqueTagCount'] = 0;
        $item['columnIndexes'] = [];
        $item['uniqueTagSha256s'] = [];
        $item['records'] = [];

        if (($item['external'] ?? null) === true) {
            $item['issues'][] = 'external-recipient-data';
        } else {
            $contentTypeBase = is_string($item['contentTypeBase'] ?? null) ? $item['contentTypeBase'] : '';
            if ($contentTypeBase !== '') {
                $item['contentTypeMatchesExpected'] = in_array($contentTypeBase, $expectedContentTypeBases, true);
                if ($item['contentTypeMatchesExpected'] !== true) {
                    $item['issues'][] = 'unexpected-content-type';
                }
            }
        }

        $targetPart = is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null;
        if ($targetPart === null || ($item['exists'] ?? false) !== true || !isset($parts[$targetPart])) {
            return $this->finalizeMailMergeRecipientDataPartSummary($item);
        }

        $dom = $this->loadXmlForProvenance($parts[$targetPart], $targetPart);
        if (!$dom instanceof \DOMDocument) {
            $item['validXml'] = false;
            $item['xmlParseError'] = $this->lastXmlPreflightError($parts[$targetPart], $targetPart);
            $item['issues'][] = 'invalid-recipient-data-xml';

            return $this->finalizeMailMergeRecipientDataPartSummary($item);
        }

        $root = $dom->documentElement;
        $validRoot = $root instanceof \DOMElement
            && in_array($root->namespaceURI, [self::NS_W, self::NS_WNE], true)
            && $root->localName === 'recipients';
        $item['validXml'] = $root instanceof \DOMElement;
        $item['rootNamespace'] = $root instanceof \DOMElement ? $root->namespaceURI : null;
        $item['rootLocalName'] = $root instanceof \DOMElement ? $root->localName : null;
        $item['validRoot'] = $validRoot;
        if (!$validRoot) {
            $item['issues'][] = 'unexpected-recipient-data-root';

            return $this->finalizeMailMergeRecipientDataPartSummary($item);
        }

        $xpath = $this->xpath($dom);
        $records = [];
        $columnIndexes = [];
        $uniqueTagSha256s = [];
        foreach ($this->elements($xpath, '/*[local-name()="recipients"]/*[local-name()="recipientData"]') as $index => $recipientData) {
            $active = $this->mailMergeRecipientChildBoolean($recipientData, 'active');
            $columnIndex = $this->mailMergeRecipientChildInt($recipientData, 'column');
            $uniqueTag = $this->mailMergeRecipientChildValue($recipientData, 'uniqueTag');
            $uniqueTagKind = 'uniqueTag';
            if ($uniqueTag === null) {
                $uniqueTag = $this->mailMergeRecipientChildValue($recipientData, 'hash');
                $uniqueTagKind = $uniqueTag === null ? null : 'hash';
            }
            $uniqueTagLength = $uniqueTag === null ? null : strlen($uniqueTag);
            $uniqueTagSha256 = $uniqueTag === null ? null : hash('sha256', $uniqueTag);
            $recordIssues = [];
            if ($columnIndex === null) {
                $recordIssues[] = 'missing-recipient-column';
            } else {
                $columnIndexes[$columnIndex] = true;
            }
            if ($uniqueTag === null) {
                $recordIssues[] = 'missing-recipient-unique-tag';
            } elseif ($uniqueTagSha256 !== null) {
                $uniqueTagSha256s[$uniqueTagSha256] = true;
            }

            $records[] = [
                'index' => $index,
                'active' => $active,
                'included' => $active !== false,
                'columnIndex' => $columnIndex,
                'uniqueTagPresent' => $uniqueTag !== null,
                'uniqueTagKind' => $uniqueTagKind,
                'uniqueTagLength' => $uniqueTagLength,
                'uniqueTagSha256' => $uniqueTagSha256,
                'issues' => $recordIssues,
            ];
            foreach ($recordIssues as $issue) {
                $item['issues'][] = $issue;
            }
        }

        $columnIndexValues = array_keys($columnIndexes);
        sort($columnIndexValues, SORT_NUMERIC);
        $uniqueTagSha256Values = array_keys($uniqueTagSha256s);
        sort($uniqueTagSha256Values, SORT_STRING);

        $item['recordCount'] = count($records);
        $item['includedRecordCount'] = count(array_filter($records, static fn (array $record): bool => $record['included'] === true));
        $item['explicitIncludedRecordCount'] = count(array_filter($records, static fn (array $record): bool => $record['active'] === true));
        $item['implicitIncludedRecordCount'] = count(array_filter($records, static fn (array $record): bool => $record['active'] === null));
        $item['excludedRecordCount'] = count(array_filter($records, static fn (array $record): bool => $record['active'] === false));
        $item['uniqueTagCount'] = count($uniqueTagSha256Values);
        $item['columnIndexes'] = $columnIndexValues;
        $item['uniqueTagSha256s'] = $uniqueTagSha256Values;
        $item['records'] = $records;

        return $this->finalizeMailMergeRecipientDataPartSummary($item);
    }

    /**
     * @param array<string, mixed> $item
     * @return array<string, mixed>
     */
    private function finalizeMailMergeRecipientDataPartSummary(array $item): array
    {
        $item['issues'] = array_values(array_unique(array_map('strval', $item['issues'] ?? [])));
        sort($item['issues'], SORT_STRING);

        return $item;
    }

    private function mailMergeRecipientChildElement(\DOMElement $parent, string $localName): ?\DOMElement
    {
        foreach ($parent->childNodes as $child) {
            if (
                $child instanceof \DOMElement
                && in_array($child->namespaceURI, [self::NS_W, self::NS_WNE], true)
                && $child->localName === $localName
            ) {
                return $child;
            }
        }

        return null;
    }

    private function mailMergeRecipientChildValue(\DOMElement $parent, string $localName): ?string
    {
        $child = $this->mailMergeRecipientChildElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        foreach ([self::NS_W, self::NS_WNE] as $namespace) {
            $value = trim($child->getAttributeNS($namespace, 'val'));
            if ($value !== '') {
                return $value;
            }
        }

        $value = trim($child->textContent);

        return $value === '' ? null : $value;
    }

    private function mailMergeRecipientChildBoolean(\DOMElement $parent, string $localName): ?bool
    {
        $child = $this->mailMergeRecipientChildElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $value = $this->mailMergeRecipientChildValue($parent, $localName);
        if ($value === null) {
            return true;
        }

        return $this->onOffStringValue($value);
    }

    private function mailMergeRecipientChildInt(\DOMElement $parent, string $localName): ?int
    {
        $value = $this->mailMergeRecipientChildValue($parent, $localName);
        if ($value === null || preg_match('/^-?\d+$/', $value) !== 1) {
            return null;
        }

        return (int) $value;
    }

    /**
     * @return array{kind:string, scheme:?string, allowed:bool, issues:list<string>}
     */
    private function externalRelationshipTargetPolicy(string $target): array
    {
        $scheme = null;
        $kind = 'relative-reference';
        if (preg_match('/^([A-Za-z][A-Za-z0-9+.-]*):/', $target, $match) === 1) {
            $scheme = strtolower($match[1]);
            $kind = 'absolute-uri';
        } elseif (str_starts_with($target, '//')) {
            $kind = 'network-path-reference';
        }

        $allowed = $scheme === null || in_array($scheme, ['http', 'https', 'mailto', 'urn'], true);
        $issues = $allowed ? [] : ['external-target-unsafe-scheme'];

        return [
            'kind' => $kind,
            'scheme' => $scheme,
            'allowed' => $allowed,
            'issues' => $issues,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readWebSettings(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'validXml' => false,
                'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                'issueCount' => 1,
                'issueCodes' => ['invalid-web-settings-xml'],
            ];
        }

        $xpath = $this->xpath($dom);
        $webSettings = [
            'validXml' => true,
            'xmlParseError' => null,
            'issueCount' => 0,
            'issueCodes' => [],
        ];

        foreach ([
            'optimizeForBrowser' => 'optimizeForBrowser',
            'allowPNG' => 'allowPng',
            'relyOnVML' => 'relyOnVml',
            'doNotRelyOnCSS' => 'doNotRelyOnCss',
            'doNotSaveAsSingleFile' => 'doNotSaveAsSingleFile',
            'doNotOrganizeInFolder' => 'doNotOrganizeInFolder',
            'doNotUseLongFileNames' => 'doNotUseLongFileNames',
        ] as $source => $target) {
            $element = $this->firstElement($xpath, '/w:webSettings/w:' . $source, $dom);
            if ($element instanceof \DOMElement) {
                $webSettings[$target] = $this->wordBoolean($element);
            }
        }

        foreach ([
            'encoding' => 'encoding',
            'targetScreenSz' => 'targetScreenSize',
        ] as $source => $target) {
            $element = $this->firstElement($xpath, '/w:webSettings/w:' . $source, $dom);
            if ($element instanceof \DOMElement) {
                $value = $element->getAttributeNS(self::NS_W, 'val');
                if ($value !== '') {
                    $webSettings[$target] = $value;
                }
            }
        }

        $pixelsPerInch = $this->firstElement($xpath, '/w:webSettings/w:pixelsPerInch', $dom);
        if ($pixelsPerInch instanceof \DOMElement && is_numeric($pixelsPerInch->getAttributeNS(self::NS_W, 'val'))) {
            $webSettings['pixelsPerInch'] = (int) $pixelsPerInch->getAttributeNS(self::NS_W, 'val');
        }

        if ($webSettings !== []) {
            $webSettings['outputPolicy'] = $this->webSettingsOutputPolicy($webSettings);
        }

        return $webSettings;
    }

    /**
     * @param array<string, mixed> $webSettings
     * @return array<string, mixed>
     */
    private function webSettingsOutputPolicy(array $webSettings): array
    {
        $flags = [];
        foreach ([
            'optimizeForBrowser' => [
                'enabled' => 'browser-optimized',
                'disabled' => 'browser-optimization-disabled',
            ],
            'allowPng' => [
                'enabled' => 'png-allowed',
                'disabled' => 'png-disabled',
            ],
            'relyOnVml' => [
                'enabled' => 'vml-required',
                'disabled' => 'vml-not-required',
            ],
            'doNotRelyOnCss' => [
                'enabled' => 'css-output-disabled',
                'disabled' => 'css-output-allowed',
            ],
            'doNotSaveAsSingleFile' => [
                'enabled' => 'single-file-output-disabled',
                'disabled' => 'single-file-output-allowed',
            ],
            'doNotOrganizeInFolder' => [
                'enabled' => 'folder-organization-disabled',
                'disabled' => 'folder-organization-allowed',
            ],
            'doNotUseLongFileNames' => [
                'enabled' => 'long-file-names-disabled',
                'disabled' => 'long-file-names-allowed',
            ],
        ] as $key => $labels) {
            $value = $webSettings[$key] ?? null;
            if (is_bool($value)) {
                $flags[] = $value ? $labels['enabled'] : $labels['disabled'];
            }
        }

        return [
            'flagCount' => count($flags),
            'flags' => $flags,
            'browserOptimized' => $webSettings['optimizeForBrowser'] ?? null,
            'pngAllowed' => $webSettings['allowPng'] ?? null,
            'vmlRequired' => $webSettings['relyOnVml'] ?? null,
            'cssOutputDisabled' => $webSettings['doNotRelyOnCss'] ?? null,
            'singleFileOutputDisabled' => $webSettings['doNotSaveAsSingleFile'] ?? null,
            'folderOrganizationDisabled' => $webSettings['doNotOrganizeInFolder'] ?? null,
            'longFileNamesDisabled' => $webSettings['doNotUseLongFileNames'] ?? null,
            'encoding' => is_string($webSettings['encoding'] ?? null) ? $webSettings['encoding'] : null,
            'targetScreenSize' => is_string($webSettings['targetScreenSize'] ?? null) ? $webSettings['targetScreenSize'] : null,
            'pixelsPerInch' => is_int($webSettings['pixelsPerInch'] ?? null) ? $webSettings['pixelsPerInch'] : null,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readFontTable(string $xml, string $partName, array $parts, array $contentTypes): array
    {
        if ($xml === '') {
            return [];
        }

        $relationshipsPart = $this->relationshipsPartFor($partName);
        $relationships = $this->readRelationshipsPart($parts, $relationshipsPart);
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'relationshipsPart' => $relationshipsPart,
                'relationshipCount' => count($relationships),
                'validXml' => false,
                'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                'invalidXmlCount' => 1,
                'issueCount' => 1,
                'issueCodes' => ['invalid-font-table-xml'],
                'fontCount' => 0,
                'embeddedFontRelationshipCount' => 0,
                'embeddedFontExistingCount' => 0,
                'embeddedFontMissingCount' => 0,
                'embeddedFontExternalCount' => 0,
                'embeddedFontAllowedExternalCount' => 0,
                'embeddedFontUnsafeExternalCount' => 0,
                'embeddedFontUnsafeExternalTargets' => [],
                'embeddedFontExternalTargetKindCounts' => [],
                'embeddedFontExternalTargetSchemeCounts' => [],
                'embeddedFontExternalTargetIssueCodes' => [],
                'embeddedFontKeyPresentCount' => 0,
                'embeddedFontKeyMissingCount' => 0,
                'embeddedFontKeyExpectedByteLengthCount' => 0,
                'embeddedFontKeyUnexpectedByteLengthCount' => 0,
                'embeddedFontKeyFormatCounts' => [],
                'embeddedFontIssueCount' => 0,
                'embeddedFontIssueCodes' => [],
                'notTrueTypeCount' => 0,
                'signatureCount' => 0,
                'signatureUnicodeRangeCount' => 0,
                'signatureCodePageRangeCount' => 0,
                'declaredNames' => [],
                'fonts' => [],
                'byName' => [],
            ];
        }

        $xpath = $this->xpath($dom);
        $fonts = [];
        $byName = [];
        $embeddedFontRelationshipCount = 0;
        $embeddedFontExistingCount = 0;
        $embeddedFontMissingCount = 0;
        $embeddedFontExternalCount = 0;
        $embeddedFontAllowedExternalCount = 0;
        $embeddedFontUnsafeExternalCount = 0;
        $embeddedFontUnsafeExternalTargets = [];
        $embeddedFontExternalTargetKindCounts = [];
        $embeddedFontExternalTargetSchemeCounts = [];
        $embeddedFontExternalTargetIssueCodes = [];
        $embeddedFontKeyPresentCount = 0;
        $embeddedFontKeyMissingCount = 0;
        $embeddedFontKeyExpectedByteLengthCount = 0;
        $embeddedFontKeyUnexpectedByteLengthCount = 0;
        $embeddedFontKeyFormatCounts = [];
        $embeddedFontIssueCount = 0;
        $embeddedFontIssueCodes = [];
        foreach ($this->elements($xpath, '/w:fonts/w:font') as $font) {
            $name = $font->getAttributeNS(self::NS_W, 'name');
            if ($name === '') {
                continue;
            }

            $record = array_filter([
                'name' => $name,
                'alternateName' => $this->childAttr($font, 'altName', 'val') ?: null,
                'charset' => $this->childAttr($font, 'charset', 'val') ?: null,
                'family' => $this->childAttr($font, 'family', 'val') ?: null,
                'pitch' => $this->childAttr($font, 'pitch', 'val') ?: null,
                'panose1' => $this->childAttr($font, 'panose1', 'val') ?: null,
            ], static fn (mixed $value): bool => $value !== null && $value !== '');
            $notTrueType = $this->childElement($font, 'notTrueType');
            if ($notTrueType instanceof \DOMElement) {
                $record['notTrueType'] = $this->wordBoolean($notTrueType);
            }
            $signature = $this->fontTableSignature($font);
            if ($signature !== []) {
                $record['signature'] = $signature;
            }
            $embeddedFonts = $this->fontTableEmbeddedFonts($font, $parts, $relationships, $partName, $relationshipsPart, $contentTypes);
            $record['embeddedFontCount'] = count($embeddedFonts);
            $record['embeddedFonts'] = $embeddedFonts;
            $embeddedFontRelationshipCount += count($embeddedFonts);
            foreach ($embeddedFonts as $embeddedFont) {
                if (($embeddedFont['external'] ?? false) === true) {
                    ++$embeddedFontExternalCount;
                    if (($embeddedFont['externalTargetAllowed'] ?? null) === true) {
                        ++$embeddedFontAllowedExternalCount;
                    } else {
                        ++$embeddedFontUnsafeExternalCount;
                        $this->appendUniqueString($embeddedFontUnsafeExternalTargets, is_string($embeddedFont['target'] ?? null) ? $embeddedFont['target'] : null);
                    }

                    $kind = is_string($embeddedFont['externalTargetKind'] ?? null) ? $embeddedFont['externalTargetKind'] : '(unknown)';
                    $embeddedFontExternalTargetKindCounts[$kind] = ($embeddedFontExternalTargetKindCounts[$kind] ?? 0) + 1;
                    $scheme = is_string($embeddedFont['externalTargetScheme'] ?? null) ? $embeddedFont['externalTargetScheme'] : '(none)';
                    $embeddedFontExternalTargetSchemeCounts[$scheme] = ($embeddedFontExternalTargetSchemeCounts[$scheme] ?? 0) + 1;
                    foreach (($embeddedFont['externalTargetIssues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $embeddedFontExternalTargetIssueCodes[$issue] = true;
                        }
                    }
                }
                $keyFormat = is_string($embeddedFont['fontKeyFormat'] ?? null) && $embeddedFont['fontKeyFormat'] !== ''
                    ? $embeddedFont['fontKeyFormat']
                    : 'unknown';
                $embeddedFontKeyFormatCounts[$keyFormat] = ($embeddedFontKeyFormatCounts[$keyFormat] ?? 0) + 1;
                if (($embeddedFont['fontKeyPresent'] ?? false) === true) {
                    ++$embeddedFontKeyPresentCount;
                    if (($embeddedFont['fontKeyExpectedByteLength'] ?? false) === true) {
                        ++$embeddedFontKeyExpectedByteLengthCount;
                    } else {
                        ++$embeddedFontKeyUnexpectedByteLengthCount;
                    }
                } else {
                    ++$embeddedFontKeyMissingCount;
                }
                if (($embeddedFont['external'] ?? false) === false && ($embeddedFont['exists'] ?? false) === true) {
                    ++$embeddedFontExistingCount;
                }
                if (in_array('missing-in-package', $embeddedFont['issues'], true)) {
                    ++$embeddedFontMissingCount;
                }
                if ($embeddedFont['issues'] !== []) {
                    ++$embeddedFontIssueCount;
                }
                foreach ($embeddedFont['issues'] as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $embeddedFontIssueCodes[$issue] = true;
                    }
                }
            }

            $fonts[] = $record;
            $byName[$name] = $record;
        }
        ksort($embeddedFontExternalTargetKindCounts, SORT_STRING);
        ksort($embeddedFontExternalTargetSchemeCounts, SORT_STRING);
        ksort($embeddedFontExternalTargetIssueCodes, SORT_STRING);
        ksort($embeddedFontKeyFormatCounts, SORT_STRING);
        ksort($embeddedFontIssueCodes, SORT_STRING);

        return [
            'relationshipsPart' => $relationshipsPart,
            'relationshipCount' => count($relationships),
            'validXml' => true,
            'xmlParseError' => null,
            'invalidXmlCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
            'fontCount' => count($fonts),
            'embeddedFontRelationshipCount' => $embeddedFontRelationshipCount,
            'embeddedFontExistingCount' => $embeddedFontExistingCount,
            'embeddedFontMissingCount' => $embeddedFontMissingCount,
            'embeddedFontExternalCount' => $embeddedFontExternalCount,
            'embeddedFontAllowedExternalCount' => $embeddedFontAllowedExternalCount,
            'embeddedFontUnsafeExternalCount' => $embeddedFontUnsafeExternalCount,
            'embeddedFontUnsafeExternalTargets' => $embeddedFontUnsafeExternalTargets,
            'embeddedFontExternalTargetKindCounts' => $embeddedFontExternalTargetKindCounts,
            'embeddedFontExternalTargetSchemeCounts' => $embeddedFontExternalTargetSchemeCounts,
            'embeddedFontExternalTargetIssueCodes' => array_keys($embeddedFontExternalTargetIssueCodes),
            'embeddedFontKeyPresentCount' => $embeddedFontKeyPresentCount,
            'embeddedFontKeyMissingCount' => $embeddedFontKeyMissingCount,
            'embeddedFontKeyExpectedByteLengthCount' => $embeddedFontKeyExpectedByteLengthCount,
            'embeddedFontKeyUnexpectedByteLengthCount' => $embeddedFontKeyUnexpectedByteLengthCount,
            'embeddedFontKeyFormatCounts' => $embeddedFontKeyFormatCounts,
            'embeddedFontIssueCount' => $embeddedFontIssueCount,
            'embeddedFontIssueCodes' => array_keys($embeddedFontIssueCodes),
            'notTrueTypeCount' => count(array_filter($fonts, static fn (array $font): bool => ($font['notTrueType'] ?? false) === true)),
            'signatureCount' => count(array_filter($fonts, static fn (array $font): bool => isset($font['signature']))),
            'signatureUnicodeRangeCount' => array_sum(array_map(static fn (array $font): int => (int) ($font['signature']['unicodeRangeCount'] ?? 0), $fonts)),
            'signatureCodePageRangeCount' => array_sum(array_map(static fn (array $font): int => (int) ($font['signature']['codePageRangeCount'] ?? 0), $fonts)),
            'declaredNames' => array_column($fonts, 'name'),
            'fonts' => $fonts,
            'byName' => $byName,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function fontTableSignature(\DOMElement $font): array
    {
        $signature = $this->childElement($font, 'sig');
        if (!$signature instanceof \DOMElement) {
            return [];
        }

        $unicodeRanges = [];
        foreach (['usb0', 'usb1', 'usb2', 'usb3'] as $attribute) {
            $value = trim($signature->getAttributeNS(self::NS_W, $attribute));
            if ($value !== '') {
                $unicodeRanges[$attribute] = $value;
            }
        }

        $codePageRanges = [];
        foreach (['csb0', 'csb1'] as $attribute) {
            $value = trim($signature->getAttributeNS(self::NS_W, $attribute));
            if ($value !== '') {
                $codePageRanges[$attribute] = $value;
            }
        }

        return [
            'unicodeRanges' => $unicodeRanges,
            'unicodeRangeCount' => count($unicodeRanges),
            'codePageRanges' => $codePageRanges,
            'codePageRangeCount' => count($codePageRanges),
            'rawAttributes' => [
                'usb0' => $unicodeRanges['usb0'] ?? null,
                'usb1' => $unicodeRanges['usb1'] ?? null,
                'usb2' => $unicodeRanges['usb2'] ?? null,
                'usb3' => $unicodeRanges['usb3'] ?? null,
                'csb0' => $codePageRanges['csb0'] ?? null,
                'csb1' => $codePageRanges['csb1'] ?? null,
            ],
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return list<array<string, mixed>>
     */
    private function fontTableEmbeddedFonts(
        \DOMElement $font,
        array $parts,
        array $relationships,
        string $fontTablePart,
        string $relationshipsPart,
        array $contentTypes
    ): array {
        $embeddedFonts = [];
        foreach ([
            'embedRegular' => 'regular',
            'embedBold' => 'bold',
            'embedItalic' => 'italic',
            'embedBoldItalic' => 'bold-italic',
        ] as $localName => $style) {
            $embedded = $this->childElement($font, $localName);
            if (!$embedded instanceof \DOMElement) {
                continue;
            }

            $relationshipId = $this->fontTableEmbeddedFontRelationshipId($embedded);
            $embeddedFonts[] = $this->fontTableEmbeddedFontItem(
                $parts,
                $relationships[$relationshipId] ?? null,
                $fontTablePart,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                $style,
                $this->fontTableEmbeddedFontKey($embedded),
            );
        }

        return $embeddedFonts;
    }

    private function fontTableEmbeddedFontRelationshipId(\DOMElement $embedded): string
    {
        $relationshipId = trim($embedded->getAttributeNS(self::NS_R, 'id'));
        if ($relationshipId !== '') {
            return $relationshipId;
        }

        return trim($embedded->getAttribute('id'));
    }

    private function fontTableEmbeddedFontKey(\DOMElement $embedded): string
    {
        $fontKey = trim($embedded->getAttributeNS(self::NS_W, 'fontKey'));
        if ($fontKey !== '') {
            return $fontKey;
        }

        return trim($embedded->getAttribute('fontKey'));
    }

    /**
     * @return array<string, mixed>
     */
    private function fontTableEmbeddedFontKeyMetadata(string $fontKey): array
    {
        $present = $fontKey !== '';
        if (!$present) {
            return [
                'present' => false,
                'sha256' => null,
                'format' => 'missing',
                'valueLength' => 0,
                'normalizedHexLength' => 0,
                'byteLength' => null,
                'validHex' => false,
                'hasGuidBraces' => false,
                'guidFormat' => false,
                'expectedByteLength' => false,
            ];
        }

        $hasGuidBraces = str_starts_with($fontKey, '{') && str_ends_with($fontKey, '}');
        $unwrapped = $hasGuidBraces ? substr($fontKey, 1, -1) : $fontKey;
        $normalizedHex = str_replace('-', '', $unwrapped);
        $normalizedHexLength = strlen($normalizedHex);
        $validHex = $normalizedHexLength > 0
            && $normalizedHexLength % 2 === 0
            && preg_match('/^[0-9A-Fa-f]+$/', $normalizedHex) === 1;
        $byteLength = $validHex ? intdiv($normalizedHexLength, 2) : null;
        $guidFormat = preg_match('/^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$/', $unwrapped) === 1;
        $hyphenlessExpectedKey = preg_match('/^[0-9A-Fa-f]{32}$/', $unwrapped) === 1;
        $format = 'other';
        if ($guidFormat && $hasGuidBraces) {
            $format = 'braced-guid';
        } elseif ($guidFormat) {
            $format = 'guid';
        } elseif ($hyphenlessExpectedKey) {
            $format = 'hex-16-byte';
        } elseif ($validHex) {
            $format = 'hex';
        }

        return [
            'present' => true,
            'sha256' => hash('sha256', $fontKey),
            'format' => $format,
            'valueLength' => strlen($fontKey),
            'normalizedHexLength' => $normalizedHexLength,
            'byteLength' => $byteLength,
            'validHex' => $validHex,
            'hasGuidBraces' => $hasGuidBraces,
            'guidFormat' => $guidFormat,
            'expectedByteLength' => $validHex && $byteLength === 16,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function fontTableEmbeddedFontItem(
        array $parts,
        ?array $relationship,
        string $fontTablePart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        string $style,
        string $fontKey
    ): array {
        $fontKeyMetadata = $this->fontTableEmbeddedFontKeyMetadata($fontKey);
        $item = [
            'style' => $style,
            'id' => $relationshipId,
            'sourcePart' => $fontTablePart,
            'relationshipsPart' => $relationshipsPart,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'expectedContentTypeBase' => self::CT_OBFUSCATED_FONT,
            'external' => false,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'externalTargetIssues' => [],
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'fontKeyPresent' => $fontKeyMetadata['present'],
            'fontKeySha256' => $fontKeyMetadata['sha256'],
            'fontKeyFormat' => $fontKeyMetadata['format'],
            'fontKeyValueLength' => $fontKeyMetadata['valueLength'],
            'fontKeyNormalizedHexLength' => $fontKeyMetadata['normalizedHexLength'],
            'fontKeyByteLength' => $fontKeyMetadata['byteLength'],
            'fontKeyValidHex' => $fontKeyMetadata['validHex'],
            'fontKeyHasGuidBraces' => $fontKeyMetadata['hasGuidBraces'],
            'fontKeyGuidFormat' => $fontKeyMetadata['guidFormat'],
            'fontKeyExpectedByteLength' => $fontKeyMetadata['expectedByteLength'],
            'fontKeyReviewPolicy' => 'embedded-font-key-metadata-only',
            'byteExposurePolicy' => 'embedded-font-bytes-blocked',
            'reviewPolicy' => 'embedded-font-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'missing-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $fontTablePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['external'] = $external;
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['externalTargetIssues'] = $summary['externalTargetIssues'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::FONT_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($external) {
            $item['issues'][] = 'external-embedded-font';
            foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $item['issues'][] = $issue;
                }
            }
        } else {
            if (!$exists) {
                $item['issues'][] = 'missing-in-package';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-content-type';
            } elseif ($contentTypeBase !== self::CT_OBFUSCATED_FONT) {
                $item['issues'][] = 'unexpected-embedded-font-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @return array<string, mixed>
     */
    private function readTheme(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->namespaceURI !== self::NS_A || $root->localName !== 'theme') {
            return [];
        }

        $theme = [];
        $name = trim($root->getAttribute('name'));
        if ($name !== '') {
            $theme['name'] = $name;
        }

        $fonts = $this->themeFontScheme($xpath, $root);
        if ($fonts !== []) {
            $theme['fonts'] = $fonts;
        }

        $colors = $this->themeColorScheme($xpath, $root);
        if ($colors !== []) {
            $theme['colors'] = $colors;
        }

        return $theme;
    }

    /**
     * @return array<string, string>
     */
    private function themeFontScheme(\DOMXPath $xpath, \DOMElement $theme): array
    {
        $fontScheme = $this->firstElement($xpath, 'a:themeElements/a:fontScheme', $theme);
        if (!$fontScheme instanceof \DOMElement) {
            return [];
        }

        $fonts = [];
        $schemeName = trim($fontScheme->getAttribute('name'));
        if ($schemeName !== '') {
            $fonts['schemeName'] = $schemeName;
        }

        $supplementalFontCount = 0;
        $supplementalFontScripts = [];
        foreach ([
            'majorFont' => 'major',
            'minorFont' => 'minor',
        ] as $fontElementName => $prefix) {
            $fontElement = $this->firstElement($xpath, 'a:' . $fontElementName, $fontScheme);
            if (!$fontElement instanceof \DOMElement) {
                continue;
            }

            foreach ([
                'latin' => 'Latin',
                'ea' => 'EastAsia',
                'cs' => 'ComplexScript',
            ] as $source => $target) {
                $sourceElement = $this->firstElement($xpath, 'a:' . $source, $fontElement);
                if (!$sourceElement instanceof \DOMElement) {
                    continue;
                }

                $typeface = trim($sourceElement->getAttribute('typeface'));
                if ($typeface !== '') {
                    $fonts[$prefix . $target] = $typeface;
                }
            }

            $supplemental = $this->themeSupplementalFonts($fontElement);
            if ($supplemental['items'] !== []) {
                $fonts[$prefix . 'SupplementalFontCount'] = count($supplemental['items']);
                $fonts[$prefix . 'SupplementalFonts'] = $supplemental['items'];
                $fonts[$prefix . 'SupplementalFontsByScript'] = $supplemental['byScript'];
                $supplementalFontCount += count($supplemental['items']);
                foreach (array_keys($supplemental['byScript']) as $script) {
                    $supplementalFontScripts[$script] = true;
                }
            }
        }

        if ($supplementalFontCount > 0) {
            $fonts['supplementalFontCount'] = $supplementalFontCount;
            $scripts = array_keys($supplementalFontScripts);
            sort($scripts, SORT_STRING);
            $fonts['supplementalFontScripts'] = $scripts;
        }

        return $fonts;
    }

    /**
     * @return array{items:list<array{script:string, typeface:string}>, byScript:array<string, string>}
     */
    private function themeSupplementalFonts(\DOMElement $fontElement): array
    {
        $items = [];
        $byScript = [];
        foreach ($fontElement->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_A || $child->localName !== 'font') {
                continue;
            }

            $script = trim($child->getAttribute('script'));
            $typeface = trim($child->getAttribute('typeface'));
            if ($script === '' || $typeface === '') {
                continue;
            }

            $items[] = [
                'script' => $script,
                'typeface' => $typeface,
            ];
            $byScript[$script] = $typeface;
        }

        return [
            'items' => $items,
            'byScript' => $byScript,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function themeColorScheme(\DOMXPath $xpath, \DOMElement $theme): array
    {
        $colorScheme = $this->firstElement($xpath, 'a:themeElements/a:clrScheme', $theme);
        if (!$colorScheme instanceof \DOMElement) {
            return [];
        }

        $items = [];
        $byName = [];
        $transformCount = 0;
        $transformNames = [];
        foreach ($colorScheme->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_A) {
                continue;
            }

            $name = $child->localName;
            if (!in_array($name, ['dk1', 'lt1', 'dk2', 'lt2', 'accent1', 'accent2', 'accent3', 'accent4', 'accent5', 'accent6', 'hlink', 'folHlink'], true)) {
                continue;
            }

            $color = $this->themeColorSchemeEntry($child);
            if ($color === null) {
                continue;
            }

            $item = ['name' => $name] + $color;
            if (isset($item['transformCount']) && is_int($item['transformCount'])) {
                $transformCount += $item['transformCount'];
                foreach (($item['transformNames'] ?? []) as $transformName) {
                    if (is_string($transformName)) {
                        $transformNames[$transformName] = true;
                    }
                }
            }
            $items[] = $item;
            if (is_string($item['rgb'] ?? null) && $item['rgb'] !== '') {
                $byName[$name] = $item['rgb'];
                foreach ($this->themeColorAliases($name) as $alias) {
                    $byName[$alias] = $item['rgb'];
                }
            }
        }

        if ($items === []) {
            return [];
        }

        $scheme = [
            'count' => count($items),
            'items' => $items,
            'byName' => $byName,
        ];
        if ($transformCount > 0) {
            $names = array_keys($transformNames);
            sort($names, SORT_STRING);
            $scheme['transformCount'] = $transformCount;
            $scheme['transformNames'] = $names;
        }
        $schemeName = trim($colorScheme->getAttribute('name'));
        if ($schemeName !== '') {
            $scheme = ['schemeName' => $schemeName] + $scheme;
        }

        return $scheme;
    }

    /**
     * @return array<string, mixed>|null
     */
    private function themeColorSchemeEntry(\DOMElement $container): ?array
    {
        foreach ($container->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_A) {
                continue;
            }

            if ($child->localName === 'srgbClr') {
                $rgb = $this->normalizedRgb($child->getAttribute('val'));
                if ($rgb === null) {
                    continue;
                }

                return $this->themeColorEntryWithTransforms($child, [
                    'kind' => 'srgb',
                    'value' => $rgb,
                    'rgb' => $rgb,
                ]);
            }

            if ($child->localName === 'sysClr') {
                $value = trim($child->getAttribute('val'));

                return $this->themeColorEntryWithTransforms($child, [
                    'kind' => 'system',
                    'value' => $value !== '' ? $value : null,
                    'rgb' => $this->normalizedRgb($child->getAttribute('lastClr')),
                ]);
            }

            if ($child->localName === 'prstClr') {
                $value = trim($child->getAttribute('val'));
                if ($value === '') {
                    continue;
                }

                return $this->themeColorEntryWithTransforms($child, [
                    'kind' => 'preset',
                    'value' => $value,
                    'rgb' => null,
                ]);
            }

            if ($child->localName === 'schemeClr') {
                $value = trim($child->getAttribute('val'));
                if ($value === '') {
                    continue;
                }

                return $this->themeColorEntryWithTransforms($child, [
                    'kind' => 'scheme',
                    'value' => $value,
                    'rgb' => null,
                ]);
            }
        }

        return null;
    }

    /**
     * @param array<string, mixed> $entry
     * @return array<string, mixed>
     */
    private function themeColorEntryWithTransforms(\DOMElement $color, array $entry): array
    {
        $transforms = $this->themeColorTransforms($color);
        if ($transforms['items'] === []) {
            return $entry;
        }

        $entry['transformCount'] = count($transforms['items']);
        $entry['transforms'] = $transforms['items'];
        $entry['transformNames'] = $transforms['names'];
        $entry['transformValuesByName'] = $transforms['valuesByName'];

        return $entry;
    }

    /**
     * @return array{items:list<array{name:string, value:?string}>, names:list<string>, valuesByName:array<string, string>}
     */
    private function themeColorTransforms(\DOMElement $color): array
    {
        $transformNames = [
            'alpha' => true,
            'alphaMod' => true,
            'alphaOff' => true,
            'blue' => true,
            'blueMod' => true,
            'blueOff' => true,
            'comp' => true,
            'gamma' => true,
            'gray' => true,
            'green' => true,
            'greenMod' => true,
            'greenOff' => true,
            'hue' => true,
            'hueMod' => true,
            'hueOff' => true,
            'inv' => true,
            'invGamma' => true,
            'lum' => true,
            'lumMod' => true,
            'lumOff' => true,
            'red' => true,
            'redMod' => true,
            'redOff' => true,
            'sat' => true,
            'satMod' => true,
            'satOff' => true,
            'shade' => true,
            'tint' => true,
        ];
        $items = [];
        $names = [];
        $valuesByName = [];

        foreach ($color->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_A || !isset($transformNames[$child->localName])) {
                continue;
            }

            $value = trim($child->getAttribute('val'));
            $items[] = [
                'name' => $child->localName,
                'value' => $value !== '' ? $value : null,
            ];
            $names[$child->localName] = true;
            if ($value !== '') {
                $valuesByName[$child->localName] = $value;
            }
        }

        $sortedNames = array_keys($names);
        sort($sortedNames, SORT_STRING);

        return [
            'items' => $items,
            'names' => $sortedNames,
            'valuesByName' => $valuesByName,
        ];
    }

    private function normalizedRgb(string $value): ?string
    {
        $value = strtoupper(trim($value));

        return preg_match('/^[0-9A-F]{6}$/D', $value) === 1 ? $value : null;
    }

    /**
     * @return list<string>
     */
    private function themeColorAliases(string $name): array
    {
        return match ($name) {
            'dk1' => ['dark1', 'text1'],
            'lt1' => ['light1', 'background1'],
            'dk2' => ['dark2', 'text2'],
            'lt2' => ['light2', 'background2'],
            'hlink' => ['hyperlink'],
            'folHlink' => ['followedHyperlink', 'followed-hyperlink'],
            default => [],
        };
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return array<string, mixed>
     */
    private function readGlossaryDocument(
        array $parts,
        string $xml,
        string $partName,
        bool $exists,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering,
        array $referencedNotes
    ): array {
        $relationshipDiagnostics = $this->relatedPartRelationshipDiagnostics(
            $parts,
            $relationships,
            $partName,
            $relationshipsPart,
            $contentTypes,
        );
        $relationshipReview = $this->glossaryDocumentRelationshipReview([], $relationshipDiagnostics);
        $summary = [
            'partName' => $partName,
            'exists' => $exists,
            'relationshipsPart' => $relationshipsPart,
            'validXml' => null,
            'xmlParseError' => null,
            'validRoot' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'invalidXmlCount' => 0,
            'invalidRootCount' => 0,
            'count' => 0,
            'bodyBlockCount' => 0,
            'names' => [],
            'galleries' => [],
            'categories' => [],
            'types' => [],
            'behaviors' => [],
            'relationshipIds' => [],
            'byName' => [],
            'items' => [],
            'issueCount' => 0,
            'issueCodes' => [],
            'reviewPolicy' => 'glossary-document-metadata-only',
        ];
        foreach ($relationshipReview as $key => $value) {
            if ($key !== 'items' && $key !== 'byName') {
                $summary[$key] = $value;
            }
        }

        if (!$exists || $xml === '') {
            return $summary;
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            $summary['validXml'] = false;
            $summary['validRoot'] = false;
            $summary['xmlParseError'] = $this->lastXmlPreflightError($xml, $partName);
            $summary['invalidXmlCount'] = 1;
            $summary['invalidRootCount'] = 1;
            $summary['issueCount'] = 1;
            $summary['issueCodes'] = ['invalid-xml'];

            return $summary;
        }

        $root = $dom->documentElement;
        $summary['validXml'] = $root instanceof \DOMElement;
        $summary['rootNamespace'] = $root instanceof \DOMElement ? $root->namespaceURI : null;
        $summary['rootLocalName'] = $root instanceof \DOMElement ? $root->localName : null;
        $summary['validRoot'] = $root instanceof \DOMElement
            && $root->namespaceURI === self::NS_W
            && $root->localName === 'glossaryDocument';

        if ($summary['validRoot'] !== true) {
            $summary['invalidRootCount'] = 1;
            $summary['issueCount'] = 1;
            $summary['issueCodes'] = ['unexpected-root'];

            return $summary;
        }

        $xpath = $this->xpath($dom);
        $issueCodes = [];
        foreach ($this->elements($xpath, '/w:glossaryDocument/w:docParts/w:docPart') as $docPart) {
            $item = $this->glossaryDocPartItem(
                $docPart,
                $xpath,
                $relationships,
                $contentTypes,
                $styles,
                $numbering,
                $referencedNotes,
                count($summary['items']),
            );
            $summary['items'][] = $item;
            $summary['bodyBlockCount'] += $item['bodyBlockCount'];

            $this->appendUniqueString($summary['names'], $item['name']);
            $this->appendUniqueString($summary['galleries'], $item['gallery']);
            $this->appendUniqueString($summary['categories'], $item['category']);
            foreach ($item['types'] as $type) {
                $this->appendUniqueString($summary['types'], $type);
            }
            foreach ($item['behaviors'] as $behavior) {
                $this->appendUniqueString($summary['behaviors'], $behavior);
            }
            foreach ($item['relationshipIds'] as $relationshipId) {
                $this->appendUniqueString($summary['relationshipIds'], $relationshipId);
            }
            foreach ($item['issues'] as $issue) {
                $issueCodes[$issue] = true;
            }
        }

        $relationshipReview = $this->glossaryDocumentRelationshipReview($summary['items'], $relationshipDiagnostics);
        $summary['items'] = $relationshipReview['items'];
        $summary['byName'] = $relationshipReview['byName'];
        foreach ($relationshipReview as $key => $value) {
            if ($key !== 'items' && $key !== 'byName') {
                $summary[$key] = $value;
            }
        }
        ksort($issueCodes, SORT_STRING);
        $summary['count'] = count($summary['items']);
        $summary['issueCount'] = count(array_filter($summary['items'], static fn (array $item): bool => $item['issues'] !== []));
        $summary['issueCodes'] = array_keys($issueCodes);

        return $summary;
    }

    /**
     * @param list<array<string, mixed>> $items
     * @param array<string, mixed> $relationshipDiagnostics
     * @return array<string, mixed>
     */
    private function glossaryDocumentRelationshipReview(array $items, array $relationshipDiagnostics): array
    {
        $relationships = is_array($relationshipDiagnostics['byId'] ?? null) ? $relationshipDiagnostics['byId'] : [];
        $allRelationshipIds = is_array($relationshipDiagnostics['relationshipIds'] ?? null)
            ? array_values(array_filter(
                array_map('strval', $relationshipDiagnostics['relationshipIds']),
                static fn (string $value): bool => $value !== '',
            ))
            : [];
        sort($allRelationshipIds, SORT_STRING);
        $relationshipRecords = is_array($relationshipDiagnostics['relationshipRecords'] ?? null)
            ? $relationshipDiagnostics['relationshipRecords']
            : [];
        $relationshipRecordsById = [];
        foreach ($relationshipRecords as $record) {
            if (!is_array($record)) {
                continue;
            }

            $recordId = is_string($record['id'] ?? null) ? $record['id'] : '';
            if ($recordId === '') {
                continue;
            }

            $relationshipRecordsById[$recordId][] = $record;
        }

        $duplicateRelationshipIds = is_array($relationshipDiagnostics['duplicateRelationshipIds'] ?? null)
            ? array_values(array_filter(
                array_map('strval', $relationshipDiagnostics['duplicateRelationshipIds']),
                static fn (string $value): bool => $value !== '',
            ))
            : [];
        $duplicateRelationshipIdSet = array_fill_keys($duplicateRelationshipIds, true);
        $relationshipBacklinks = [];
        $referencedRelationshipIds = [];
        $knownReferencedRelationshipIds = [];
        $missingReferencedRelationshipIds = [];
        $reconciledItems = [];
        $reconciledByName = [];

        foreach ($items as $itemIndex => $item) {
            $relationshipIds = is_array($item['relationshipIds'] ?? null) ? $item['relationshipIds'] : [];
            $knownRelationshipIds = [];
            $itemDuplicateRelationshipIds = [];
            $itemReferencedRelationships = [];
            $itemReferencedRelationshipItems = [];
            $itemReferencedRelationshipRecords = [];
            $itemRelationshipBacklinks = [];
            $itemRelationshipIssueCodes = [];

            foreach ($relationshipIds as $relationshipId) {
                if (!is_string($relationshipId) || $relationshipId === '') {
                    continue;
                }

                $itemName = is_string($item['name'] ?? null) ? $item['name'] : null;
                $backlink = [
                    'relationshipId' => $relationshipId,
                    'itemIndex' => $itemIndex,
                    'itemName' => $itemName,
                    'known' => isset($relationships[$relationshipId]),
                ];
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if (isset($relationships[$relationshipId])) {
                    $this->appendUniqueString($knownRelationshipIds, $relationshipId);
                    $this->appendUniqueString($knownReferencedRelationshipIds, $relationshipId);
                    $itemReferencedRelationships[$relationshipId] = $relationships[$relationshipId];
                    $itemReferencedRelationshipItems[] = $relationships[$relationshipId];
                    foreach (($relationships[$relationshipId]['issues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $itemRelationshipIssueCodes[$issue] = true;
                        }
                    }
                } else {
                    $this->appendUniqueString($missingReferencedRelationshipIds, $relationshipId);
                    $itemRelationshipIssueCodes['missing-relationship'] = true;
                }
                if (isset($duplicateRelationshipIdSet[$relationshipId])) {
                    $this->appendUniqueString($itemDuplicateRelationshipIds, $relationshipId);
                }
                foreach ($relationshipRecordsById[$relationshipId] ?? [] as $record) {
                    $itemReferencedRelationshipRecords[] = $record;
                }

                $relationshipBacklinks[$relationshipId] ??= [];
                $relationshipBacklinks[$relationshipId][] = $backlink;
                $itemRelationshipBacklinks[] = $backlink;
            }

            ksort($itemRelationshipIssueCodes, SORT_STRING);
            $item['knownRelationshipIds'] = $knownRelationshipIds;
            $item['knownRelationshipCount'] = count($knownRelationshipIds);
            $item['referencedRelationshipIds'] = $knownRelationshipIds;
            $item['referencedRelationshipCount'] = count($knownRelationshipIds);
            $item['missingRelationshipIds'] = $this->missingRelationshipIds($relationshipIds, $relationships);
            $item['missingRelationshipCount'] = count($item['missingRelationshipIds']);
            $item['referencedDuplicateRelationshipIds'] = $itemDuplicateRelationshipIds;
            $item['duplicateRelationshipIds'] = $itemDuplicateRelationshipIds;
            $item['duplicateRelationshipCount'] = count($itemDuplicateRelationshipIds);
            $item['referencedRelationships'] = $itemReferencedRelationships;
            $item['referencedRelationshipItems'] = $itemReferencedRelationshipItems;
            $item['referencedRelationshipRecordCount'] = count($itemReferencedRelationshipRecords);
            $item['referencedRelationshipRecords'] = $itemReferencedRelationshipRecords;
            $item['relationshipIssueCount'] = count($itemRelationshipIssueCodes);
            $item['relationshipIssueCodes'] = array_keys($itemRelationshipIssueCodes);
            $item['relationshipBacklinks'] = $itemRelationshipBacklinks;

            $reconciledItems[] = $item;
            if (is_string($item['name'] ?? null) && $item['name'] !== '' && !isset($reconciledByName[$item['name']])) {
                $reconciledByName[$item['name']] = $item;
            }
        }

        $unreferencedRelationshipIds = [];
        foreach (($relationshipDiagnostics['relationshipIds'] ?? []) as $relationshipId) {
            if (!is_string($relationshipId) || $relationshipId === '') {
                continue;
            }

            $referenced = in_array($relationshipId, $referencedRelationshipIds, true);
            if (!$referenced) {
                $unreferencedRelationshipIds[] = $relationshipId;
            }

            if (isset($relationships[$relationshipId])) {
                $relationships[$relationshipId]['referenced'] = $referenced;
                $relationships[$relationshipId]['orphaned'] = !$referenced;
                $relationships[$relationshipId]['referencedItemNames'] = array_values(array_filter(array_unique(array_map(
                    static fn (array $backlink): string => is_string($backlink['itemName'] ?? null) ? $backlink['itemName'] : '',
                    $relationshipBacklinks[$relationshipId] ?? [],
                )), static fn (string $value): bool => $value !== ''));
                $relationships[$relationshipId]['referencedItemIndexes'] = array_values(array_unique(array_map(
                    static fn (array $backlink): int => (int) ($backlink['itemIndex'] ?? 0),
                    $relationshipBacklinks[$relationshipId] ?? [],
                )));
                $relationships[$relationshipId]['referencedItemCount'] = count($relationships[$relationshipId]['referencedItemNames']);
                $relationships[$relationshipId]['referenceBacklinks'] = $relationshipBacklinks[$relationshipId] ?? [];
            }
        }

        $relationshipDiagnostics['referencedRelationshipIds'] = $referencedRelationshipIds;
        $relationshipDiagnostics['knownReferencedRelationshipIds'] = $knownReferencedRelationshipIds;
        $relationshipDiagnostics['unreferencedRelationshipIds'] = $unreferencedRelationshipIds;
        $relationshipDiagnostics['orphanedRelationshipIds'] = $unreferencedRelationshipIds;
        $relationshipDiagnostics['missingReferencedRelationshipIds'] = $missingReferencedRelationshipIds;
        $relationshipDiagnostics['relationshipBacklinks'] = $relationshipBacklinks;
        $relationshipDiagnostics['byId'] = $relationships;
        $relationshipDiagnostics['items'] = array_values($relationships);

        return [
            'items' => $reconciledItems,
            'byName' => $reconciledByName,
            'relationshipsPart' => $relationshipDiagnostics['relationshipsPart'],
            'relationshipCount' => $relationshipDiagnostics['relationshipCount'],
            'relationshipRecordCount' => $relationshipDiagnostics['relationshipRecordCount'],
            'duplicateRelationshipIdCount' => $relationshipDiagnostics['duplicateRelationshipIdCount'],
            'duplicateRelationshipRecordCount' => $relationshipDiagnostics['duplicateRelationshipRecordCount'],
            'duplicateRelationshipIds' => $relationshipDiagnostics['duplicateRelationshipIds'],
            'duplicateRelationshipIdItems' => $relationshipDiagnostics['duplicateRelationshipIdItems'],
            'invalidRelationshipRecordCount' => $relationshipDiagnostics['invalidRelationshipRecordCount'],
            'relationshipRecordIssueCount' => $relationshipDiagnostics['relationshipRecordIssueCount'],
            'relationshipRecordIssueCodes' => $relationshipDiagnostics['relationshipRecordIssueCodes'],
            'invalidRelationshipRecords' => $relationshipDiagnostics['invalidRelationshipRecords'],
            'internalRelationshipCount' => $relationshipDiagnostics['internalRelationshipCount'],
            'externalRelationshipCount' => $relationshipDiagnostics['externalRelationshipCount'],
            'existingRelationshipTargetCount' => $relationshipDiagnostics['existingTargetCount'],
            'missingRelationshipTargetCount' => $relationshipDiagnostics['missingTargetCount'],
            'missingRelationshipContentTypeCount' => $relationshipDiagnostics['missingContentTypeCount'],
            'relationshipTargetReferenceSuffixCount' => $relationshipDiagnostics['targetReferenceSuffixCount'],
            'relationshipIds' => $allRelationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'knownReferencedRelationshipIds' => $knownReferencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'orphanedRelationshipIds' => $unreferencedRelationshipIds,
            'missingReferencedRelationshipIds' => $missingReferencedRelationshipIds,
            'referencedRelationshipCount' => count($referencedRelationshipIds),
            'knownReferencedRelationshipCount' => count($knownReferencedRelationshipIds),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'orphanedRelationshipCount' => count($unreferencedRelationshipIds),
            'missingReferencedRelationshipCount' => count($missingReferencedRelationshipIds),
            'relationshipTargetParts' => $relationshipDiagnostics['targetParts'],
            'relationshipExternalTargets' => $relationshipDiagnostics['externalTargets'],
            'relationshipTargetReferenceSuffixes' => $relationshipDiagnostics['targetReferenceSuffixes'],
            'relationshipIssueCount' => $relationshipDiagnostics['issueCount'],
            'relationshipIssueCodes' => $relationshipDiagnostics['issueCodes'],
            'relationshipRecords' => $relationshipRecords,
            'relationshipBacklinks' => $relationshipBacklinks,
            'relationships' => $relationships,
            'relationshipDiagnostics' => $relationshipDiagnostics,
        ];
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return array<string, mixed>
     */
    private function glossaryDocPartItem(
        \DOMElement $docPart,
        \DOMXPath $xpath,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering,
        array $referencedNotes,
        int $index
    ): array {
        $properties = $this->childElement($docPart, 'docPartPr');
        $body = $this->childElement($docPart, 'docPartBody');
        $types = $this->glossaryDocPartValues($xpath, 'w:types/w:type', $properties);
        $behaviors = $this->glossaryDocPartValues($xpath, 'w:behaviors/w:behavior', $properties);
        $blocks = $body instanceof \DOMElement
            ? $this->readWordBlockChildren($body->childNodes, $xpath, $relationships, $contentTypes, $styles, $numbering, $referencedNotes)
            : [];
        $relationshipIds = $body instanceof \DOMElement ? $this->relationshipIdsInElement($body) : [];
        $issues = [];
        if (!$body instanceof \DOMElement) {
            $issues[] = 'missing-body';
        }

        return [
            'index' => $index,
            'sourceType' => 'glossaryDocument',
            'name' => $this->glossaryDocPartValue('name', $properties),
            'styleId' => $this->glossaryDocPartValue('style', $properties),
            'category' => $this->glossaryDocPartNestedValue('category', 'name', $properties),
            'gallery' => $this->glossaryDocPartNestedValue('category', 'gallery', $properties),
            'description' => $this->glossaryDocPartValue('description', $properties),
            'guid' => $this->glossaryDocPartValue('guid', $properties),
            'types' => $types,
            'behaviors' => $behaviors,
            'relationshipCount' => count($relationshipIds),
            'relationshipIds' => $relationshipIds,
            'bodyBlockCount' => count($blocks),
            'text' => $this->plainBlockText($blocks),
            'issues' => $issues,
        ];
    }

    private function glossaryDocPartValue(string $childLocalName, ?\DOMElement $properties): ?string
    {
        if (!$properties instanceof \DOMElement) {
            return null;
        }

        return $this->emptyStringToNull($this->childAttr($properties, $childLocalName, 'val'));
    }

    private function glossaryDocPartNestedValue(string $parentLocalName, string $childLocalName, ?\DOMElement $properties): ?string
    {
        $parent = $this->childElement($properties, $parentLocalName);
        if (!$parent instanceof \DOMElement) {
            return null;
        }

        return $this->glossaryDocPartValue($childLocalName, $parent);
    }

    /**
     * @return list<string>
     */
    private function glossaryDocPartValues(\DOMXPath $xpath, string $query, ?\DOMElement $properties): array
    {
        if (!$properties instanceof \DOMElement) {
            return [];
        }

        $values = [];
        foreach ($this->elements($xpath, $query, $properties) as $element) {
            $this->appendUniqueString($values, $this->emptyStringToNull($element->getAttributeNS(self::NS_W, 'val')));
        }

        return $values;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @return array{summary:array{count:int, ids:list<string>, byId:array<string, array{id:string, sourceType:string, type:string, blockCount:int, text:string}>, items:list<array{id:string, sourceType:string, type:string, blockCount:int, text:string}>}, nodes:array<string, AstNode>}
     */
    private function readNotes(
        array $parts,
        string $xml,
        string $partName,
        string $relationshipsPart,
        string $rootName,
        string $itemName,
        string $sourceType,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering
    ): array {
        $relationshipDiagnostics = $this->relatedPartRelationshipDiagnostics(
            $parts,
            $relationships,
            $partName,
            $relationshipsPart,
            $contentTypes,
        );
        $xmlProvenance = [
            'validXml' => null,
            'xmlParseError' => null,
            'validRoot' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'invalidXmlCount' => 0,
            'invalidRootCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
        ];
        if ($xml === '') {
            return [
                'summary' => $this->noteCollectionSummary([], [], $relationshipDiagnostics, $xmlProvenance),
                'nodes' => [],
            ];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument || !$dom->documentElement instanceof \DOMElement) {
            $xmlProvenance['validXml'] = false;
            $xmlProvenance['xmlParseError'] = $this->lastXmlPreflightError($xml, $partName);
            $xmlProvenance['validRoot'] = false;
            $xmlProvenance['invalidXmlCount'] = 1;
            $xmlProvenance['invalidRootCount'] = 1;
            $xmlProvenance['issueCount'] = 1;
            $xmlProvenance['issueCodes'] = ['invalid-' . $rootName . '-xml'];

            return [
                'summary' => $this->noteCollectionSummary([], [], $relationshipDiagnostics, $xmlProvenance),
                'nodes' => [],
            ];
        }

        $root = $dom->documentElement;
        $xmlProvenance['validXml'] = true;
        $xmlProvenance['rootNamespace'] = $root->namespaceURI;
        $xmlProvenance['rootLocalName'] = $root->localName;
        $xmlProvenance['validRoot'] = $root->namespaceURI === self::NS_W && $root->localName === $rootName;
        if ($xmlProvenance['validRoot'] !== true) {
            $xmlProvenance['invalidRootCount'] = 1;
            $xmlProvenance['issueCount'] = 1;
            $xmlProvenance['issueCodes'] = ['unexpected-' . $rootName . '-root'];

            return [
                'summary' => $this->noteCollectionSummary([], [], $relationshipDiagnostics, $xmlProvenance),
                'nodes' => [],
            ];
        }

        $xpath = $this->xpath($dom);
        $items = [];
        $byId = [];
        $nodes = [];
        foreach ($root->childNodes as $note) {
            if (!$note instanceof \DOMElement || $note->namespaceURI !== self::NS_W || $note->localName !== $itemName) {
                continue;
            }

            $id = $note->getAttributeNS(self::NS_W, 'id');
            $type = strtolower($note->getAttributeNS(self::NS_W, 'type'));
            if ($id === '' || str_starts_with($id, '-') || in_array($type, ['separator', 'continuationseparator', 'continuationnotice'], true)) {
                continue;
            }

            $blocks = $this->readNoteBlocks($note, $xpath, $relationships, $contentTypes, $styles, $numbering);
            $relationshipIds = $this->relationshipIdsInElement($note);
            $item = [
                'id' => $id,
                'sourceType' => $sourceType,
                'type' => $type === '' ? 'normal' : $type,
                'blockCount' => count($blocks),
                'text' => $this->plainBlockText($blocks),
                'relationshipCount' => count($relationshipIds),
                'relationshipIds' => $relationshipIds,
                'missingRelationshipIds' => $this->missingRelationshipIds($relationshipIds, $relationships),
            ];
            $items[] = $item;
            $byId[$id] = $item;
            $nodes[$id] = new AstNode('note', [
                'id' => $id,
                'sourceType' => $sourceType,
            ], $blocks);
        }

        return [
            'summary' => $this->noteCollectionSummary($items, $byId, $relationshipDiagnostics, $xmlProvenance),
            'nodes' => $nodes,
        ];
    }

    /**
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readPeoplePart(
        string $xml,
        string $partName,
        bool $exists,
        ?array $relationship,
        array $contentTypes
    ): array {
        $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
        $items = [];
        $byAuthor = [];
        $authors = [];
        $providerIds = [];
        $userIds = [];
        $presenceInfoCount = 0;
        $issues = [];
        $validXml = null;
        $xmlParseError = null;
        $rootNamespace = null;
        $rootLocalName = null;
        $validRoot = null;

        if ($relationship !== null && !$exists) {
            $issues[] = 'missing-people-part';
        }
        if ($exists) {
            if (($contentTypeResolution['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-people-content-type';
            } elseif (($contentTypeResolution['contentTypeBase'] ?? '') !== self::CT_WORD_PEOPLE) {
                $issues[] = 'unexpected-people-content-type';
            }

            $dom = $this->loadXmlForProvenance($xml, $partName);
            if (!$dom instanceof \DOMDocument || !$dom->documentElement instanceof \DOMElement) {
                $validXml = false;
                $xmlParseError = $this->lastXmlPreflightError($xml, $partName);
                $validRoot = false;
                $issues[] = 'invalid-people-xml';
            } else {
                $root = $dom->documentElement;
                $validXml = true;
                $rootNamespace = $root->namespaceURI;
                $rootLocalName = $root->localName;
                $validRoot = $rootNamespace === self::NS_W15 && $rootLocalName === 'people';
                if (!$validRoot) {
                    $issues[] = 'unexpected-people-root';
                } else {
                    foreach ($root->childNodes as $person) {
                        if (!$person instanceof \DOMElement || $person->namespaceURI !== self::NS_W15 || $person->localName !== 'person') {
                            continue;
                        }

                        $author = $this->emptyStringToNull($person->getAttributeNS(self::NS_W15, 'author'));
                        if ($author !== null) {
                            $author = $this->boundedMetadataString($author);
                            $this->appendUniqueString($authors, $author);
                        }

                        $presenceInfo = [];
                        foreach ($person->childNodes as $presence) {
                            if (!$presence instanceof \DOMElement || $presence->namespaceURI !== self::NS_W15 || $presence->localName !== 'presenceInfo') {
                                continue;
                            }

                            ++$presenceInfoCount;
                            $providerId = $this->emptyStringToNull($presence->getAttributeNS(self::NS_W15, 'providerId'));
                            $userId = $this->emptyStringToNull($presence->getAttributeNS(self::NS_W15, 'userId'));
                            if ($providerId !== null) {
                                $providerId = $this->boundedMetadataString($providerId);
                                $this->appendUniqueString($providerIds, $providerId);
                            }
                            if ($userId !== null) {
                                $userId = $this->boundedMetadataString($userId);
                                $this->appendUniqueString($userIds, $userId);
                            }

                            $presenceInfo[] = [
                                'providerId' => $providerId,
                                'userId' => $userId,
                            ];
                        }

                        $item = [
                            'index' => count($items),
                            'author' => $author,
                            'presenceInfoCount' => count($presenceInfo),
                            'presenceInfo' => $presenceInfo,
                        ];
                        $items[] = $item;
                        if ($author !== null && !isset($byAuthor[$author])) {
                            $byAuthor[$author] = $item;
                        }
                    }
                }
            }
        }

        $issueCodes = array_values(array_unique($issues));
        sort($issueCodes, SORT_STRING);

        return [
            'partName' => $partName,
            'exists' => $exists,
            'relationshipId' => $relationship['id'] ?? null,
            'byteLength' => $exists ? strlen($xml) : null,
            'crc32' => $exists ? sprintf('%08x', crc32($xml)) : null,
            'sha256' => $exists ? hash('sha256', $xml) : null,
            'validXml' => $validXml,
            'xmlParseError' => $xmlParseError,
            'rootNamespace' => $rootNamespace,
            'rootLocalName' => $rootLocalName,
            'validRoot' => $validRoot,
            'contentType' => $contentTypeResolution['contentType'],
            'contentTypeBase' => $contentTypeResolution['contentTypeBase'],
            'contentTypeHasParameters' => $contentTypeResolution['contentTypeHasParameters'],
            'contentTypeParameterCount' => $contentTypeResolution['contentTypeParameterCount'],
            'contentTypeParameters' => $contentTypeResolution['contentTypeParameters'],
            'contentTypeParameterMap' => $contentTypeResolution['contentTypeParameterMap'],
            'contentTypeSource' => $contentTypeResolution['contentTypeSource'],
            'defaultExtension' => $contentTypeResolution['defaultExtension'],
            'overridePartName' => $contentTypeResolution['overridePartName'],
            'expectedContentTypeBase' => self::CT_WORD_PEOPLE,
            'contentTypeMatchesExpected' => ($contentTypeResolution['contentTypeBase'] ?? '') === self::CT_WORD_PEOPLE,
            'count' => count($items),
            'presenceInfoCount' => $presenceInfoCount,
            'authorCount' => count($authors),
            'authors' => $authors,
            'providerIdCount' => count($providerIds),
            'providerIds' => $providerIds,
            'userIdCount' => count($userIds),
            'userIds' => $userIds,
            'byAuthor' => $byAuthor,
            'items' => $items,
            'byteExposurePolicy' => 'people-part-bytes-blocked',
            'reviewPolicy' => 'people-part-metadata-only',
            'issueCount' => count($issueCodes),
            'issueCodes' => $issueCodes,
            'issues' => $issueCodes,
        ];
    }

    /**
     * @return array{summary:array<string, mixed>, byParaId:array<string, array<string, mixed>>}
     */
    private function readCommentsExtended(string $xml, string $partName): array
    {
        $empty = [
            'count' => 0,
            'resolvedCount' => 0,
            'threadedCount' => 0,
            'missingParaIdCount' => 0,
            'duplicateParaIdCount' => 0,
            'duplicateParaIds' => [],
            'paraIds' => [],
            'byParaId' => [],
            'items' => [],
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'invalidXmlCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
        ];
        if ($xml === '') {
            return [
                'summary' => $empty,
                'byParaId' => [],
            ];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'summary' => [
                    ...$empty,
                    'validXml' => false,
                    'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                    'validRoot' => false,
                    'invalidXmlCount' => 1,
                    'issueCount' => 1,
                    'issueCodes' => ['invalid-comments-extended-xml'],
                ],
                'byParaId' => [],
            ];
        }

        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->namespaceURI !== self::NS_W15 || $root->localName !== 'commentsEx') {
            return [
                'summary' => [
                    ...$empty,
                    'validXml' => $root instanceof \DOMElement,
                    'rootNamespace' => $root instanceof \DOMElement ? $root->namespaceURI : null,
                    'rootLocalName' => $root instanceof \DOMElement ? $root->localName : null,
                    'validRoot' => false,
                    'issueCount' => 1,
                    'issueCodes' => ['unexpected-comments-extended-root'],
                ],
                'byParaId' => [],
            ];
        }

        $items = [];
        $byParaId = [];
        $paraIds = [];
        $paraIdCounts = [];
        $missingParaIdCount = 0;
        $issueCount = 0;
        $issueCodes = [];
        foreach ($root->childNodes as $comment) {
            if (!$comment instanceof \DOMElement || $comment->namespaceURI !== self::NS_W15 || $comment->localName !== 'commentEx') {
                continue;
            }

            $paraId = $this->wordExtensionAttr($comment, 'paraId');
            if ($paraId === null || $paraId === '') {
                $paraId = null;
            }

            $parentParaId = $this->wordExtensionAttr($comment, 'paraIdParent');
            if ($parentParaId === '') {
                $parentParaId = null;
            }
            $resolved = $this->onOffStringValue($this->wordExtensionAttr($comment, 'done'));
            $issues = [];
            if ($paraId === null) {
                $issues[] = 'missing-para-id';
                ++$missingParaIdCount;
            } else {
                $this->appendUniqueString($paraIds, $paraId);
                $paraIdCounts[$paraId] = ($paraIdCounts[$paraId] ?? 0) + 1;
            }
            foreach ($issues as $issue) {
                $this->appendUniqueString($issueCodes, $issue);
            }
            $issueCount += count($issues);

            $item = [
                'paraId' => $paraId,
                'parentParaId' => $parentParaId,
                'resolved' => $resolved,
                'partName' => $partName,
                'issues' => $issues,
            ];
            $items[] = $item;
            if ($paraId !== null) {
                $byParaId[$paraId] = $item;
            }
        }

        $duplicateParaIds = [];
        foreach ($paraIdCounts as $paraId => $count) {
            if ($count > 1) {
                $duplicateParaIds[] = $paraId;
            }
        }
        sort($duplicateParaIds, SORT_STRING);
        $duplicateLookup = array_fill_keys($duplicateParaIds, true);
        foreach ($items as &$item) {
            $paraId = $item['paraId'];
            $item['duplicateParaId'] = is_string($paraId) && isset($duplicateLookup[$paraId]);
        }
        unset($item);
        foreach ($byParaId as $paraId => $item) {
            $item['duplicateParaId'] = isset($duplicateLookup[$paraId]);
            $byParaId[$paraId] = $item;
        }

        return [
            'summary' => [
                'count' => count($items),
                'resolvedCount' => count(array_filter($items, static fn (array $item): bool => $item['resolved'] === true)),
                'threadedCount' => count(array_filter($items, static fn (array $item): bool => is_string($item['parentParaId']) && $item['parentParaId'] !== '')),
                'missingParaIdCount' => $missingParaIdCount,
                'duplicateParaIdCount' => count($duplicateParaIds),
                'duplicateParaIds' => $duplicateParaIds,
                'paraIds' => $paraIds,
                'byParaId' => $byParaId,
                'items' => $items,
                'validXml' => true,
                'xmlParseError' => null,
                'rootNamespace' => $root->namespaceURI,
                'rootLocalName' => $root->localName,
                'validRoot' => true,
                'invalidXmlCount' => 0,
                'issueCount' => $issueCount,
                'issueCodes' => $issueCodes,
            ],
            'byParaId' => $byParaId,
        ];
    }

    /**
     * @return array{summary:array<string, mixed>, byParaId:array<string, array<string, mixed>>}
     */
    private function readCommentsIds(string $xml, string $partName): array
    {
        $empty = [
            'count' => 0,
            'missingParaIdCount' => 0,
            'missingDurableIdCount' => 0,
            'duplicateParaIdCount' => 0,
            'duplicateParaIds' => [],
            'paraIds' => [],
            'durableIds' => [],
            'byParaId' => [],
            'items' => [],
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'invalidXmlCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
        ];
        if ($xml === '') {
            return [
                'summary' => $empty,
                'byParaId' => [],
            ];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'summary' => [
                    ...$empty,
                    'validXml' => false,
                    'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                    'validRoot' => false,
                    'invalidXmlCount' => 1,
                    'issueCount' => 1,
                    'issueCodes' => ['invalid-comments-ids-xml'],
                ],
                'byParaId' => [],
            ];
        }

        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->namespaceURI !== self::NS_W16CID || $root->localName !== 'commentsIds') {
            return [
                'summary' => [
                    ...$empty,
                    'validXml' => $root instanceof \DOMElement,
                    'rootNamespace' => $root instanceof \DOMElement ? $root->namespaceURI : null,
                    'rootLocalName' => $root instanceof \DOMElement ? $root->localName : null,
                    'validRoot' => false,
                    'issueCount' => 1,
                    'issueCodes' => ['unexpected-comments-ids-root'],
                ],
                'byParaId' => [],
            ];
        }

        $items = [];
        $byParaId = [];
        $paraIds = [];
        $durableIds = [];
        $paraIdCounts = [];
        $duplicateParaIds = [];
        $missingParaIdCount = 0;
        $missingDurableIdCount = 0;
        $issueCount = 0;
        $issueCodes = [];

        foreach ($root->childNodes as $commentId) {
            if (!$commentId instanceof \DOMElement || $commentId->namespaceURI !== self::NS_W16CID || $commentId->localName !== 'commentId') {
                continue;
            }

            $paraId = $this->emptyStringToNull($commentId->getAttributeNS(self::NS_W16CID, 'paraId'));
            $durableId = $this->emptyStringToNull($commentId->getAttributeNS(self::NS_W16CID, 'durableId'));
            $issues = [];
            if ($paraId === null) {
                $issues[] = 'missing-para-id';
                $missingParaIdCount++;
            } else {
                $this->appendUniqueString($paraIds, $paraId);
                $paraIdCounts[$paraId] = ($paraIdCounts[$paraId] ?? 0) + 1;
                if ($paraIdCounts[$paraId] === 2) {
                    $duplicateParaIds[] = $paraId;
                }
            }
            if ($durableId === null) {
                $issues[] = 'missing-durable-id';
                $missingDurableIdCount++;
            } else {
                $this->appendUniqueString($durableIds, $durableId);
            }
            foreach ($issues as $issue) {
                $this->appendUniqueString($issueCodes, $issue);
            }
            $issueCount += count($issues);

            $item = [
                'paraId' => $paraId,
                'durableId' => $durableId,
                'partName' => $partName,
                'issues' => $issues,
            ];
            $items[] = $item;
            if ($paraId !== null) {
                $byParaId[$paraId] = $item;
            }
        }

        return [
            'summary' => [
                'count' => count($items),
                'missingParaIdCount' => $missingParaIdCount,
                'missingDurableIdCount' => $missingDurableIdCount,
                'duplicateParaIdCount' => count($duplicateParaIds),
                'duplicateParaIds' => $duplicateParaIds,
                'paraIds' => $paraIds,
                'durableIds' => $durableIds,
                'byParaId' => $byParaId,
                'items' => $items,
                'validXml' => true,
                'xmlParseError' => null,
                'rootNamespace' => $root->namespaceURI,
                'rootLocalName' => $root->localName,
                'validRoot' => true,
                'invalidXmlCount' => 0,
                'issueCount' => $issueCount,
                'issueCodes' => $issueCodes,
            ],
            'byParaId' => $byParaId,
        ];
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, mixed>> $commentsExtended
     * @param array<string, array<string, mixed>> $commentsIds
     * @param array<string, mixed> $people
     * @return array{summary:array<string, mixed>, nodes:array<string, AstNode>}
     */
    private function readComments(
        array $parts,
        string $xml,
        string $partName,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering,
        array $commentsExtended = [],
        array $commentsIds = [],
        array $people = []
    ): array {
        $relationshipDiagnostics = $this->relatedPartRelationshipDiagnostics(
            $parts,
            $relationships,
            $partName,
            $relationshipsPart,
            $contentTypes,
        );
        if ($xml === '') {
            $summary = $this->commentAuthorPeopleSummary(
                $this->noteCollectionSummary([], [], $relationshipDiagnostics),
                $people,
                0,
                0,
                [],
                [],
            );

            return [
                'summary' => $summary,
                'nodes' => [],
            ];
        }

        $dom = $this->loadXml($xml, $partName);
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->namespaceURI !== self::NS_W || $root->localName !== 'comments') {
            $summary = $this->commentAuthorPeopleSummary(
                $this->noteCollectionSummary([], [], $relationshipDiagnostics),
                $people,
                0,
                0,
                [],
                [],
            );

            return [
                'summary' => $summary,
                'nodes' => [],
            ];
        }

        $xpath = $this->xpath($dom);
        $items = [];
        $byId = [];
        $nodes = [];
        $authorPeopleMatchedCount = 0;
        $authorPeopleUnmatchedCount = 0;
        $authorPeopleMatchedAuthors = [];
        $authorPeopleUnmatchedAuthors = [];
        foreach ($root->childNodes as $comment) {
            if (!$comment instanceof \DOMElement || $comment->namespaceURI !== self::NS_W || $comment->localName !== 'comment') {
                continue;
            }

            $id = $comment->getAttributeNS(self::NS_W, 'id');
            if ($id === '') {
                continue;
            }

            $blocks = $this->readNoteBlocks($comment, $xpath, $relationships, $contentTypes, $styles, $numbering);
            $relationshipIds = $this->relationshipIdsInElement($comment);
            $attrs = [
                'id' => $id,
                'sourceType' => 'comment',
            ];
            $author = $this->emptyStringToNull($comment->getAttributeNS(self::NS_W, 'author'));
            $initials = $this->emptyStringToNull($comment->getAttributeNS(self::NS_W, 'initials'));
            $date = $this->emptyStringToNull($comment->getAttributeNS(self::NS_W, 'date'));
            if ($author !== null) {
                $attrs['author'] = $author;
            }
            if ($initials !== null) {
                $attrs['initials'] = $initials;
            }
            if ($date !== null) {
                $attrs['date'] = $date;
            }
            if ($author !== null) {
                foreach ($this->commentAuthorPeopleAttrs($author, $people) as $key => $value) {
                    $attrs[$key] = $value;
                }
                if (($attrs['commentAuthorPeopleMatched'] ?? false) === true) {
                    ++$authorPeopleMatchedCount;
                    $this->appendUniqueString($authorPeopleMatchedAuthors, $author);
                } else {
                    ++$authorPeopleUnmatchedCount;
                    $this->appendUniqueString($authorPeopleUnmatchedAuthors, $author);
                }
            }
            foreach ($this->commentPackageAttrs($comment, $commentsExtended, $commentsIds) as $key => $value) {
                $attrs[$key] = $value;
            }

            $item = [
                'id' => $id,
                'sourceType' => 'comment',
                'type' => 'normal',
                'blockCount' => count($blocks),
                'text' => $this->plainBlockText($blocks),
                'author' => $author,
                'initials' => $initials,
                'date' => $date,
                'commentParaId' => $attrs['commentParaId'] ?? null,
                'commentParentParaId' => $attrs['commentParentParaId'] ?? null,
                'commentResolved' => $attrs['commentResolved'] ?? null,
                'commentsExtendedPart' => $attrs['commentsExtendedPart'] ?? null,
                'commentDurableId' => $attrs['commentDurableId'] ?? null,
                'commentsIdsPart' => $attrs['commentsIdsPart'] ?? null,
                'commentIdIssues' => $attrs['commentIdIssues'] ?? [],
                'commentAuthorPeopleMatched' => $attrs['commentAuthorPeopleMatched'] ?? null,
                'commentAuthorPeoplePart' => $attrs['commentAuthorPeoplePart'] ?? null,
                'commentAuthorPersonIndex' => $attrs['commentAuthorPersonIndex'] ?? null,
                'commentAuthorPresenceInfoCount' => $attrs['commentAuthorPresenceInfoCount'] ?? null,
                'commentAuthorPresenceInfo' => $attrs['commentAuthorPresenceInfo'] ?? [],
                'commentAuthorProviderIds' => $attrs['commentAuthorProviderIds'] ?? [],
                'commentAuthorUserIds' => $attrs['commentAuthorUserIds'] ?? [],
                'commentAuthorPeopleReviewPolicy' => $attrs['commentAuthorPeopleReviewPolicy'] ?? null,
                'relationshipCount' => count($relationshipIds),
                'relationshipIds' => $relationshipIds,
                'missingRelationshipIds' => $this->missingRelationshipIds($relationshipIds, $relationships),
            ];
            $items[] = $item;
            $byId[$id] = $item;
            $nodes[$id] = new AstNode('note', $attrs, $blocks);
        }

        $summary = $this->commentAuthorPeopleSummary(
            $this->noteCollectionSummary($items, $byId, $relationshipDiagnostics),
            $people,
            $authorPeopleMatchedCount,
            $authorPeopleUnmatchedCount,
            $authorPeopleMatchedAuthors,
            $authorPeopleUnmatchedAuthors,
        );

        return [
            'summary' => $summary,
            'nodes' => $nodes,
        ];
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>>|null $referencedNotes
     * @return list<AstNode>
     */
    private function readNoteBlocks(
        \DOMElement $note,
        \DOMXPath $xpath,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering,
        ?array $referencedNotes = null
    ): array {
        $blocks = [];
        $currentList = null;
        $referencedNotes ??= ['footnote' => [], 'endnote' => [], 'comment' => []];
        foreach ($note->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_W) {
                continue;
            }

            if ($child->localName === 'p') {
                $paragraph = $this->readParagraph($child, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                if ($paragraph === null) {
                    $this->flushCurrentList($currentList, $blocks);
                    continue;
                }

                $list = $this->paragraphListAttrs($child, $numbering);
                if ($list !== null && $paragraph->type === 'paragraph') {
                    $key = $list['type'] . ':' . $list['numId'] . ':' . $list['level'] . ':' . ($list['style'] ?? '') . ':' . ($list['delimiter'] ?? '') . ':' . $list['start'] . ':' . ($list['pictureBulletId'] ?? '');
                    if (!is_array($currentList) || $currentList['key'] !== $key) {
                        $this->flushCurrentList($currentList, $blocks);
                        $attrs = [
                            'docxNumId' => $list['numId'],
                            'docxLevel' => $list['level'],
                        ];
                        if ($list['type'] === 'ordered_list') {
                            $attrs['start'] = $list['start'];
                            $attrs['style'] = $list['style'];
                            $attrs['delimiter'] = $list['delimiter'];
                        } else {
                            $attrs['bulletChar'] = $list['text'];
                        }
                        if (is_string($list['pictureBulletId'] ?? null)) {
                            $attrs['pictureBulletId'] = $list['pictureBulletId'];
                        }
                        if (is_array($list['pictureBullet'] ?? null)) {
                            $attrs['pictureBullet'] = $list['pictureBullet'];
                        }
                        $currentList = [
                            'key' => $key,
                            'type' => $list['type'],
                            'attrs' => $attrs,
                            'items' => [],
                        ];
                    }

                    $currentList['items'][] = new AstNode('list_item', [], [$paragraph]);
                    continue;
                }

                $this->flushCurrentList($currentList, $blocks);
                $blocks[] = $paragraph;
                continue;
            }

            if ($child->localName === 'tbl') {
                $this->flushCurrentList($currentList, $blocks);
                $table = $this->readTable($child, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                if ($table !== null) {
                    $blocks[] = $table;
                }
            }
        }
        $this->flushCurrentList($currentList, $blocks);

        return $blocks;
    }

    /**
     * @param array<string, array<string, AstNode>> $referencedNotes
     */
    private function referencedNoteNode(array $referencedNotes, string $sourceType, \DOMElement $reference): ?AstNode
    {
        $id = $reference->getAttributeNS(self::NS_W, 'id');
        if ($id === '') {
            return null;
        }

        $attrs = [
            'id' => $id,
            'sourceType' => $sourceType,
        ];
        $customMarkFollows = strtolower($reference->getAttributeNS(self::NS_W, 'customMarkFollows'));
        if ($customMarkFollows !== '' && !in_array($customMarkFollows, ['0', 'false', 'off'], true)) {
            $attrs['customMarkFollows'] = true;
        }

        $note = $referencedNotes[$sourceType][$id] ?? null;
        if ($note instanceof AstNode) {
            return new AstNode('note', array_replace($note->attrs, $attrs), $note->children);
        }

        return new AstNode('note', ['missing' => true] + $attrs);
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, array{path:string, contentType:string, size:int, sha1:string}>
     */
    private function mediaMetadata(array $parts, array $contentTypes): array
    {
        $media = [];
        foreach ($parts as $name => $contents) {
            if (!str_starts_with($name, 'word/media/')) {
                continue;
            }
            $media[$name] = [
                'path' => $name,
                'contentType' => $this->contentTypeFor($name, $contentTypes),
                'size' => strlen($contents),
                'sha1' => sha1($contents),
            ];
        }

        return $media;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return list<AstNode>
     */
    private function readDocumentBlocks(string $xml, array $relationships, array $contentTypes, array $styles, array $numbering, array $referencedNotes): array
    {
        $dom = $this->loadXml($xml, 'word/document.xml');
        $xpath = $this->xpath($dom);
        $body = $this->firstElement($xpath, '/w:document/w:body', $dom);
        if (!$body instanceof \DOMElement) {
            return [];
        }

        return $this->readWordBlockChildren($body->childNodes, $xpath, $relationships, $contentTypes, $styles, $numbering, $referencedNotes);
    }

    /**
     * @param iterable<\DOMNode> $children
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return list<AstNode>
     */
    private function readWordBlockChildren(iterable $children, \DOMXPath $xpath, array $relationships, array $contentTypes, array $styles, array $numbering, array $referencedNotes): array
    {
        $blocks = [];
        $currentList = null;

        foreach ($children as $bodyChild) {
            if (!$bodyChild instanceof \DOMElement) {
                continue;
            }

            if ($bodyChild->namespaceURI === self::NS_W && $bodyChild->localName === 'p') {
                $paragraph = $this->readParagraph($bodyChild, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                if ($paragraph === null) {
                    $this->flushCurrentList($currentList, $blocks);
                    continue;
                }

                $list = $this->paragraphListAttrs($bodyChild, $numbering);
                if ($list !== null && $paragraph->type === 'paragraph') {
                    $key = $list['type'] . ':' . $list['numId'] . ':' . $list['level'] . ':' . ($list['style'] ?? '') . ':' . ($list['delimiter'] ?? '') . ':' . $list['start'] . ':' . ($list['pictureBulletId'] ?? '');
                    if (!is_array($currentList) || $currentList['key'] !== $key) {
                        $this->flushCurrentList($currentList, $blocks);
                        $attrs = [
                            'docxNumId' => $list['numId'],
                            'docxLevel' => $list['level'],
                        ];
                        if ($list['type'] === 'ordered_list') {
                            $attrs['start'] = $list['start'];
                            $attrs['style'] = $list['style'];
                            $attrs['delimiter'] = $list['delimiter'];
                        } else {
                            $attrs['bulletChar'] = $list['text'];
                        }
                        if (is_string($list['pictureBulletId'] ?? null)) {
                            $attrs['pictureBulletId'] = $list['pictureBulletId'];
                        }
                        if (is_array($list['pictureBullet'] ?? null)) {
                            $attrs['pictureBullet'] = $list['pictureBullet'];
                        }
                        $currentList = [
                            'key' => $key,
                            'type' => $list['type'],
                            'attrs' => $attrs,
                            'items' => [],
                        ];
                    }

                    $currentList['items'][] = new AstNode('list_item', [], [$paragraph]);
                    continue;
                }

                $this->flushCurrentList($currentList, $blocks);
                $blocks[] = $paragraph;
                continue;
            }

            if ($bodyChild->namespaceURI === self::NS_W && $bodyChild->localName === 'tbl') {
                $this->flushCurrentList($currentList, $blocks);
                $table = $this->readTable($bodyChild, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                if ($table !== null) {
                    $blocks[] = $table;
                }
                continue;
            }

            if ($bodyChild->namespaceURI === self::NS_W && $bodyChild->localName === 'sdt') {
                $this->flushCurrentList($currentList, $blocks);
                $content = $this->childElement($bodyChild, 'sdtContent');
                if ($content instanceof \DOMElement) {
                    array_push(
                        $blocks,
                        ...$this->readWordBlockChildren($content->childNodes, $xpath, $relationships, $contentTypes, $styles, $numbering, $referencedNotes)
                    );
                }
            }
        }
        $this->flushCurrentList($currentList, $blocks);

        return $blocks;
    }

    /**
     * @return list<string>
     */
    private function relationshipIdsInElement(\DOMElement $element): array
    {
        $relationshipIds = [];
        $stack = [$element];
        while ($stack !== []) {
            $current = array_pop($stack);
            if (!$current instanceof \DOMElement) {
                continue;
            }

            foreach (['id', 'embed', 'link'] as $attribute) {
                $this->appendUniqueString($relationshipIds, $this->emptyStringToNull($current->getAttributeNS(self::NS_R, $attribute)));
            }

            foreach ($current->childNodes as $child) {
                if ($child instanceof \DOMElement) {
                    $stack[] = $child;
                }
            }
        }

        sort($relationshipIds, SORT_STRING);

        return $relationshipIds;
    }

    /**
     * @param array{key:string, type:string, attrs:array<string, mixed>, items:list<AstNode>}|null $currentList
     * @param list<AstNode> $blocks
     */
    private function flushCurrentList(?array &$currentList, array &$blocks): void
    {
        if (!is_array($currentList)) {
            return;
        }

        $blocks[] = new AstNode($currentList['type'], $currentList['attrs'], $currentList['items']);
        $currentList = null;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array<string, AstNode>> $referencedNotes
     */
    private function readParagraph(\DOMElement $paragraph, \DOMXPath $xpath, array $relationships, array $contentTypes, array $styles, array $referencedNotes): ?AstNode
    {
        $inlines = $this->readParagraphInlines($paragraph, $xpath, $relationships, $contentTypes, $referencedNotes);
        $text = $this->plainInlineText($inlines);
        if ($inlines === [] && $text === '') {
            return null;
        }

        $attrs = ['text' => $text];
        $styleId = $this->paragraphStyleId($paragraph);
        if ($styleId !== '') {
            $attrs['docxStyleId'] = $styleId;
            $style = $styles[$styleId] ?? null;
            if (is_array($style)) {
                $attrs['docxStyleName'] = $style['name'];
                if ($style['headingLevel'] !== null) {
                    $attrs['level'] = $style['headingLevel'];
                    $attrs['id'] = $this->identifierFromText($text);

                    return new AstNode('heading', $attrs, $inlines);
                }
            }
        }

        return new AstNode('paragraph', $attrs, $inlines);
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return list<AstNode>
     */
    private function readParagraphInlines(\DOMElement $paragraph, \DOMXPath $xpath, array $relationships, array $contentTypes, array $referencedNotes): array
    {
        $inlines = [];
        foreach ($paragraph->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }

            if ($child->namespaceURI === self::NS_W && $child->localName === 'r') {
                array_push($inlines, ...$this->readRun($child, $xpath, $relationships, $contentTypes, $referencedNotes));
                continue;
            }

            if ($child->namespaceURI === self::NS_W && $child->localName === 'hyperlink') {
                $linkInlines = [];
                foreach ($this->elements($xpath, 'w:r', $child) as $run) {
                    array_push($linkInlines, ...$this->readRun($run, $xpath, $relationships, $contentTypes, $referencedNotes));
                }
                if ($linkInlines !== []) {
                    $inlines[] = new AstNode('link', $this->hyperlinkAttrs($child, $relationships), $linkInlines);
                }
                continue;
            }

            if (in_array($child->localName, ['ins', 'smartTag', 'sdt'], true)) {
                foreach ($this->elements($xpath, './/w:r', $child) as $run) {
                    array_push($inlines, ...$this->readRun($run, $xpath, $relationships, $contentTypes, $referencedNotes));
                }
            }
        }

        return $this->mergeAdjacentText($inlines);
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @return array<string, mixed>
     */
    private function hyperlinkAttrs(\DOMElement $hyperlink, array $relationships): array
    {
        $relationshipId = $hyperlink->getAttributeNS(self::NS_R, 'id');
        $anchor = $hyperlink->getAttributeNS(self::NS_W, 'anchor');
        $attrs = ['url' => ''];
        if ($relationshipId !== '' && isset($relationships[$relationshipId])) {
            $relationship = $relationships[$relationshipId];
            $attrs['url'] = $relationship['targetMode'] === 'External'
                ? $relationship['target']
                : $relationship['resolvedTarget'];
            $attrs['relationshipId'] = $relationshipId;
            $attrs['relationshipType'] = $relationship['type'];
            $attrs['targetMode'] = $relationship['targetMode'];
        } elseif ($anchor !== '') {
            $attrs['url'] = '#' . $anchor;
        }

        if ($anchor !== '' && $relationshipId !== '') {
            $attrs['url'] .= '#' . $anchor;
        }

        return $attrs;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return list<AstNode>
     */
    private function readRun(\DOMElement $run, \DOMXPath $xpath, array $relationships, array $contentTypes, array $referencedNotes): array
    {
        $inlines = [];
        foreach ($run->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }

            if ($child->namespaceURI === self::NS_W && $child->localName === 't') {
                $this->appendText($inlines, $child->textContent);
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'tab') {
                $this->appendText($inlines, "\t");
                continue;
            }
            if ($child->namespaceURI === self::NS_W && in_array($child->localName, ['br', 'cr'], true)) {
                $inlines[] = new AstNode('linebreak');
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'noBreakHyphen') {
                $this->appendText($inlines, "\u{2011}");
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'softHyphen') {
                $this->appendText($inlines, "\u{00AD}");
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'sym') {
                $hex = $child->getAttributeNS(self::NS_W, 'char');
                if ($hex !== '' && ctype_xdigit($hex)) {
                    $this->appendText($inlines, html_entity_decode('&#x' . $hex . ';', ENT_QUOTES | ENT_XML1, 'UTF-8'));
                }
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'drawing') {
                array_push($inlines, ...$this->readDrawingImages($child, $xpath, $relationships, $contentTypes));
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'pict') {
                array_push($inlines, ...$this->readPictImages($child, $xpath, $relationships, $contentTypes));
                continue;
            }
            if ($child->namespaceURI === self::NS_W && in_array($child->localName, ['footnoteRef', 'endnoteRef'], true)) {
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'footnoteReference') {
                $note = $this->referencedNoteNode($referencedNotes, 'footnote', $child);
                if ($note !== null) {
                    $inlines[] = $note;
                }
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'endnoteReference') {
                $note = $this->referencedNoteNode($referencedNotes, 'endnote', $child);
                if ($note !== null) {
                    $inlines[] = $note;
                }
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'commentReference') {
                $note = $this->referencedNoteNode($referencedNotes, 'comment', $child);
                if ($note !== null) {
                    $inlines[] = $note;
                }
            }
        }

        return $this->wrapRunInlines($run, $inlines);
    }

    /**
     * @param list<AstNode> $inlines
     * @return list<AstNode>
     */
    private function wrapRunInlines(\DOMElement $run, array $inlines): array
    {
        if ($inlines === []) {
            return [];
        }

        $rPr = $this->childElement($run, 'rPr');
        if (!$rPr instanceof \DOMElement) {
            return $inlines;
        }

        $wrappers = [];
        $vertical = $this->childAttr($rPr, 'vertAlign', 'val');
        if ($vertical === 'superscript') {
            $wrappers[] = 'superscript';
        } elseif ($vertical === 'subscript') {
            $wrappers[] = 'subscript';
        }
        if ($this->runPropertyEnabled($rPr, 'smallCaps')) {
            $wrappers[] = 'small_caps';
        }
        if ($this->runPropertyEnabled($rPr, 'u')) {
            $wrappers[] = 'underline';
        }
        if ($this->runPropertyEnabled($rPr, 'strike') || $this->runPropertyEnabled($rPr, 'dstrike')) {
            $wrappers[] = 'strikeout';
        }
        if ($this->runPropertyEnabled($rPr, 'i')) {
            $wrappers[] = 'emph';
        }
        if ($this->runPropertyEnabled($rPr, 'b')) {
            $wrappers[] = 'strong';
        }

        foreach ($wrappers as $type) {
            $inlines = [new AstNode($type, [], $inlines)];
        }

        return $inlines;
    }

    private function runPropertyEnabled(\DOMElement $rPr, string $name): bool
    {
        $property = $this->childElement($rPr, $name);
        if (!$property instanceof \DOMElement) {
            return false;
        }

        $value = strtolower($property->getAttributeNS(self::NS_W, 'val'));
        if ($name === 'u' && $value === 'none') {
            return false;
        }

        return !in_array($value, ['0', 'false', 'off'], true);
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return list<AstNode>
     */
    private function readDrawingImages(\DOMElement $drawing, \DOMXPath $xpath, array $relationships, array $contentTypes): array
    {
        $images = [];
        $docPr = $this->firstElement($xpath, './/wp:docPr', $drawing);
        foreach ($this->elements($xpath, './/a:blip', $drawing) as $blip) {
            $relationshipId = $blip->getAttributeNS(self::NS_R, 'embed');
            if ($relationshipId === '') {
                $relationshipId = $blip->getAttributeNS(self::NS_R, 'link');
            }

            $relationship = $relationships[$relationshipId] ?? null;
            if (!is_array($relationship)) {
                continue;
            }

            $isExternal = $this->isExternalRelationshipTarget($relationship);
            $targetPart = $isExternal ? null : $this->stripQueryAndFragment($relationship['resolvedTarget']);
            $targetSuffix = $this->targetReferenceSuffix($relationship['resolvedTarget']);
            $url = $isExternal ? $relationship['target'] : (string) $targetPart;
            $alt = $docPr instanceof \DOMElement ? trim($docPr->getAttribute('descr')) : '';
            $title = $docPr instanceof \DOMElement ? trim($docPr->getAttribute('title') ?: $docPr->getAttribute('name')) : '';
            $attrs = [
                'url' => $url,
                'relationshipId' => $relationshipId,
                'relationshipType' => $relationship['type'],
                'targetMode' => $relationship['targetMode'],
                'target' => $relationship['target'],
                'resolvedTarget' => $relationship['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $targetSuffix['query'],
                'targetFragment' => $targetSuffix['fragment'],
                'targetReferenceSuffix' => $targetSuffix['suffix'],
            ];
            if (!$isExternal && $targetPart !== null) {
                $attrs['mediaPath'] = $targetPart;
                $attrs['contentType'] = $this->contentTypeFor($targetPart, $contentTypes);
            }
            if ($alt !== '') {
                $attrs['alt'] = $alt;
            }
            if ($title !== '') {
                $attrs['title'] = $title;
            }

            $children = $alt === '' ? [] : [new AstNode('text', ['text' => $alt])];
            $images[] = new AstNode('image', $attrs, $children);
        }

        return $images;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return list<AstNode>
     */
    private function readPictImages(\DOMElement $pict, \DOMXPath $xpath, array $relationships, array $contentTypes): array
    {
        $images = [];
        foreach ($this->elements($xpath, './/v:imagedata', $pict) as $imageData) {
            $relationshipId = $this->vmlImageRelationshipId($imageData);
            $relationship = $relationships[$relationshipId] ?? null;
            if (!is_array($relationship)) {
                continue;
            }

            $isExternal = $relationship['targetMode'] === 'External';
            $url = $isExternal ? $relationship['target'] : $relationship['resolvedTarget'];
            $alt = $this->vmlImageAlt($imageData);
            $title = $this->vmlImageTitle($imageData);
            $attrs = [
                'url' => $url,
                'relationshipId' => $relationshipId,
                'relationshipType' => $relationship['type'],
                'targetMode' => $relationship['targetMode'],
                'imageSource' => 'vml-pict',
            ];
            if (!$isExternal) {
                $attrs['mediaPath'] = $relationship['resolvedTarget'];
                $attrs['contentType'] = $this->contentTypeFor($this->stripQueryAndFragment($relationship['resolvedTarget']), $contentTypes);
            }
            if ($alt !== '') {
                $attrs['alt'] = $alt;
            }
            if ($title !== '') {
                $attrs['title'] = $title;
            }

            $children = $alt === '' ? [] : [new AstNode('text', ['text' => $alt])];
            $images[] = new AstNode('image', $attrs, $children);
        }

        return $images;
    }

    private function vmlImageRelationshipId(\DOMElement $imageData): string
    {
        $relationshipId = $imageData->getAttributeNS(self::NS_R, 'id');
        if ($relationshipId === '') {
            $relationshipId = $imageData->getAttributeNS(self::NS_R, 'embed');
        }
        if ($relationshipId === '') {
            $relationshipId = $imageData->getAttributeNS(self::NS_R, 'link');
        }
        if ($relationshipId === '') {
            $relationshipId = $imageData->getAttributeNS(self::NS_O, 'relid');
        }

        return $relationshipId;
    }

    private function vmlImageAlt(\DOMElement $imageData): string
    {
        $node = $imageData->parentNode;
        while ($node instanceof \DOMElement) {
            if ($node->namespaceURI === self::NS_V && $node->localName === 'shape') {
                return trim($node->getAttribute('alt'));
            }
            $node = $node->parentNode;
        }

        return '';
    }

    private function vmlImageTitle(\DOMElement $imageData): string
    {
        $title = trim($imageData->getAttributeNS(self::NS_O, 'title'));
        if ($title === '') {
            $title = trim($imageData->getAttribute('title'));
        }

        return $title;
    }

    /**
     * @param array<string, array{abstractNumId:string, levels:array<int, array<string, mixed>>}> $numbering
     * @return array<string, mixed>|null
     */
    private function paragraphListAttrs(\DOMElement $paragraph, array $numbering): ?array
    {
        $pPr = $this->childElement($paragraph, 'pPr');
        $numPr = $pPr instanceof \DOMElement ? $this->childElement($pPr, 'numPr') : null;
        if (!$numPr instanceof \DOMElement) {
            return null;
        }

        $numId = $this->childAttr($numPr, 'numId', 'val');
        if ($numId === '' || !isset($numbering[$numId])) {
            return null;
        }

        $ilvl = (int) ($this->childAttr($numPr, 'ilvl', 'val') ?: '0');
        $level = $numbering[$numId]['levels'][$ilvl] ?? ['format' => 'decimal', 'text' => '%' . ($ilvl + 1) . '.', 'start' => 1];
        $format = $level['format'];
        $type = $format === 'bullet' ? 'bullet_list' : 'ordered_list';

        $attrs = [
            'type' => $type,
            'numId' => $numId,
            'level' => $ilvl,
            'start' => $level['start'],
            'style' => $this->listStyleForFormat($format),
            'delimiter' => $this->listDelimiterForText($level['text']),
            'text' => $level['text'],
        ];
        if (is_string($level['pictureBulletId'] ?? null)) {
            $attrs['pictureBulletId'] = $level['pictureBulletId'];
        }
        if (is_array($level['pictureBullet'] ?? null)) {
            $attrs['pictureBullet'] = $level['pictureBullet'];
        }

        return $attrs;
    }

    private function paragraphStyleId(\DOMElement $paragraph): string
    {
        $pPr = $this->childElement($paragraph, 'pPr');
        if (!$pPr instanceof \DOMElement) {
            return '';
        }

        return $this->childAttr($pPr, 'pStyle', 'val');
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array<string, AstNode>> $referencedNotes
     */
    private function readTable(\DOMElement $table, \DOMXPath $xpath, array $relationships, array $contentTypes, array $styles, array $referencedNotes): ?AstNode
    {
        $rows = [];
        foreach ($this->elements($xpath, 'w:tr', $table) as $row) {
            $cells = [];
            foreach ($this->elements($xpath, 'w:tc', $row) as $cell) {
                $blocks = [];
                foreach ($this->elements($xpath, 'w:p', $cell) as $paragraph) {
                    $node = $this->readParagraph($paragraph, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                    if ($node !== null) {
                        $blocks[] = $node;
                    }
                }
                $gridSpan = $this->firstElement($xpath, 'w:tcPr/w:gridSpan', $cell);
                $attrs = ['text' => $this->plainBlockText($blocks)];
                if ($gridSpan instanceof \DOMElement) {
                    $attrs['colspan'] = max(1, (int) ($gridSpan->getAttributeNS(self::NS_W, 'val') ?: '1'));
                }
                $cells[] = new AstNode('table_cell', $attrs, $blocks);
            }
            if ($cells !== []) {
                $rows[] = new AstNode('table_row', [], $cells);
            }
        }

        if ($rows === []) {
            return null;
        }

        return new AstNode('table', ['caption' => '', 'sourceFormat' => 'docx'], [
            new AstNode('table_body', [], $rows),
        ]);
    }

    private function listStyleForFormat(string $format): string
    {
        return match ($format) {
            'lowerLetter' => 'lower_alpha',
            'upperLetter' => 'upper_alpha',
            'lowerRoman' => 'lower_roman',
            'upperRoman' => 'upper_roman',
            default => 'decimal',
        };
    }

    private function listDelimiterForText(string $text): string
    {
        $trimmed = trim($text);
        if (str_starts_with($trimmed, '(') && str_ends_with($trimmed, ')')) {
            return 'two_parens';
        }
        if (str_ends_with($trimmed, ')')) {
            return 'one_paren';
        }

        return 'period';
    }

    /**
     * @param list<AstNode> $nodes
     * @return list<AstNode>
     */
    private function mergeAdjacentText(array $nodes): array
    {
        $merged = [];
        foreach ($nodes as $node) {
            if ($node->type === 'text' && $merged !== [] && end($merged)->type === 'text') {
                $previous = array_pop($merged);
                $merged[] = new AstNode('text', ['text' => (string) $previous->attr('text', '') . (string) $node->attr('text', '')]);
                continue;
            }
            $merged[] = $node;
        }

        return $merged;
    }

    /**
     * @param list<AstNode> $nodes
     */
    private function appendText(array &$nodes, string $text): void
    {
        if ($text === '') {
            return;
        }

        if ($nodes !== [] && end($nodes)->type === 'text') {
            $previous = array_pop($nodes);
            $nodes[] = new AstNode('text', ['text' => (string) $previous->attr('text', '') . $text]);
            return;
        }

        $nodes[] = new AstNode('text', ['text' => $text]);
    }

    private function emptyStringToNull(string $value): ?string
    {
        $value = trim($value);

        return $value === '' ? null : $value;
    }

    /**
     * @param list<AstNode> $nodes
     */
    private function plainInlineText(array $nodes): string
    {
        $text = '';
        foreach ($nodes as $node) {
            $text .= match ($node->type) {
                'text', 'code' => (string) $node->attr('text', ''),
                'softbreak', 'linebreak' => ' ',
                'image' => (string) $node->attr('alt', ''),
                'note' => '',
                default => $this->plainInlineText($node->children),
            };
        }

        return trim(preg_replace('/\s+/u', ' ', $text) ?? $text);
    }

    /**
     * @param list<AstNode> $blocks
     */
    private function plainBlockText(array $blocks): string
    {
        $parts = [];
        foreach ($blocks as $block) {
            $parts[] = $block->attr('text', $this->plainInlineText($block->children));
        }

        return trim(implode(' ', array_map(static fn (mixed $part): string => (string) $part, $parts)));
    }

    private function identifierFromText(string $text): string
    {
        $id = strtolower(trim(preg_replace('/[^\pL\pN]+/u', '-', $text) ?? $text, '-'));

        return $id === '' ? 'section' : $id;
    }

    /**
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     */
    private function contentTypeFor(string $partName, array $contentTypes): string
    {
        $partName = $this->normalizePartName($partName);
        if (isset($contentTypes['overrides'][$partName])) {
            return $contentTypes['overrides'][$partName];
        }

        $extension = strtolower(pathinfo($partName, PATHINFO_EXTENSION));
        return $contentTypes['defaults'][$extension] ?? '';
    }

    private function relationshipsPartFor(string $partName): string
    {
        $partName = $this->normalizePartName($partName);
        $directory = dirname($partName);
        $baseName = basename($partName);

        return ($directory === '.' ? '' : $directory . '/') . '_rels/' . $baseName . '.rels';
    }

    private function documentSiblingPart(string $documentPart, string $fileName): string
    {
        $directory = dirname($this->normalizePartName($documentPart));

        return ($directory === '.' || $directory === '' ? '' : $directory . '/') . $fileName;
    }

    private function resolveRelationshipTarget(string $relsPartName, string $target, string $targetMode): string
    {
        if ($targetMode === 'External' || preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $target) === 1) {
            return $target;
        }

        $sourcePart = $this->sourcePartForRelationshipsPart($relsPartName);
        try {
            return $this->normalizePartName(OpcPackagePath::resolveInternalTarget(
                $sourcePart === '' ? '/' : '/' . $sourcePart,
                $target,
            ));
        } catch (\InvalidArgumentException) {
            return $this->resolveRelationshipTargetTolerantly($sourcePart, $target);
        }
    }

    private function resolveRelationshipTargetTolerantly(string $sourcePart, string $target): string
    {
        if (str_starts_with($target, '/')) {
            return $this->normalizePartName($target);
        }

        $base = $sourcePart === '' ? '' : dirname($sourcePart);
        $path = ($base === '' || $base === '.' ? '' : $base . '/') . $target;

        return $this->normalizePartName($path);
    }

    private function sourcePartForRelationshipsPart(string $relsPartName): string
    {
        if ($relsPartName === '_rels/.rels') {
            return '';
        }

        if (preg_match('~^_rels/([^/]+)\.rels$~', $relsPartName, $match) === 1) {
            return $match[1];
        }

        if (preg_match('~^(.*)/_rels/([^/]+)\.rels$~', $relsPartName, $match) === 1) {
            return ($match[1] === '' ? '' : $match[1] . '/') . $match[2];
        }

        return '';
    }

    private function normalizePartName(string $partName): string
    {
        $partName = str_replace('\\', '/', $partName);
        $partName = ltrim($partName, '/');
        $segments = [];
        foreach (explode('/', $partName) as $segment) {
            if ($segment === '' || $segment === '.') {
                continue;
            }
            if ($segment === '..') {
                array_pop($segments);
                continue;
            }
            $segments[] = $segment;
        }

        return implode('/', $segments);
    }

    private function stripQueryAndFragment(string $partName): string
    {
        $partName = preg_replace('/[#?].*$/', '', $partName) ?? $partName;

        return $this->normalizePartName($partName);
    }

    private function loadXml(string $xml, string $partName): \DOMDocument
    {
        $dom = new \DOMDocument();
        $previous = libxml_use_internal_errors(true);
        $ok = $dom->loadXML($xml, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING);
        if (!$ok) {
            $errors = libxml_get_errors();
            libxml_clear_errors();
            libxml_use_internal_errors($previous);
            $message = $errors === [] ? 'unknown XML parse error' : trim($errors[0]->message);
            throw new \RuntimeException("Invalid DOCX XML part {$partName}: {$message}");
        }
        libxml_clear_errors();
        libxml_use_internal_errors($previous);

        return $dom;
    }

    private function xpath(\DOMDocument $dom): \DOMXPath
    {
        $xpath = new \DOMXPath($dom);
        $xpath->registerNamespace('ct', self::NS_CT);
        $xpath->registerNamespace('rel', self::NS_REL);
        $xpath->registerNamespace('w', self::NS_W);
        $xpath->registerNamespace('w16cid', self::NS_W16CID);
        $xpath->registerNamespace('r', self::NS_R);
        $xpath->registerNamespace('dc', self::NS_DC);
        $xpath->registerNamespace('cp', self::NS_CP);
        $xpath->registerNamespace('dcterms', self::NS_DCTERMS);
        $xpath->registerNamespace('ep', self::NS_EP);
        $xpath->registerNamespace('cust', self::NS_CUSTOM_PROPS);
        $xpath->registerNamespace('vt', self::NS_VT);
        $xpath->registerNamespace('a', self::NS_A);
        $xpath->registerNamespace('wp', self::NS_WP);
        $xpath->registerNamespace('c', self::NS_C);
        $xpath->registerNamespace('b', self::NS_BIB);
        $xpath->registerNamespace('m', self::NS_M);
        $xpath->registerNamespace('v', self::NS_V);
        $xpath->registerNamespace('dgm', self::NS_DGM);
        $xpath->registerNamespace('o', self::NS_O);
        $xpath->registerNamespace('ds', self::NS_DS);

        return $xpath;
    }

    /**
     * @return list<\DOMElement>
     */
    private function elements(\DOMXPath $xpath, string $query, ?\DOMNode $context = null): array
    {
        $nodes = $context instanceof \DOMNode ? $xpath->query($query, $context) : $xpath->query($query);
        if (!$nodes instanceof \DOMNodeList) {
            return [];
        }

        $elements = [];
        foreach ($nodes as $node) {
            if ($node instanceof \DOMElement) {
                $elements[] = $node;
            }
        }

        return $elements;
    }

    private function firstElement(\DOMXPath $xpath, string $query, \DOMNode $context): ?\DOMElement
    {
        $elements = $this->elements($xpath, $query, $context);

        return $elements[0] ?? null;
    }

    /**
     * @param array<string, mixed> $summary
     * @param array<string, mixed> $people
     * @param list<string> $matchedAuthors
     * @param list<string> $unmatchedAuthors
     * @return array<string, mixed>
     */
    private function commentAuthorPeopleSummary(
        array $summary,
        array $people,
        int $matchedCount,
        int $unmatchedCount,
        array $matchedAuthors,
        array $unmatchedAuthors
    ): array {
        $summary['authorPeopleMatchedCount'] = $matchedCount;
        $summary['authorPeopleUnmatchedCount'] = $unmatchedCount;
        $summary['authorPeopleMatchedAuthors'] = $matchedAuthors;
        $summary['authorPeopleUnmatchedAuthors'] = $unmatchedAuthors;
        $summary['authorPeoplePart'] = is_string($people['partName'] ?? null) ? $people['partName'] : null;
        $summary['authorPeopleReviewPolicy'] = 'comment-author-people-metadata-only';

        return $summary;
    }

    /**
     * @param array<string, mixed> $people
     * @return array<string, mixed>
     */
    private function commentAuthorPeopleAttrs(string $author, array $people): array
    {
        $attrs = [
            'commentAuthorPeopleMatched' => false,
            'commentAuthorPresenceInfoCount' => 0,
            'commentAuthorPresenceInfo' => [],
            'commentAuthorProviderIds' => [],
            'commentAuthorUserIds' => [],
            'commentAuthorPeopleReviewPolicy' => 'comment-author-people-metadata-only',
        ];
        $byAuthor = is_array($people['byAuthor'] ?? null) ? $people['byAuthor'] : [];
        $person = $byAuthor[$author] ?? null;
        if (!is_array($person)) {
            return $attrs;
        }

        $presenceInfo = [];
        $providerIds = [];
        $userIds = [];
        foreach (($person['presenceInfo'] ?? []) as $presence) {
            if (!is_array($presence)) {
                continue;
            }

            $providerId = is_string($presence['providerId'] ?? null) ? $presence['providerId'] : null;
            $userId = is_string($presence['userId'] ?? null) ? $presence['userId'] : null;
            $presenceInfo[] = [
                'providerId' => $providerId,
                'userId' => $userId,
            ];
            $this->appendUniqueString($providerIds, $providerId);
            $this->appendUniqueString($userIds, $userId);
        }

        $attrs['commentAuthorPeopleMatched'] = true;
        $attrs['commentAuthorPeoplePart'] = is_string($people['partName'] ?? null) ? $people['partName'] : null;
        if (is_int($person['index'] ?? null)) {
            $attrs['commentAuthorPersonIndex'] = $person['index'];
        }
        $attrs['commentAuthorPresenceInfoCount'] = is_int($person['presenceInfoCount'] ?? null)
            ? $person['presenceInfoCount']
            : count($presenceInfo);
        $attrs['commentAuthorPresenceInfo'] = $presenceInfo;
        $attrs['commentAuthorProviderIds'] = $providerIds;
        $attrs['commentAuthorUserIds'] = $userIds;

        return $attrs;
    }

    /**
     * @param array<string, array<string, mixed>> $commentsExtended
     * @param array<string, array<string, mixed>> $commentsIds
     * @return array<string, mixed>
     */
    private function commentPackageAttrs(\DOMElement $comment, array $commentsExtended, array $commentsIds): array
    {
        $paraId = $this->commentParagraphId($comment);
        if ($paraId === null) {
            return [];
        }

        $attrs = [
            'commentParaId' => $paraId,
        ];
        $extended = $commentsExtended[$paraId] ?? null;
        if (is_array($extended)) {
            $attrs['commentsExtendedPart'] = $extended['partName'];
            if (is_string($extended['parentParaId']) && $extended['parentParaId'] !== '') {
                $attrs['commentParentParaId'] = $extended['parentParaId'];
            }
            if (is_bool($extended['resolved'])) {
                $attrs['commentResolved'] = $extended['resolved'];
            }
        }

        $commentId = $commentsIds[$paraId] ?? null;
        if (is_array($commentId)) {
            $attrs['commentsIdsPart'] = $commentId['partName'];
            if (is_string($commentId['durableId'] ?? null) && $commentId['durableId'] !== '') {
                $attrs['commentDurableId'] = $commentId['durableId'];
            }
            if (is_array($commentId['issues'] ?? null) && $commentId['issues'] !== []) {
                $attrs['commentIdIssues'] = $commentId['issues'];
            }
        }

        return $attrs;
    }

    private function commentParagraphId(\DOMElement $comment): ?string
    {
        foreach ($comment->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_W || $child->localName !== 'p') {
                continue;
            }

            return $this->wordExtensionAttr($child, 'paraId');
        }

        return null;
    }

    private function wordExtensionAttr(\DOMElement $element, string $localName): ?string
    {
        foreach ([self::NS_W15, self::NS_W14] as $namespace) {
            $value = $element->getAttributeNS($namespace, $localName);
            if ($value !== '') {
                return $value;
            }
        }

        return null;
    }

    private function onOffStringValue(?string $value): ?bool
    {
        if ($value === null) {
            return null;
        }

        $value = strtolower(trim($value));
        if (in_array($value, ['1', 'true', 'on'], true)) {
            return true;
        }
        if (in_array($value, ['0', 'false', 'off'], true)) {
            return false;
        }

        return null;
    }

    private function childElement(?\DOMElement $parent, string $localName): ?\DOMElement
    {
        if (!$parent instanceof \DOMElement) {
            return null;
        }

        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_W && $child->localName === $localName) {
                return $child;
            }
        }

        return null;
    }

    /**
     * @return list<\DOMElement>
     */
    private function childElementsByLocalName(?\DOMElement $parent, string $localName): array
    {
        if (!$parent instanceof \DOMElement) {
            return [];
        }

        $elements = [];
        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_W && $child->localName === $localName) {
                $elements[] = $child;
            }
        }

        return $elements;
    }

    private function childAttr(\DOMElement $parent, string $childLocalName, string $attrLocalName): string
    {
        $child = $this->childElement($parent, $childLocalName);

        return $child instanceof \DOMElement ? $child->getAttributeNS(self::NS_W, $attrLocalName) : '';
    }

    private function wordBoolean(\DOMElement $element, string $attribute = 'val'): bool
    {
        $value = strtolower($element->getAttributeNS(self::NS_W, $attribute));

        return !in_array($value, ['0', 'false', 'off'], true);
    }

    private function wordOptionalIntAttr(\DOMElement $element, string $attribute): ?int
    {
        $value = trim($element->getAttributeNS(self::NS_W, $attribute));
        if ($value === '' || preg_match('/^-?\d+$/', $value) !== 1) {
            return null;
        }

        return (int) $value;
    }

    private function wordOptionalBooleanAttr(\DOMElement $element, string $attribute): ?bool
    {
        $value = $element->getAttributeNS(self::NS_W, $attribute);
        if ($value === '') {
            return null;
        }

        return $this->onOffStringValue($value);
    }

    /**
     * @param list<string> $names
     * @return array<string, string|int|bool>
     */
    private function wordAttributeMap(\DOMElement $element, array $names): array
    {
        $attributes = [];
        foreach ($names as $name) {
            $value = $element->getAttributeNS(self::NS_W, $name);
            if ($value !== '') {
                $attributes[$name] = $value;
            }
        }

        return $attributes;
    }
}
